INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sahuadarsh0/Wallet/gradle-build-performance', 'gradle-build-performance', 'sahuadarsh0', 'Wallet', 'community', 'gradle-build-performance sahuadarsh0 Wallet community The gradle-build-performance skill helps developers optimize their Gradle builds, reducing slow build times and improving overall performance. It assists in identifying configuration vs execution bottlenecks and debugging kapt/KSP annotation processing. Gradle 构建性能优化涉及分析和优化构建过程，减少不必要的重新编译，调试注解处理等 Gradle ビルド パフォーマンス最適化は、ビルド プロセスの分析と最適化、不要な再コンパイルの削減、注釈処理のデバッグなどを含む Gradle 빌드 성능 최적화는 빌드 프로세스를 분석하고 최적화하여 불필요한 재컴파일을 줄이고 注解 처리를 디버깅하는 등을 포함 Optimice los tiempos de construcción de Gradle con nuestra guía de rendimiento. Analice y mejore el rendimiento de su build Améliorez les performances de construction Gradle avec nos conseils d''optimisation. Analysez et améliorez le rendimiento de votre build Optimieren Sie die Gradle-Build-Performance mit unserem Leitfaden. Analysieren und verbessern Sie die Build-Leistung Otimização do desempenho de build do Gradle para reduzir tempos de build e melhorar a eficiência do CI/CD Настройка производительности сборки Gradle для уменьшения времени сборки и повышения эффективности CI/CD تحسين أداء بناء جرادل لتقليل أوقات البناء وتحسين كفاءة CI/CD how to optimize gradle build performance gradle build performance best practices gradle build scan analysis reducing gradle build times gradle configuration cache setup debugging kapt annotation processing gradle build performance optimization guide gradle ci/cd pipeline optimization Gradle 性能优化 Gradle 构建扫描 CI/CD 优化 Gradle 配置缓存 注解处理调试 Gradle 构建时间优化 Gradle 性能分析 Gradle 优化技巧 Analyzes Gradle Build Scans to identify performance bottlenecks Optimizes CI/CD build times by reducing unnecessary recompilation Enables Gradle Configuration Cache for faster builds Debugs kapt/KSP annotation processing issues Investigates build performance regressions and configuration vs execution bottlenecks gradle-build-performance is a skill that focuses on improving the efficiency and speed of Gradle builds, enabling developers to analyze and optimize their build processes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('worm-13/pet-design-agent/image-quality-enhancement', 'community', 'worm-13', 'pet-design-agent', 'worm-13/pet-design-agent', 'image-quality-enhancement', 0, 0, 54, '2026-03-08T01:57:15.475Z', '2026-03-08T02:09:45.175Z', '620be53586fc3c596ebab56987e1d7c2d365472e2fb9f68df00c5dc5bce05555', '{"id":"worm-13/pet-design-agent/image-quality-enhancement","name":"image-quality-enhancement","description":{"en":"The image-quality-enhancement skill checks image clarity and enhances it using Real-ESRGAN if necessary, benefiting developers working with image processing tasks.","zh":"image-quality-enhancement技能使用Laplacian方差计算图像清晰度，若不足则通过Real-ESRGAN提升图像质量","ja":"image-quality-enhancementスキルは、ラプラシアン方差を使用して画像のクオリティーを計算し、Real-ESRGANで強化します","ko":"image-quality-enhancement 기능은 Laplacian 분산을 사용하여 이미지의 품질을 계산하고 Real-ESRGAN으로 향상시킵니다","es":"La habilidad de mejora de calidad de imagen utiliza Real-ESRGAN para mejorar la calidad de las imágenes. Evalúa la claridad de la imagen y la mejora si es necesario.","fr":"La compétence d''amélioration de la qualité d''image utilise Real-ESRGAN pour améliorer la qualité des images. Elle évalue la clarté de l''image et la améliore si nécessaire.","de":"Die Fähigkeit zur Bildqualitätsverbesserung verwendet Real-ESRGAN, um die Qualität von Bildern zu verbessern. Sie bewertet die Schärfe des Bildes und verbessert sie wenn nötig.","pt":"O skill de melhoria de qualidade de imagem utiliza Real-ESRGAN para avaliar e melhorar a nitidez de imagens, oferecendo saídas de alta qualidade.","ru":"Навык улучшения качества изображений использует Real-ESRGAN для оценки и улучшения резкости изображений, предлагая выходы высокого качества.","ar":"مهارة تحسين جودة الصور تستخدم Real-ESRGAN لتقييم و تحسين وضوح الصور، وتقدم مخرجات عالية الجودة."},"seo":{"title":{"en":"Image-Quality-Enhancement: Setup Guide for AI Agen