INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('worm-13/pet-design-agent/image-quality-enhancement', 'image-quality-enhancement', 'worm-13', 'pet-design-agent', 'community', 'image-quality-enhancement worm-13 pet-design-agent community The image-quality-enhancement skill checks image clarity and enhances it using Real-ESRGAN if necessary, benefiting developers working with image processing tasks. image-quality-enhancement技能使用Laplacian方差计算图像清晰度，若不足则通过Real-ESRGAN提升图像质量 image-quality-enhancementスキルは、ラプラシアン方差を使用して画像のクオリティーを計算し、Real-ESRGANで強化します image-quality-enhancement 기능은 Laplacian 분산을 사용하여 이미지의 품질을 계산하고 Real-ESRGAN으로 향상시킵니다 La habilidad de mejora de calidad de imagen utiliza Real-ESRGAN para mejorar la calidad de las imágenes. Evalúa la claridad de la imagen y la mejora si es necesario. La compétence d''amélioration de la qualité d''image utilise Real-ESRGAN pour améliorer la qualité des images. Elle évalue la clarté de l''image et la améliore si nécessaire. Die Fähigkeit zur Bildqualitätsverbesserung verwendet Real-ESRGAN, um die Qualität von Bildern zu verbessern. Sie bewertet die Schärfe des Bildes und verbessert sie wenn nötig. O skill de melhoria de qualidade de imagem utiliza Real-ESRGAN para avaliar e melhorar a nitidez de imagens, oferecendo saídas de alta qualidade. Навык улучшения качества изображений использует Real-ESRGAN для оценки и улучшения резкости изображений, предлагая выходы высокого качества. مهارة تحسين جودة الصور تستخدم Real-ESRGAN لتقييم و تحسين وضوح الصور، وتقدم مخرجات عالية الجودة. how to use image-quality-enhancement image-quality-enhancement setup guide what is image-quality-enhancement image-quality-enhancement alternative image-quality-enhancement vs Real-ESRGAN install image-quality-enhancement image-quality-enhancement for AI agents Real-ESRGAN image enhancement Laplacian variance image clarity 图像清晰度提升 Real-ESRGAN Laplacian方差 图像超分辨率 AI图像处理 图像质量增强 图像处理技术 Evaluates image clarity using Laplacian variance Enhances image quality with Real-ESRGAN via Replicate API Supports customizable minimum clarity standards Outputs enhanced images in accessible formats Utilizes nightmareai/real-esrgan for super-resolution tasks Integrates with projects via skills/image-quality-enhancement and scripts directories image-quality-enhancement is a skill that assesses and improves image clarity using Laplacian variance and Real-ESRGAN technology');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sedarged/TikTok-AI-Agent/repo-audit', 'community', 'sedarged', 'TikTok-AI-Agent', 'sedarged/TikTok-AI-Agent', 'repo-audit', 0, 0, 54, '2026-03-08T01:57:15.476Z', '2026-03-08T02:09:47.575Z', 'c0125cacae3d9c9396b279d48d6ad462bb441e150fb2b57db476a82e67d35a74', '{"id":"sedarged/TikTok-AI-Agent/repo-audit","name":"repo-audit","description":{"en":"The repo-audit skill runs a validation pipeline, producing a markdown report. It benefits developers by validating code quality through linting, type checking, and testing.","zh":"Repo Audit AI工具帮助您运行验证管道并生成Markdown报告，确保代码质量和稳定性","ja":"リポジトリ監査AIエージェントは検証パイプラインを実行し、Markdownレポートを生成してコードの品質と安定性を確保します","ko":"Repo Audit AI 도구는 검증 파이프라인을 실행하고 Markdown 보고서를 생성하여 코드 품질과 안정성을 보장합니다","es":"repo-audit es una herramienta para validar repositorios con npm, que ejecuta comandos como lint, typecheck y test para asegurar la calidad del código","fr":"repo-audit est un outil pour valider les référentiels avec npm, qui exécute des commandes comme lint, typecheck et test pour assurer la qualité du code","de":"repo-audit ist ein Tool zur Validierung von Repositories mit npm, das Befehle wie lint, typecheck und test ausführt, um die Codequalität sicherzustellen","pt":"O Repo-Audit é uma ferramenta de análise de código que executa pipelines de validação e gera relatórios em markdown.","ru":"Repo-Audit - это инструмент анализа кода, который запускает管道ы валидации и генерирует отчеты в markdown для ИИ Агентов","ar":"Repo-Audit هو أداة فحص الكود التي تعمل على تشغيل خطوط أنابيب التحقق وتوليد تقارير في صيغة markdown للوكلاء الذكاء الاصطناعي"},"seo":{"title":{"en":"repo-audit: Validation Pipeline Setup Guide | AI Agent Skill","zh":"Repo Audit 设置指南 - AI工具","ja":"リポジトリ監査のベストプラクティス - AIエージェント","ko":"Repo Audit 설정 가이드 - AI 도구","es":"Guía de configuración para repo-audit: Validación de repo...","fr":"Configurer repo-audit: Guide pour la validation des référ...","de":"Einrichtung von repo-audit: Validierung von Repositories ...","pt":"Guia de Configuração do Repo-Audit: Ferramenta de Análise...","ru":"Настройка Repo-Audit: Инструмент для анализа кода ИИ Агентов","ar":"دليل إعداد Repo-Audit: أداة فحص الكود للوكلاء الذكاء الاص..."},"description":{"en":"Run validation pipelines with repo-audit and generate markdown reports. Learn how to set up and use this AI agent skill for efficient code validation.","zh":"了解如何使用Repo Audit AI工具运行验证管道并生成Markdown报告，优化您的代码质量","ja":"リポジトリ監査AIエージェントを使用して検証パイプラインを実行し、Markdownレポートを生成する方法を学びます","ko":"Repo Audit AI 도구를 사용하여 검증 파이프라인을 실행하고 Markdown 보고서를 생성하여 코드 품질을 최적화하는 방법을 알아보세요","es":"Aprende a configurar y ejecutar repo-audit para validar tus repositorios con npm run lint, typecheck y test","fr":"Découvrez comment configurer et exécuter repo-audit pour valider vos référentiels avec npm run lint, typecheck et test","de":"Erfahren Sie, wie Sie repo-audit konfigurieren und ausführen, um Ihre Repositories mit npm run lint, typecheck und test zu validieren","pt":"Aprenda a configurar o Repo-Audit para analisar seu código e melhorar a qualidade do seu projeto com essa ferramenta de análise de código","ru":"Узнайте, как настроить Repo-Audit для анализа вашего кода и улучшения качества вашего проекта с помощью этого инструмента анализа кода ИИ Агентов","ar":"تعلم كيفية إعداد Repo-Audit لتحليل كودك وتحسين جودة مشروعك باستخدام أداة فحص الكود للوكلاء الذكاء الاصطناعي"},"definition":{"en":"repo-audit is a skill that automates code validation by running a series of commands, including npm run lint, npm run typecheck, and npm run test, to produce a markdown report.","zh":"Repo Audit是AI工具，用于运行验证管道并生成Markdown报告","ja":"リポジトリ監査はAIエージェントであり、検証パイプラインを実行し、Markdownレポートを生成します","ko":"Repo Audit는 AI 도구로서 검증 파이프라인을 실행하고 Markdown 보고서를 생성합니다","es":"repo-audit es una herramienta de validación de repositorios que utiliza npm para ejecutar comandos de verificación de código","fr":"repo-audit est un outil de validation de référentiels qui utilise npm pour exécuter des commandes de vérification de code","de":"repo-audit ist ein Tool zur Validierung von Repositories, das npm verwendet, um Code-Überprüfungsbefehle auszuführen","pt":"O que é Repo-Audit? É uma ferramenta de análise de código que executa pipelines de validação","ru":"Что такое Repo-Audit? Это инструмент анализа кода, который запускает管道ы валидации для ИИ Агентов","ar":"ما هو Repo-Audit? هو أداة فحص الكود التي تعمل على تشغيل خطوط أنابيب التحقق للوكلاء الذكاء الاصطناعي"},"features":{"en":["Runs npm run lint to identify code formatting issues","Executes npm run typecheck for type safety validation","Performs npm run test for unit testing and error detection","Generates a markdown report summarizing validation results","Optionally skips test:e2e for backend-only validation scope"],"zh":["运行npm run lint进行代码检查","运行npm run typecheck进行类型检查","运行npm run test进行测试","运行npm run test:rend进行渲染测试","支持可选的scope参数（例如\"backend only\"）","生成Markdown报告"],"ja":["npm run lintを実行してコードをチェックする","npm run typecheckを実行してタイプをチェックする","npm run testを実行してテストする","npm run test:rendを実行してレンダリングテストする","オプションのscopeパラメータ（例：\"backend only\"）をサポートする","Markdownレポートを生成する"],"ko":["npm run lint를 실행하여 코드를 확인","npm run typecheck를 실행하여 유형을 확인","npm run test를 실행하여 테스트","npm run test:rend를 실행하여 렌더링 테스트","선택적 scope 매개변수(예: \"backend only\")를 지원","Markdown 보고서를 생성"],"es":["Ejecución de npm run lint para la verificación de estilo de código","Ejecución de npm run typecheck para la verificación de tipos","Ejecución de npm run test para la verificación de funcionalidad","Ejecución de npm run test:rend para la verificación de rendimiento","Compatibilidad con scopes de backend y frontend","Generación de informes de validación en formato markdown"],"fr":["Exécution de npm run lint pour la vérification du style de code","Exécution de npm run typecheck pour la vérification des types","Exécution de npm run test pour la vérification de la fonctionnalité","Exécution de npm run test:rend pour la vérification des performances","Compatibilité avec les scopes de backend et de frontend","Génération de rapports de validation au format markdown"],"de":["Ausführung von npm run lint für die Überprüfung des Code-Stils","Ausführung von npm run typecheck für die Überprüfung der Typen","Ausführung von npm run test für die Überprüfung der Funktionalität","Ausführung von npm run test:rend für die Überprüfung der Leistung","Kompatibilität mit Backend- und Frontend-Scopes","Erstellung von Validierungsberichten im Markdown-Format"],"pt":["Executa pipelines de validação","Gera relatórios em markdown","Verifica erros de lint","Verifica erros de typecheck","Executa testes unitários e de integração"],"ru":["Запускает管道ы валидации","Генерирует отчеты в markdown","Проверяет ошибки lint","Проверяет ошибки typecheck","Запускает модульные и интеграционные тесты для ИИ Агентов"],"ar":["تشغيل خطوط أنابيب التحقق","توليد تقارير في صيغة markdown","تحقق من أخطاء lint","تحقق من أخطاء typecheck","تشغيل الاختبارات الوحدانية والتكاملية للوكلاء الذكاء الاصطناعي"]},"keywords":{"en":["how to use repo-audit","repo-audit setup guide","npm run lint","code validation pipeline","repo-audit vs code analysis tools","install repo-audit","markdown report generation","what is repo-audit","repo-audit alternative"],"zh":["Repo Audit","AI工具","代码检查","类型检查","测试","渲染测试","Markdown报告","npm run lint","npm run typecheck","npm run test"],"ja":["リポジトリ監査","AIエージェント","コードチェック","タイプチェック","テスト","レンダリングテスト","Markdownレポート","npm run lint","npm run typecheck","npm run test"],"ko":["Repo Audit","AI 도구","코드 확인","유형 확인","테스트","렌더링 테스트","Markdown 보고서","npm run lint","npm run typecheck","npm run test"],"es":["repo-audit","validación de repositorios","npm","lint","typecheck","test","scopes de backend y frontend","informes de validación","herramientas de desarrollo","desarrollo de software"],"fr":["repo-audit","validation de référentiels","npm","lint","typecheck","test","scopes de backend et de frontend","rapports de validation","outils de développement","développement de logiciels"],"de":["repo-audit","Validierung von Repositories","npm","lint","typecheck","test","Backend- und Frontend-Scopes","Validierungsberichte","Entwicklungstools","Softwareentwicklung"],"pt":["repo-audit","ferramenta de análise de código","análise de código","pipelines de validação","relatórios em markdown","lint","typecheck","testes unitários","testes de integração"],"ru":["repo-audit","инструмент анализа кода","анализ кода","管道ы валидации","отчеты в markdown","lint","typecheck","модульные тесты","интеграционные тесты","ИИ Агенты"],"ar":["repo-audit","أداة فحص الكود","فحص الكود","خطوط أنابيب التحقق","تقارير في صيغة markdown","lint","typecheck","اختبارات الوحدانية","اختبارات التكاملية","الوكلاء الذكاء الاصطناعي"]}},"owner":"sedarged","repo":"TikTok-AI-Agent","repoPath":"sedarged/TikTok-AI-Agent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.476Z","topics":[],"category":"community","skillMd":{"name":"repo-audit","description":"Run lint, typecheck, test, and test:render; collect results and produce a short audit report. Use when asked to audit the repo, check project health, or run full validation.","bodyPreview":"# Repo Audit\n\nRun the validation pipeline and produce a short markdown report.\n\n## Input\n\n- Open workspace (TikTok-AI-Agent). Optionally a \"scope\" (e.g. \"backend only\") – still run from root; you may skip `test:e2e` if scope is backend-only.\n\n## Steps\n\n1. From repo root, run in order:\n   - `npm run lint` – note pass or first ~5 lines of errors.\n   - `npm run typecheck` – note pass or first ~5 lines of errors.\n   - `npm run test` – note pass or failing test names/messages.\n   - `npm run test:rend","body":"# Repo Audit\n\nRun the validation pipeline and produce a short markdown report.\n\n## Input\n\n- Open workspace (TikTok-AI-Agent). Optionally a \"scope\" (e.g. \"backend only\") – still run from root; you may skip `test:e2e` if scope is backend-only.\n\n## Steps\n\n1. From repo root, run in order:\n   - `npm run lint` – note pass or first ~5 lines of errors.\n   - `npm run typecheck` – note pass or first ~5 lines of errors.\n   - `npm run test` – note pass or failing test names/messages.\n   - `npm run test:render` – note pass or failures.\n2. Optionally `npm run test:e2e` if full audit (requires Playwright browsers).\n3. Produce a **short markdown report** with:\n   - Each step: **ok** or **fail** + summary.\n   - Final line: **Audit: pass** or **Audit: fail** and list of failed steps.\n\n## Output\n\nA concise report, e.g.:\n\n```markdown\n## Repo audit\n\n- `npm run lint` – ok\n- `npm run typecheck` – ok\n- `npm run test` – ok\n- `npm run test:render` – ok\n\n**Audit: pass**\n```\n\nOr, on failure, which steps failed and the first few error lines.\n\n## References\n\n- [.cursor/commands/validate.md](.cursor/commands/validate.md) – validate command (same steps, no report format)\n- [docs/testing.md](../../docs/testing.md) – test setup, env, commands\n"},"lastSynced":"2026-03-08T02:09:47.575Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents needing comprehensive validation through linting, type checking, and testing.","zh":"适合需要通过 linting、类型检查和测试进行全面验证的代码审查代理。","ja":"linting、型チェック、テストを通じて包括的な検証が必要なコードレビュー代理に最適です。","ko":"linting, 유형 확인 및 테스트를 통해 종합적인 검증이 필요한 코드 리뷰 에이전트에 적합합니다.","es":"Ideal para Agentes de Revisión de Código que necesitan una validación integral a través de linting, verificación de tipos y pruebas.","fr":"Idéal pour les Agents de Révision de Code nécessitant une validation complète via le linting, la vérification de types et les tests.","de":"Ideal für Code-Review-Agents, die eine umfassende Validierung durch Linting, Typüberprüfung und Tests benötigen.","pt":"Ideal para Agentes de Revisão de Código que necessitam de validação abrangente por meio de linting, verificação de tipo e teste.","ru":"Идеально подходит для агентов проверки кода, требующих всесторонней проверки с помощью linting, проверки типа и тестирования.","ar":"مثالي للوكلاء المراجعة للشفرة الذين يحتاجون إلى التحقق الشامل من خلال linting و فحص النوع و الاختبار."},"recommendation":{"en":"Empowers agents to validate code quality using npm scripts for linting, type checking, and testing, producing a markdown report with key insights from `npm run lint`, `npm run typecheck`, and `npm run test` commands.","zh":"使代理能够使用 npm 脚本进行 linting、类型检查和测试，生成包含来自 `npm run lint`、`npm run typecheck` 和 `npm run test` 命令的关键见解的 markdown 报告。","ja":"npm スクリプトを使用して linting、型チェック、テストを実行し、`npm run lint`、`npm run typecheck`、`npm run test` コマンドからの主要な洞察を含む markdown レポートを生成することで、エージェントがコード品質を検証できるようにします。","ko":"npm 스크립트를 사용하여 linting, 유형 확인 및 테스트를 수행하고 `npm run lint`, `npm run typecheck`, `npm run test` 명령의 주요 통찰력을 포함하는 markdown 보고서를 생성하여 에이전트가 코드 품질을 검증할 수 있도록 합니다.","es":"Habilita a los agentes a validar la calidad del código utilizando scripts de npm para linting, verificación de tipos y pruebas, produciendo un informe en markdown con información clave de los comandos `npm run lint`, `npm run typecheck` y `npm run test`.","fr":"Permet aux agents de valider la qualité du code en utilisant des scripts npm pour le linting, la vérification de types et les tests, produisant un rapport markdown avec des informations clés des commandes `npm run lint`, `npm run typecheck` et `npm run test`.","de":"Ermächtigt die Agenten, die Code-Qualität mithilfe von npm-Skripten für Linting, Typüberprüfung und Tests zu validieren, wodurch ein Markdown-Bericht mit wichtigen Erkenntnissen aus den Befehlen `npm run lint`, `npm run typecheck` und `npm run test` erstellt wird.","pt":"Habilita os agentes a validar a qualidade do código usando scripts npm para linting, verificação de tipo e teste, produzindo um relatório em markdown com informações-chave dos comandos `npm run lint`, `npm run typecheck` e `npm run test`.","ru":"Позволяет агентам проверять качество кода с помощью скриптов npm для linting, проверки типа и тестирования, генерируя отчет в markdown с ключевыми сведениями из команд `npm run lint`, `npm run typecheck` и `npm run test`.","ar":"يمنح الوكلاء القدرة على التحقق من جودة الشفرة باستخدام سكريبتات npm ل linting و فحص النوع و الاختبار و إنتاج تقرير markdown مع informacións الرئيسية من أوامر `npm run lint` و `npm run typecheck` و `npm run test`."},"useCases":{"en":["Validating code quality for backend-only scopes","Running comprehensive validation pipelines from the repository root","Generating markdown reports for code review"],"zh":["后端范围的代码质量验证","从存储库根运行全面验证管道","生成代码审查的 markdown 报告"],"ja":["バックエンド専用のスコープのコード品質の検証","リポジトリのルートから包括的な検証パイプラインを実行","コードレビューの markdown レポートを生成"],"ko":["백엔드 전용 범위의 코드 품질 검증","저장소 루트에서 포괄적인 검증 파이프라인 실행","코드 리뷰를 위한 markdown 보고서 생성"],"es":["Validar la calidad del código para ámbitos de solo backend","Ejecutar tuberías de validación integrales desde la raíz del repositorio","Generar informes en markdown para la revisión de código"],"fr":["Valider la qualité du code pour les portées de backend uniquement","Exécuter des pipelines de validation complets à partir de la racine du référentiel","Générer des rapports markdown pour la révision de code"],"de":["Validieren der Code-Qualität für backend-only-Umfänge","Ausführen umfassender Validierungspipelines vom Repository-Stamm","Erstellen von Markdown-Berichten für die Code-Überprüfung"],"pt":["Validar a qualidade do código para escopos de backend apenas","Executar pipelines de validação abrangentes a partir da raiz do repositório","Gerar relatórios em markdown para revisão de código"],"ru":["Проверка качества кода для областей применения только для бэкэнда","Запуск всесторонних конвейеров проверки из корня репозитория","Генерация отчетов в markdown для проверки кода"],"ar":["التحقق من جودة الشفرة لمدى_BACKEND فقط","تشغيل أنابيب التحقق الشامل من الجذر للمستودع","إنتاج تقارير markdown للتحقق من الشفرة"]},"limitations":{"en":["Requires npm scripts configuration","Runs from repository root","Optional scope parameter for custom validation"],"zh":["需要 npm 脚本配置","从存储库根运行","可选范围参数用于自定义验证"],"ja":["npm スクリプトの構成が必要","リポジトリのルートから実行","カスタム検証用のオプションのスコープパラメータ"],"ko":["npm 스크립트 구성이 필요","저장소 루트에서 실행","사용자 지정 검증을 위한 선택적 범위 매개 변수"],"es":["Requiere configuración de scripts de npm","Se ejecuta desde la raíz del repositorio","Parámetro de ámbito opcional para validación personalizada"],"fr":["Nécessite la configuration des scripts npm","S''exécute à partir de la racine du référentiel","Paramètre d''étendue facultatif pour la validation personnalisée"],"de":["Benötigt npm-Skript-Konfiguration","Wird vom Repository-Stamm aus ausgeführt","Optional: Bereichsparameter für benutzerdefinierte Validierung"],"pt":["Requer configuração de scripts npm","Executa a partir da raiz do repositório","Parâmetro de escopo opcional para validação personalizada"],"ru":["Требует конфигурации скриптов npm","Запускается из корня репозитория","Необязательный параметр области действия для индивидуальной проверки"],"ar":["يتطلب تكوين سكريبتات npm","ينفذ من الجذر للمستودع","معامل نطاق اختياري للتحقق المخصص"]},"version":4},"contentHash":"c0125cacae3d9c9396b279d48d6ad462bb441e150fb2b57db476a82e67d35a74","qualityScore":54}');
