INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sedarged/TikTok-AI-Agent/repo-audit', 'repo-audit', 'sedarged', 'TikTok-AI-Agent', 'community', 'repo-audit sedarged TikTok-AI-Agent community The repo-audit skill runs a validation pipeline, producing a markdown report. It benefits developers by validating code quality through linting, type checking, and testing. Repo Audit AI工具帮助您运行验证管道并生成Markdown报告，确保代码质量和稳定性 リポジトリ監査AIエージェントは検証パイプラインを実行し、Markdownレポートを生成してコードの品質と安定性を確保します Repo Audit AI 도구는 검증 파이프라인을 실행하고 Markdown 보고서를 생성하여 코드 품질과 안정성을 보장합니다 repo-audit es una herramienta para validar repositorios con npm, que ejecuta comandos como lint, typecheck y test para asegurar la calidad del código repo-audit est un outil pour valider les référentiels avec npm, qui exécute des commandes comme lint, typecheck et test pour assurer la qualité du code repo-audit ist ein Tool zur Validierung von Repositories mit npm, das Befehle wie lint, typecheck und test ausführt, um die Codequalität sicherzustellen O Repo-Audit é uma ferramenta de análise de código que executa pipelines de validação e gera relatórios em markdown. Repo-Audit - это инструмент анализа кода, который запускает管道ы валидации и генерирует отчеты в markdown для ИИ Агентов Repo-Audit هو أداة فحص الكود التي تعمل على تشغيل خطوط أنابيب التحقق وتوليد تقارير في صيغة markdown للوكلاء الذكاء الاصطناعي how to use repo-audit repo-audit setup guide npm run lint code validation pipeline repo-audit vs code analysis tools install repo-audit markdown report generation what is repo-audit repo-audit alternative Repo Audit AI工具 代码检查 类型检查 测试 渲染测试 Markdown报告 npm run lint npm run typecheck npm run test Runs npm run lint to identify code formatting issues Executes npm run typecheck for type safety validation Performs npm run test for unit testing and error detection Generates a markdown report summarizing validation results Optionally skips test:e2e for backend-only validation scope repo-audit is a skill that automates code validation by running a series of commands, including npm run lint, npm run typecheck, and npm run test, to produce a markdown report.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sweeden-ttu/spring-2026/jekyll-article-generator', 'community', 'sweeden-ttu', 'spring-2026', 'sweeden-ttu/spring-2026', 'jekyll-article-generator', 0, 0, 54, '2026-03-08T01:57:15.477Z', '2026-03-08T02:09:49.672Z', '59d90039228e4528e23f48d7a57e59de09cb9184dad442bab5cb7e583f5caf1e', '{"id":"sweeden-ttu/spring-2026/jekyll-article-generator","name":"jekyll-article-generator","description":{"en":"The jekyll-article-generator skill creates publication-quality articles and blog posts for Jekyll sites, specializing in software verification and validation topics. It benefits developers and writers seeking to generate well-structured content.","zh":"Jekyll 文章生成器是一种专门的 AI 工具，用于生成符合 Jekyll-TeXt 主题约定和最佳实践的高质量文章和博客帖子","ja":"Jekyll 記事生成ツールは、Jekyll-TeXt テーマの規約とベストプラクティスに従った、高品質な記事とブログ投稿を生成するための専門の AI エージェントです","ko":"Jekyll 文章 생성기는 Jekyll-TeXt 테ーマ의 규약과 최고의 관행에 따라 높은 품질의 文章과 블로그 게시물을 생성하기 위한 전문 AI 에이전트입니다","es":"jekyll-article-generator es un agente especializado en generar artículos de publicación para sitios Jekyll con temas de verificación y validación de software","fr":"jekyll-article-generator est un agent spécialisé dans la génération d''articles de publication pour les sites Jekyll sur les thèmes de vérification et de validation de logiciels","de":"jekyll-article-generator ist ein Spezialagent für die Erstellung von Publikationsartikeln für Jekyll-Websites mit Themen zu Software-Verifizierung und -Validierung","pt":"O jekyll-article-generator é um agente especializado em criar artigos de qualidade publicável sobre verificação e validação de software.","ru":"jekyll-article-generator - это агент, специализирующийся на создании публикаций о верификации и валидации программного обеспечения.","ar":"jekyll-article-generator هو وكيل متخصص في إنشاء مقالات منشورة عالية الجودة حول التحقق والتحقق من صحة البرامج."},"seo":{"title":{"en":"jekyll-article-generator: Publication-Ready Article Setup...","zh":"Jekyll 文章生成器 Setup Guide - 软件验证和加密","ja":"Jekyll 記事生成ツールのベストプラクティス - AIエージェントによるソフトウェア検証","ko":"Jekyll 文章 생성기 설정 가이드 - 소프트웨어 검증 및 암호화","es":"Guía de configuración de jekyll-article-generator para Ag...","fr":"Guide d''installation de jekyll-article-generator pour les...","de":"Einrichtungsleitfaden für jekyll-article-generator für KI...","pt":"Guia de Configuração do jekyll-article-generator para Fer...","ru":"Настройка jekyll-article-generator: ИИ Агенты для Верифик...","ar":"دليل إعداد jekyll-article-generator لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how jekyll-article-generator creates well-structured articles for Jekyll sites. Learn to generate publication-quality content with ease and explore ...","zh":"了解 Jekyll 文章生成器如何帮助您创建高质量的文章和博客帖子，专注于软件验证和加密","ja":"Jekyll 記事生成ツールを使用して、ソフトウェア検証と暗号化に関する質の高い記事とブログ投稿を作成する方法を学びます","ko":"Jekyll 文章 생성기를 사용하여 소프트웨어 검증 및 암호화에 대한 높은 품질의 文章과 블로그 게시물을 생성하는 방법에 대해 알아보세요","es":"Descubre cómo configurar jekyll-article-generator para generar artículos de calidad para tu sitio Jekyll con temas de verificación y validación de software","fr":"Découvrez comment configurer jekyll-article-generator pour générer des articles de haute qualité pour votre site Jekyll sur les thèmes de vérification et de ...","de":"Erfahren Sie, wie Sie jekyll-article-generator konfigurieren, um qualitativ hochwertige Artikel für Ihre Jekyll-Website mit Themen zu Software-Verifizierung ...","pt":"Aprenda a configurar o jekyll-article-generator para criar artigos de qualidade publicável sobre verificação e validação de software com o tema jekyll-TeXt","ru":"Откройте для себя, как настроить jekyll-article-generator для создания публикаций о верификации и валидации программного обеспечения с помощью темы jekyll-TeXt","ar":"اكتشف كيفية إعداد jekyll-article-generator لإنشاء مقالات منشورة عالية الجودة حول التحقق والتحقق من صحة البرامج باستخدام tema jekyll-TeXt"},"definition":{"en":"jekyll-article-generator is a specialized AI agent skill for generating publication-quality articles and blog posts for Jekyll sites, focusing on software verification and validation.","zh":"Jekyll 文章生成器是一种 AI 工具，用于生成软件验证和加密相关的高质量文章和博客帖子","ja":"Jekyll 記事生成ツールは、ソフトウェア検証と暗号化に関する高品質な記事とブログ投稿を生成するための AI エージェントです","ko":"Jekyll 文章 생성기는 소프트웨어 검증 및 암호화에 대한 높은 품질의 文章과 블로그 게시물을 생성하기 위한 AI 에이전트입니다","es":"jekyll-article-generator es un agente de IA que genera artículos de calidad para sitios Jekyll","fr":"jekyll-article-generator est un outil d''IA qui génère des articles de haute qualité pour les sites Jekyll","de":"jekyll-article-generator ist ein KI-Tool, das qualitativ hochwertige Artikel für Jekyll-Websites erstellt","pt":"O jekyll-article-generator é um agente de IA que gera artigos de qualidade publicável sobre verificação e validação de software.","ru":"jekyll-article-generator - это ИИ Агент, генерирующий публикации о верификации и валидации программного обеспечения.","ar":"jekyll-article-generator هو وكيل ذكاء اصطناعي يولد مقالات منشورة عالية الجودة حول التحقق والتحقق من صحة البرامج."},"features":{"en":["Generates well-structured articles following jekyll-TeXt-theme conventions","Creates publication-ready blog posts with proper article layout and front matter","Maintains academic and professional tone in generated content","Covers software verification and validation topics with deep expertise","Uses proper Markdown formatting for readability and compatibility"],"zh":["生成符合 Jekyll-TeXt 主题约定和最佳实践的文章","使用适当的文章布局和前置内容","维持学术和专业的语气","涵盖软件验证和加密主题"],"ja":["Jekyll-TeXt テーマの規約とベストプラクティスに従った記事を生成","適切な記事レイアウトとフロントマターを使用","学術的かつ専門的なトーンを維持","ソフトウェア検証と暗号化のトピックをカバー"],"ko":["Jekyll-TeXt 테ーマ의 규약과 최고의 관행에 따라 文章을 생성","적절한 文章 레이아웃과 프론트 매터를 사용","학술적이고 전문적인 토드를 유지","소프트웨어 검증 및 암호화 주제를 다룸"],"es":["Genera artículos con formato y front matter adecuados para Jekyll","Mantiene un tono académico y profesional en los artículos","Cubre temas de verificación y validación de software","Sigue las convenciones y mejores prácticas de jekyll-TeXt-theme","Crea artículos con estructura y diseño adecuados para publicaciones"],"fr":["Génère des articles avec un format et un front matter adaptés à Jekyll","Maintient un ton académique et professionnel dans les articles","Couvre les thèmes de vérification et de validation de logiciels","Suit les conventions et les meilleures pratiques de jekyll-TeXt-theme","Crée des articles avec une structure et un design adaptés à la publication"],"de":["Erstellt Artikel mit geeignetem Format und Front Matter für Jekyll","Hält einen akademischen und professionellen Ton in den Artikeln ein","Behandelt Themen zu Software-Verifizierung und -Validierung","Folgt den Konventionen und Best Practices von jekyll-TeXt-theme","Erstellt Artikel mit geeigneter Struktur und Design für die Veröffentlichung"],"pt":["Geração de artigos com layout e front matter adequados","Manutenção de tom acadêmico e profissional","Cobertura de tópicos de verificação de software","Compatibilidade com o tema jekyll-TeXt","Geração de artigos de qualidade publicável"],"ru":["Генерация статей с правильным макетом и фронт-материалом","Поддержание академического и профессионального тона","Освещение тем верификации программного обеспечения","Совместимость с темой jekyll-TeXt","Генерация публикаций высокого качества"],"ar":["إنشاء مقالات بالتنسيق والمادة الأمامية المناسبة","الحفاظ على النبرة الأكاديمية والمهنية","التغطية مواضيع التحقق من صحة البرامج","التوافق مع tema jekyll-TeXt","إنشاء مقالات منشورة عالية الجودة"]},"keywords":{"en":["how to use jekyll-article-generator","jekyll-article-generator setup guide","jekyll-article-generator alternative","jekyll-article-generator vs other generators","what is jekyll-article-generator","jekyll-article-generator install","jekyll-TeXt-theme article generation","software verification and validation tools","publication-quality article generation"],"zh":["Jekyll 文章生成器","软件验证","加密","AI 工具","Jekyll-TeXt 主题","文章生成","博客帖子","高质量内容"],"ja":["Jekyll 記事生成ツール","ソフトウェア検証","暗号化","AI エージェント","Jekyll-TeXt テーマ","記事生成","ブログ投稿","高品質コンテンツ"],"ko":["Jekyll 文章 생성기","소프트웨어 검증","암호화","AI 에이전트","Jekyll-TeXt 테ーマ","文章 생성","블로그 게시물","높은 품질의 컨텐츠"],"es":["jekyll-article-generator","Agentes de IA para escritura","Generación de artículos para Jekyll","Verificación y validación de software","jekyll-TeXt-theme","Herramientas de IA para escritura técnica","Configuración de jekyll-article-generator","Guía de instalación de jekyll-article-generator"],"fr":["jekyll-article-generator","Outils d''IA pour l''écriture","Génération d''articles pour Jekyll","Vérification et validation de logiciels","jekyll-TeXt-theme","Outils d''IA pour l''écriture technique","Configuration de jekyll-article-generator","Guide d''installation de jekyll-article-generator"],"de":["jekyll-article-generator","KI-Tools für Schreiben","Erstellung von Artikeln für Jekyll","Software-Verifizierung und -Validierung","jekyll-TeXt-theme","KI-Tools für technisches Schreiben","Konfiguration von jekyll-article-generator","Einrichtungsleitfaden für jekyll-article-generator"],"pt":["jekyll-article-generator","ferramentas de IA","verificação de software","validação de software","jekyll-TeXt","artigos de qualidade publicável","geração de artigos","tema jekyll"],"ru":["jekyll-article-generator","ИИ Агенты","верификация программного обеспечения","валидация программного обеспечения","jekyll-TeXt","публикации высокого качества","генерация статей","тема jekyll"],"ar":["jekyll-article-generator","أدوات الذكاء الاصطناعي","التحقق من صحة البرامج","التحقق من صحة البرامج","jekyll-TeXt","مقالات منشورة عالية الجودة","إنشاء مقالات","tema jekyll"]}},"owner":"sweeden-ttu","repo":"spring-2026","repoPath":"sweeden-ttu/spring-2026","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.477Z","topics":[],"category":"community","skillMd":{"name":"jekyll-article-generator","description":"Specialized agent for generating high-quality articles and blog posts using jekyll-TeXt-theme, with expertise in software verification and validation. Use when creating course materials, lecture notes, topic articles, or blog posts for the Spring 2026 coursework site.","bodyPreview":"# Jekyll TeXt Theme Article Generator\n\nThis agent specializes in generating publication-quality articles and blog posts for the jekyll-TeXt-theme Jekyll site, with deep expertise in software verification and validation topics.\n\n## Purpose and Scope\n\nGenerate well-structured, publication-ready articles and blog posts that:\n- Follow jekyll-TeXt-theme conventions and best practices\n- Use proper article layout and front matter\n- Maintain academic and professional tone\n- Cover software verification,","body":"# Jekyll TeXt Theme Article Generator\n\nThis agent specializes in generating publication-quality articles and blog posts for the jekyll-TeXt-theme Jekyll site, with deep expertise in software verification and validation topics.\n\n## Purpose and Scope\n\nGenerate well-structured, publication-ready articles and blog posts that:\n- Follow jekyll-TeXt-theme conventions and best practices\n- Use proper article layout and front matter\n- Maintain academic and professional tone\n- Cover software verification, validation, testing, and related topics\n- Can serve as course materials, lecture notes, or blog content\n\n## Target Location\n\nThis skill is project-specific and should be stored at:\n- `.cursor/skills/jekyll-article-generator/` (in the spring-2026 project)\n\n## Trigger Scenarios\n\nAutomatically apply this skill when users request:\n- Creating new articles or blog posts\n- Generating course materials or lecture notes\n- Writing topic articles for software verification topics\n- Converting notes to publication format\n- Creating documentation or tutorial content\n\n## Key Domain Knowledge\n\n### Software Verification & Validation Expertise\n\nThe agent understands:\n- **Verification vs. Validation**: Building the product right vs. building the right product\n- **Testing Techniques**: Black box, white box, model-based, graph-based, fault-based testing\n- **Formal Methods**: Model checking, theorem proving, formal verification\n- **Testing Tools**: LangSmith, testing frameworks, coverage tools\n- **AI/LLM Testing**: Evaluation methods, prompt testing, LLM quality assurance\n- **Industry Practices**: Test adequacy criteria, coverage metrics, test strategies\n\n### Jekyll TeXt Theme Knowledge\n\nThe agent understands:\n- **Layouts**: `article`, `page`, `home`, `landing`, `archive`\n- **Front Matter**: Required and optional fields for articles\n- **Article Structure**: Excerpt separation with `<!--more-->`, proper heading hierarchy\n- **Theme Features**: MathJax, Mermaid diagrams, syntax highlighting\n- **Navigation Configuration**: Header and sidebar navigation via `_data/navigation.yml`\n\n## Article Format Standards\n\n### Front Matter Template\n\n```yaml\n---\nlayout: article\ntitle: Article Title\nkey: unique-article-key\ntags:\n  - Tag1\n  - Tag2\n  - Tag3\npermalink: /path/to/article/\nmathjax: true  # Optional: for mathematical notation\nmermaid: true  # Optional: for diagrams\n---\n```\n\n### Content Structure\n\n1. **Opening Paragraph** (Excerpt)\n   - Engaging introduction\n   - Clear statement of topic\n   - Sets context and expectations\n\n2. **Excerpt Separator**\n   - `<!--more-->` after first paragraph or section\n   - Marks where excerpt ends in article lists\n\n3. **Main Content**\n   - Logical sections with proper headings (##, ###)\n   - Examples and code blocks where appropriate\n   - Clear explanations and definitions\n   - Academic tone with professional language\n\n4. **Conclusion/Summary**\n   - Key takeaways\n   - Further reading/resources\n   - Navigation to related articles\n\n### Style Guidelines\n\n- **Tone**: Academic but accessible, professional yet engaging\n- **Structure**: Clear hierarchy with descriptive headings\n- **Examples**: Include code examples, diagrams, or practical illustrations\n- **Citations**: Reference course materials, standards, or research when appropriate\n- **Formatting**: Use Markdown features (code blocks, lists, emphasis) effectively\n\n## Examples\n\n### Course Topic Article\n\n```yaml\n---\nlayout: article\ntitle: Black Box Testing\nkey: topic-black-box-testing\ntags:\n  - Testing\n  - Black Box\n  - Functional Testing\npermalink: /software-verification/topics/black-box-testing/\n---\n\nBlack box testing is a fundamental testing methodology where the internal structure of the software is not known to the tester. Instead, testers focus on functionality and behavior based on specifications.\n\n<!--more-->\n\n## Understanding Black Box Testing\n\n[Main content here...]\n```\n\n### Lecture Notes Article\n\n```yaml\n---\nlayout: article\ntitle: Lecture 5: Model-Based Testing\nkey: lecture-05-model-based-testing\ntags:\n  - Lecture Notes\n  - Model-Based Testing\n  - CS-5374\ndate: 2026-02-12\npermalink: /software-verification/lectures/2026-02-12-model-based-testing/\n---\n\nThis lecture covers model-based testing techniques and their application in software verification.\n\n<!--more-->\n\n## Topics Covered\n\n[Lecture content...]\n```\n\n## Best Practices\n\n1. **Always use `layout: article`** for articles and blog posts\n2. **Include `key` field** with unique identifier (letter + alphanumeric)\n3. **Add relevant tags** for categorization and navigation\n4. **Use `<!--more-->` separator** after excerpt\n5. **Maintain heading hierarchy** (## for main sections, ### for subsections)\n6. **Include code examples** in appropriate language blocks\n7. **Link to related articles** and resources\n8. **Use MathJax/Mermaid** when mathematical notation or diagrams are needed\n\n## Navigation Checklist\n\nWhen creating articles that need navigation:\n\n- [ ] Determine if article should appear in header or sidebar navigation\n- [ ] Check `_data/navigation.yml` for existing navigation structures\n- [ ] Add article to appropriate navigation structure if needed\n- [ ] Use consistent URL patterns with other related articles\n- [ ] If using sidebar, add `sidebar: { nav: nav-name }` to front matter\n- [ ] Verify navigation URLs match article permalinks\n- [ ] Ensure navigation hierarchy is logical and well-organized\n\n## Quality Checklist\n\nBefore finalizing an article, ensure:\n- [ ] Front matter includes `layout: article`, `title`, `key`, `tags`, `permalink`\n- [ ] Sidebar navigation configured if article is part of a topic series\n- [ ] Opening paragraph serves as good excerpt\n- [ ] `<!--more-->` separator is present\n- [ ] Content is well-structured with proper headings\n- [ ] Academic tone is maintained throughout\n- [ ] Technical terms are defined or explained\n- [ ] Examples or illustrations are included where appropriate\n- [ ] Links to related content are provided\n- [ ] Navigation is updated in `_data/navigation.yml` if article should appear in menus\n- [ ] Content is publication-ready\n\n## Navigation Configuration\n\n### Understanding `_data/navigation.yml`\n\nThe jekyll-TeXt-theme uses `_data/navigation.yml` to define navigation. The agent must understand two types:\n\n#### Header Navigation\n\nDefined under the `header` key. Used for main site navigation menu:\n\n```yaml\nheader:\n  - title:      Home\n    url:        /\n  - title:      Docs\n    url:        /docs/en/quick-start\n    key:        docs  # Optional: unique identifier\n  - titles:     # Multi-language support\n      en:       Archive\n      zh:       归档\n    url:        /archive.html\n  - title:      External Link\n    url:        https://example.com\n```\n\n**Key Points**:\n- Each item has `title` (or `titles` for multi-language) and `url`\n- Optional `key` field for unique identification\n- Can include external URLs\n- Supports single `title` or `titles` object for internationalization\n\n#### Sidebar Navigation\n\nDefined as named navigation structures. Used for article sidebar navigation:\n\n```yaml\ncourse-topics:\n  - title:      Fundamentals\n    children:\n      - title:  Introduction to V&V\n        url:    /software-verification/topics/01-introduction-vv/\n      - title:  Adequacy Criterion\n        url:    /software-verification/topics/02-adequacy-criterion/\n  - title:      Testing Techniques\n    children:\n      - title:  Black Box Testing\n        url:    /software-verification/topics/04-black-box-testing/\n      - title:  White Box Testing\n        url:    /software-verification/topics/05-white-box-testing/\n```\n\n**Key Points**:\n- Named navigation structure (e.g., `course-topics:`, `docs-en:`)\n- Hierarchical structure with `children` arrays\n- Each child has `title` and `url`\n- Supports nested navigation (parent → children)\n\n### Using Sidebar Navigation in Articles\n\nTo enable sidebar navigation in an article, add to front matter:\n\n```yaml\n---\nlayout: article\ntitle: Article Title\nsidebar:\n  nav: course-topics  # References navigation structure in navigation.yml\n---\n```\n\n### Navigation Best Practices\n\nWhen creating articles, consider navigation:\n\n1. **Header Navigation**: Add important pages/sections to `header` in `_data/navigation.yml`\n2. **Sidebar Navigation**: Create named navigation structures for topic groups\n3. **Update Navigation**: When creating new articles, update `navigation.yml` if they should appear in navigation\n4. **Consistent URLs**: Use consistent permalink patterns for related articles\n5. **Hierarchical Organization**: Use `children` to group related topics under parent categories\n\n### Example Navigation File\n\nComplete `_data/navigation.yml` structure:\n\n```yaml\nheader:\n  - title: Home\n    url: /\n  - title: Software Verification\n    url: /software-verification/introduction/\n  - title: Topics\n    url: /software-verification/introduction/\n  - title: Courses\n    url: /courses/\n\n# Sidebar navigation for course topics\ncourse-topics:\n  - title: Introduction\n    children:\n      - title: Introduction to V&V\n        url: /software-verification/topics/01-introduction-vv/\n      - title: Adequacy Criterion\n        url: /software-verification/topics/02-adequacy-criterion/\n  - title: Testing Methods\n    children:\n      - title: Black Box Testing\n        url: /software-verification/topics/04-black-box-testing/\n      - title: White Box Testing\n        url: /software-verification/topics/05-white-box-testing/\n      - title: Model-based Testing\n        url: /software-verification/topics/06-model-based-testing/\n```\n\n## Integration with Course Site\n\nArticles should:\n- Reference course data from `_data/` directories when appropriate\n- Use Liquid templating for dynamic content\n- Follow site navigation structure defined in `_data/navigation.yml`\n- Update navigation.yml when creating new article series or sections\n- Link to related lectures, topics, or resources\n- Use sidebar navigation where appropriate for topic organization\n- Maintain consistency with existing course materials\n\n## Navigation Workflow\n\nWhen creating articles that should appear in navigation:\n\n1. **Determine Navigation Type**: \n   - Header navigation: For main site navigation items\n   - Sidebar navigation: For topic-based article organization\n\n2. **Check Existing Navigation**: Review `_data/navigation.yml` for existing structures\n\n3. **Update Navigation File**: \n   - Add to `header:` for main navigation items\n   - Add to appropriate sidebar navigation structure (e.g., `course-topics:`)\n   - Maintain hierarchical structure with `children` where appropriate\n\n4. **Reference in Front Matter**: \n   - If using sidebar, add `sidebar: { nav: navigation-name }` to article front matter\n\n5. **Maintain Consistency**: \n   - Use consistent URL patterns\n   - Group related articles under same parent in sidebar\n   - Keep navigation structures organized and logical\n\n## Workflow\n\nWhen generating articles:\n\n1. **Understand Requirements**: Clarify article type, topic, and audience\n2. **Gather Context**: Review related course materials or existing articles\n3. **Check Navigation**: Review `_data/navigation.yml` to see where article fits\n4. **Create Structure**: Plan sections and content flow\n5. **Write Content**: Generate article following format standards\n6. **Update Navigation**: Add article to appropriate navigation structure if needed\n7. **Review and Refine**: Ensure quality, consistency, and completeness\n8. **Add Metadata**: Include tags, links, front matter, and sidebar navigation if applicable\n\n## Navigation Examples\n\n### Example: Complete Navigation File\n\nReference the `_data/navigation.yml` structure from the jekyll-TeXt-theme repository:\n- **Header Navigation**: Simple flat structure with `title` and `url`\n- **Sidebar Navigation**: Hierarchical structure with named navigation groups\n- **Multi-language Support**: Use `titles` object instead of `title` for i18n\n\n### Example: Using Sidebar in Article\n\n```yaml\n---\nlayout: article\ntitle: Black Box Testing\nkey: topic-black-box-testing\ntags:\n  - Testing\nsidebar:\n  nav: course-topics  # References navigation structure in _data/navigation.yml\npermalink: /software-verification/topics/04-black-box-testing/\n---\n```\n\nThis will display the `course-topics` navigation in the sidebar when viewing this article.\n\n### Example: Multi-language Navigation\n\n```yaml\nheader:\n  - titles:\n      en: Archive\n      zh: 归档\n    url: /archive.html\n```\n\nUse `titles` object for internationalization support.\n\n## Reference Files\n\n- **Theme Navigation**: https://github.com/sweeden-ttu/jekyll-TeXt-theme/blob/master/docs/_data/navigation.yml\n- **Site Navigation**: `_data/navigation.yml` (should be created/updated as articles are added)\n- **Article Examples**: See `/software-verification/_pages/topics/` for examples of course topic articles\n- **Navigation Documentation**: See theme docs at `/docs/en/navigation` or `/docs/zh/navigation`\n"},"lastSynced":"2026-03-08T02:09:49.672Z","agentAnalysis":{"suitability":{"en":"Perfect for Content Generation Agents specializing in software verification and validation topics, requiring structured article generation for Jekyll sites.","zh":"适用于专注于软件验证和验证主题的内容生成代理，需要为Jekyll站点生成结构化文章。","ja":"ソフトウェアの検証とバリデーションのトピックを専門とするコンテンツ生成エージェントに適しています。Jekyllサイト向けの構造化された記事の生成が必要です。","ko":"소프트웨어 검증 및 유효성 검사 주제에 전문적인 콘텐츠 생성 에이전트에게 적합합니다. Jekyll 사이트를 위한 구조화된 기사의 생성이 필요합니다.","es":"Perfecto para Agentes de Generación de Contenido que se especializan en temas de verificación y validación de software, y que requieren la generación de artículos estructurados para sitios Jekyll.","fr":"Idéal pour les Agents de Génération de Contenu spécialisés dans les sujets de vérification et de validation de logiciels, nécessitant la génération d''articles structurés pour les sites Jekyll.","de":"Perfekt für Inhaltsgenerierungsagenten, die sich auf Software-Verifizierungs- und Validierungsthemen spezialisieren und strukturierte Artikelgenerierung für Jekyll-Seiten erfordern.","pt":"Perfeito para Agentes de Geração de Conteúdo especializados em tópicos de verificação e validação de software, que exigem geração de artigos estruturados para sites Jekyll.","ru":"Идеально подходит для агентов по созданию контента, специализирующихся на темах верификации и валидации программного обеспечения, требующих структурированного создания статей для сайтов Jekyll.","ar":"مثالي لوكلاء إنتاج المحتوى المتخصصين في مواضيع التحقق والتحقق من البرمجيات ، التي تتطلب إنشاء مقالات منظمات للمواقع Jekyll."},"recommendation":{"en":"Empowers agents to generate publication-quality articles and blog posts following jekyll-TeXt-theme conventions, utilizing proper article layout, front matter, and maintaining an academic and professional tone, all while covering software verification and validation topics.","zh":"赋予代理生成符合jekyll-TeXt-theme约定的出版物级别的文章和博客帖子，利用适当的文章布局、前置内容，并保持学术性和专业的语气，同时涵盖软件验证和验证主题。","ja":"jekyll-TeXt-themeの規約に従った出版物レベルの記事やブログ投稿を生成できるようにエージェントをEmpowerします。適切な記事レイアウト、フロントマターを使用し、学術的かつプロフェッショナルな口調を維持しながら、ソフトウェアの検証とバリデーションのトピックをカバーします。","ko":"에이전트가 jekyll-TeXt-theme 규약을 따르는 출판물 수준의 기사와 블로그 게시물을 생성하도록 함으로써, 적절한 기사 레이아웃, 프론트 매터를 사용하고, 학술적이고 전문적인语气를 유지하면서 소프트웨어 검증 및 유효성 검사 주제를 다룹니다.","es":"Habilita a los agentes a generar artículos y publicaciones de calidad de publicación que siguen las convenciones del tema jekyll-TeXt, utilizando un diseño de artículo adecuado, front matter y manteniendo un tono académico y profesional, todo mientras cubre temas de verificación y validación de software.","fr":"Permet aux agents de générer des articles et des billets de blog de qualité de publication qui suivent les conventions du thème jekyll-TeXt, en utilisant une mise en page d''article appropriée, front matter et en maintenant un ton académique et professionnel, le tout en couvrant les sujets de vérification et de validation de logiciels.","de":"Ermöglicht es Agenten, publikationsreife Artikel und Blog-Beiträge zu erstellen, die den Konventionen des jekyll-TeXt-Themas folgen, unter Verwendung einer geeigneten Artikelstruktur, Front Matter und unter Beibehaltung eines akademischen und professionellen Tons, während sie Themen der Software-Verifizierung und -Validierung abdecken.","pt":"Habilita os agentes a gerar artigos e postagens de blog de qualidade de publicação, seguindo as convenções do jekyll-TeXt-theme, utilizando o layout de artigo adequado, front matter e mantendo um tom acadêmico e profissional, tudo isso abordando tópicos de verificação e validação de software.","ru":"Наделяет агентов возможностью создавать публикации класса статьи и блог-постов, следующих соглашениям jekyll-TeXt-theme, используя правильный макет статьи, front matter и поддерживая академический и профессиональный тон, все это охватывая темы верификации и валидации программного обеспечения.","ar":"يتمكن الوكلاء من إنتاج مقالات ومنشورات مدونة من الدرجة الأولى والنشر ، اتباعاً لاتفاقيات jekyll-TeXt-theme ، واستخدام تخطيط المقال المناسب و front matter والحفاظ على نبرة أكاديمية ومهنية ، كل ذلك يشمل مواضيع التحقق والتحقق من البرمجيات."},"useCases":{"en":["Generating well-structured articles for Jekyll sites","Creating publication-ready blog posts on software verification topics","Automating content creation for jekyll-TeXt-theme sites with a focus on validation topics"],"zh":["为Jekyll站点生成结构化的文章","创建关于软件验证主题的出版就绪博客帖子","自动为jekyll-TeXt-theme站点创建内容，重点关注验证主题"],"ja":["Jekyllサイト向けの構造化された記事を生成する","ソフトウェアの検証に関するトピックの出版就緒のブログ投稿を作成する","jekyll-TeXt-themeサイト向けのコンテンツを自動生成し、バリデーションのトピックに重点を置く"],"ko":["Jekyll 사이트를 위한 구조화된 기사를 생성한다","소프트웨어 검증 주제에 대한 출판 준비 블로그 게시물을 생성한다","jekyll-TeXt-theme 사이트를 위한 콘텐츠를 자동 생성하며, 유효성 검사 주제에 중점을 둔다"],"es":["Generar artículos bien estructurados para sitios Jekyll","Crear publicaciones de blog listas para su publicación sobre temas de verificación de software","Automatizar la creación de contenido para sitios con el tema jekyll-TeXt con enfoque en temas de validación"],"fr":["Générer des articles bien structurés pour les sites Jekyll","Créer des billets de blog prêts pour la publication sur les sujets de vérification de logiciels","Automatiser la création de contenu pour les sites avec le thème jekyll-TeXt avec un focus sur les sujets de validation"],"de":["Erstellen von gut strukturierten Artikeln für Jekyll-Seiten","Erstellen von publikationsreifen Blog-Beiträgen zu Software-Verifizierungsthemen","Automatisieren der Inhaltsersstellung für Seiten mit dem jekyll-TeXt-Theme mit Fokus auf Validierungsthemen"],"pt":["Gerar artigos bem estruturados para sites Jekyll","Criar postagens de blog prontas para publicação sobre tópicos de verificação de software","Automatizar a criação de conteúdo para sites jekyll-TeXt-theme com foco em tópicos de validação"],"ru":["Генерировать хорошо структурированные статьи для сайтов Jekyll","Создавать публикационные блог-посты по темам верификации программного обеспечения","Автоматизировать создание контента для сайтов jekyll-TeXt-theme с фокусом на темах валидации"],"ar":["إنشاء مقالات منظمات جيدة للمواقع Jekyll","إنشاء منشورات مدونة جاهزة للنشر حول مواضيع التحقق من البرمجيات","ت自動 إنتاج المحتوى للمواقع jekyll-TeXt-theme مع التركيز على مواضيع التحقق"]},"limitations":{"en":["Specific to jekyll-TeXt-theme Jekyll sites","Limited to software verification and validation topics","Requires understanding of Jekyll site structure and conventions"],"zh":["仅适用于jekyll-TeXt-theme Jekyll站点","仅限于软件验证和验证主题","需要了解Jekyll站点结构和约定"],"ja":["jekyll-TeXt-theme Jekyllサイトのみに特化している","ソフトウェアの検証とバリデーションのトピックに限定されている","Jekyllサイトの構造と規約の理解が必要"],"ko":["jekyll-TeXt-theme Jekyll 사이트에만 특화되어 있음","소프트웨어 검증 및 유효성 검사 주제에만 국한됨","Jekyll 사이트 구조 및 규약에 대한 이해가 필요"],"es":["Específico para sitios Jekyll con el tema jekyll-TeXt","Limitado a temas de verificación y validación de software","Requiere comprensión de la estructura y convenciones de los sitios Jekyll"],"fr":["Spécifique aux sites Jekyll avec le thème jekyll-TeXt","Limité aux sujets de vérification et de validation de logiciels","Nécessite une compréhension de la structure et des conventions des sites Jekyll"],"de":["Spezifisch für Jekyll-Seiten mit dem jekyll-TeXt-Theme","Begrenzt auf Software-Verifizierungs- und Validierungsthemen","Erfordert Verständnis der Struktur und Konventionen von Jekyll-Seiten"],"pt":["Específico para sites Jekyll com jekyll-TeXt-theme","Limitado a tópicos de verificação e validação de software","Exige compreensão da estrutura e convenções do site Jekyll"],"ru":["Специфичен для сайтов Jekyll с jekyll-TeXt-theme","Ограничен темами верификации и валидации программного обеспечения","Требует понимания структуры и соглашений сайта Jekyll"],"ar":["محدد للمواقع Jekyll مع jekyll-TeXt-theme","محدود بمواضيع التحقق والتحقق من البرمجيات","يتطلب فهم هيكل واتفاقيات موقع Jekyll"]},"version":4},"contentHash":"59d90039228e4528e23f48d7a57e59de09cb9184dad442bab5cb7e583f5caf1e","qualityScore":54}');
