INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sweeden-ttu/spring-2026/jekyll-article-generator', 'jekyll-article-generator', 'sweeden-ttu', 'spring-2026', 'community', 'jekyll-article-generator sweeden-ttu spring-2026 community The jekyll-article-generator skill creates publication-quality articles and blog posts for Jekyll sites, specializing in software verification and validation topics. It benefits developers and writers seeking to generate well-structured content. Jekyll 文章生成器是一种专门的 AI 工具，用于生成符合 Jekyll-TeXt 主题约定和最佳实践的高质量文章和博客帖子 Jekyll 記事生成ツールは、Jekyll-TeXt テーマの規約とベストプラクティスに従った、高品質な記事とブログ投稿を生成するための専門の AI エージェントです Jekyll 文章 생성기는 Jekyll-TeXt 테ーマ의 규약과 최고의 관행에 따라 높은 품질의 文章과 블로그 게시물을 생성하기 위한 전문 AI 에이전트입니다 jekyll-article-generator es un agente especializado en generar artículos de publicación para sitios Jekyll con temas de verificación y validación de software jekyll-article-generator est un agent spécialisé dans la génération d''articles de publication pour les sites Jekyll sur les thèmes de vérification et de validation de logiciels jekyll-article-generator ist ein Spezialagent für die Erstellung von Publikationsartikeln für Jekyll-Websites mit Themen zu Software-Verifizierung und -Validierung O jekyll-article-generator é um agente especializado em criar artigos de qualidade publicável sobre verificação e validação de software. jekyll-article-generator - это агент, специализирующийся на создании публикаций о верификации и валидации программного обеспечения. jekyll-article-generator هو وكيل متخصص في إنشاء مقالات منشورة عالية الجودة حول التحقق والتحقق من صحة البرامج. how to use jekyll-article-generator jekyll-article-generator setup guide jekyll-article-generator alternative jekyll-article-generator vs other generators what is jekyll-article-generator jekyll-article-generator install jekyll-TeXt-theme article generation software verification and validation tools publication-quality article generation Jekyll 文章生成器 软件验证 加密 AI 工具 Jekyll-TeXt 主题 文章生成 博客帖子 高质量内容 Generates well-structured articles following jekyll-TeXt-theme conventions Creates publication-ready blog posts with proper article layout and front matter Maintains academic and professional tone in generated content Covers software verification and validation topics with deep expertise Uses proper Markdown formatting for readability and compatibility jekyll-article-generator is a specialized AI agent skill for generating publication-quality articles and blog posts for Jekyll sites, focusing on software verification and validation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Edgame2/castiel2/create-event-handlers', 'community', 'Edgame2', 'castiel2', 'Edgame2/castiel2', 'create-event-handlers', 0, 0, 54, '2026-03-08T01:57:15.477Z', '2026-03-08T02:09:50.221Z', '7c9e736ba71dc0c7880d2a372579f7a0a870a57a5344dba5a76dd649dbe38360', '{"id":"Edgame2/castiel2/create-event-handlers","name":"create-event-handlers","description":{"en":"The create-event-handlers skill sets up RabbitMQ event publishers and consumers, following the ModuleImplementationGuide.md Section 9. It benefits developers working with tenant-only context and event-driven architectures.","zh":"创建事件处理程序以设置RabbitMQ事件发布者和消费者，遵循ModuleImplementationGuide.md第9节","ja":"イベントハンドラーを作成してRabbitMQイベントパブリッシャーとコンシューマーを設定します。ModuleImplementationGuide.mdの第9節に従います","ko":"이벤트 핸들러를 생성하여 RabbitMQ 이벤트 발행자 및 소비자를 설정합니다. ModuleImplementationGuide.md의 9절을 따릅니다","es":"El skill ''create-event-handlers'' configura editores y consumidores de eventos de RabbitMQ. Sigue la guía de implementación de módulos para crear eventos con nombre de dominio, entidad y acción","fr":"Le skill ''create-event-handlers'' configure les éditeurs et les consommateurs d''événements de RabbitMQ. Suivez le guide d''implémentation de modules pour créer des événements avec un nom de domaine, d''entité et d''action","de":"Das Skill ''create-event-handlers'' konfiguriert RabbitMQ-Ereignisveröffentlicher und -verbraucher. Befolgen Sie den Leitfaden für die Modulimplementierung, um Ereignisse mit Domänen-, Entitäts- und Aktionennamen zu erstellen","pt":"Criar tratadores de eventos com RabbitMQ para publicação e consumo de eventos","ru":"Настройка обработчиков событий с RabbitMQ для публикации и потребления событий","ar":"إنشاء معالجات الأحداث باستخدام RabbitMQ لنشر واستهلاك الأحداث"},"seo":{"title":{"en":"create-event-handlers: Setup Guide for RabbitMQ Event Pub...","zh":"创建事件处理程序设置指南 - AIエージェント","ja":"イベントハンドラーの作成 - AIエージェントベストプラクティス","ko":"이벤트 핸들러 생성 설정 가이드 - AI 도구","es":"Crear Controladores de Eventos: Guía de Configuración de ...","fr":"Créer des Gestionnaires d''Événements: Guide de Configurat...","de":"Erstellen von Ereignishandlern: Konfigurationsleitfaden f...","pt":"Guia de Configuração de Tratadores de Eventos com RabbitMQ","ru":"ИИ Агенты: Настройка Обработчиков Событий с RabbitMQ","ar":"إعداد معالجات الأحداث باستخدام RabbitMQ"},"description":{"en":"Discover how to set up RabbitMQ event publishers and consumers with create-event-handlers. Learn the best practices for event naming conventions and tenant-o...","zh":"了解如何使用AIエージェント创建事件处理程序，包括RabbitMQ事件发布者和消费者设置","ja":"AIエージェントを使用してイベントハンドラーを作成する方法を学び、RabbitMQイベントパブリッシャーとコンシューマーの設定を理解する","ko":"AI 도구를 사용하여 이벤트 핸들러를 생성하는 방법에 대해 알아보고 RabbitMQ 이벤트 발행자 및 소비자 설정에 대해 자세히 알아보세요","es":"Aprende a crear controladores de eventos con RabbitMQ y sigue las mejores prácticas para la implementación de eventos en tu aplicación","fr":"Découvrez comment créer des gestionnaires d''événements avec RabbitMQ et suivez les meilleures pratiques pour la mise en œuvre d''événements dans votre applica...","de":"Erfahren Sie, wie Sie Ereignishandler mit RabbitMQ erstellen und folgen Sie den bewährten Methoden für die Implementierung von Ereignissen in Ihrer Anwendung","pt":"Aprenda a criar tratadores de eventos com RabbitMQ seguindo o guia de implementação de módulos","ru":"Настройте обработчики событий с RabbitMQ, следуя руководству по реализации модулей","ar":"تعلم كيفية إنشاء معالجات الأحداث باستخدام RabbitMQ باتباع دليل تنفيذ الوحدات"},"definition":{"en":"create-event-handlers is a skill that sets up RabbitMQ event publishers and consumers, following a specific event naming convention and tenant-only context.","zh":"创建事件处理程序是指设置RabbitMQ事件发布者和消费者以处理特定事件","ja":"イベントハンドラーの作成は、特定のイベントを処理するためにRabbitMQイベントパブリッシャーとコンシューマーを設定することを指します","ko":"이벤트 핸들러 생성은 특정 이벤트를 처리하기 위해 RabbitMQ 이벤트 발행자 및 소비자를 설정하는 것을 의미합니다","es":"Un controlador de eventos es un componente que gestiona la publicación y el consumo de eventos en una aplicación, utilizando un formato de nombre de dominio, entidad y acción","fr":"Un gestionnaire d''événements est un composant qui gère la publication et la consommation d''événements dans une application, en utilisant un format de nom de domaine, d''entité et d''action","de":"Ein Ereignishandler ist ein Komponente, der die Veröffentlichung und den Verbrauch von Ereignissen in einer Anwendung verwaltet, unter Verwendung eines Formats mit Domänen-, Entitäts- und Aktionennamen","pt":"Tratadores de eventos são funções que lidam com eventos publicados por aplicativos","ru":"Обработчики событий - это функции, которые обрабатывают события, опубликованные приложениями","ar":"معالجات الأحداث هي دوال تتعامل مع الأحداث المنشورة بواسطة التطبيقات"},"features":{"en":["Sets up RabbitMQ event publishers and consumers following ModuleImplementationGuide.md Section 9","Follows a specific event naming convention: {domain}.{entity}.{action}","Supports tenant-only context using tenantId","Excludes organizationId from event payloads and createBaseEvent","Adheres to guidelines outlined in ModuleImplementationGuide.md Section 9.1","Generates events in the format of user.created, auth.login.success, and notification.email.sent"],"zh":["设置RabbitMQ事件发布者和消费者","遵循ModuleImplementationGuide.md第9节","使用tenantId作为事件上下文","事件命名约定：{domain}.{entity}.{action}","支持正确的事件命名格式，例如user.created、auth.login.success","不包括organizationId在事件有效载荷或createBaseEvent中"],"ja":["RabbitMQイベントパブリッシャーとコンシューマーの設定","ModuleImplementationGuide.mdの第9節に従う","tenantIdをイベントコンテキストとして使用","イベント命名規則：{domain}.{entity}.{action}","正しいイベント命名形式をサポートします。例：user.created、auth.login.success","イベントペイロードまたはcreateBaseEventにorganizationIdを含めない"],"ko":["RabbitMQ 이벤트 발행자 및 소비자 설정","ModuleImplementationGuide.md의 9절을 따름","tenantId를 이벤트 컨텍스트로 사용","이벤트 명명 규칙：{domain}.{entity}.{action}","정확한 이벤트 명명 형식을 지원합니다. 예：user.created、auth.login.success","이벤트 페이로드 또는 createBaseEvent에 organizationId를 포함하지 않음"],"es":["Configuración de editores y consumidores de eventos de RabbitMQ","Seguimiento de la guía de implementación de módulos para crear eventos","Uso de un formato de nombre de dominio, entidad y acción para los eventos","Compatibilidad con eventos de tenant-only con tenantId","No incluye organizationId en las cargas de eventos o en createBaseEvent"],"fr":["Configuration des éditeurs et des consommateurs d''événements de RabbitMQ","Suivi du guide d''implémentation de modules pour créer des événements","Utilisation d''un format de nom de domaine, d''entité et d''action pour les événements","Compatibilité avec les événements de tenant-only avec tenantId","N''inclut pas organizationId dans les charges d''événements ou dans createBaseEvent"],"de":["Konfiguration von RabbitMQ-Ereignisveröffentlichrn und -verbrauchern","Befolgen des Leitfadens für die Modulimplementierung, um Ereignisse zu erstellen","Verwendung eines Formats mit Domänen-, Entitäts- und Aktionennamen für Ereignisse","Kompatibilität mit Ereignissen von tenant-only mit tenantId","Enthält keine organizationId in den Ereignisladungen oder in createBaseEvent"],"pt":["Utiliza RabbitMQ para publicação e consumo de eventos","Segue o guia de implementação de módulos para eventos","Utiliza a convenção de nomenclatura de eventos {domínio}.{entidade}.{ação}","Suporta eventos com contexto de tenant","Não inclui organizationId em payloads de eventos","Utiliza tenantId para contexto de tenant"],"ru":["Использует RabbitMQ для публикации и потребления событий","Следует руководству по реализации модулей для событий","Использует конвенцию именования событий {домен}.{сущность}.{действие}","Поддерживает события с контекстом арендатора","Не включает organizationId в荷ады событий","Использует tenantId для контекста арендатора"],"ar":["يستخدم RabbitMQ لنشر واستهلاك الأحداث","يتباع دليل تنفيذ الوحدات للأحداث","يستخدم اتفاقية تسمية الأحداث {النطاق}.{الكيان}.{الإجراء}","يدعم الأحداث مع سياق المستأجر","لا يรวม organizationId في حمولات الأحداث","يستخدم tenantId لسياق المستأجر"]},"keywords":{"en":["how to use create-event-handlers","create-event-handlers setup guide","RabbitMQ event publishers","tenant-only context","event naming convention","create-event-handlers vs RabbitMQ","create-event-handlers install","what is create-event-handlers","create-event-handlers alternative","event-driven architecture with create-event-handlers"],"zh":["AIエージェント","创建事件处理程序","RabbitMQ事件发布者","RabbitMQ事件消费者","事件命名约定","tenantId","ModuleImplementationGuide.md","事件处理程序设置","AI工具"],"ja":["AIエージェント","イベントハンドラーの作成","RabbitMQイベントパブリッシャー","RabbitMQイベントコンシューマー","イベント命名規則","tenantId","ModuleImplementationGuide.md","イベントハンドラーの設定","イベント処理"],"ko":["AI 도구","이벤트 핸들러 생성","RabbitMQ 이벤트 발행자","RabbitMQ 이벤트 소비자","이벤트 명명 규칙","tenantId","ModuleImplementationGuide.md","이벤트 핸들러 설정","이벤트 처리"],"es":["controladores de eventos","RabbitMQ","guía de implementación de módulos","eventos de tenant-only","tenantId","createBaseEvent","Herramientas de IA para desarrolladores","agentes de IA"],"fr":["gestionnaires d''événements","RabbitMQ","guide d''implémentation de modules","événements de tenant-only","tenantId","createBaseEvent","Outils d''IA pour les développeurs","agents d''IA"],"de":["Ereignishandler","RabbitMQ","Leitfaden für die Modulimplementierung","Ereignisse von tenant-only","tenantId","createBaseEvent","KI-Tools für Entwickler","KI-Agenten"],"pt":["tratadores de eventos","RabbitMQ","guia de implementação de módulos","convenção de nomenclatura de eventos","contexto de tenant","tenantId","organizationId","publicação de eventos","consumo de eventos"],"ru":["обработчики событий","RabbitMQ","руководство по реализации модулей","конвенция именования событий","контекст арендатора","tenantId","organizationId","публикация событий","потребление событий"],"ar":["معالجات الأحداث","RabbitMQ","دليل تنفيذ الوحدات","اتفاقية تسمية الأحداث","سياق المستأجر","tenantId","organizationId","نشر الأحداث","استهلاك الأحداث"]}},"owner":"Edgame2","repo":"castiel2","repoPath":"Edgame2/castiel2","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.477Z","topics":[],"category":"community","skillMd":{"name":"create-event-handlers","description":"Sets up RabbitMQ event publishers and consumers following ModuleImplementationGuide.md Section 9. RabbitMQ only (no Azure Service Bus). Creates publishers with DomainEvent (tenantId only; no organizationId), consumers with handlers, naming {domain}.{entity}.{action}, required fields (id, type, version, timestamp, tenantId, source, data). Use when adding event-driven communication, async workflows, or integrating via events.","bodyPreview":"# Create Event Handlers\n\nSets up RabbitMQ event publishers and consumers following ModuleImplementationGuide.md Section 9.\n\n**Tenant-only:** Events use `tenantId` only for tenant context. Do not include `organizationId` in event payloads or in `createBaseEvent`; use `tenantId` only.\n\n## Event Naming Convention\n\nReference: ModuleImplementationGuide.md Section 9.1\n\nFormat: `{domain}.{entity}.{action}`\n\n✅ **Correct:**\n- `user.created`\n- `auth.login.success`\n- `notification.email.sent`\n- `secret.rot","body":"# Create Event Handlers\n\nSets up RabbitMQ event publishers and consumers following ModuleImplementationGuide.md Section 9.\n\n**Tenant-only:** Events use `tenantId` only for tenant context. Do not include `organizationId` in event payloads or in `createBaseEvent`; use `tenantId` only.\n\n## Event Naming Convention\n\nReference: ModuleImplementationGuide.md Section 9.1\n\nFormat: `{domain}.{entity}.{action}`\n\n✅ **Correct:**\n- `user.created`\n- `auth.login.success`\n- `notification.email.sent`\n- `secret.rotated`\n\n❌ **Wrong:**\n- `userCreated`\n- `loginSuccess`\n- `emailSent`\n\n**Standard Actions:**\n- `created`, `updated`, `deleted`\n- `started`, `completed`, `failed`\n- `sent`, `received`, `expired`, `rotated`\n\n## Event Structure\n\nReference: ModuleImplementationGuide.md Section 9.2\n\n```typescript\ninterface DomainEvent<T = unknown> {\n  // Identity\n  id: string;                    // Unique event ID (UUID)\n  type: string;                  // Event type (domain.entity.action)\n  \n  // Metadata\n  timestamp: string;             // ISO 8601\n  version: string;               // Event schema version\n  source: string;                // Module that emitted\n  correlationId?: string;        // Request correlation\n  \n  // Context\n  tenantId: string;             // Tenant context (required; all users and data are scoped by tenant)\n  userId?: string;               // Actor\n  \n  // Payload\n  data: T;                       // Event-specific data\n}\n```\n\n## Event Publisher\n\nReference: containers/auth/src/events/publishers/AuthEventPublisher.ts\n\n### src/events/publishers/[Module]EventPublisher.ts\n\n```typescript\nimport { randomUUID } from ''crypto'';\nimport { EventPublisher, getChannel, closeConnection } from ''@coder/shared'';\nimport { log } from ''../../utils/logger'';\nimport { getConfig } from ''../../config'';\n\nlet publisher: EventPublisher | null = null;\n\nexport async function initializeEventPublisher(): Promise<void> {\n  if (publisher) return;\n  \n  const config = getConfig();\n  if (!config.rabbitmq?.url) {\n    log.warn(''RabbitMQ URL not configured, events will not be published'');\n    return;\n  }\n  \n  try {\n    await getChannel();\n    publisher = new EventPublisher(config.rabbitmq.exchange || ''coder_events'');\n    log.info(''Event publisher initialized'', { exchange: config.rabbitmq.exchange });\n  } catch (error: any) {\n    log.error(''Failed to initialize event publisher'', error);\n  }\n}\n\nexport async function closeEventPublisher(): Promise<void> {\n  try {\n    await closeConnection();\n    publisher = null;\n  } catch (error: any) {\n    log.error(''Error closing event publisher'', error);\n  }\n}\n\nfunction getPublisher(): EventPublisher | null {\n  if (!publisher) {\n    const config = getConfig();\n    publisher = new EventPublisher(config.rabbitmq.exchange || ''coder_events'');\n  }\n  return publisher;\n}\n\nexport function createBaseEvent(\n  type: string,\n  userId?: string,\n  tenantId?: string,\n  correlationId?: string,\n  data?: any\n) {\n  return {\n    id: randomUUID(),\n    type,\n    timestamp: new Date().toISOString(),\n    version: ''1.0'',\n    source: ''[module-name]'',\n    correlationId,\n    tenantId,\n    userId,\n    data: data || {},\n  };\n}\n\nexport async function publishEvent(event: any, routingKey?: string): Promise<void> {\n  const pub = getPublisher();\n  if (!pub) {\n    log.warn(''Event publisher not initialized, skipping event'', { type: event.type });\n    return;\n  }\n  \n  try {\n    await pub.publish(routingKey || event.type, event);\n    log.debug(''Event published'', { type: event.type, id: event.id });\n  } catch (error: any) {\n    log.error(''Failed to publish event'', error, { type: event.type });\n  }\n}\n```\n\n### Usage in Services\n\n```typescript\nimport { publishEvent, createBaseEvent } from ''../events/publishers/ModuleEventPublisher'';\n\n// Publish event (tenantId for tenant context)\nconst event = createBaseEvent(\n  ''resource.created'',\n  userId,\n  tenantId,\n  correlationId,\n  {\n    resourceId: resource.id,\n    name: resource.name,\n  }\n);\n\nawait publishEvent(event);\n```\n\n## Event Consumer\n\nReference: ModuleImplementationGuide.md Section 9.4\n\n### src/events/consumers/[Resource]Consumer.ts\n\n```typescript\nimport { EventConsumer } from ''@coder/shared'';\nimport { log } from ''../../utils/logger'';\nimport { getConfig } from ''../../config'';\n\nlet consumer: EventConsumer | null = null;\n\nexport async function initializeEventConsumer(): Promise<void> {\n  if (consumer) return;\n  \n  const config = getConfig();\n  if (!config.rabbitmq?.url) {\n    log.warn(''RabbitMQ URL not configured, events will not be consumed'');\n    return;\n  }\n  \n  try {\n    consumer = new EventConsumer({\n      queue: config.rabbitmq.queue || ''[module-name]_service'',\n      exchange: config.rabbitmq.exchange || ''coder_events'',\n      bindings: config.rabbitmq.bindings || [],\n    });\n    \n    // Register handlers\n    consumer.on(''other.resource.created'', handleResourceCreated);\n    consumer.on(''other.resource.updated'', handleResourceUpdated);\n    \n    await consumer.start();\n    log.info(''Event consumer initialized'', { queue: config.rabbitmq.queue });\n  } catch (error: any) {\n    log.error(''Failed to initialize event consumer'', error);\n  }\n}\n\nasync function handleResourceCreated(event: any): Promise<void> {\n  log.info(''Resource created event received'', { resourceId: event.data.resourceId });\n  // Handle the event\n}\n\nasync function handleResourceUpdated(event: any): Promise<void> {\n  log.info(''Resource updated event received'', { resourceId: event.data.resourceId });\n  // Handle the event\n}\n\nexport async function closeEventConsumer(): Promise<void> {\n  try {\n    if (consumer) {\n      await consumer.stop();\n      consumer = null;\n    }\n  } catch (error: any) {\n    log.error(''Error closing event consumer'', error);\n  }\n}\n```\n\n## Event Documentation\n\nReference: ModuleImplementationGuide.md Section 9.5\n\n### logs-events.md (if events are logged)\n\nCreate in module root if module publishes events that get logged:\n\n```markdown\n# [Module Name] - Logs Events\n\n## Published Events\n\n### {domain}.{entity}.{action}\n\n**Description**: When this event is triggered.\n\n**Triggered When**: \n- Condition 1\n- Condition 2\n\n**Event Type**: `{domain}.{entity}.{action}`\n\n**Event Schema**:\n\n\\`\\`\\`json\n{\n  \"$schema\": \"http://json-schema.org/draft-07/schema#\",\n  \"type\": \"object\",\n  \"required\": [\"id\", \"type\", \"timestamp\", \"version\", \"source\", \"data\"],\n  \"properties\": {\n    \"id\": { \"type\": \"string\", \"format\": \"uuid\" },\n    \"type\": { \"type\": \"string\" },\n    \"timestamp\": { \"type\": \"string\", \"format\": \"date-time\" },\n    \"version\": { \"type\": \"string\" },\n    \"source\": { \"type\": \"string\" },\n    \"tenantId\": { \"type\": \"string\", \"format\": \"uuid\" },\n    \"userId\": { \"type\": \"string\", \"format\": \"uuid\" },\n    \"data\": {\n      \"type\": \"object\",\n      \"properties\": {\n        \"resourceId\": { \"type\": \"string\" }\n      }\n    }\n  }\n}\n\\`\\`\\`\n```\n\n### notifications-events.md (if events trigger notifications)\n\nCreate in module root if module publishes events that trigger notifications.\n\n## Configuration\n\nAdd to config/default.yaml:\n\n```yaml\nrabbitmq:\n  url: ${RABBITMQ_URL}\n  exchange: coder_events\n  queue: [module-name]_service\n  bindings:\n    - \"other.resource.created\"\n    - \"other.resource.updated\"\n```\n\n## Checklist\n\n- [ ] Event publisher created following pattern\n- [ ] Event consumer created (if consuming events)\n- [ ] Events follow naming convention: {domain}.{entity}.{action}\n- [ ] Events include all required fields (id, type, version, timestamp, source, data)\n- [ ] Events include tenantId when applicable (tenantId only; no organizationId in events)\n- [ ] RabbitMQ only; no Azure Service Bus\n- [ ] logs-events.md created (if events are logged)\n- [ ] notifications-events.md created (if events trigger notifications)\n- [ ] RabbitMQ config added to default.yaml\n"},"lastSynced":"2026-03-08T02:09:50.221Z","agentAnalysis":{"suitability":{"en":"Perfect for Event-Driven Architecture Agents needing RabbitMQ event publishers and consumers integration.","zh":"非常适合需要RabbitMQ事件发布者和消费者集成的事件驱动架构代理。","ja":"RabbitMQイベントパブリッシャーとコンシューマーの統合が必要なイベント駆動型アーキテクチャエージェントに最適。","ko":"RabbitMQ 이벤트 게시자와 소비자가 필요로 하는 이벤트 주도형 아키텍처 에이전트에게 적합합니다.","es":"Perfecto para agentes de Arquitectura Orientada a Eventos que necesitan integración de publicadores y consumidores de eventos de RabbitMQ.","fr":"Parfait pour les agents d''Architecture Orientée aux Événements nécessitant une intégration de publieurs et de consommateurs d''événements RabbitMQ.","de":"Perfekt für Event-Driven Architecture Agents, die eine RabbitMQ-Ereignis-Verleger- und -Abonnenten-Integration benötigen.","pt":"Perfeito para Agentes de Arquitetura Orientada a Eventos que necessitam de integração de publicadores e consumidores de eventos RabbitMQ.","ru":"Идеально подходит для агентов, ориентированных на события, требующих интеграции с RabbitMQ для публикации и потребления событий.","ar":"مثالي لعميل الوكيل الموجه بالأحداث الذي يحتاج إلى دمج الناشرين ومستهلكي الأحداث RabbitMQ."},"recommendation":{"en":"Empowers agents to handle events with tenant-only context using RabbitMQ, following the ModuleImplementationGuide.md Section 9, and adhering to a strict event naming convention format: {domain}.{entity}.{action}, enabling seamless interaction with event-driven systems via RabbitMQ event publishers and consumers.","zh":"赋予代理使用RabbitMQ处理具有租户唯一上下文的事件的能力，遵循ModuleImplementationGuide.md第9节，并遵循严格的事件命名约定格式：{domain}.{entity}.{action}，实现与事件驱动系统的无缝交互通过RabbitMQ事件发布者和消费者。","ja":"RabbitMQを使用して、テナント専用のコンテキストを持つイベントを処理するエージェントを可能にします。ModuleImplementationGuide.mdのセクション9に従い、厳格なイベント命名規則フォーマット：{domain}.{entity}.{action}に従うことで、RabbitMQイベントパブリッシャーとコンシューマーを介してイベント駆動型システムとのシームレスな相互作用を実現します。","ko":"RabbitMQ를 사용하여 테넌트 전용 컨텍스트를 갖는 이벤트를 처리할 수 있는 에이전트를 가능하게 합니다. ModuleImplementationGuide.md의 섹션 9를 따르고 엄격한 이벤트 명명 규칙 형식: {domain}.{entity}.{action}을 따르므로 RabbitMQ 이벤트 게시자 및 소비자를 통해 이벤트 주도형 시스템과 원활한 상호 작용을实现합니다.","es":"Habilita a los agentes para manejar eventos con contexto solo de inquilino utilizando RabbitMQ, siguiendo la guía ModuleImplementationGuide.md Sección 9, y ajustándose a un formato de convención de nombres de eventos estricto: {dominio}.{entidad}.{acción}, lo que permite una interacción sin problemas con sistemas orientados a eventos a través de publicadores y consumidores de eventos de RabbitMQ.","fr":"Permet aux agents de gérer les événements avec un contexte spécifique au locataire en utilisant RabbitMQ, en suivant le guide ModuleImplementationGuide.md Section 9, et en respectant un format de convention de nommage d''événements strict : {domaine}.{entité}.{action}, ce qui permet une interaction transparente avec les systèmes orientés vers les événements via les publieurs et les consommateurs d''événements RabbitMQ.","de":"Ermächtigt Agenten, Ereignisse mit mandantenbezogenem Kontext unter Verwendung von RabbitMQ zu verarbeiten, indem sie der Anleitung ModuleImplementationGuide.md Abschnitt 9 folgen und einem strengen Ereignis-Namenskonventionsformat entsprechen: {domain}.{entity}.{action}, wodurch eine nahtlose Interaktion mit ereignisgesteuerten Systemen über RabbitMQ-Ereignis-Verleger und -Abonnenten ermöglicht wird.","pt":"Habilita os agentes a lidarem com eventos com contexto exclusivo do locatário usando RabbitMQ, seguindo o ModuleImplementationGuide.md Seção 9, e aderindo a um formato estrito de convenção de nomenclatura de eventos: {domain}.{entity}.{action}, permitindo interação sem problemas com sistemas orientados a eventos via publicadores e consumidores de eventos RabbitMQ.","ru":"Наделяет агентов возможностью обрабатывать события с контекстом только для арендатора, используя RabbitMQ, следуя ModuleImplementationGuide.md Раздел 9, и придерживаясь строгого формата именования событий: {domain}.{entity}.{action}, обеспечивая беспроблемное взаимодействие с системами, ориентированными на события, через публикацию и потребление событий RabbitMQ.","ar":"يمكّن الوكلاء من التعامل مع الأحداث بسياق معين للمستأجر باستخدام RabbitMQ، متبعًا إرشادات ModuleImplementationGuide.md القسم 9، والامتثال لتنسيق صارم لتسمية الأحداث: {domain}.{entity}.{action}، وتمكين التفاعل السلس مع الأنظمة الموجهة بالأحداث عبر منشورات ومستهلكي الأحداث RabbitMQ."},"useCases":{"en":["Setting up RabbitMQ event publishers for tenant-specific events","Creating event consumers for handling actions like user.created or auth.login.success","Implementing event-driven architectures with tenant-only context"],"zh":["设置RabbitMQ事件发布者以处理租户特定事件","创建事件消费者以处理诸如user.created或auth.login.success之类的操作","使用租户唯一上下文实现事件驱动架构"],"ja":["テナント固有のイベントを処理するためのRabbitMQイベントパブリッシャーの設定","user.createdまたはauth.login.successなどの操作を処理するイベントコンシューマーの作成","テナント専用のコンテキストを使用したイベント駆動型アーキテクチャの実装"],"ko":["테넌트 특정 이벤트를 처리하기 위한 RabbitMQ 이벤트 게시자의 설정","user.created 또는 auth.login.success와 같은 동작을 처리하기 위한 이벤트 소비자의 생성","테넌트 전용 컨텍스트를 사용한 이벤트 주도형 아키텍처 구현"],"es":["Configuración de publicadores de eventos de RabbitMQ para eventos específicos de inquilino","Creación de consumidores de eventos para manejar acciones como user.created o auth.login.success","Implementación de arquitecturas orientadas a eventos con contexto solo de inquilino"],"fr":["Configuration de publieurs d''événements RabbitMQ pour des événements spécifiques au locataire","Création de consommateurs d''événements pour gérer des actions comme user.created ou auth.login.success","Mise en œuvre d''architectures orientées vers les événements avec un contexte spécifique au locataire"],"de":["Einrichtung von RabbitMQ-Ereignis-Verlegern für mandantenspezifische Ereignisse","Erstellung von Ereignisabonnenten zur Verarbeitung von Aktionen wie user.created oder auth.login.success","Implementierung von ereignisgesteuerten Architekturen mit mandantenbezogenem Kontext"],"pt":["Configurando publicadores de eventos RabbitMQ para eventos específicos do locatário","Criando consumidores de eventos para lidar com ações como user.created ou auth.login.success","Implementando arquiteturas orientadas a eventos com contexto exclusivo do locatário"],"ru":["Настройка публикации событий RabbitMQ для событий, специфичных для арендатора","Создание потребителей событий для обработки действий, таких как user.created или auth.login.success","Реализация архитектур, ориентированных на события, с контекстом только для арендатора"],"ar":["تكوين منشورات الأحداث RabbitMQ للأحداث المحددة للمستأجر","إنشاء مستهلكي الأحداث لمعالجة الإجراءات مثل user.created أو auth.login.success","تنفيذ عمارة موجهة بالأحداث بسياق معين للمستأجر"]},"limitations":{"en":["Requires RabbitMQ setup and configuration","Adheres to specific event naming convention","Tenant-only context, excluding organizationId"],"zh":["需要RabbitMQ的设置和配置","遵循特定的事件命名约定","仅限租户上下文，排除organizationId"],"ja":["RabbitMQの設定と構成が必要","特定のイベント命名規則に従う","テナントコンテキストのみ、organizationIdは除く"],"ko":["RabbitMQ 설정 및 구성이 필요합니다","특정 이벤트 명명 규칙을 따름","테넌트 컨텍스트만 해당하며 organizationId는 제외합니다"],"es":["Requiere configuración y configuración de RabbitMQ","Se ajusta a una convención de nombres de eventos específica","Contexto solo de inquilino, excluyendo organizationId"],"fr":["Nécessite une configuration et une configuration de RabbitMQ","Respecte une convention de nommage d''événements spécifique","Contexte spécifique au locataire, excluant organizationId"],"de":["Erfordert RabbitMQ-Setup und -Konfiguration","Befolgt eine spezifische Ereignis-Namenskonvention","Mandantenbezogener Kontext, ausschließlich organizationId"],"pt":["Requer configuração e instalação do RabbitMQ","Adere a uma convenção de nomenclatura de eventos específica","Contexto exclusivo do locatário, excluindo organizationId"],"ru":["Требует настройки и конфигурации RabbitMQ","Придерживается определенной конвенции именования событий","Контекст только для арендатора, исключая organizationId"],"ar":["يتطلب إعدادًا وتكوينًا لبرنامج RabbitMQ","الامتثال لاتفاقية تسمية الأحداث المحددة","سياق معين للمستأجر، باستثناء organizationId"]},"version":4},"contentHash":"7c9e736ba71dc0c7880d2a372579f7a0a870a57a5344dba5a76dd649dbe38360","qualityScore":54}');
