INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kafkaspanel1/panel/frontend-developer', 'frontend-developer', 'kafkaspanel1', 'panel', 'community', 'frontend-developer kafkaspanel1 panel community The frontend-developer skill creates and manages React components, UI library, and state management for Turkish non-profit organization management systems, benefiting frontend developers and organizations alike. Frontend Developer 技能使用 React 组件、UI 库、状态管理和用户体验来构建 Next.js 16 admin 面板 フロントエンド開発者スキルは React コンポーネント、UI ライブラリ、ステート管理、ユーザーエクスペリエンスを使用して Next.js 16 管理パネルを構築 프론트엔드 개발자 기능은 React 컴포넌트, UI 라이브러리, 상태 관리 및 사용자 경험을 사용하여 Next.js 16 관리 패널을 구축 Desarrolla aplicaciones frontend con Next.js 16 y mejora la experiencia del usuario con React y Tailwind CSS Développez des applications frontend avec Next.js 16 et améliorez l''expérience utilisateur avec React et Tailwind CSS Entwickeln Sie Frontend-Anwendungen mit Next.js 16 und verbessern Sie die Benutzererfahrung mit React und Tailwind CSS O frontend developer cria componentes React, gerencia estado com Zustand e implementa formulários com React Hook Form + Zod Frontend разработчик создает компоненты React, управляет состоянием с Zustand и реализует формы с React Hook Form + Zod для ИИ Агентов مطور الواجهة الأمامية يُنشئ مكونات React ويدر状态 Zustand وينفذ استمارات مع React Hook Form + Zod لأدوات الذكاء الاصطناعي how to use frontend-developer frontend-developer alternative frontend-developer setup guide what is frontend-developer frontend-developer vs React frontend-developer install Next.js 16 admin panel tutorial React component development Zustand state management AIエージェント Frontend Developer React Next.js 状态管理 用户体验 UI 库 TanStack Query Tailwind CSS Generates React components with Zustand state management Implements form handling using React Hook Form and Zod Enables data fetching with TanStack Query Creates responsive designs using Tailwind CSS Develops PWA features for enhanced user experience Handles loading states and skeleton screens for seamless interaction Frontend-developer is a skill that develops and optimizes React components, UI library, state management, and user experience for efficient frontend development.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('guillem-aistech/satellite-orbit-simulator/write-commits', 'community', 'guillem-aistech', 'satellite-orbit-simulator', 'guillem-aistech/satellite-orbit-simulator', 'write-commits', 0, 0, 54, '2026-03-08T01:57:15.484Z', '2026-03-08T02:10:02.540Z', '5299da044289967d22d527fdb50fd0b1dc4355267e776072b061effc15a2bcad', '{"id":"guillem-aistech/satellite-orbit-simulator/write-commits","name":"write-commits","description":{"en":"write-commits generates commit messages following repository conventions, helping developers maintain consistent and descriptive commit histories. It benefits developers and teams working with Git.","zh":"Write Commits 是一个帮助开发者生成符合仓库规范的 Git 提交消息的工具，通过分析暂存的变化和编写有意义的提交消息","ja":"Write Commits は、開発者がリポジトリの規約に従った Git コミットメッセージを生成するのに役立つツールです。ステージングされた変更を分析し、意味のあるコミットメッセージを書きます","ko":"Write Commits는 개발자가 리포지토리 규칙에 따라 Git 커밋 메시지를 생성하도록 도와주는 도구로, 暫定 변경 사항을 분석하고 의미 있는 커밋 메시지를 작성합니다","es":"Write-commits es una herramienta para generar mensajes de commit siguiendo las convenciones del repositorio","fr":"Write-commits est un outil pour créer des messages de commit conformes aux conventions du référentiel","de":"Write-commits ist ein Tool zum Erstellen von Commit-Nachrichten, die den Repository-Konventionen entsprechen","pt":"O Write Commits é uma ferramenta que ajuda a gerar mensagens de commit personalizadas e a melhorar o controle de versão do seu repositório Git.","ru":"Write Commits — это инструмент, который помогает генерировать индивидуальные сообщения коммитов и улучшать контроль версий в вашем репозитории Git.","ar":"Write Commits هو أداة تساعد في إنشاء رسائل Commit مخصصة وتحسين التحكم في الإصدارات لمخزن Git الخاص بك."},"seo":{"title":{"en":"write-commits: Git Commit Message Generation Guide | AI A...","zh":"Write Commits 设置指南：Git 提交消息最佳实践","ja":"Write Commits 導入ガイド：Git コミットメッセージのベストプラクティス","ko":"Write Commits 설정 가이드: Git 커밋 메시지 모범 사례","es":"Guía de configuración de write-commits para mensajes de c...","fr":"Configurer write-commits pour des messages de commit effi...","de":"Write-commits Einrichtungsleitfaden für optimale Commit-N...","pt":"Guia de Configuração do Write Commits para Controle de Ve...","ru":"Настройка Write Commits для контроля версий: ИИ Агенты","ar":"دليل إعداد Write Commits للتحكم في الإصدارات باستخدام أدو..."},"description":{"en":"Master Git commit message writing with write-commits. Learn how to generate perfect commit messages with ease and consistency. Get started now!","zh":"学习如何使用 Write Commits 生成符合仓库规范的 Git 提交消息，提高代码质量和团队合作效率","ja":"Write Commits を使用して、リポジトリの規約に従った Git コミットメッセージを生成し、コード品質とチームコラボレーションの効率を向上させます","ko":"Write Commits를 사용하여 리포지토리 규칙에 따라 Git 커밋 메시지를 생성하고 코드 품질 및 팀 협업 효율을 개선하는 방법을 알아보세요","es":"Aprende a utilizar write-commits para generar mensajes de commit coherentes y bien estructurados en tu repositorio","fr":"Découvrez comment configurer write-commits pour créer des messages de commit clairs et professionnels","de":"Erfahren Sie, wie Sie write-commits einrichten, um konsistente und gut strukturierte Commit-Nachrichten zu erstellen","pt":"Aprenda a utilizar o Write Commits para gerar mensagens de commit personalizadas e melhorar o controle de versão do seu repositório Git","ru":"Узнайте, как использовать Write Commits для генерации индивидуальных сообщений коммитов и улучшения контроля версий в вашем репозитории Git с помощью ИИ Агентов","ar":"تعرف على كيفية استخدام Write Commits لإنشاء رسائل Commit مخصصة وتحسين التحكم في الإصدارات لمخزن Git الخاص بك باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"write-commits is a skill that generates commit messages following repository conventions, using commands like git diff --cached --stat to analyze staged changes.","zh":"Write Commits 是一个 Git 提交消息生成工具，帮助开发者遵循仓库规范","ja":"Write Commits は、Git コミットメッセージを生成するツールで、開発者がリポジトリの規約に従うことを助けます","ko":"Write Commits는 Git 커밋 메시지를 생성하는 도구로, 개발자가 리포지토리 규칙을 따르도록 도와줍니다","es":"Write-commits es una herramienta de línea de comandos para generar mensajes de commit","fr":"Write-commits est un outil en ligne de commande pour créer des messages de commit","de":"Write-commits ist ein Command-Line-Tool zum Erstellen von Commit-Nachrichten","pt":"O Write Commits é uma ferramenta de controle de versão que gera mensagens de commit personalizadas","ru":"Write Commits — это инструмент контроля версий, который генерирует индивидуальные сообщения коммитов","ar":"Write Commits هو أداة التحكم في الإصدارات التي تُنشئ رسائل Commit مخصصة"},"features":{"en":["Analyzes staged changes using git diff --cached --stat","Identifies files changed and their paths","Determines nature of changes (new feature, bug fix, refactor, etc.)","Writes commit messages in imperative mood with optional body bullet points","Follows specific commit message format for consistency"],"zh":["分析暂存的变化以确定提交消息","生成符合仓库规范的提交消息","支持多种提交消息格式","使用 Git CLI 命令与仓库交互"],"ja":["ステージングされた変更を分析してコミットメッセージを決定する","リポジトリの規約に従ったコミットメッセージを生成する","複数のコミットメッセージ形式をサポートする","Git CLI コマンドを使用してリポジトリとやり取りする"],"ko":["暂定 변경 사항을 분석하여 커밋 메시지를 결정합니다","리포지토리 규칙에 따라 커밋 메시지를 생성합니다","여러 가지 커밋 메시지 형식을 지원합니다","Git CLI 명령을 사용하여 리포지토리와 상호 작용합니다"],"es":["Análisis de cambios staged con git diff","Generación de mensajes de commit en modo imperativo","Soporte para descripciones de cambios en pasado","Compatibilidad con convenciones de repositorio","Identificación de archivos cambiados y su ruta","Natureza de los cambios (nueva característica, arreglo de errores, refactor, etc.)"],"fr":["Analyse des changements staged avec git diff","Génération de messages de commit en mode impératif","Prise en charge des descriptions de changements en passé","Compatibilité avec les conventions de référentiel","Identification des fichiers modifiés et de leur chemin","Nature des changements (nouvelle fonctionnalité, correction de bogues, refactoring, etc.)"],"de":["Analyse von staged-Änderungen mit git diff","Erstellung von Commit-Nachrichten im Imperativ-Modus","Unterstützung für Änderungsbeschreibungen im Past-Tense","Kompatibilität mit Repository-Konventionen","Identifizierung von geänderten Dateien und ihrem Pfad","Art der Änderungen (neue Funktion, Fehlerbehebung, Refactoring usw.)"],"pt":["Geração de mensagens de commit personalizadas","Análise de alterações em arquivos","Identificação da natureza das alterações","Formato de mensagem de commit personalizado","Regras para mensagens de commit","Integração com Git"],"ru":["Генерация индивидуальных сообщений коммитов","Анализ изменений в файлах","Определение характера изменений","Пользовательский формат сообщений коммитов","Правила для сообщений коммитов","Интеграция с Git"],"ar":["إنشاء رسائل Commit مخصصة","تحليل التغييرات في الملفات","تحديد طبيعة التغييرات","تنسيق رسائل Commit مخصص","قواعد لرسائل Commit","التكامل مع Git"]},"keywords":{"en":["how to use write-commits","write-commits alternative","git commit message generation","write-commits setup guide","what is write-commits","write-commits vs git commit","git commit best practices","write-commits install","git commit message format"],"zh":["Write Commits","Git 提交消息","仓库规范","代码质量","团队合作","Git CLI","提交消息生成"],"ja":["Write Commits","Git コミットメッセージ","リポジトリ規約","コード品質","チームコラボレーション","Git CLI","コミットメッセージ生成"],"ko":["Write Commits","Git 커밋 메시지","리포지토리 규칙","코드 품질","팀 협업","Git CLI","커밋 메시지 생성"],"es":["write-commits","mensajes de commit","convenciones de repositorio","git diff","modo imperativo","descripciones de cambios","compatibilidad con repositorio","herramientas de línea de comandos","desarrollo de software"],"fr":["write-commits","messages de commit","conventions de référentiel","git diff","mode impératif","descriptions de changements","compatibilité avec référentiel","outils en ligne de commande","développement de logiciels"],"de":["write-commits","Commit-Nachrichten","Repository-Konventionen","git diff","Imperativ-Modus","Änderungsbeschreibungen","Kompatibilität mit Repository","Command-Line-Tools","Software-Entwicklung"],"pt":["Write Commits","controle de versão","Git","mensagens de commit","análise de alterações","formato de mensagem de commit","regras para mensagens de commit","ferramentas de desenvolvimento","desenvolvimento de software"],"ru":["Write Commits","контроль версий","Git","сообщения коммитов","анализ изменений","формат сообщений коммитов","правила для сообщений коммитов","инструменты разработки","разработка программного обеспечения","ИИ Агенты"],"ar":["Write Commits","التحكم في الإصدارات","Git","رسائل Commit","تحليل التغييرات","تنسيق رسائل Commit","قواعد لرسائل Commit","أدوات التطوير","تطوير البرمجيات","أدوات الذكاء الاصطناعي"]}},"owner":"guillem-aistech","repo":"satellite-orbit-simulator","repoPath":"guillem-aistech/satellite-orbit-simulator","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.484Z","topics":[],"category":"community","skillMd":{"name":"write-commits","description":"Generates git commit messages following this repositorys conventions. Analyzes staged changes and outputs properly formatted commit messages. Use when user asks to write, generate, or format a commit message.","bodyPreview":"# Write Commits\n\nGenerate commit messages following repository conventions.\n\n## Instructions\n\n### Step 1: Analyze Staged Changes\n\n```bash\ngit diff --cached --stat\ngit diff --cached\n```\n\nIdentify:\n\n- Files changed and their paths\n- Nature of changes (new feature, bug fix, refactor, etc.)\n\n### Step 2: Write Commit Message\n\n**Format:**\n\n```text\nSubject in imperative mood\n\n- Body bullet in past tense with period (only if subject isn''t enough).\n- Another change description.\n```\n\n**Rules:**\n\n- Subject","body":"# Write Commits\n\nGenerate commit messages following repository conventions.\n\n## Instructions\n\n### Step 1: Analyze Staged Changes\n\n```bash\ngit diff --cached --stat\ngit diff --cached\n```\n\nIdentify:\n\n- Files changed and their paths\n- Nature of changes (new feature, bug fix, refactor, etc.)\n\n### Step 2: Write Commit Message\n\n**Format:**\n\n```text\nSubject in imperative mood\n\n- Body bullet in past tense with period (only if subject isn''t enough).\n- Another change description.\n```\n\n**Rules:**\n\n- Subject: imperative mood, capital start, no period, max 72 chars\n- Body: only include when subject line alone doesn''t adequately describe the changes\n- Body bullets: past tense, capital start, period at end\n- No attribution (no \"Co-Authored-By\" or \"Generated with\")\n\n### Step 3: Output\n\nProvide the commit message ready to use. Only include a body when the subject line alone isn''t sufficient to describe the changes.\n\n## Examples\n\n**Simple change:**\n\n```text\nAdd task details dialog\n```\n\n**Change with body (subject alone isn''t enough):**\n\n```text\nAdd task details dialog\n\n- Added OrderDetailsDialog with map preview and navigation.\n- Extracted filtering and pagination into reusable hooks.\n```\n\n**Bug fix:**\n\n```text\nCorrect button disabled state styling\n```\n\n**Refactor with body (subject alone isn''t enough):**\n\n```text\nSimplify locale resolution logic\n\n- Replaced manual locale matching with Intl.LocaleMatcher.\n- Removed fallback chain in favor of single default.\n```\n\n**Configuration update with body (multiple changes):**\n\n```text\nUpdate workspaces and dependencies\n\n- Added shared/repositories/* to workspaces.\n- Bumped @biomejs/biome to 2.3.8.\n```\n"},"lastSynced":"2026-03-08T02:10:02.540Z","agentAnalysis":{"suitability":{"en":"Perfect for Git-based agents needing standardized commit message generation.","zh":"适合需要标准化提交消息生成的基于Git的代理。","ja":"Gitベースのエージェントが標準化されたコミットメッセージ生成を必要とする場合に最適です。","ko":"표준화된 커밋 메시지 생성이 필요한 Git 기반 에이전트에 적합합니다.","es":"Perfecto para agentes basados en Git que necesitan una generación de mensajes de confirmación estandarizados.","fr":"Parfait pour les agents basés sur Git nécessitant une génération de messages de validation standardisés.","de":"Perfekt für Git-basierte Agenten, die eine standardisierte Commit-Nachrichtengenerierung benötigen.","pt":"Perfeito para agentes baseados em Git que necessitam de geração de mensagens de commit padronizadas.","ru":"Идеально для агентов на основе Git, требующих стандартизированной генерации сообщений о коммитах.","ar":"مثالي لعميل الوكيل الذي يعتمد على جيت و الذي يحتاج إلى توليد رسائل الالتزام بشكل معياري."},"recommendation":{"en":"Empowers agents to generate consistent and descriptive commit histories following repository conventions, utilizing Git commands like ''git diff'' for staged change analysis and adhering to specific commit message formats.","zh":"赋予代理生成一致且具有描述性的提交历史记录的能力，遵循存储库约定，利用如''git diff''的Git命令进行暂存更改分析，并遵循特定的提交消息格式。","ja":"エージェントが一貫性のある記述的なコミット履歴を生成する能力を与え、リポジトリの規約に従い、''git diff''などのGitコマンドを使用してステージされた変更を分析し、特定のコミットメッセージ形式に従う。","ko":"에이전트가 일관성 있고 설명 가능한 커밋 기록을 생성할 수 있는 능력을 부여하여 리포지토리 규약을 따르고 ''git diff''와 같은 Git 명령을 사용하여 스테이징된 변경 사항을 분석하며 특정 커밋 메시지 형식을 따릅니다.","es":"Habilita a los agentes a generar historias de confirmación consistentes y descriptivas siguiendo las convenciones del repositorio, utilizando comandos de Git como ''git diff'' para el análisis de cambios en espera y ajustándose a formatos de mensajes de confirmación específicos.","fr":"Permet aux agents de générer des historiques de validation cohérents et descriptifs en suivant les conventions de référentiel, en utilisant des commandes Git comme ''git diff'' pour l''analyse des modifications en attente et en respectant des formats de messages de validation spécifiques.","de":"Ermächtigt Agenten, konsistente und beschreibende Commit-Verlaufsprotokolle zu generieren, die den Repository-Konventionen folgen, indem Git-Befehle wie ''git diff'' für die Analyse von gestellten Änderungen verwendet werden und bestimmte Commit-Nachrichtenformate eingehalten werden.","pt":"Permite que os agentes gerem históricos de commit consistentes e descritivos, seguindo as convenções do repositório, utilizando comandos Git como ''git diff'' para análise de alterações em estágio e aderindo a formatos de mensagens de commit específicos.","ru":"Позволяет агентам генерировать последовательные и описательные истории коммитов, следующие репозиторным конвенциям, используя команды Git, такие как ''git diff'', для анализа изменений в очереди и придерживаясь определенных форматов сообщений о коммитах.","ar":"يمكّن الوكلاء من توليد سجلات التزامات متسقة و وصفية تتبع اتفاقيات المستودع، و باستخدام أوامر جيت مثل ''git diff'' لتحليل التغييرات المجدولة و الالتزام بالتنسيقات المحددة لرسائل الالتزام."},"useCases":{"en":["Automating commit message generation","Standardizing commit histories for team collaboration","Debugging commit message formatting issues"],"zh":["自动化提交消息生成","标准化提交历史以便团队协作","调试提交消息格式问题"],"ja":["コミットメッセージ生成の自動化","チームコラボレーションのためのコミット履歴の標準化","コミットメッセージ形式の問題のデバッグ"],"ko":["커밋 메시지 생성 자동화","팀 협업을 위한 커밋 기록 표준화","커밋 메시지 형식 문제 디버깅"],"es":["Automatizar la generación de mensajes de confirmación","Establecer historias de confirmación estandarizadas para la colaboración en equipo","Depurar problemas de formato de mensajes de confirmación"],"fr":["Automatiser la génération de messages de validation","Standardiser les historiques de validation pour la collaboration d''équipe","Déboguer les problèmes de formatage des messages de validation"],"de":["Automatisieren der Commit-Nachrichtengenerierung","Standardisieren von Commit-Verlaufsprotokollen für Teamzusammenarbeit","Beheben von Formatierungsproblemen bei Commit-Nachrichten"],"pt":["Automatizar a geração de mensagens de commit","Padronizar históricos de commit para colaboração em equipe","Depurar problemas de formatação de mensagens de commit"],"ru":["Автоматизировать генерацию сообщений о коммитах","Стандартизировать истории коммитов для командной работы","Отладить проблемы форматирования сообщений о коммитах"],"ar":["أتمتة توليد رسائل الالتزام","ت قياس سجلات الالتزامات للتعاون الفريقي","تصحيح مشاكل تنسيق رسائل الالتزام"]},"limitations":{"en":["Requires Git installation and configuration","Limited to generating commit messages in a specific format"],"zh":["需要Git安装和配置","仅限生成特定格式的提交消息"],"ja":["Gitのインストールと設定が必要","特定の形式のコミットメッセージの生成のみ"],"ko":["Git 설치 및 구성이 필요","특정 형식의 커밋 메시지 생성만 가능"],"es":["Requiere la instalación y configuración de Git","Limitado a la generación de mensajes de confirmación en un formato específico"],"fr":["Nécessite l''installation et la configuration de Git","Limité à la génération de messages de validation dans un format spécifique"],"de":["Benötigt die Installation und Konfiguration von Git","Begrenzt auf die Generierung von Commit-Nachrichten in einem bestimmten Format"],"pt":["Requer instalação e configuração do Git","Limitado a gerar mensagens de commit em um formato específico"],"ru":["Требует установки и конфигурации Git","Ограничен генерацией сообщений о коммитах в определенном формате"],"ar":["يتطلب تثبيت جيت وتفصيله","محدود بتوليد رسائل الالتزام بنفس التنسيق"]},"version":4},"contentHash":"5299da044289967d22d527fdb50fd0b1dc4355267e776072b061effc15a2bcad","qualityScore":54}');
