INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('guillem-aistech/satellite-orbit-simulator/write-commits', 'write-commits', 'guillem-aistech', 'satellite-orbit-simulator', 'community', 'write-commits guillem-aistech satellite-orbit-simulator community write-commits generates commit messages following repository conventions, helping developers maintain consistent and descriptive commit histories. It benefits developers and teams working with Git. Write Commits 是一个帮助开发者生成符合仓库规范的 Git 提交消息的工具，通过分析暂存的变化和编写有意义的提交消息 Write Commits は、開発者がリポジトリの規約に従った Git コミットメッセージを生成するのに役立つツールです。ステージングされた変更を分析し、意味のあるコミットメッセージを書きます Write Commits는 개발자가 리포지토리 규칙에 따라 Git 커밋 메시지를 생성하도록 도와주는 도구로, 暫定 변경 사항을 분석하고 의미 있는 커밋 메시지를 작성합니다 Write-commits es una herramienta para generar mensajes de commit siguiendo las convenciones del repositorio Write-commits est un outil pour créer des messages de commit conformes aux conventions du référentiel Write-commits ist ein Tool zum Erstellen von Commit-Nachrichten, die den Repository-Konventionen entsprechen O Write Commits é uma ferramenta que ajuda a gerar mensagens de commit personalizadas e a melhorar o controle de versão do seu repositório Git. Write Commits — это инструмент, который помогает генерировать индивидуальные сообщения коммитов и улучшать контроль версий в вашем репозитории Git. Write Commits هو أداة تساعد في إنشاء رسائل Commit مخصصة وتحسين التحكم في الإصدارات لمخزن Git الخاص بك. how to use write-commits write-commits alternative git commit message generation write-commits setup guide what is write-commits write-commits vs git commit git commit best practices write-commits install git commit message format Write Commits Git 提交消息 仓库规范 代码质量 团队合作 Git CLI 提交消息生成 Analyzes staged changes using git diff --cached --stat Identifies files changed and their paths Determines nature of changes (new feature, bug fix, refactor, etc.) Writes commit messages in imperative mood with optional body bullet points Follows specific commit message format for consistency write-commits is a skill that generates commit messages following repository conventions, using commands like git diff --cached --stat to analyze staged changes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('madihg/oulipo/oulipo-brand', 'community', 'madihg', 'oulipo', 'madihg/oulipo', 'oulipo-brand', 0, 0, 54, '2026-03-08T01:57:15.453Z', '2026-03-08T02:10:10.591Z', '470a8298d07e143228dd2c2142f5a326017a30d320f95ba0408bffcd10be4b1c', '{"id":"madihg/oulipo/oulipo-brand","name":"oulipo-brand","description":{"en":"The oulipo-brand skill provides a design system and brand guidelines for oulipo.xyz, a laboratory of experimental computational poetry. It benefits developers and designers working on related projects.","zh":"Oulipo品牌设计系统提供了实验计算诗歌的开发和设计指南，包括字体栈和设计一致性指南","ja":"Oulipoブランドのデザインシステムは、実験計算詩の開発と設計のためのガイドラインを提供します。フォントスタックやデザインの一貫性に関するガイドラインが含まれます","ko":"Oulipo 브랜드의 디자인 시스템은 실험 계산 시의 개발과 디자인을 위한 가이드라인을 제공합니다. 폰트 스택과 디자인 일관성에 대한 가이드라인이 포함되어 있습니다","es":"Oulipo-brand es un sistema de diseño y marca para la poesía computacional experimental, que ofrece una guía para la creación de componentes y proyectos relacionados","fr":"Oulipo-brand est un système de design et de marque pour la poésie computationnelle expérimentale, qui fournit un guide pour la création de composants et de projets liés","de":"Oulipo-brand ist ein Design- und Markensystem für experimentelle Computergedichte, das eine Anleitung für die Erstellung von Komponenten und verwandten Projekten bietet","pt":"O oulipo-brand é um laboratório de poesia computacional experimental que fornece diretrizes de design e sistema de marca para criar projetos relacionados","ru":"Oulipo-brand - это лаборатория экспериментальной вычислительной поэзии, предоставляющая руководство по дизайну и системе бренда для создания связанных проектов","ar":"oulipo-brand هو مختبر للشعر الحاسوبي التجريبي الذي يوفر إرشادات للتصميم ونظام العلامة التجارية لإنشاء مشاريع متعلقة"},"seo":{"title":{"en":"oulipo-brand: Design System Setup Guide | AI Agent Skill","zh":"Oulipo品牌设置指南 - 实验计算诗歌设计系统","ja":"Oulipoブランド設定ガイド - 実験計算詩のデザインシステム","ko":"Oulipo 브랜드 설정 가이드 - 실험 계산 시의 디자인 시스템","es":"Guía de configuración de Oulipo-brand para poesía computa...","fr":"Guide de mise en place d''Oulipo-brand pour la poésie comp...","de":"Einrichtungsleitfaden für Oulipo-brand Experimentelle Com...","pt":"Oulipo-brand: Guia de Configuração de Poesia Computacional","ru":"ИИ Агент Oulipo-brand: Руководство по Настройке Вычислите...","ar":"oulipo-brand: دليل إعداد الشعر الحاسوبي التجريبي"},"description":{"en":"Unlock the secrets of experimental computational poetry with oulipo-brand. Discover how to apply design consistency and typography guidelines for a unique ae...","zh":"了解Oulipo品牌的设计系统和品牌指南，用于实验计算诗歌的开发和设计","ja":"Oulipoブランドのデザインシステムとブランドガイドラインを紹介します。実験計算詩の開発と設計に役立ちます","ko":"Oulipo 브랜드의 디자인 시스템과 브랜드 가이드라인을 확인하세요. 실험 계산 시의 개발과 디자인에 도움이 됩니다","es":"Aprende a implementar Oulipo-brand en tus proyectos de poesía computacional con nuestra guía de diseño y sistema de marca","fr":"Découvrez comment mettre en œuvre Oulipo-brand dans vos projets de poésie computationnelle avec notre guide de design et système de marque","de":"Erfahren Sie, wie Sie Oulipo-brand in Ihre experimentellen Computergedichte-Projekte integrieren können, mit unserem Design- und Markensystem-Leitfaden","pt":"Aprenda a configurar o oulipo-brand para criar poesia computacional experimental com nosso guia de design e sistema de marca","ru":"Изучите руководство по настройке oulipo-brand для создания экспериментальной вычислительной поэзии с нашей системой дизайна и бренда","ar":"تعرف على كيفية إعداد oulipo-brand لإنشاء شعر حاسوبي تجريبي مع دليلنا للتصميم ونظام العلامة التجارية"},"definition":{"en":"oulipo-brand is a set of design system and brand guidelines for creating experimental computational poetry projects with a consistent aesthetic.","zh":"Oulipo品牌是实验计算诗歌的设计系统和品牌指南","ja":"Oulipoブランドは実験計算詩のデザインシステムとブランドガイドラインのこと","ko":"Oulipo 브랜드는 실험 계산 시의 디자인 시스템과 브랜드 가이드라인입니다","es":"Oulipo-brand es un sistema de diseño y marca para la creación de poesía computacional experimental","fr":"Oulipo-brand est un système de design et de marque pour la création de poésie computationnelle expérimentale","de":"Oulipo-brand ist ein Design- und Markensystem für die Erstellung von experimentellen Computergedichten","pt":"O oulipo-brand é um conjunto de diretrizes de design e sistema de marca para criar poesia computacional experimental","ru":"Oulipo-brand - это набор руководств по дизайну и системе бренда для создания экспериментальной вычислительной поэзии","ar":"oulipo-brand هو مجموعة من إرشادات التصميم ونظام العلامة التجارية لإنشاء شعر حاسوبي تجريبي"},"features":{"en":["Reference design system guidelines for building new pages on oulipo.xyz","Apply typography guidelines using a specified font stack","Ensure design consistency across the site with review guidelines","Modify existing oulipo components to match the oulipo aesthetic","Create related projects with a consistent design language"],"zh":["提供字体栈的设计指南","包括设计一致性指南","适用于实验计算诗歌的开发和设计","支持创建新页面和修改现有组件","提供相关项目的设计指南"],"ja":["フォントスタックのデザインガイドラインを提供","デザインの一貫性に関するガイドラインを含む","実験計算詩の開発と設計に適している","新しいページの作成と既存のコンポーネントの変更をサポート","関連プロジェクトのデザインガイドラインを提供"],"ko":["폰트 스택의 디자인 가이드라인을 제공","디자인 일관성에 대한 가이드라인을 포함","실험 계산 시의 개발과 디자인에 적합","새로운 페이지의 생성과 기존 컴포넌트의 변경을 지원","관련 프로젝트의 디자인 가이드라인을 제공"],"es":["Sistema de diseño para la creación de componentes y proyectos de poesía computacional","Guía de estilo para la tipografía y el diseño de la marca","Compatibilidad con la creación de proyectos relacionados con la poesía computacional","Diseño de la pila de fuentes para la presentación de la poesía","Guía para la revisión de la coherencia del diseño en el sitio web","Integración con la plataforma de poesía computacional experimental de Halim Madi"],"fr":["Système de design pour la création de composants et de projets de poésie computationnelle","Guide de style pour la typographie et le design de la marque","Compatibilité avec la création de projets liés à la poésie computationnelle","Conception de la pile de polices pour la présentation de la poésie","Guide pour la révision de la cohérence du design sur le site web","Intégration avec la plateforme de poésie computationnelle expérimentale de Halim Madi"],"de":["Designsystem für die Erstellung von Komponenten und Projekten für experimentelle Computergedichte","Stilguide für die Typografie und das Design der Marke","Kompatibilität mit der Erstellung von Projekten im Zusammenhang mit experimentellen Computergedichten","Entwurf der Schriftstapel für die Präsentation von Gedichten","Leitfaden für die Überprüfung der Designkonsistenz auf der Website","Integration mit der Plattform für experimentelle Computergedichte von Halim Madi"],"pt":["Font Stack personalizado para poesia computacional","Sistema de design para criar projetos relacionados","Diretrizes de marca para manter a consistência visual","Laboratório de poesia computacional experimental","Guia de configuração para criar novas páginas e componentes"],"ru":["Пользовательский Font Stack для вычислительной поэзии","Система дизайна для создания связанных проектов","Руководство по бренду для поддержания визуальной согласованности","Лаборатория экспериментальной вычислительной поэзии","Руководство по настройке для создания новых страниц и компонентов"],"ar":["Font Stack مخصص للشعر الحاسوبي","نظام تصميم لإنشاء مشاريع متعلقة","دليل العلامة التجارية لضمان الاتساق البصري","مختبر الشعر الحاسوبي التجريبي","دليل الإعداد لإنشاء صفحات و مكونات جديدة"]},"keywords":{"en":["how to use oulipo-brand","oulipo-brand design system","oulipo-brand typography guidelines","oulipo-brand alternative","oulipo-brand setup guide","experimental computational poetry tools"],"zh":["Oulipo品牌","实验计算诗歌","设计系统","品牌指南","字体栈","设计一致性","AIエージェント","计算诗歌开发"],"ja":["Oulipoブランド","実験計算詩","デザインシステム","ブランドガイドライン","フォントスタック","デザインの一貫性","AIエージェント","計算詩開発"],"ko":["Oulipo 브랜드","실험 계산 시","디자인 시스템","브랜드 가이드라인","폰트 스택","디자인 일관성","AI 에이전트","계산 시 개발"],"es":["poesía computacional experimental","sistema de diseño","marca","tipografía","diseño de componentes","proyectos de poesía","guía de estilo","Herramientas de AI para la poesía","Agentes de IA para la creatividad"],"fr":["poésie computationnelle expérimentale","système de design","marque","typographie","conception de composants","projets de poésie","guide de style","Outils d''IA pour la poésie","Agents d''IA pour la créativité"],"de":["experimentelle Computergedichte","Designsystem","Marke","Typografie","Entwurf von Komponenten","Projekte für Gedichte","Stilguide","AI-Tools für die Poesie","KI-Agenten für die Kreativität"],"pt":["oulipo-brand","poesia computacional","design de marca","sistema de design","laboratório de poesia","guia de configuração","font stack","tipografia"],"ru":["ИИ Агент","oulipo-brand","вычислительная поэзия","система дизайна","руководство по бренду","лаборатория поэзии","руководство по настройке","font stack","типография"],"ar":["oulipo-brand","شعر حاسوبي","تصميم العلامة التجارية","نظام التصميم","مختبر الشعر","دليل الإعداد","font stack","طباعة"]}},"owner":"madihg","repo":"oulipo","repoPath":"madihg/oulipo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.453Z","topics":[],"category":"community","skillMd":{"name":"oulipo-brand","description":"Oulipo.xyz brand guidelines and design system. Typography: Standard (body), Terminal Grotesque (h1), Diatype Variable (headings, captions, metadata). Colors: white background, dark text. Use when building or modifying oulipo.xyz pages, components, or related projects.","bodyPreview":"# Oulipo.xyz Brand Guidelines\n\nDesign system and brand guidelines for oulipo.xyz — a laboratory of experimental computational poetry by Halim Madi.\n\n## When to Apply\n\nReference these guidelines when:\n\n- Building new pages for oulipo.xyz\n- Modifying existing oulipo components\n- Creating related projects that should match the oulipo aesthetic\n- Reviewing design consistency across the site\n\n---\n\n## Typography\n\n### Font Stack\n\n| Font                      | Usage","body":"# Oulipo.xyz Brand Guidelines\n\nDesign system and brand guidelines for oulipo.xyz — a laboratory of experimental computational poetry by Halim Madi.\n\n## When to Apply\n\nReference these guidelines when:\n\n- Building new pages for oulipo.xyz\n- Modifying existing oulipo components\n- Creating related projects that should match the oulipo aesthetic\n- Reviewing design consistency across the site\n\n---\n\n## Typography\n\n### Font Stack\n\n| Font                      | Usage                                             | Weight                 | Source    |\n| ------------------------- | ------------------------------------------------- | ---------------------- | --------- |\n| **Standard**              | Body text, navigation, hero subtitle              | Book (400), Bold (700) | Cargo CDN |\n| **Terminal Grotesque**    | Main h1 headings only                             | Regular (400)          | Cargo CDN |\n| **Diatype Variable**      | h2 headings                                       | 200-1000 (variable)    | Cargo CDN |\n| **Diatype Mono Variable** | Captions, work titles, metadata (with `''MONO'' 1`) | 200-1000 (variable)    | Cargo CDN |\n\n### Font Face Declarations\n\n```css\n/* Standard - Body Font */\n@font-face {\n  font-display: block;\n  font-family: \"Standard\";\n  src: url(\"https://type.cargo.site/files/Standard-Book.woff\") format(\"woff\");\n  font-style: normal;\n  font-weight: normal;\n}\n@font-face {\n  font-display: block;\n  font-family: \"Standard\";\n  src: url(\"https://type.cargo.site/files/Standard-Bold.woff\") format(\"woff\");\n  font-style: normal;\n  font-weight: bold;\n}\n\n/* Terminal Grotesque - Display Font for h1 */\n@font-face {\n  font-display: block;\n  font-family: \"Terminal Grotesque\";\n  src: url(\"https://type.cargo.site/files/TerminalGrotesque.woff\")\n    format(\"woff\");\n  font-style: normal;\n  font-weight: normal;\n}\n\n/* Diatype Variable - h2 Headings (proportional) */\n@font-face {\n  font-display: block;\n  font-family: \"Diatype Variable\";\n  src: url(\"https://type.cargo.site/files/Cargo-DiatypePlusVariable.woff2\")\n    format(\"woff2-variations\");\n  font-style: normal;\n  font-weight: 200 1000;\n}\n\n/* Diatype Mono Variable - Captions, Work Titles, Metadata (monospace) */\n@font-face {\n  font-display: block;\n  font-family: \"Diatype Mono Variable\";\n  src: url(\"https://type.cargo.site/files/Cargo-DiatypePlusVariable.woff2\")\n    format(\"woff2-variations\");\n  font-style: normal;\n  font-weight: 200 1000;\n}\n```\n\n### Font Variation Settings\n\nThe Diatype Plus Variable font supports axis switching between proportional and monospace:\n\n```css\n/* Proportional (Diatype Variable) */\nfont-variation-settings:\n  \"slnt\" 0,\n  \"MONO\" 0;\n\n/* Monospace (Diatype Mono Variable) - USE THIS FOR CAPTIONS */\nfont-variation-settings:\n  \"slnt\" 0,\n  \"MONO\" 1;\n```\n\n### Typography Specifications\n\n| Element          | Font Family        | Size                            | Weight | Line Height |\n| ---------------- | ------------------ | ------------------------------- | ------ | ----------- |\n| `body`           | Standard           | 1.3rem                          | 400    | 1.2         |\n| `h1`             | Terminal Grotesque | 7rem (desktop), 4.5rem (mobile) | 400    | 0.9         |\n| `h2`             | Diatype Variable   | 2rem                            | 700    | 1.2         |\n| `.caption`       | Diatype Variable   | 1.2rem                          | 400    | 1.25        |\n| `.work-title`    | Diatype Variable   | 1.1rem                          | 400    | —           |\n| `.work-meta`     | Diatype Variable   | 0.9rem                          | 400    | —           |\n| `.hero-subtitle` | Standard           | 1rem                            | 400    | 1.4         |\n\n---\n\n## Colors\n\n### Core Palette\n\n| Name                | Value                 | Usage              |\n| ------------------- | --------------------- | ------------------ |\n| **Background**      | `#ffffff`             | Page background    |\n| **Primary Text**    | `rgba(0, 0, 0, 0.85)` | Body text, links   |\n| **Black**           | `#000000`             | Headings, captions |\n| **Muted Text**      | `rgba(0, 0, 0, 0.7)`  | Descriptions       |\n| **Subtle Text**     | `rgba(0, 0, 0, 0.5)`  | Metadata, dates    |\n| **Subtle Text Alt** | `rgba(0, 0, 0, 0.6)`  | Section subtitles  |\n| **Border/Divider**  | `rgba(0, 0, 0, 0.75)` | Horizontal rules   |\n| **Overlay**         | `rgba(0, 0, 0, 0.25)` | Menu overlay       |\n\n### CSS Variables (Optional)\n\n```css\n:root {\n  --oulipo-bg: #ffffff;\n  --oulipo-text: rgba(0, 0, 0, 0.85);\n  --oulipo-text-black: #000000;\n  --oulipo-text-muted: rgba(0, 0, 0, 0.7);\n  --oulipo-text-subtle: rgba(0, 0, 0, 0.5);\n  --oulipo-border: rgba(0, 0, 0, 0.75);\n  --oulipo-overlay: rgba(0, 0, 0, 0.25);\n}\n```\n\n---\n\n## Layout\n\n### Spacing\n\n| Element           | Value                         |\n| ----------------- | ----------------------------- |\n| Page padding      | 4rem (desktop), 2rem (mobile) |\n| Max content width | 1200px                        |\n| Section margin    | 3rem bottom                   |\n| Grid gap          | 2rem                          |\n\n### Grid System\n\n```css\n/* 3-column grid on desktop */\n.grid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 2rem;\n}\n\n/* 2-column on tablet (≤900px) */\n@media (max-width: 900px) {\n  .grid {\n    grid-template-columns: repeat(2, 1fr);\n  }\n}\n\n/* 1-column on mobile (≤600px) */\n@media (max-width: 600px) {\n  .grid {\n    grid-template-columns: 1fr;\n  }\n}\n```\n\n### Featured Work Layout\n\n```css\n/* Image 2/3, Description 1/3 */\n.work-featured-body {\n  display: grid;\n  grid-template-columns: 2fr 1fr;\n  gap: 2rem;\n}\n\n@media (max-width: 900px) {\n  .work-featured-body {\n    grid-template-columns: 1fr;\n  }\n}\n```\n\n---\n\n## Components\n\n### Links\n\n```css\na {\n  color: rgba(0, 0, 0, 0.85);\n  text-decoration: underline;\n}\n\na:hover {\n  opacity: 0.7;\n}\n```\n\n### Horizontal Rule\n\n```css\nhr {\n  background: rgba(0, 0, 0, 0.75);\n  border: 0;\n  height: 1px;\n  margin: 2rem 0;\n}\n```\n\n### Side Menu\n\n- Width: 420px (desktop), 100% (mobile)\n- Background: white\n- Slide in from right\n- Line height for links: 1.15\n\n---\n\n## Site Structure\n\n### Current Sections\n\n1. **Featured Works** (max 3 items) — Highlighted projects with image + description\n2. **Selected Works** — Additional notable works\n3. **Non Human Poets** — AI/machine poetry experiments\n4. **Border/line** — Immigration-themed interactive series\n5. **Somatic Poetry Sandbox** — Experimental interactive pieces\n\n### Navigation\n\n- Top-left: \"Halim Madi\" link (hides on scroll)\n- Top-right: Hamburger menu (hides on scroll)\n- Side drawer with links to halimmadi.com sections\n\n---\n\n## File Organization\n\n```\noulipo/\n├── index.html              # Main landing page\n├── Assets/\n│   ├── screenshots/        # Work screenshots\n│   └── curl-screenshot.png\n├── borderline/             # Border/line series\n├── somatic-poetry-sandbox/ # Interactive experiments\n├── curl/                   # Curl project\n├── becoming-borders/       # Becoming Borders project\n├── case-against-the-son/   # Case Against the Son\n└── unlisted/               # Unlisted/archived works\n```\n\n---\n\n## Quick Copy-Paste\n\n### Minimal HTML Head\n\n```html\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Page Title — oulipo.xyz</title>\n  <style>\n    @font-face {\n      font-family: \"Standard\";\n      src: url(\"https://type.cargo.site/files/Standard-Book.woff\")\n        format(\"woff\");\n    }\n    @font-face {\n      font-family: \"Terminal Grotesque\";\n      src: url(\"https://type.cargo.site/files/TerminalGrotesque.woff\")\n        format(\"woff\");\n    }\n    @font-face {\n      font-family: \"Diatype Variable\";\n      src: url(\"https://type.cargo.site/files/Cargo-DiatypePlusVariable.woff2\")\n        format(\"woff2-variations\");\n      font-weight: 200 1000;\n    }\n    body {\n      margin: 0;\n      padding: 4rem;\n      background: #ffffff;\n      color: rgba(0, 0, 0, 0.85);\n      font-family: Standard, sans-serif;\n      font-size: 1.3rem;\n      line-height: 1.2;\n    }\n    h1 {\n      font-family: \"Terminal Grotesque\", sans-serif;\n      font-size: 7rem;\n      line-height: 0.9;\n    }\n    h2 {\n      font-family: \"Diatype Variable\", sans-serif;\n      font-size: 2rem;\n      font-weight: 700;\n    }\n  </style>\n</head>\n```\n\n---\n\n## Screenshots\n\n### IMPORTANT: Screenshot Border Requirements\n\n**All screenshots on oulipo.xyz MUST have a thin 1px black border.**\n\nWhen adding or updating screenshots:\n\n1. **Take the screenshot** of the work/page\n2. **Add a 1px black border** around the entire image\n3. **Save to** `Assets/screenshots/` with a descriptive name (e.g., `project-name.png`)\n\n### Adding Borders with Python (Pillow)\n\n```python\nfrom PIL import Image\n\ndef add_border(image_path, output_path=None, border_width=1, border_color=(0, 0, 0)):\n    \"\"\"Add a thin black border to a screenshot\"\"\"\n    if output_path is None:\n        output_path = image_path\n\n    img = Image.open(image_path)\n    new_width = img.width + 2 * border_width\n    new_height = img.height + 2 * border_width\n\n    bordered_img = Image.new(''RGB'', (new_width, new_height), border_color)\n    bordered_img.paste(img, (border_width, border_width))\n    bordered_img.save(output_path, quality=95)\n\n# Usage\nadd_border(\"Assets/screenshots/my-project.png\")\n```\n\n### Screenshot Naming Convention\n\n- Use lowercase with hyphens: `project-name.png`\n- Match the work title where possible\n- Store in `Assets/screenshots/`\n\n---\n\n## Brand Voice\n\nOulipo.xyz is described as:\n\n> \"A kitchen laboratory of experimental computational poetry. Non-human poets, anti-gravitational word interfaces, somatic semantics. This is where I break and mend things.\"\n\nKey themes:\n\n- Experimental and playful\n- Code meets poetry\n- Human-machine interaction\n- Border/migration/identity exploration\n- Somatic (body-based) interactions\n"},"lastSynced":"2026-03-08T02:10:10.591Z","agentAnalysis":{"suitability":{"en":"Perfect for Design-focused Agents needing consistent brand guidelines and typography management for experimental computational poetry projects.","zh":"非常适合需要一致的品牌指南和字体管理的设计导向型代理，用于实验计算机诗歌项目。","ja":"デザインに焦点を当てたエージェントが、実験的な計算機詩プロジェクトのための統一されたブランドガイドラインとタイポグラフィ管理を必要とする場合に最適です。","ko":"실험적인 계산 기법 시 프로젝트를 위한 일관된 브랜드 가이드라인 및 타이포그래피 관리가 필요한 디자인 중심 에이전트에게 적합합니다.","es":"Perfecto para agentes enfocados en el diseño que necesitan directrices de marca consistentes y gestión de tipografía para proyectos de poesía computacional experimental.","fr":"Parfait pour les agents axés sur la conception nécessitant des directives de marque cohérentes et une gestion de la typographie pour les projets de poésie computationnelle expérimentale.","de":"Perfekt für designorientierte Agenten, die konsistente Markenrichtlinien und Typografieverwaltung für experimentelle computergenerierte Poesieprojekte benötigen.","pt":"Perfeito para Agentes focados em Design que necessitam de diretrizes de marca consistentes e gerenciamento de tipografia para projetos de poesia computacional experimental.","ru":"Идеально подходит для агентов, ориентированных на дизайн, которым требуются последовательные рекомендации по бренду и управление типографией для экспериментальных проектов вычислительной поэзии.","ar":"مثالي لعميل يركز على التصميم الذي يحتاج إلى إرشادات العلامة التجارية الثابتة وإدارة الطباعة لنماذج مشاريع الشعر الحاسوبي التجريبية."},"recommendation":{"en":"Empowers agents to maintain design consistency across oulipo.xyz using a standardized font stack and typography guidelines, ensuring a cohesive user experience through HTML and CSS implementations.","zh":"赋予代理维护oulipo.xyz上的一致设计，通过标准化的字体栈和タイポグラフィ指南，确保通过HTML和CSS实现的一致用户体验。","ja":"エージェントが、標準化されたフォントスタックとタイポグラフィガイドラインを使用して、oulipo.xyz全体での一貫した設計を維持できるようにします。HTMLとCSSの実装を通じて、一貫したユーザーエクスペリエンスを保証します。","ko":"에이전트가 표준화된 폰트 스택과 타이포그래피 가이드라인을 사용하여 oulipo.xyz 전체에서 일관된 디자인을 유지할 수 있도록 합니다. HTML 및 CSS 구현을 통해 일관된 사용자 경험을 보장합니다.","es":"Permite a los agentes mantener la coherencia del diseño en toda oulipo.xyz utilizando una pila de fuentes estandarizada y directrices de tipografía, garantizando una experiencia del usuario cohesiva a través de implementaciones de HTML y CSS.","fr":"Permet aux agents de maintenir la cohérence de la conception sur tout oulipo.xyz en utilisant une pile de polices standardisée et des directives de typographie, garantissant une expérience utilisateur cohérente grâce aux implémentations HTML et CSS.","de":"Ermächtigt Agenten, die Designkonsistenz über alle oulipo.xyz hinweg beizubehalten, indem sie einen standardisierten Schriftstapel und Typografie-Richtlinien verwenden, und stellt so eine kohärente Benutzeroberfläche durch HTML- und CSS-Implementierungen sicher.","pt":"Habilita os agentes a manter a consistência do design em toda a oulipo.xyz usando uma pilha de fontes padronizada e diretrizes de tipografia, garantindo uma experiência de usuário coesa por meio de implementações HTML e CSS.","ru":"Наделяет агентов возможностью поддерживать согласованность дизайна на всем сайте oulipo.xyz, используя стандартизированный стек шрифтов и руководство по типографике, обеспечивая целостный пользовательский опыт через реализации HTML и CSS.","ar":"تمكين الوكلاء من الحفاظ على συνέفات التصميم عبر oulipo.xyz باستخدام حزمة خطوط معيارية وارشادات طباعية، مما يضمن تجربة مستخدم متسقة من خلال تنفيذات HTML و CSS."},"useCases":{"en":["Applying brand guidelines for new page development","Ensuring design consistency across oulipo.xyz","Creating related projects with matching aesthetics"],"zh":["为新页面开发应用品牌指南","确保oulipo.xyz上的设计一致性","创建具有匹配美学的相关项目"],"ja":["新しいページ開発のためのブランドガイドラインの適用","oulipo.xyz全体でのデザインの一貫性の確保","一致した美学を持つ関連プロジェクトの作成"],"ko":["새 페이지 개발을 위한 브랜드 가이드라인 적용","oulipo.xyz 전체에서 디자인 일관성 보장","일치하는 미학을 갖는 관련 프로젝트 생성"],"es":["Aplicar directrices de marca para el desarrollo de nuevas páginas","Garantizar la coherencia del diseño en toda oulipo.xyz","Crear proyectos relacionados con estéticas coincidentes"],"fr":["Appliquer des directives de marque pour le développement de nouvelles pages","Assurer la cohérence de la conception sur tout oulipo.xyz","Créer des projets liés avec des esthétiques correspondantes"],"de":["Markenrichtlinien für die Entwicklung neuer Seiten anwenden","Designkonsistenz über alle oulipo.xyz hinweg sicherstellen","Erstellung von verwandten Projekten mit übereinstimmenden Ästhetiken"],"pt":["Aplicar diretrizes de marca para desenvolvimento de novas páginas","Garantir a consistência do design em toda a oulipo.xyz","Criar projetos relacionados com estética correspondente"],"ru":["Применение рекомендаций по бренду для разработки новых страниц","Обеспечение согласованности дизайна на всем сайте oulipo.xyz","Создание связанных проектов с соответствующей эстетикой"],"ar":["تطبيق إرشادات العلامة التجارية لتطوير صفحات جديدة","ضمان συνέفات التصميم عبر oulipo.xyz","إنشاء مشاريع متعلقة بالجمالية المتوافقة"]},"limitations":{"en":["Specific to oulipo.xyz design system","Requires knowledge of HTML and CSS for implementation"],"zh":["仅限oulipo.xyz设计系统","需要HTML和CSS知识来实现"],"ja":["oulipo.xyzデザインシステムに特有の制限","実装にはHTMLとCSSの知識が必要"],"ko":["oulipo.xyz 디자인 시스템에 특정된 제한","구현을 위해 HTML 및 CSS 지식이 필요"],"es":["Específico del sistema de diseño de oulipo.xyz","Requiere conocimiento de HTML y CSS para la implementación"],"fr":["Spécifique au système de conception d''oulipo.xyz","Nécessite des connaissances en HTML et CSS pour la mise en œuvre"],"de":["Spezifisch für das Designsystem von oulipo.xyz","Benötigt Kenntnisse von HTML und CSS für die Implementierung"],"pt":["Específico para o sistema de design da oulipo.xyz","Requer conhecimento de HTML e CSS para implementação"],"ru":["Конкретно для системы дизайна oulipo.xyz","Требует знания HTML и CSS для реализации"],"ar":["محدد لنظام التصميم في oulipo.xyz","يتطلب معرفة HTML و CSS للتطبيق"]},"version":4},"contentHash":"470a8298d07e143228dd2c2142f5a326017a30d320f95ba0408bffcd10be4b1c","qualityScore":54}');
