INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('madihg/oulipo/oulipo-brand', 'oulipo-brand', 'madihg', 'oulipo', 'community', 'oulipo-brand madihg oulipo community The oulipo-brand skill provides a design system and brand guidelines for oulipo.xyz, a laboratory of experimental computational poetry. It benefits developers and designers working on related projects. Oulipo品牌设计系统提供了实验计算诗歌的开发和设计指南，包括字体栈和设计一致性指南 Oulipoブランドのデザインシステムは、実験計算詩の開発と設計のためのガイドラインを提供します。フォントスタックやデザインの一貫性に関するガイドラインが含まれます Oulipo 브랜드의 디자인 시스템은 실험 계산 시의 개발과 디자인을 위한 가이드라인을 제공합니다. 폰트 스택과 디자인 일관성에 대한 가이드라인이 포함되어 있습니다 Oulipo-brand es un sistema de diseño y marca para la poesía computacional experimental, que ofrece una guía para la creación de componentes y proyectos relacionados Oulipo-brand est un système de design et de marque pour la poésie computationnelle expérimentale, qui fournit un guide pour la création de composants et de projets liés Oulipo-brand ist ein Design- und Markensystem für experimentelle Computergedichte, das eine Anleitung für die Erstellung von Komponenten und verwandten Projekten bietet O oulipo-brand é um laboratório de poesia computacional experimental que fornece diretrizes de design e sistema de marca para criar projetos relacionados Oulipo-brand - это лаборатория экспериментальной вычислительной поэзии, предоставляющая руководство по дизайну и системе бренда для создания связанных проектов oulipo-brand هو مختبر للشعر الحاسوبي التجريبي الذي يوفر إرشادات للتصميم ونظام العلامة التجارية لإنشاء مشاريع متعلقة how to use oulipo-brand oulipo-brand design system oulipo-brand typography guidelines oulipo-brand alternative oulipo-brand setup guide experimental computational poetry tools Oulipo品牌 实验计算诗歌 设计系统 品牌指南 字体栈 设计一致性 AIエージェント 计算诗歌开发 Reference design system guidelines for building new pages on oulipo.xyz Apply typography guidelines using a specified font stack Ensure design consistency across the site with review guidelines Modify existing oulipo components to match the oulipo aesthetic Create related projects with a consistent design language oulipo-brand is a set of design system and brand guidelines for creating experimental computational poetry projects with a consistent aesthetic.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Atlas-Memory-Framework/AtlasMemory-Cursor-Tools/implementation-planning', 'community', 'Atlas-Memory-Framework', 'AtlasMemory-Cursor-Tools', 'Atlas-Memory-Framework/AtlasMemory-Cursor-Tools', 'implementation-planning', 0, 0, 54, '2026-03-08T01:57:15.496Z', '2026-03-08T02:10:13.329Z', '33236a776b0e2e1ef7cb0b72103a154eb1d25caf90a0348ab813126e684559f6', '{"id":"Atlas-Memory-Framework/AtlasMemory-Cursor-Tools/implementation-planning","name":"implementation-planning","description":{"en":"Implementation-planning generates a draft implementation plan section for build execution, including file deltas and workstreams. It benefits developers working with AtlasMemory.","zh":"实现规划是开发过程中的关键步骤，AIエージェント可以帮助您创建详细的计划，包括文件变化、工作流和集成检查","ja":"実装計画は開発プロセスの重要なステップです。AIエージェントは、ファイルの変更、ワークフロー、統合チェックを含む詳細な計画を作成するのに役立ちます","ko":"구현 계획은 개발 프로세스의 중요한 단계입니다. AI 에이전트는 파일 변경, 워크플로 및 통합 확인을 포함한 자세한 계획을 생성하는 데 도움이 될 수 있습니다","es":"El agente de planificación de implementación crea la sección de plan de implementación para la ejecución de construcción. Genera un borrador de sección que incluye deltas de archivos exhaustivos y workstreams con dependencias.","fr":"L''agent de planification d''implémentation crée la section de plan d''implémentation pour l''exécution de construction. Il génère un brouillon de section qui inclut des deltas de fichiers exhaustifs et des workstreams avec des dépendances.","de":"Der Implementierungsplanungs-Agent erstellt die Implementierungsplan-Sektion für die Build-Ausführung. Er generiert einen Entwurf einer Sektion, der umfassende Dateideltas und Workstreams mit Abhängigkeiten enthält.","pt":"A habilidade de planejamento de implementação cria um plano de implementação para execução de build, incluindo deltas de arquivos exaustivos e workstreams com dependências.","ru":"Навык планирования реализации создает план реализации для выполнения сборки, включая исчерпывающие файловые deltas и потоки работы с зависимостями.","ar":"مهارة التخطيط التنفيذي تُنشئ خطة تنفيذ للبناء، بما في ذلك deltas الملفات الشاملة وworkstreams ذات العلاقات."},"seo":{"title":{"en":"Implementation-Planning: Setup Guide for AI Agents","zh":"AIエージェント实现规划设置指南","ja":"AIエージェントの実装計画ガイド","ko":"AI 에이전트 구현 계획 설정 가이드","es":"Guía de Implementación de Planificación - Herramientas de...","fr":"Guide de Planification d''Implémentation - Outils d''Agent IA","de":"Implementierungsplanungs-Leitfaden - AI Agent Tools","pt":"Guia de Configuração de Planejamento de Implementação com...","ru":"Настройка Планирования Реализации с Помощью ИИ Агентов","ar":"دليل إعداد التخطيط التنفيذي باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Learn how to create a draft implementation plan with exhaustive file deltas, workstreams, and integration checklists. Get started with implementation-plannin...","zh":"了解如何使用AIエージェント实现规划来优化您的开发流程，包括文件变化、工作流和集成检查","ja":"AIエージェントの実装計画を使用して開発プロセスを最適化する方法を学びます。ファイルの変更、ワークフロー、統合チェックを含みます","ko":"AI 에이전트 구현 계획을 사용하여 개발 프로세스를 최적화하는 방법을 배우세요. 파일 변경, 워크플로 및 통합 확인을 포함합니다","es":"Aprende a crear un plan de implementación efectivo con nuestro agente de planificación. Descubre cómo generar un borrador de sección para la ejecución de con...","fr":"Découvrez comment créer un plan d''implémentation efficace avec notre agent de planification. Apprenez à générer un brouillon de section pour l''exécution de c...","de":"Erfahren Sie, wie Sie mit unserem Planungsagenten einen effektiven Implementierungsplan erstellen. Entdecken Sie, wie Sie einen Entwurf einer Sektion für die...","pt":"Aprenda a criar um plano de implementação eficaz com a habilidade de planejamento de implementação, incluindo deltas de arquivos exaustivos e workstreams com...","ru":"Изучите, как создать эффективный план реализации с помощью навыка планирования реализации, включая исчерпывающие файловые deltas и потоки работы с зависимостями","ar":"تعلم كيفية إنشاء خطة تنفيذ فعالة باستخدام مهارة التخطيط التنفيذي، بما في ذلك deltas الملفات الشاملة وworkstreams ذات العلاقات"},"definition":{"en":"Implementation-planning is a skill that creates the Implementation Plan section for build execution, returning a draft section to the orchestrator.","zh":"实现规划是指创建详细的开发计划，包括文件变化、工作流和集成检查，以确保开发项目的顺利执行","ja":"実装計画とは、ファイルの変更、ワークフロー、統合チェックを含む詳細な開発計画を作成することです。開発プロジェクトのスムーズな実行を確保するために必要です","ko":"구현 계획이란 파일 변경, 워크플로 및 통합 확인을 포함한詳細한 개발 계획을 생성하는 것을 의미합니다. 개발 프로젝트의 원활한 진행을 보장하기 위해 필수적입니다","es":"La planificación de implementación es un proceso que implica la creación de un plan detallado para la ejecución de construcción, utilizando herramientas de AI Agent para generar un borrador de sección.","fr":"La planification d''implémentation est un processus qui consiste à créer un plan détaillé pour l''exécution de construction, en utilisant des outils d''Agent IA pour générer un brouillon de section.","de":"Die Implementierungsplanung ist ein Prozess, der die Erstellung eines detaillierten Plans für die Build-Ausführung beinhaltet, unter Verwendung von AI Agent-Tools, um einen Entwurf einer Sektion zu generieren.","pt":"O planejamento de implementação é uma habilidade que cria um plano de implementação para execução de build, incluindo deltas de arquivos e workstreams.","ru":"Планирование реализации - это навык, который создает план реализации для выполнения сборки, включая файловые deltas и потоки работы.","ar":"التخطيط التنفيذي هو مهارة تُنشئ خطة تنفيذ للبناء، بما في ذلك deltas الملفات وworkstreams."},"features":{"en":["Generates exhaustive file deltas with change type and explicit owner","Creates workstreams with dependencies, merge points, and explicitly owned files","Produces an integration/merge points checklist for smooth execution","Runs as a sub-agent to return a draft section to the orchestrator","Enforces implementation plan best practices for AtlasMemory development"],"zh":["文件变化追踪","工作流管理","集成检查","详细的开发计划生成","文件所有权和依赖关系管理","集成点和合并点检查"],"ja":["ファイルの変更追跡","ワークフロー管理","統合チェック","詳細な開発計画の生成","ファイルの所有権と依存関係の管理","統合点とマージポイントのチェック"],"ko":["파일 변경 추적","워크플로 관리","통합 확인","자세한 개발 계획 생성","파일 소유권 및 종속성 관리","통합 점 및 병합 점 확인"],"es":["Generación de deltas de archivos exhaustivos con tipo de cambio, propietario explícito y justificación","Creación de workstreams con dependencias, puntos de fusión y archivos explícitamente propiedad de un agente","Generación de una lista de verificación de puntos de integración y fusión","Enfoque en la ejecución de construcción y la creación de un plan de implementación","Utilización de herramientas de AI Agent para agilizar el proceso de planificación","Capacidad para generar un borrador de sección para la ejecución de construcción"],"fr":["Génération de deltas de fichiers exhaustifs avec type de changement, propriétaire explicite et justification","Création de workstreams avec des dépendances, des points de fusion et des fichiers explicitement propriété d''un agent","Génération d''une liste de vérification des points d''intégration et de fusion","Focus sur l''exécution de construction et la création d''un plan d''implémentation","Utilisation d''outils d''Agent IA pour accélérer le processus de planification","Capacité à générer un brouillon de section pour l''exécution de construction"],"de":["Generierung umfassender Dateideltas mit Änderungstyp, explizitem Eigentümer und Begründung","Erstellung von Workstreams mit Abhängigkeiten, Merge-Punkten und explizit eigentümlichen Dateien","Generierung einer Prüfliste für Integrations- und Merge-Punkte","Fokus auf die Build-Ausführung und die Erstellung eines Implementierungsplans","Verwendung von AI Agent-Tools, um den Planungsprozess zu beschleunigen","Fähigkeit, einen Entwurf einer Sektion für die Build-Ausführung zu generieren"],"pt":["Criação de plano de implementação para execução de build","Inclusão de deltas de arquivos exaustivos com tipo de alteração e proprietário explícito","Definição de workstreams com dependências e pontos de merge","Criação de checklist de integração e pontos de merge","Suporte à execução de gates de integração"],"ru":["Создание плана реализации для выполнения сборки","Включение исчерпывающих файловых deltas с типом изменений и явным владельцем","Определение потоков работы с зависимостями и точками слияния","Создание чек-листа интеграции и точек слияния","Поддержка выполнения шлюзов интеграции"],"ar":["إنشاء خطة تنفيذ للبناء","إدراج deltas الملفات الشاملة مع نوع التغيير والملك الصريح","تحديد workstreams ذات العلاقات ونقاط الدمج","إنشاء قائمة مراجعة للدمج ونقاط الدمج","دعم تشغيل بوابات الدمج"]},"keywords":{"en":["how to use implementation-planning","implementation-planning setup guide","implementation-planning vs competing skills","what is implementation-planning","implementation-planning alternative for AtlasMemory","implementation-planning install for AI agents","implementation-planning tutorial for developers","implementation-planning best practices for build execution"],"zh":["AIエージェント","实现规划","开发流程优化","文件变化追踪","工作流管理","集成检查","开发计划生成","文件所有权管理"],"ja":["AIエージェント","実装計画","開発プロセス最適化","ファイルの変更追跡","ワークフロー管理","統合チェック","開発計画の生成","ファイルの所有権管理"],"ko":["AI 에이전트","구현 계획","개발 프로세스 최적화","파일 변경 추적","워크플로 관리","통합 확인","개발 계획 생성","파일 소유권 관리"],"es":["planificación de implementación","herramientas de AI Agent","ejecución de construcción","generación de deltas de archivos","workstreams con dependencias","puntos de integración y fusión","plan de implementación","AI Agent para la planificación","desarrollo de software","ingeniería de software"],"fr":["planification d''implémentation","outils d''Agent IA","exécution de construction","génération de deltas de fichiers","workstreams avec des dépendances","points d''intégration et de fusion","plan d''implémentation","Agent IA pour la planification","développement de logiciels","ingénierie de logiciels"],"de":["Implementierungsplanung","AI Agent-Tools","Build-Ausführung","Generierung umfassender Dateideltas","Workstreams mit Abhängigkeiten","Integrations- und Merge-Punkte","Implementierungsplan","AI Agent für die Planung","Software-Entwicklung","Software-Ingenieurwesen"],"pt":["planejamento de implementação","ferramentas de inteligência artificial","desenvolvimento de software","execução de build","deltas de arquivos","workstreams","pontos de merge","integração contínua","gates de integração"],"ru":["планирование реализации","ИИ агенты","разработка программного обеспечения","выполнение сборки","файловые deltas","потоки работы","точки слияния","непрерывная интеграция","шлюзы интеграции"],"ar":["تخطيط التنفيذ","أدوات الذكاء الاصطناعي","تطوير البرمجيات","تنفيذ البناء","deltas الملفات","workstreams","نقاط الدمج","الدمج المستمر","بوابات الدمج"]}},"owner":"Atlas-Memory-Framework","repo":"AtlasMemory-Cursor-Tools","repoPath":"Atlas-Memory-Framework/AtlasMemory-Cursor-Tools","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.496Z","topics":[],"category":"community","skillMd":{"name":"implementation-planning","description":"Produce the execution plan in the current plan artifact including file deltas, workstreams, phases, and gates. Use during /plan Implementation stage.","bodyPreview":"# /implementation-planning\n\n## Purpose\nCreate the Implementation Plan section for build execution. Run as a sub-agent and return a draft section to the orchestrator; do not write the plan artifact directly.\n\n## Required outputs\n- Exhaustive file deltas with change type, explicit owner (existing agent/WS), and rationale.\n- Workstreams with dependencies, merge points, and explicitly owned files.\n- An integration / merge points checklist (what gets integrated, how, and what gates run).\n- Enforce th","body":"# /implementation-planning\n\n## Purpose\nCreate the Implementation Plan section for build execution. Run as a sub-agent and return a draft section to the orchestrator; do not write the plan artifact directly.\n\n## Required outputs\n- Exhaustive file deltas with change type, explicit owner (existing agent/WS), and rationale.\n- Workstreams with dependencies, merge points, and explicitly owned files.\n- An integration / merge points checklist (what gets integrated, how, and what gates run).\n- Enforce the workstream file-ownership rule: each file delta is owned by exactly one workstream until an explicit merge point.\n- Phases and tasks mapped to workstreams/owners.\n- Evidence-based exit criteria per phase.\n- Build-time gates for each phase.\n- Test Plan including at least a minimal test matrix (risk -> test type -> where it runs).\n- Rollout/Deployment steps (even minimal) and an explicit rollback trigger + rollback steps.\n - Draft section content for `## Implementation Plan`\n\n## Anti-placeholder rule (hard rule)\n- Do not use placeholder language like “run smoke tests” or “add gates” without naming:\n  - the gate name(s),\n  - where they run (CI vs local vs deployed), and\n  - the entrypoint/command (or test runner/target) and what “green” means.\n- If specifics are truly unknown, convert them into either:\n  - an explicit Decision boundary (A/B/C) with a recommended default, OR\n  - a DR-backed Defer with an explicit trigger.\n\n## Q/A wrapper\n- The orchestrator must run the inline Q/A loop to confirm user understanding and agreement on scope, ownership, and gates.\n\n## Ownership policy\n- Prefer existing agents from the plan''s `## Context Snapshot` or the user-provided roster.\n- If no roster is available, return `Questions` asking for the available agents/owners before assigning work.\n- Do not default all ownership to the user unless the user explicitly requests it.\n\n## Parallel workstreams / multi-agent contract (hard rule)\n- If the user requests multiple agents or parallel workstreams:\n  - Ensure the draft includes an explicit **agent roster** (names/handles) and assigns ownership for each workstream and file-delta cluster.\n  - If the roster is missing, ask a single focused question to obtain it (do not guess).\n  - The orchestrator should mirror this roster into `## Context Snapshot` (call this out explicitly in `Notes` if needed).\n\n## Sub-agent output contract\nReturn a single block in this shape:\n\n```md\nDraftSection:\n<exact section content for ## Implementation Plan (must include the section header)>\n\nChecklist:\n- <criterion>: Pass | Fail\n\nQuestions:\n- <if blocked>\n\nNotes:\n- <optional risks/assumptions/tests updates>\n```\n\n## Malformed output handling\n- If you cannot produce the exact section header or required fields, return `Questions` explaining what is missing and leave `DraftSection` as `N/A`.\n\n## User experience rule (no \"go read the plan\")\n- When asking the user to confirm plan readiness, paste the key parts directly in the chat response:\n  - File deltas (owned)\n  - Workstreams + owned files + merge points\n  - Phase list with exit criteria\n  - Test matrix + rollback\n\n## Output template (required for PlanTier: Full)\nUse this exact structure so the `/plan` validator can deterministically check executability:\n\n```md\n## Implementation Plan\n### Agent roster (required for PlanTier: Full)\n- <agent/owner>: <responsibilities>\n\n### File Deltas (exhaustive) + rationale\n- path/to/file.ext - change type (create/modify/delete) - owner (WSx / agent) - rationale\n\n### Workstreams + merge points\n- WS1: <name>\n  - Owner:\n  - Depends on:\n  - Review gates (named):\n    - G-...\n  - Owns files:\n    - path/to/file.ext\n  - Merge point / integration step:\n\n### Phases + tasks + exit criteria\n#### Phase 1: <name>\n- Owner(s):\n- Depends on:\n- Tasks (by owner):\n  - Owner: <agent>\n    - [ ] Task\n- Exit criteria (evidence):\n- Gates (named):\n  - G-...\n\n### Review gates (named + definitions)\n- G-...:\n  - Where it runs: CI | Local | Deployed\n  - Entry point / command:\n  - Green means:\n\n### Merge points -> required gates\n- MP1: <merge point>\n  - Blocks on:\n    - G-...\n\n### Test Matrix\n- Area/component - risk - test type - where it runs\n\n### Test plan (CI vs deployed)\n- CI:\n  - ...\n- Deployed environment:\n  - ...\n\n### Rollout / Rollback\n- Rollout:\n- Rollback trigger:\n- Rollback steps:\n```\n"},"lastSynced":"2026-03-08T02:10:13.329Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, or Claude Code that require detailed build execution planning with file deltas and workstreams.","zh":"适合于Cursor、Windsurf或Claude Code等需要详细构建执行计划、文件变更和工作流的AI代理。","ja":"Cursor、Windsurf、またはClaude Codeなどの詳細なビルド実行計画とファイルデルタおよびワークフローを必要とするAIエージェントに適しています。","ko":"Cursor, Windsurf 또는 Claude Code와 같은 파일 델타 및 워크스트림이 포함된 자세한 빌드 실행 계획을 필요로 하는 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA como Cursor, Windsurf o Claude Code que requieren una planificación detallada de la ejecución de la compilación con deltas de archivos y flujos de trabajo.","fr":"Idéal pour les agents IA comme Cursor, Windsurf ou Claude Code qui nécessitent une planification détaillée de l''exécution de la construction avec des deltas de fichiers et des flux de travail.","de":"Ideal für KI-Agents wie Cursor, Windsurf oder Claude Code, die eine detaillierte Build-Ausführungsplanung mit Dateideltas und Arbeitsflüssen erfordern.","pt":"Ideal para Agentes de IA como Cursor, Windsurf ou Claude Code que requerem planejamento de execução de compilação detalhado com deltas de arquivos e fluxos de trabalho.","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf или Claude Code, которые требуют детального планирования выполнения сборки с дельтами файлов и потоками работы.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Cursor و Windsurf أو Claude Code التي تتطلب تخطيط تنفيذ بناء مفصل مع دلتا الملفات و تدفقات العمل."},"recommendation":{"en":"Empowers agents to generate exhaustive file deltas with change type, explicit owner, and rationale, while also creating workstreams with dependencies and merge points, utilizing AtlasMemory for efficient development workflows.","zh":"赋予代理生成详细的文件变更，包括变更类型、明确所有者和理由，同时利用AtlasMemory创建具有依赖关系和合并点的工作流，从而实现高效的开发工作流程。","ja":"エージェントに、変更タイプ、明示的な所有者、理由を含む詳細なファイルデルタを生成する能力を与え、同時にAtlasMemoryを利用して依存関係とマージポイントを持つワークフローを作成し、効率的な開発ワークフローを実現します。","ko":"에이전트가 변경 유형, 명시적 소유자 및 이유를 포함하는详细한 파일 델타를 생성하도록 하며,同時に AtlasMemory를 사용하여 의존성 및 병합 지점을 갖는 워크스트림을 생성하여 효율적인 개발 워크플로우를实现합니다.","es":"Habilita a los agentes a generar deltas de archivos exhaustivos con tipo de cambio, propietario explícito y justificación, al tiempo que crea flujos de trabajo con dependencias y puntos de fusión, utilizando AtlasMemory para flujos de trabajo de desarrollo eficientes.","fr":"Permet aux agents de générer des deltas de fichiers exhaustifs avec type de modification, propriétaire explicite et justification, tout en créant des flux de travail avec des dépendances et des points de fusion, en utilisant AtlasMemory pour des flux de travail de développement efficaces.","de":"Ermächtigt Agents, umfassende Dateideltas mit Änderungstyp, explizitem Besitzer und Begründung zu generieren, während auch Arbeitsflüsse mit Abhängigkeiten und Merge-Punkten erstellt werden, wobei AtlasMemory für effiziente Entwicklungsworkflows verwendet wird.","pt":"Habilita os agentes a gerar deltas de arquivos exaustivos com tipo de alteração, proprietário explícito e justificativa, enquanto também cria fluxos de trabalho com dependências e pontos de mesclagem, utilizando AtlasMemory para fluxos de trabalho de desenvolvimento eficientes.","ru":"Позволяет агентам генерировать исчерпывающие дельты файлов с типом изменения, явным владельцем и обоснованием, а также создавать потоки работы с зависимостями и точками слияния, используя AtlasMemory для эффективных рабочих процессов разработки.","ar":"يمنح العميل القدرة على توليد دلتا الملفات الشاملة مع نوع التغيير و المالك الصريح و المبرر، في حين يخلق أيضًا تدفقات العمل مع الاعتماديات و نقاط الدمج، باستخدام AtlasMemory من أجل سير عمل التطوير الفعال."},"useCases":{"en":["Automating implementation plan generation for build execution","Generating exhaustive file deltas with explicit ownership and rationale","Creating workstreams with dependencies, merge points, and owned files for efficient development"],"zh":["为构建执行生成自动化实施计划","生成具有明确所有权和理由的详细文件变更","创建具有依赖关系、合并点和所有权文件的工作流以实现高效开发"],"ja":["ビルド実行の自動実装計画の生成","明示的な所有権と理由を持つ詳細なファイルデルタの生成","依存関係、合并点、所有ファイルを持つワークフローの作成による効率的な開発"],"ko":["빌드 실행을 위한 자동화 구현 계획 생성","명시적 소유권 및 이유를 갖는详细한 파일 델타 생성","의존성, 병합 지점, 소유 파일을 갖는 워크스트림 생성을 통한 효율적인 개발"],"es":["Automatización de la generación de planes de implementación para la ejecución de la compilación","Generación de deltas de archivos exhaustivos con propiedad explícita y justificación","Creación de flujos de trabajo con dependencias, puntos de fusión y archivos propiedad para un desarrollo eficiente"],"fr":["Automatisation de la génération de plans d''implémentation pour l''exécution de la construction","Génération de deltas de fichiers exhaustifs avec propriété explicite et justification","Création de flux de travail avec des dépendances, des points de fusion et des fichiers propriétaires pour un développement efficace"],"de":["Automatisierung der Generierung von Implementierungsplänen für die Build-Ausführung","Generierung umfassender Dateideltas mit explizitem Besitzer und Begründung","Erstellung von Arbeitsflüssen mit Abhängigkeiten, Merge-Punkten und eigenen Dateien für effizientes Entwickeln"],"pt":["Automatizar a geração de planos de implementação para execução de compilação","Gerar deltas de arquivos exaustivos com propriedade explícita e justificativa","Criar fluxos de trabalho com dependências, pontos de mesclagem e arquivos proprietários para desenvolvimento eficiente"],"ru":["Автоматизировать генерацию планов реализации для выполнения сборки","Генерировать исчерпывающие дельты файлов с явным владением и обоснованием","Создавать потоки работы с зависимостями, точками слияния и файлами-владельцами для эффективной разработки"],"ar":["تأتمة توليد خطط التنفيذ للمجمع","توليد دلتا الملفات الشاملة مع الملكية الصريحة و المبرر","إنشاء تدفقات العمل مع الاعتماديات و نقاط الدمج و الملفات المملوكة من أجل التطوير الفعال"]},"limitations":{"en":["Requires AtlasMemory for development workflows","Must be run as a sub-agent to return draft implementation plans to the orchestrator"],"zh":["需要AtlasMemory进行开发工作流程","必须作为子代理运行以将草稿实施计划返回给编排器"],"ja":["開発ワークフローにAtlasMemoryが必要","下位エージェントとして実行して、下書き実装計画をオーケストレーターに返す"],"ko":["개발 워크플로우에 AtlasMemory가 필요","하위 에이전트로서 실행하여 초안 구현 계획을 오케스트레이터에 반환"],"es":["Requiere AtlasMemory para flujos de trabajo de desarrollo","Debe ejecutarse como subagente para devolver planes de implementación provisionales al orquestador"],"fr":["Nécessite AtlasMemory pour les flux de travail de développement","Doit être exécuté en tant que sous-agent pour renvoyer des plans d''implémentation provisoires à l''orchestrateur"],"de":["Benötigt AtlasMemory für Entwicklungsworkflows","Muss als Sub-Agent ausgeführt werden, um Entwurfs-Implementierungspläne an den Orchestrator zurückzugeben"],"pt":["Requer AtlasMemory para fluxos de trabalho de desenvolvimento","Deve ser executado como sub-agente para retornar planos de implementação de rascunho para o orquestrador"],"ru":["Требует AtlasMemory для рабочих процессов разработки","Должно быть запущено как подагент, чтобы вернуть черновые планы реализации оркестратору"],"ar":["يتطلب AtlasMemory من أجل سير عمل التطوير","يجب تشغيله كعميل فرعي لإرجاع مسودات خطط التنفيذ إلى المنسق"]},"version":4},"contentHash":"33236a776b0e2e1ef7cb0b72103a154eb1d25caf90a0348ab813126e684559f6","qualityScore":54}');
