INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dezverev/AnimalAL-v1/sync-providers', 'sync-providers', 'dezverev', 'AnimalAL-v1', 'community', 'sync-providers dezverev AnimalAL-v1 community The sync-providers skill keeps providers in src/Plugins/Providers/ aligned with their interfaces, benefiting developers working with multiple providers. It ensures consistency after interface changes or new method additions. sync-providers 是一个保持真实和假设提供者与接口同步的工具，用于提高开发效率 sync-providers は、提供者パターンを同期させて開発効率を向上させるツールです sync-providers는 실제 및 가상 제공자를 인터페이스와 동기화하여 개발 효율성을 높이는 도구입니다 Sync-providers mantiene proveedores reales y falsos alineados con sus interfaces en proyectos de desarrollo Sync-providers garde les fournisseurs réels et fictifs alignés sur leurs interfaces dans vos projets de développement Sync-providers hält reale und fake-Provider mit ihren Schnittstellen in Entwicklungsvorhaben abgestimmt O sync-providers é uma ferramenta que mantém provedores reais e falsos alinhados com suas interfaces. Use após alterações de interface ou ao adicionar novos métodos de provedor. Sync-providers - это инструмент, который поддерживает реальных и фальшивых провайдеров в согласии с их интерфейсами. Используйте после изменений интерфейса или при добавлении новых методов провайдера. sync-providers هو أداة تحافظ على مقدمي الخدمات الحقيقيين والزائفين مع واجهاتهم. استخدم بعد تغييرات الواجهة أو عند إضافة أساليب جديدة لمقدم الخدمة. how to use sync-providers sync-providers setup guide provider pattern synchronization sync-providers alternative sync-providers vs interface management tools sync-providers install what is sync-providers sync-providers tutorial sync-providers best practices sync-providers AIエージェント 提供者接口同步 开发效率 Provider Pattern 同步 自动修复 接口管理 开发工具 Checks all providers using /sync-providers command Supports checking individual providers like ICalendarDataProvider Auto-fixes missing stubs with /sync-providers --fix option Keeps providers in src/Plugins/Providers/ aligned with their interfaces Ensures consistency after interface changes or new method additions Works with multiple providers for streamlined development sync-providers is a synchronization tool that keeps real and fake providers in alignment with their interfaces, ensuring consistency and accuracy in development workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Sivanwol/freelancer-site/review-implementing', 'community', 'Sivanwol', 'freelancer-site', 'Sivanwol/freelancer-site', 'review-implementing', 0, 0, 54, '2026-03-08T01:57:15.497Z', '2026-03-08T02:10:15.564Z', '110c53375da762f5451f34f9e5daaa41dbcf52389e519880d2dcf8b2bb5f8ded', '{"id":"Sivanwol/freelancer-site/review-implementing","name":"review-implementing","description":{"en":"The review-implementing skill helps developers systematically process and implement code review feedback, benefiting teams who use PR review notes and reviewer comments.","zh":"代码审查反馈实施系统，能够解析审查员注释、处理编号列表和项目符号，并实施更改","ja":"コードレビューフィードバック実装システムは、レビューアーの注釈を解析し、番号付きリストと箇条書きを処理し、変更を実装します","ko":"코드 리뷰 피드백 구현 시스템은 리뷰어의 주석을 해석하고 번호가 있는 목록과 항목을 처리하여 변경 사항을 구현합니다","es":"El proceso de implementación de revisión de código implica la identificación y aplicación sistemática de comentarios de revisión. Esta guía cubre los pasos clave para implementar cambios en tu código.","fr":"Le processus de mise en œuvre de la revue de code implique l''identification et l''application systématique des commentaires de revue. Ce guide couvre les étapes clés pour implémenter des modifications dans votre code.","de":"Der Prozess der Implementierung von Code-Review umfasst die systematische Identifizierung und Anwendung von Review-Kommentaren. Dieser Leitfaden deckt die wichtigsten Schritte zur Implementierung von Änderungen in Ihrem Code ab.","pt":"Implemente revisões de código de forma sistemática com ferramentas de IA. Processar e implementar mudanças baseadas em feedback de revisão de código.","ru":"Реализуйте обзор кода систематически с помощью ИИ Агентов. Обрабатывайте и внедряйте изменения на основе обратной связи по обзору кода.","ar":"نفذ مراجعات الكود بشكل منهجي باستخدام أدوات الذكاء الاصطناعي. معالجة وتنفيذ التغييرات dựa على ملاحظات مراجعة الكود"},"seo":{"title":{"en":"Review-Implementing: Systematic Code Review Feedback Setu...","zh":"代码审查反馈实施指南","ja":"コードレビューフィードバック実装ベストプラクティス","ko":"코드 리뷰 피드백 구현 설정 가이드","es":"Guía de Implementación de Revisión de Código con Herramie...","fr":"Mise en Œuvre de la Revue de Code avec Outils d''Intellige...","de":"Leitfaden zur Implementierung von Code-Review mit KI-Tools","pt":"Guia de Implementação de Revisão de Código com Ferramenta...","ru":"Руководство по реализации обзора кода с помощью ИИ Агентов","ar":"دليل تنفيذ مراجعة الكود باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Streamline your code review process with review-implementing. Learn how to systematically process and implement changes based on feedback. Get started now!","zh":"系统地处理和实施代码审查反馈，提高代码质量和开发效率","ja":"コードレビューフィードバックを体系的に処理して実装し、コード品質と開発効率を向上させる","ko":"코드 리뷰 피드백을 체계적으로 처리하고 구현하여 코드 품질과 개발 효율성을 높입니다","es":"Aprende a implementar cambios en tu código basado en comentarios de revisión con herramientas de AI. Mejora tu flujo de trabajo con nuestra guía","fr":"Découvrez comment implémenter des modifications dans votre code en fonction des commentaires de revue avec des outils d''IA. Améliorez votre flux de travail a...","de":"Erfahren Sie, wie Sie Änderungen in Ihrem Code basierend auf Review-Kommentaren mit KI-Tools implementieren. Verbessern Sie Ihren Arbeitsablauf mit unserem L...","pt":"Aprenda a implementar revisões de código com eficiência usando ferramentas de IA. Descubra como processar e implementar mudanças baseadas em feedback de revi...","ru":"Узнайте, как эффективно реализовывать обзор кода с помощью ИИ Агентов. Откройте для себя, как систематически обрабатывать и внедрять изменения на основе обра...","ar":"تعلم كيفية تنفيذ مراجعات الكود بفعالية باستخدام أدوات الذكاء الاصطناعي. اكتشف كيفية معالجة وتنفيذ التغييرات dựa على ملاحظات مراجعة الكود"},"definition":{"en":"review-implementing is a systematic workflow for processing and implementing code review feedback, handling items such as numbered lists and bullet points.","zh":"代码审查反馈实施是指根据代码审查的反馈结果进行代码修改和优化的过程","ja":"コードレビューフィードバック実装とは、コードレビューのフィードバック結果に基づいてコードを変更し、最適化するプロセスです","ko":"코드 리뷰 피드백 구현은 코드 리뷰의 피드백 결과를 기반으로 코드를 수정하고 최적화하는 과정입니다","es":"La implementación de revisión de código es el proceso de aplicación sistemática de comentarios de revisión para mejorar la calidad del código","fr":"La mise en œuvre de la revue de code est le processus d''application systématique des commentaires de revue pour améliorer la qualité du code","de":"Die Implementierung von Code-Review ist der Prozess der systematischen Anwendung von Review-Kommentaren zur Verbesserung der Code-Qualität","pt":"O que é revisão de código? É o processo de revisar e implementar mudanças baseadas em feedback de revisão de código.","ru":"Что такое обзор кода? Это процесс реализации изменений на основе обратной связи по обзору кода.","ar":"ما هي مراجعة الكود؟ هي عملية مراجعة وتنفيذ التغييرات dựa على ملاحظات مراجعة الكود"},"features":{"en":["Parses reviewer notes to identify individual feedback items","Handles numbered lists and bullet points for organized feedback","Supports systematic workflow for implementing review suggestions","Processes PR review notes for efficient feedback implementation","Splits numbered lists for easy feedback item identification"],"zh":["解析审查员注释","处理编号列表和项目符号","实施代码更改","支持PR审查笔记","处理审查员反馈项目"],"ja":["レビューアーの注釈を解析","番号付きリストと箇条書きを処理","コードの変更を実装","PRレビューノートをサポート","レビューアーのフィードバック項目を処理"],"ko":["리뷰어의 주석을 해석","번호가 있는 목록과 항목을 처리","코드 변경 사항을 구현","PR 리뷰 노트 지원","리뷰어의 피드백 항목을 처리"],"es":["Identificación de elementos de comentarios de revisión","Procesamiento de listas numeradas y de puntos","Implementación sistemática de cambios en el código","Uso de herramientas de AI para mejorar el flujo de trabajo","Análisis de notas de revisión y comentarios de los revisores"],"fr":["Identification d''éléments de commentaires de revue","Traitement de listes numérotées et de points","Mise en œuvre systématique de modifications dans le code","Utilisation d''outils d''IA pour améliorer le flux de travail","Analyse de notes de revue et de commentaires des réviseurs"],"de":["Identifizierung von Elementen von Review-Kommentaren","Verarbeitung von nummerierten und punktierten Listen","Systematische Implementierung von Änderungen im Code","Verwendung von KI-Tools zur Verbesserung des Arbeitsablaufs","Analyse von Review-Notizen und Kommentaren der Rezensenten"],"pt":["Processamento sistemático de feedback de revisão de código","Implementação de mudanças baseadas em feedback de revisão de código","Análise de itens de feedback individuais","Tratamento de listas numeradas e de itens","Implementação de sugestões de revisão de código"],"ru":["Систематическая обработка обратной связи по обзору кода","Внедрение изменений на основе обратной связи по обзору кода","Анализ отдельных элементов обратной связи","Обработка пронумерованных списков и пунктов","Реализация предложений по обзору кода"],"ar":["معالجة منهجية لملاحظات مراجعة الكود","تنفيذ التغييرات dựa على ملاحظات مراجعة الكود","تحليل عناصر ملاحظات فردية","معالجة القوائم المرقمة والنقاط","تنفيذ اقتراحات مراجعة الكود"]},"keywords":{"en":["how to use review-implementing","review-implementing alternative","review-implementing setup guide","what is review-implementing","review-implementing vs code review tools","review-implementing install for AI agents"],"zh":["代码审查反馈","代码审查实施","代码优化","代码修改","AI代码审查工具","代码审查最佳实践"],"ja":["コードレビューフィードバック","コードレビュー実装","コード最適化","コード変更","AIコードレビューツール","コードレビューベストプラクティス"],"ko":["코드 리뷰 피드백","코드 리뷰 구현","코드 최적화","코드 수정","AI 코드 리뷰 도구","코드 리뷰 최선의 관행"],"es":["herramientas de AI para revisión de código","implementación de revisión de código","mejora del flujo de trabajo con AI","análisis de comentarios de revisión","identificación de elementos de comentarios de revisión","desarrollo de software con AI","revisión de código automatizada","herramientas de desarrollo de software"],"fr":["outils d''IA pour la revue de code","mise en œuvre de la revue de code","amélioration du flux de travail avec l''IA","analyse de commentaires de revue","identification d''éléments de commentaires de revue","développement de logiciels avec l''IA","revue de code automatisée","outils de développement de logiciels"],"de":["KI-Tools für Code-Review","Implementierung von Code-Review","Verbesserung des Arbeitsablaufs mit KI","Analyse von Review-Kommentaren","Identifizierung von Elementen von Review-Kommentaren","Software-Entwicklung mit KI","automatisierte Code-Review","Software-Entwicklungstools"],"pt":["revisão de código","ferramentas de IA","implementação de feedback","processamento de feedback","análise de itens de feedback","desenvolvimento de software","revisão de código sistemática"],"ru":["обзор кода","ИИ Агенты","реализация обратной связи","обработка обратной связи","анализ элементов обратной связи","разработка программного обеспечения","систематический обзор кода"],"ar":["مراجعة الكود","أدوات الذكاء الاصطناعي","تنفيذ ملاحظات","معالجة ملاحظات","تحليل عناصر ملاحظات","تطوير البرمجيات","مراجعة الكود المنهجية"]}},"owner":"Sivanwol","repo":"freelancer-site","repoPath":"Sivanwol/freelancer-site","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.497Z","topics":[],"category":"community","skillMd":{"name":"review-implementing","description":"Process and implement code review feedback systematically. Use when user provides reviewer comments, PR feedback, code review notes, or asks to implement suggestions from reviews.","bodyPreview":"# Review Feedback Implementation\n\nSystematically process and implement changes based on code review feedback.\n\n## When to Use\n\n- Provides reviewer comments or feedback\n- Pastes PR review notes\n- Mentions implementing review suggestions\n- Says \"address these comments\" or \"implement feedback\"\n- Shares list of changes requested by reviewers\n\n## Systematic Workflow\n\n### 1. Parse Reviewer Notes\n\nIdentify individual feedback items:\n- Split numbered lists (1., 2., etc.)\n- Handle bullet points or unnumb","body":"# Review Feedback Implementation\n\nSystematically process and implement changes based on code review feedback.\n\n## When to Use\n\n- Provides reviewer comments or feedback\n- Pastes PR review notes\n- Mentions implementing review suggestions\n- Says \"address these comments\" or \"implement feedback\"\n- Shares list of changes requested by reviewers\n\n## Systematic Workflow\n\n### 1. Parse Reviewer Notes\n\nIdentify individual feedback items:\n- Split numbered lists (1., 2., etc.)\n- Handle bullet points or unnumbered feedback\n- Extract distinct change requests\n- Clarify ambiguous items before starting\n\n### 2. Create Todo List\n\nUse TodoWrite tool to create actionable tasks:\n- Each feedback item becomes one or more todos\n- Break down complex feedback into smaller tasks\n- Make tasks specific and measurable\n- Mark first task as `in_progress` before starting\n\nExample:\n```\n- Add type hints to extract function\n- Fix duplicate tag detection logic\n- Update docstring in chain.py\n- Add unit test for edge case\n```\n\n### 3. Implement Changes Systematically\n\nFor each todo item:\n\n**Locate relevant code:**\n- Use Grep to search for functions/classes\n- Use Glob to find files by pattern\n- Read current implementation\n\n**Make changes:**\n- Use Edit tool for modifications\n- Follow project conventions (CLAUDE.md)\n- Preserve existing functionality unless changing behavior\n\n**Verify changes:**\n- Check syntax correctness\n- Run relevant tests if applicable\n- Ensure changes address reviewer''s intent\n\n**Update status:**\n- Mark todo as `completed` immediately after finishing\n- Move to next todo (only one `in_progress` at a time)\n\n### 4. Handle Different Feedback Types\n\n**Code changes:**\n- Use Edit tool for existing code\n- Follow type hint conventions (PEP 604/585)\n- Maintain consistent style\n\n**New features:**\n- Create new files with Write tool if needed\n- Add corresponding tests\n- Update documentation\n\n**Documentation:**\n- Update docstrings following project style\n- Modify markdown files as needed\n- Keep explanations concise\n\n**Tests:**\n- Write tests as functions, not classes\n- Use descriptive names\n- Follow pytest conventions\n\n**Refactoring:**\n- Preserve functionality\n- Improve code structure\n- Run tests to verify no regressions\n\n### 5. Validation\n\nAfter implementing changes:\n- Run affected tests\n- Check for linting errors: `uv run ruff check`\n- Verify changes don''t break existing functionality\n\n### 6. Communication\n\nKeep user informed:\n- Update todo list in real-time\n- Ask for clarification on ambiguous feedback\n- Report blockers or challenges\n- Summarize changes at completion\n\n## Edge Cases\n\n**Conflicting feedback:**\n- Ask user for guidance\n- Explain conflict clearly\n\n**Breaking changes required:**\n- Notify user before implementing\n- Discuss impact and alternatives\n\n**Tests fail after changes:**\n- Fix tests before marking todo complete\n- Ensure all related tests pass\n\n**Referenced code doesn''t exist:**\n- Ask user for clarification\n- Verify understanding before proceeding\n\n## Important Guidelines\n\n- **Always use TodoWrite** for tracking progress\n- **Mark todos completed immediately** after each item\n- **Only one todo in_progress** at any time\n- **Don''t batch completions** - update status in real-time\n- **Ask questions** for unclear feedback\n- **Run tests** if changes affect tested code\n- **Follow CLAUDE.md conventions** for all code changes\n- **Use conventional commits** if creating commits afterward\n"},"lastSynced":"2026-03-08T02:10:15.564Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing systematic feedback implementation and PR note analysis.","zh":"非常适合需要系统化反馈实现和 PR 笔记分析的代码审查代理。","ja":"コードレビュー代理が体系的なフィードバックの実装と PR ノートの分析を必要とする場合に最適です。","ko":"시스템적인 피드백 구현과 PR 노트 분석이 필요한 코드 리뷰 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan implementación de comentarios sistemáticos y análisis de notas de PR.","fr":"Parfait pour les Agents de Révision de Code nécessitant une mise en œuvre de commentaires systématiques et d''analyse de notes de PR.","de":"Perfekt für Code-Review-Agenten, die eine systematische Umsetzung von Feedback und Analyse von PR-Notizen benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de implementação de feedback sistemática e análise de notas de PR.","ru":"Идеально для агентов кодового обзора, требующих системной реализации обратной связи и анализа заметок PR.","ar":"مثالي لعمليات المراجعة البرمجية التي تحتاج إلى تنفيذ متماسك للتعليقات و تحليل ملاحظات_PR."},"recommendation":{"en":"Empowers agents to systematically process and implement code review feedback, handling reviewer comments, and parsing PR review notes with precision, utilizing techniques like splitting numbered lists and handling bullet points.","zh":"赋予代理系统地处理和实现代码审查反馈，处理审查者评论，并使用诸如拆分编号列表和处理项目符号等技术来解析 PR 审查笔记，以精确度利用它们。","ja":"エージェントがコードレビューのフィードバックを体系的に処理および実装し、レビューアーのコメントを処理し、番号付きリストを分割したりバレットポイントを処理したりするなどのテクニックを使用して PR レビュー ノートを精密に解析することを可能にします。","ko":"에이전트가 코드 리뷰 피드백을 체계적으로 처리하고 구현하고, 리뷰어의 댓글을 처리하며, 번호가 매겨진 목록을 분할하거나 글머리 기호를 처리하는 등의 기술을 사용하여 PR 리뷰 노트를 정확하게 파싱하여 활용할 수 있도록 합니다.","es":"Habilita a los agentes a procesar y implementar sistemáticamente los comentarios de revisión de código, manejar comentarios de revisores y analizar notas de revisión de PR con precisión, utilizando técnicas como la división de listas numeradas y el manejo de puntos de bala, utilizando herramientas como React, Python, CLI, API y otros frameworks.","fr":"Permet aux agents de traiter et de mettre en œuvre systématiquement les commentaires de révision de code, de gérer les commentaires des réviseurs et d''analyser les notes de révision de PR avec précision, en utilisant des techniques comme le fractionnement de listes numérotées et la gestion de points de balle, en utilisant des outils tels que React, Python, CLI, API et d''autres frameworks.","de":"Ermöglicht es Agenten, Code-Review-Feedback und PR-Review-Notizen präzise zu verarbeiten und umzusetzen, Kommentare von Reviewern zu handhaben und Techniken wie das Aufteilen von nummerierten Listen und das Handhaben von Aufzählungspunkten anzuwenden, unter Nutzung von Tools wie React, Python, CLI, API und anderen Frameworks.","pt":"Habilita os agentes a processar e implementar sistematicamente a feedback de revisão de código, lidando com comentários de revisores e analisando notas de revisão de PR com precisão, utilizando técnicas como divisão de listas numeradas e tratamento de pontos de bala.","ru":"Наделяет агентов возможностью систематически обрабатывать и реализовывать обратную связь по коду, обрабатывая комментарии рецензентов и анализируя заметки обзора PR с точностью, используя такие методы, как разделение пронумерованных списков и обработка маркированных пунктов.","ar":"تمكّن الوكلاء من معالجة وتنفيذ ملاحظات المراجعة البرمجية بشكل منهجي، و التعامل مع تعليقات المراجعين و تحليل ملاحظات المراجعة البرمجية بدقة، مستخدمين تقنيات مثل تقسيم القوائم المرقمة و معالجة نقاط الرصاص."},"useCases":{"en":["Automating code changes based on reviewer feedback","Parsing PR review notes for actionable items","Implementing systematic workflows for code review feedback"],"zh":["基于审查者反馈自动执行代码更改","解析 PR 审查笔记以获取可执行项目","为代码审查反馈实现系统化工作流"],"ja":["レビューアーのフィードバックに基づいてコードの変更を自動化する","PR レビュー ノートを解析して実行可能なアイテムを取得する","コード レビュー フィードバックのシステム化されたワークフローを実装する"],"ko":["리뷰어의 피드백을 기반으로 코드 변경을 자동화하는 것","PR 리뷰 노트를 파싱하여 실행 가능한 항목을 얻는 것","코드 리뷰 피드백을 위한 체계적인 워크플ロー 구현"],"es":["Automatización de cambios de código basados en comentarios de revisores","Análisis de notas de revisión de PR para elementos realizables","Implementación de flujos de trabajo sistemáticos para comentarios de revisión de código"],"fr":["Automatisation des modifications de code basées sur les commentaires des réviseurs","Analyse des notes de révision de PR pour les éléments réalisables","Mise en œuvre de flux de travail systématiques pour les commentaires de révision de code"],"de":["Automatisierung von Code-Änderungen basierend auf Reviewer-Kommentaren","Analyse von PR-Review-Notizen für umsetzbare Elemente","Implementierung systematischer Workflows für Code-Review-Feedback"],"pt":["Automatizar alterações de código com base na feedback de revisor","Analizar notas de revisão de PR para itens acionáveis","Implementar fluxos de trabalho sistemáticos para feedback de revisão de código"],"ru":["Автоматизировать изменения кода на основе обратной связи рецензента","Анализировать заметки обзора PR для пунктов действий","Реализовывать системные рабочие процессы для обратной связи по коду"],"ar":["التحكم الآلي في تغييرات الكود بناءً على ملاحظات المراجع","تحليل ملاحظات المراجعة البرمجية للعناصر القابلة للتنفيذ","تنفيذ سير عمل منهجي لملاحظات المراجعة البرمجية"]},"limitations":{"en":["Requires access to code review feedback and PR notes","Limited to text-based feedback analysis"],"zh":["需要访问代码审查反馈和 PR 笔记","仅限于基于文本的反馈分析"],"ja":["コード レビュー フィードバックと PR ノートへのアクセスが必要","テキスト ベースのフィードバック分析のみに限定される"],"ko":["코드 리뷰 피드백과 PR 노트에 대한 액세스가 필요함","텍스트 기반 피드백 분석에만 제한됨"],"es":["Requiere acceso a comentarios de revisión de código y notas de PR","Limitado al análisis de comentarios basados en texto"],"fr":["Nécessite l''accès aux commentaires de révision de code et aux notes de PR","Limité à l''analyse de commentaires basés sur du texte"],"de":["Erfordert Zugriff auf Code-Review-Feedback und PR-Notizen","Begrenzt auf textbasierte Feedback-Analyse"],"pt":["Requer acesso a feedback de revisão de código e notas de PR","Limitado à análise de feedback baseada em texto"],"ru":["Требует доступа к обратной связи по коду и заметкам PR","Ограничен анализом обратной связи на основе текста"],"ar":["يتطلب الوصول إلى ملاحظات المراجعة البرمجية و ملاحظات_PR","محدود بتحليل التعليقات القائمة على النص"]},"version":4},"contentHash":"110c53375da762f5451f34f9e5daaa41dbcf52389e519880d2dcf8b2bb5f8ded","qualityScore":54}');
