INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Sivanwol/freelancer-site/review-implementing', 'review-implementing', 'Sivanwol', 'freelancer-site', 'community', 'review-implementing Sivanwol freelancer-site community The review-implementing skill helps developers systematically process and implement code review feedback, benefiting teams who use PR review notes and reviewer comments. 代码审查反馈实施系统，能够解析审查员注释、处理编号列表和项目符号，并实施更改 コードレビューフィードバック実装システムは、レビューアーの注釈を解析し、番号付きリストと箇条書きを処理し、変更を実装します 코드 리뷰 피드백 구현 시스템은 리뷰어의 주석을 해석하고 번호가 있는 목록과 항목을 처리하여 변경 사항을 구현합니다 El proceso de implementación de revisión de código implica la identificación y aplicación sistemática de comentarios de revisión. Esta guía cubre los pasos clave para implementar cambios en tu código. Le processus de mise en œuvre de la revue de code implique l''identification et l''application systématique des commentaires de revue. Ce guide couvre les étapes clés pour implémenter des modifications dans votre code. Der Prozess der Implementierung von Code-Review umfasst die systematische Identifizierung und Anwendung von Review-Kommentaren. Dieser Leitfaden deckt die wichtigsten Schritte zur Implementierung von Änderungen in Ihrem Code ab. Implemente revisões de código de forma sistemática com ferramentas de IA. Processar e implementar mudanças baseadas em feedback de revisão de código. Реализуйте обзор кода систематически с помощью ИИ Агентов. Обрабатывайте и внедряйте изменения на основе обратной связи по обзору кода. نفذ مراجعات الكود بشكل منهجي باستخدام أدوات الذكاء الاصطناعي. معالجة وتنفيذ التغييرات dựa على ملاحظات مراجعة الكود how to use review-implementing review-implementing alternative review-implementing setup guide what is review-implementing review-implementing vs code review tools review-implementing install for AI agents 代码审查反馈 代码审查实施 代码优化 代码修改 AI代码审查工具 代码审查最佳实践 Parses reviewer notes to identify individual feedback items Handles numbered lists and bullet points for organized feedback Supports systematic workflow for implementing review suggestions Processes PR review notes for efficient feedback implementation Splits numbered lists for easy feedback item identification review-implementing is a systematic workflow for processing and implementing code review feedback, handling items such as numbered lists and bullet points.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Kang-chen/kownledgeBase/NoteOrganizer', 'community', 'Kang-chen', 'kownledgeBase', 'Kang-chen/kownledgeBase', 'NoteOrganizer', 0, 0, 54, '2026-03-08T01:57:15.498Z', '2026-03-08T02:10:15.987Z', '0955ede380ce1697a79645db065cdc4acf6e24551b9fbe8d90867d8607bf1467', '{"id":"Kang-chen/kownledgeBase/NoteOrganizer","name":"NoteOrganizer","description":{"en":"NoteOrganizer is a skill that automatically categorizes and stores notes in a personal knowledge base, ideal for users seeking structured note organization. It analyzes input and organizes content into a knowledge base.","zh":"NoteOrganizer 技术自动化笔记分类和存储，实现高效的知识库管理。","ja":"NoteOrganizer AIエージェントは、ノートの自動化と知識ベースの管理を実現します。","ko":"NoteOrganizer 도구는 노트를 자동으로 분류하고 저장하여 지식 기초를 관리합니다.","es":"NoteOrganizer es una habilidad que categoriza y almacena notas de forma automática en la base de conocimiento personal. Analiza la entrada y organiza el contenido","fr":"NoteOrganizer est une compétence qui catégorise et stocke des notes de manière automatique dans la base de connaissances personnelle. Elle analyse l''entrée et organise le contenu","de":"NoteOrganizer ist eine Fähigkeit, die Notizen automatisch in der persönlichen Wissensbasis kategorisiert und speichert. Sie analysiert die Eingabe und organisiert den Inhalt","pt":"O NoteOrganizer é uma habilidade que automatiza a categorização e armazenamento de notas na base de conhecimento pessoal.","ru":"NoteOrganizer - это навык, который автоматизирует категоризацию и хранение заметок в личной базе знаний.","ar":"NoteOrganizer هو مهارة يقوم بتحسين تنظيم الملاحظات وتخزينها في قاعدة المعارف الشخصية."},"seo":{"title":{"en":"NoteOrganizer: Automated Note Categorization Setup Guide ...","zh":"NoteOrganizer 工具指南：自动化笔记组织","ja":"NoteOrganizer AIエージェントのセットアップガイド","ko":"NoteOrganizer 도구 설정 가이드: 지식 기초 자동화","es":"Guía de configuración de NoteOrganizer para agentes de IA","fr":"Guide de mise en place de NoteOrganizer pour les outils d''IA","de":"Einrichtungsleitfaden für NoteOrganizer in KI-Agenten","pt":"Guia de Configuração do NoteOrganizer: Organize Seus Conh...","ru":"Настройка NoteOrganizer: ИИ Агенты для Управления Заметками","ar":"دليل إعداد NoteOrganizer: أدوات ذكاء اصطناعي لتنظيم الملا..."},"description":{"en":"Discover how NoteOrganizer simplifies personal knowledge base management. Learn to automate note categorization and get started with our setup guide today!","zh":"了解 NoteOrganizer 技术，自动化笔记组织和知识库管理。实现高效的笔记分类和存储。","ja":"NoteOrganizer AIエージェントを使用して、ノートの自動化と知識ベースの管理を実現します。","ko":"노트를 자동으로 분류하고 저장하는 NoteOrganizer 도구를 사용하여 지식 기초를 관리하세요.","es":"Automatice la organización de notas con NoteOrganizer. Descubra cómo funciona y mejore su base de conocimiento personal con esta herramienta de IA","fr":"Organisez vos notes automatiquement avec NoteOrganizer. Découvrez comment cela fonctionne et améliorez votre base de connaissances personnelle avec cet outil...","de":"Automatisieren Sie die Notizenorganisation mit NoteOrganizer. Erfahren Sie, wie es funktioniert und verbessern Sie Ihre persönliche Wissensbasis mit diesem K...","pt":"Aprenda a configurar o NoteOrganizer para automatizar a organização de suas notas e ideias no conhecimento pessoal.","ru":"Узнайте, как настроить NoteOrganizer для автоматизации организации ваших заметок и идей в личной базе знаний с помощью ИИ Агентов.","ar":"تعلم كيفية إعداد NoteOrganizer لتحسين تنظيم ملاحظاتك وأفكارك في قاعدة المعارف الشخصية باستخدام أدوات الذكاء الاصطناعي."},"definition":{"en":"NoteOrganizer is a skill responsible for automatically categorizing and storing notes in a personal knowledge base, utilizing workflow analysis and content organization.","zh":"NoteOrganizer 是一种自动化笔记组织和知识库管理的技术。","ja":"NoteOrganizer は、ノートの自動化と知識ベースの管理を行う AIエージェントです。","ko":"NoteOrganizer는 노트를 자동으로 분류하고 저장하는 도구입니다.","es":"NoteOrganizer es una habilidad de IA que permite la organización automática de notas y contenido en una base de conocimiento personal","fr":"NoteOrganizer est une compétence d''IA qui permet l''organisation automatique de notes et de contenu dans une base de connaissances personnelle","de":"NoteOrganizer ist eine KI-Fähigkeit, die die automatische Organisation von Notizen und Inhalten in einer persönlichen Wissensbasis ermöglicht","pt":"O que é NoteOrganizer? É uma habilidade de AI que organiza notas e ideias.","ru":"Что такое NoteOrganizer? Это навык ИИ, который организует заметки и идеи.","ar":"ما هو NoteOrganizer؟ إنه مهارة ذكاء اصطناعي لتنظيم الملاحظات والأفكار."},"features":{"en":["Analyzes input to categorize notes","Stores notes in a personal knowledge base","Organizes content prefixed with `[[[`","Maintains a structured personal knowledge base","Automates note categorization for efficient knowledge management"],"zh":["自动化笔记分类","知识库管理","支持 [[[` 前缀内容","实现高效的笔记存储","结构化的个人知识库"],"ja":["ノートの自動化","知識ベースの管理"," `[[` 前缀内容のサポート","効率的なノートの保存","構造化された個人知識ベース"],"ko":["노트 자동 분류","지식 기초 관리"," [[[` 접두사 내용 지원","효율적인 노트 저장","구조화된 개인 지식 기초"],"es":["Análisis de entrada para la organización de notas","Categorización automática de contenido","Almacenamiento de notas en la base de conocimiento personal","Compatibilidad con contenido prefixado con `[[[`","Mejora de la estructura de la base de conocimiento personal"],"fr":["Analyse de l''entrée pour l''organisation de notes","Catégorisation automatique de contenu","Stockage de notes dans la base de connaissances personnelle","Compatibilité avec le contenu prefixé avec `[[[`","Amélioration de la structure de la base de connaissances personnelle"],"de":["Eingabeanalyse für die Notizenorganisation","Automatische Kategorisierung von Inhalten","Speicherung von Notizen in der persönlichen Wissensbasis","Unterstützung von Inhalten mit dem Präfix `[[[`","Verbesserung der Struktur der persönlichen Wissensbasis"],"pt":["Análise de entrada de notas","Categorização automática de conteúdo","Armazenamento de notas na base de conhecimento pessoal","Suporte a prefixo [[[ para conteúdo","Melhoria da estrutura da base de conhecimento"],"ru":["Анализ входных данных заметок","Автоматическая категоризация контента","Хранение заметок в личной базе знаний","Поддержка префикса [[[ для контента","Улучшение структуры личной базы знаний"],"ar":["تحليل إدخال الملاحظات","تنظيم автомاتيكي للمحتوى","تخزين الملاحظات في قاعدة المعارف الشخصية","دعم للمحتوى المسبوق ب [[[","تحسين هيكل قاعدة المعارف الشخصية"]},"keywords":{"en":["how to use NoteOrganizer","NoteOrganizer setup guide","automated note categorization","personal knowledge base management","NoteOrganizer alternative","NoteOrganizer vs Evernote","install NoteOrganizer","NoteOrganizer workflow analysis","NoteOrganizer content organization"],"zh":["NoteOrganizer 技术","自动化笔记组织","知识库管理","AI 工具","笔记分类","知识库设置","自动化笔记存储"],"ja":["NoteOrganizer AIエージェント","ノートの自動化","知識ベースの管理","AI エージェント","ノートの分类","知識ベースの設定","ノートの自動保存"],"ko":["NoteOrganizer 도구","노트 자동 분류","지식 기초 관리","AI 도구","노트 분류","지식 기초 설정","노트 자동 저장"],"es":["NoteOrganizer","agentes de IA","organización de notas","base de conocimiento personal","categorización automática","almacenamiento de notas","herramientas de productividad","gestión de conocimiento"],"fr":["NoteOrganizer","outils d''IA","organisation de notes","base de connaissances personnelle","catégorisation automatique","stockage de notes","outils de productivité","gestion de connaissances"],"de":["NoteOrganizer","KI-Agenten","Notizenorganisation","persönliche Wissensbasis","automatische Kategorisierung","Notizenspeicherung","Produktivitätstools","Wissensmanagement"],"pt":["NoteOrganizer","organização de notas","base de conhecimento pessoal","AI para desenvolvedores","ferramentas de produtividade","automatização de tarefas","desenvolvimento de habilidades"],"ru":["NoteOrganizer","организация заметок","личная база знаний","ИИ для разработчиков","инструменты продуктивности","автоматизация задач","разработка навыков"],"ar":["NoteOrganizer","تنظيم الملاحظات","قاعدة المعارف الشخصية","أدوات ذكاء اصطناعي","أدوات إنتاجية","تحسين المهام","تطوير المهارات"]}},"owner":"Kang-chen","repo":"kownledgeBase","repoPath":"Kang-chen/kownledgeBase","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.498Z","topics":[],"category":"community","skillMd":{"name":"NoteOrganizer","description":"Organizes notes into the personal knowledge base based on predefined rules. Use when the user wants to save, categorize, or organize notes and ideas.","bodyPreview":"# NoteOrganizer Skill\n\nThis skill is responsible for automatically categorizing and storing notes in the personal knowledge base.\n\n## When to Use\n\n- Use this skill when the user wants to save a new note or idea\n- Use this skill when content needs to be organized into the knowledge base\n- Use this skill when the user provides content prefixed with `[[[`\n- This skill is helpful for maintaining a structured personal knowledge base\n\n## Instructions\n\n### Workflow\n\n1. **Analyze Input**: Analyze the us","body":"# NoteOrganizer Skill\n\nThis skill is responsible for automatically categorizing and storing notes in the personal knowledge base.\n\n## When to Use\n\n- Use this skill when the user wants to save a new note or idea\n- Use this skill when content needs to be organized into the knowledge base\n- Use this skill when the user provides content prefixed with `[[[`\n- This skill is helpful for maintaining a structured personal knowledge base\n\n## Instructions\n\n### Workflow\n\n1. **Analyze Input**: Analyze the user''s input to identify the main topic and relevant keywords.\n\n2. **Consult Rules**: Read the rule files located in `.cursor/rules/` to determine the appropriate category and directory for the note. The rules are:\n   - `knowledge_base_structure.mdc`: General structure and formatting.\n   - `planning_notes.mdc`: For notes about planning, roadmaps, etc.\n   - `programming_notes.mdc`: For notes about coding, algorithms, etc.\n   - `biology_notes.mdc`: For notes about biology, bioinformatics, etc.\n\n3. **Determine Target Path**: Based on the matching rule, determine the target directory (e.g., `knowledge/planning/`).\n\n4. **Generate File Name**: Create a descriptive, hyphen-separated filename from the note''s title (e.g., `my-new-research-plan.md`).\n\n5. **Format Content**:\n   - Add a YAML frontmatter block with `creation_date` and `tags`.\n   - Ensure the content is in valid Markdown format.\n\n6. **Save File**: Use the `edit_file` tool to create a new file with the formatted content in the determined target path.\n\n7. **Update Changelog**: Add an entry to `knowledge/logs/changelog.md` with timestamp, operation type, and description in Chinese.\n\n8. **Confirm**: Report the successful creation and location of the new note to the user.\n\n## Directory Structure\n\n```\n/knowledge/\n├── planning/      # Notes related to project planning, roadmaps, and goals.\n├── programming/   # Notes related to software development, algorithms, and coding.\n├── biology/       # Notes related to biology, bioinformatics, and research.\n├── inbox/         # Inbox for unprocessed notes and ideas.\n└── logs/          # Logs for tracking changes and activities.\n```\n\n## File Naming Convention\n\n- File names should be in English, using lowercase letters\n- Words should be separated by hyphens (`-`)\n- The file extension should be `.md`\n- Example: `my-research-notes.md`\n"},"lastSynced":"2026-03-08T02:10:15.987Z","agentAnalysis":{"suitability":{"en":"Perfect for Knowledge Management Agents needing automated note organization and categorization capabilities.","zh":"非常适合需要自动化笔记组织和分类功能的知识管理代理。","ja":"自動的なノートの整理と分類機能が必要なナレッジマネジメントエージェントに最適です。","ko":"자동화된 노트 조직화 및 분류 기능이 필요한 지식 관리 에이전트에 적합합니다.","es":"Perfecto para Agentes de Gestión del Conocimiento que necesitan capacidades de organización y categorización de notas automatizadas.","fr":"Idéal pour les agents de gestion des connaissances ayant besoin de capacités d''organisation et de catégorisation de notes automatisées.","de":"Perfekt für Wissensmanagement-Agenten, die automatisierte Notizorganisations- und Kategorisierungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Conhecimento que precisam de organização e categorização de notas automatizadas.","ru":"Идеально подходит для агентов управления знаниями, которым необходимы автоматизированные возможности организации и категоризации заметок.","ar":"مثالي لعميل إدارة المعرفة الذي يحتاج إلى تنظيم وتصنيف ملاحظات آلي."},"recommendation":{"en":"Empowers agents to analyze input and organize content into a structured personal knowledge base, utilizing prefix triggers like `[[[` and providing a comprehensive content analysis.","zh":"赋予代理分析输入并将内容组织到结构化的个人知识库中，利用诸如 `[[[` 的前缀触发器，并提供全面内容分析。","ja":"エージェントが入力データを分析し、内容を構造化された個人のナレッジベースに整理することを可能にし、`[[[` などのプレフィックストリガーを提供し、包括的なコンテンツ分析を提供します。","ko":"에이전트가 입력 데이터를 분석하고 내용을 구조화된 개인 지식베이스로 조직할 수 있도록 하며, `[[[` 같은 접두사 트리거를 제공하고, 포괄적인 콘텐츠 분석을 제공합니다.","es":"Habilita a los agentes a analizar la entrada y organizar el contenido en una base de conocimiento personal estructurada, utilizando desencadenadores de prefijo como `[[[` y proporcionando un análisis de contenido integral.","fr":"Permet aux agents d''analyser les entrées et d''organiser le contenu dans une base de connaissances personnelles structurée, en utilisant des déclencheurs de préfixe comme `[[[` et en fournissant une analyse de contenu complète.","de":"Ermächtigt Agenten, die Eingabe zu analysieren und den Inhalt in eine strukturierte persönliche Wissensbasis zu organisieren, indem sie Präfix-Auslöser wie `[[[` verwenden und eine umfassende Inhaltsanalyse bereitstellen.","pt":"Habilita os agentes a analisar a entrada e organizar o conteúdo em uma base de conhecimento pessoal estruturada, utilizando gatilhos de prefixo como `[[[` e fornecendo uma análise abrangente de conteúdo.","ru":"Наделяет агентов возможностью анализировать входные данные и организовывать контент в структурированную личную базу знаний, используя триггеры префиксов типа `[[[` и обеспечивая всесторонний анализ контента.","ar":"تمكّن الوكيل من تحليل الإدخال وتنظيم المحتوى في قاعدة معرفة شخصية منظمة، باستخدام مسوقات بادئة مثل `[[[` وتقديم تحليل محتوى شاملة."},"useCases":{"en":["Automating note categorization","Generating structured knowledge bases","Organizing content with prefix triggers"],"zh":["自动化笔记分类","生成结构化知识库","使用前缀触发器组织内容"],"ja":["ノートの自動分類","構造化されたナレッジベースの生成","プレフィックストリガーによるコンテンツの整理"],"ko":["노트 자동 분류","구조화된 지식베이스 생성","접두사 트리거로 콘텐츠를 조직화"],"es":["Automatización de la categorización de notas","Generación de bases de conocimiento estructuradas","Organización de contenido con desencadenadores de prefijo"],"fr":["Automatisation de la catégorisation de notes","Génération de bases de connaissances structurées","Organisation de contenu avec des déclencheurs de préfixe"],"de":["Automatisierung der Notizkategorisierung","Erzeugung strukturierter Wissensbasen","Organisation von Inhalten mit Präfix-Auslösern"],"pt":["Automatizar a categorização de notas","Gerar bases de conhecimento estruturadas","Organizar conteúdo com gatilhos de prefixo"],"ru":["Автоматизировать категоризацию заметок","Генерировать структурированные базы знаний","Организовывать контент с триггерами префиксов"],"ar":["أتمتة تصنيف الملاحظات","توليد قواعد معرفة منظمة","تنظيم المحتوى باستخدام مسوقات بادئة"]},"limitations":{"en":["Requires user-provided content","Prefix trigger `[[[` needed for activation"],"zh":["需要用户提供的内容","需要 `[[[` 前缀触发器来激活"],"ja":["ユーザー提供のコンテンツが必要","`[[[` プレフィックストリガーが必要"],"ko":["사용자 제공 콘텐츠가 필요함","`[[[` 접두사 트리거가 필요"],"es":["Requiere contenido proporcionado por el usuario","Se necesita el desencadenador de prefijo `[[[` para la activación"],"fr":["Nécessite un contenu fourni par l''utilisateur","Le déclencheur de préfixe `[[[` est nécessaire pour l''activation"],"de":["Benötigt von Benutzer bereitgestellten Inhalt","Präfix-Auslöser `[[[` wird für die Aktivierung benötigt"],"pt":["Requer conteúdo fornecido pelo usuário","Gatilho de prefixo `[[[` necessário para ativação"],"ru":["Требует контента, предоставленного пользователем","Триггер префикса `[[[` необходим для активации"],"ar":["يتطلب محتوى مقدم من قبل المستخدم","مسوق بادئة `[[[` ضروري للتفعيل"]},"version":4},"contentHash":"0955ede380ce1697a79645db065cdc4acf6e24551b9fbe8d90867d8607bf1467","qualityScore":54}');
