INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('simplysmartai/5cypressautomation/api-scaffolding', 'api-scaffolding', 'simplysmartai', '5cypressautomation', 'community', 'api-scaffolding simplysmartai 5cypressautomation community The api-scaffolding skill helps developers create professional REST APIs quickly, ideal for client deliverables and workflow automation. It supports building webhook receivers and setting up FastAPI projects. api-scaffolding允许您快速搭建专业的REST API，适用于SMB自动化和客户交付 api-scaffoldingは、プロフェッショナルなREST APIを迅速に構築するためのツールです api-scaffolding는 전문가 수준의 REST API를 신속하게 구축하기 위한 도구입니다 API Scaffolding es una herramienta para crear endpoints de API profesionales en minutos. Permite crear modelos Pydantic y configurar proyectos FastAPI L''API Scaffolding est un outil pour créer des endpoints d''API professionnels en quelques minutes. Il permet de créer des modèles Pydantic et de configurer des projets FastAPI API-Scaffolding ist ein Tool, um professionelle API-Endpunkte in Minuten zu erstellen. Es ermöglicht die Erstellung von Pydantic-Modellen und die Konfiguration von FastAPI-Projekten O API Scaffolding permite criar endpoints de API profissionais em minutos para entrega de clientes. É ideal para fluxos de trabalho de clientes e projetos FastAPI. API Scaffolding позволяет создать профессиональные REST API за минуты для автоматизации бизнес-процессов и проектов FastAPI. يسمح API Scaffolding بإنشاء نقاط نهاية API محترفة في دقائق لآليّة أتمتة العملاء ومشاريع FastAPI. how to use api-scaffolding api-scaffolding setup guide FastAPI project setup api-scaffolding vs Flask what is api-scaffolding api-scaffolding install api-scaffolding tutorial api-scaffolding alternative api-scaffolding documentation api-scaffolding REST API SMB自动化 客户交付 Pydantic Models FastAPI execution/脚本 AIエージェント Generates new API endpoints for client workflows Builds webhook receivers for services like Stripe and ShipStation Sets up FastAPI projects from scratch Adds endpoints to existing execution scripts Utilizes Pydantic Models for defining API schemas Supports rapid development of REST APIs api-scaffolding is a skill that enables rapid creation of REST APIs using FastAPI, supporting the development of new API endpoints, webhook receivers, and existing execution scripts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bluefa/pii-agent-demo/pr-merge', 'community', 'bluefa', 'pii-agent-demo', 'bluefa/pii-agent-demo', 'pr-merge', 0, 0, 54, '2026-03-08T01:57:15.500Z', '2026-03-08T02:10:16.959Z', '8a4da390b080723a8a137f2e199afe6076b5ddff905967478f761d3b4e22c38e', '{"id":"bluefa/pii-agent-demo/pr-merge","name":"pr-merge","description":{"en":"The pr-merge skill is a manual workflow tool for AI agents that performs pre-merge validation and executes pull request merging strategies. It benefits developers and DevOps engineers by standardizing the PR merge process using Haiku subagents for Bash operations to reduce costs.","zh":"pr-merge 技能使用 Haiku 子代理实现代码合并的优化，支持 merge、squash 和 squid 策略","ja":"pr-merge スキルは Haiku 子代理を使用してコードマージの最適化を実現し、merge、squash、squid 戦略をサポート","ko":"pr-merge 스킬은 Haiku 子代理를 사용하여 코드 머지의 최적화를 수행하며 merge, squash, squid 전략을 지원","es":"pr-merge es una habilidad que permite merge de solicitudes de extracción con estrategias de optimización de costos y subagentes Haiku","fr":"pr-merge est une compétence qui permet de fusionner les demandes d''extraction avec des stratégies d''optimisation des coûts et des sous-agents Haiku","de":"pr-merge ist eine Fähigkeit, die das Merge von Pull-Requests mit Kostenoptimierungsstrategien und Haiku-Subagenten ermöglicht","pt":"O pr-merge é uma habilidade que otimiza custos com a estratégia Haiku, permitindo a execução de operações de merge de pull requests de forma eficiente","ru":"Pr-merge - это навык, который оптимизирует затраты с помощью стратегии Haiku, позволяя выполнять операции слияния запросов на вытягивание эффективно","ar":"pr-merge هو مهارة تحسن التكلفة باستخدام استراتيجية Haiku، مما يسمح بتنفيذ عمليات الدمج لطلبات السحب بفعالية"},"seo":{"title":{"en":"pr-merge: Automate PR Validation & Merging | AI Agent Skill","zh":"pr-merge 设置指南：优化代码合并","ja":"pr-merge 導入ガイド：コードマージの最適化","