INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bluefa/pii-agent-demo/pr-merge', 'pr-merge', 'bluefa', 'pii-agent-demo', 'community', 'pr-merge bluefa pii-agent-demo community The pr-merge skill is a manual workflow tool for AI agents that performs pre-merge validation and executes pull request merging strategies. It benefits developers and DevOps engineers by standardizing the PR merge process using Haiku subagents for Bash operations to reduce costs. pr-merge 技能使用 Haiku 子代理实现代码合并的优化，支持 merge、squash 和 squid 策略 pr-merge スキルは Haiku 子代理を使用してコードマージの最適化を実現し、merge、squash、squid 戦略をサポート pr-merge 스킬은 Haiku 子代理를 사용하여 코드 머지의 최적화를 수행하며 merge, squash, squid 전략을 지원 pr-merge es una habilidad que permite merge de solicitudes de extracción con estrategias de optimización de costos y subagentes Haiku pr-merge est une compétence qui permet de fusionner les demandes d''extraction avec des stratégies d''optimisation des coûts et des sous-agents Haiku pr-merge ist eine Fähigkeit, die das Merge von Pull-Requests mit Kostenoptimierungsstrategien und Haiku-Subagenten ermöglicht O pr-merge é uma habilidade que otimiza custos com a estratégia Haiku, permitindo a execução de operações de merge de pull requests de forma eficiente Pr-merge - это навык, который оптимизирует затраты с помощью стратегии Haiku, позволяя выполнять операции слияния запросов на вытягивание эффективно pr-merge هو مهارة تحسن التكلفة باستخدام استراتيجية Haiku، مما يسمح بتنفيذ عمليات الدمج لطلبات السحب بفعالية pr-merge skill setup guide how to use pr-merge AI agent pr-merge vs traditional git merge pr-merge cost optimization Haiku install pr-merge skill what is pr-merge squash strategy pr-merge alternative tools automate GitHub PR merging pr-merge manual workflow pr-merge 代码合并优化 Haiku 子代理 AIエージェント 代码合并成本优化 开发流程优化 代码管理 版本控制 Accepts PR input as number or URL for flexible integration Executes merge strategies: merge, squash, or squid (default) Uses Haiku subagent for all Bash operations (~70% cost reduction) Requires manual invocation via Task tool for controlled execution Performs consistent pre-merge validation before merging pr-merge is an AI agent skill that handles pull request merging with pre-merge validation. It accepts a PR number or URL and executes a specified merge strategy (merge, squash, or squid) using a Haiku subagent for Bash operations to optimize computational costs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sayanget/inbound-recorder-system/baoyu-comic', 'community', 'sayanget', 'inbound-recorder-system', 'sayanget/inbound-recorder-system', 'baoyu-comic', 0, 0, 54, '2026-03-08T01:57:15.510Z', '2026-03-08T02:10:25.724Z', 'a33eefb2b486118a991ed6a3939d52b4f6dfa9f130de5e70331006a85010cd72', '{"id":"sayanget/inbound-recorder-system/baoyu-comic","name":"baoyu-comic","description":{"en":"The baoyu-comic skill creates original knowledge comics with multiple visual styles and layouts, benefiting developers and content creators. It utilizes Flask, SQLite, and automated email reports.","zh":"baoyu-comic是一个仓库入库记录系统，使用Flask和SQLite，支持离线操作，并提供自动电子邮件报告","ja":"baoyu-comicは、FlaskとSQLiteを使用した倉庫入庫記録システムです。オフライン対応であり、自動電子メールレポートも提供します","ko":"baoyu-comic은 Flask와 SQLite를 사용한 창고 입고 기록 시스템으로, 오프라인 지원과 자동 이메일 보고서를 제공합니다","es":"baoyu-comic es un sistema de grabación de entrada de almacén con Flask, SQLite y soporte offline, que permite la creación de cómics de conocimiento con múltiples estilos visuales","fr":"baoyu-comic est un système d''enregistrement d''entrée de stock avec Flask, SQLite et prise en charge hors ligne, qui permet la création de bandes dessinées de connaissances avec plusieurs styles visuels","de":"baoyu-comic ist ein Warehouse-Inbound-Recorder-System mit Flask, SQLite und Offline-Unterstützung, das die Erstellung von Wissenscomics mit mehreren visuellen Stilen ermöglicht","pt":"O baoyu-comic é um sistema de gravação de entrada de armazém que utiliza Flask e SQLite, com suporte offline e relatórios de e-mail automatizados.","ru":"baoyu-comic - это система записи входа в склад, использующая Flask и SQLite, с поддержкой offline и автоматическими отчетами по электронной почте, ИИ Агенты","ar":"baoyu-comic هو نظام تسجيل دخول المستودع الذي يستخدم Flask و SQLite، مع دعم عدم الاتصال و تقارير البريد الإلكتروني الآلية، أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"baoyu-comic: Automated Comic Creation Setup Guide | AI Ag...","zh":"baoyu-comic.setup指南：使用Flask和SQLite的离线支持","ja":"baoyu-comicセットアップガイド：FlaskとSQLiteを使用したオフライン対応","ko":"baoyu-comic설치 가이드: Flask와 SQLite를 사용한 오프라인 지원","es":"Guía de configuración de baoyu-comic: Creación de cómics ...","fr":"Guide d''installation de baoyu-comic: Création de bandes d...","de":"Einrichtungsleitfaden für baoyu-comic: Erstellung von Wis...","pt":"Guia de Configuração do baoyu-comic: Crie Quadrinhos de C...","ru":"Настройка baoyu-comic: Создание комиксов знаний с помощью...","ar":"دليل إعداد baoyu-comic: إنشاء قصص مصورة للمعرفة باستخدام ..."},"description":{"en":"Discover how to create original knowledge comics with baoyu-comic. Learn to generate comics with multiple visual styles and layouts, and get started with our...","zh":"了解baoyu-comic的技术细节，包括Flask、SQLite和自动电子邮件报告。使用baoyu-comic创建原创知识漫画","ja":"baoyu-comicの技術的詳細を学びます。Flask、SQLite、自動電子メールレポートを使用してオリジナルのナレッジコミックを作成します","ko":"baoyu-comic의 기술적 세부 사항을 학습하세요. Flask, SQLite 및 자동 이메일 보고서를 사용하여 원创 지식 만화를 생성합니다","es":"Descubre cómo configurar baoyu-comic para crear cómics de conocimiento con múltiples estilos visuales y funciones de correo electrónico automatizado","fr":"Découvrez comment installer baoyu-comic pour créer des bandes dessinées de connaissances avec plusieurs styles visuels et des fonctionnalités de courrier éle...","de":"Erfahren Sie, wie Sie baoyu-comic einrichten, um Wissenscomics mit mehreren visuellen Stilen und automatisierten E-Mail-Funktionen zu erstellen","pt":"Aprenda a configurar o baoyu-comic para criar quadrinhos de conhecimento personalizados com múltiplos estilos visuais e layouts, utilizando Flask e SQLite","ru":"Узнайте, как настроить baoyu-comic для создания оригинальных комиксов знаний с несколькими визуальными стилями и макетами, используя Flask и SQLite, ИИ Агенты","ar":"تعرف على كيفية إعداد baoyu-comic لإنشاء قصص مصورة للمعرفة المخصصة مع कई أساليب بصرية وتخطيطات، باستخدام Flask و SQLite، أدوات الذكاء الاصطناعي"},"definition":{"en":"baoyu-comic is a Warehouse Inbound Recorder System that generates knowledge comics with various styles and layouts using Flask and SQLite.","zh":"baoyu-comic是一个使用Flask和SQLite的仓库入库记录系统，支持离线操作","ja":"baoyu-comicは、FlaskとSQLiteを使用した倉庫入庫記録システムです","ko":"baoyu-comic은 Flask와 SQLite를 사용한 창고 입고 기록 시스템입니다","es":"baoyu-comic es una herramienta de creación de cómics de conocimiento que utiliza Flask y SQLite para generar historias visuales","fr":"baoyu-comic est un outil de création de bandes dessinées de connaissances qui utilise Flask et SQLite pour générer des histoires visuelles","de":"baoyu-comic ist ein Tool zum Erstellen von Wissenscomics, das Flask und SQLite verwendet, um visuelle Geschichten zu generieren","pt":"O baoyu-comic é um sistema de criação de quadrinhos de conhecimento que permite criar conteúdo personalizado com múltiplos estilos visuais e layouts","ru":"baoyu-comic - это система создания комиксов знаний, позволяющая создавать оригинальный контент с несколькими визуальными стилями и макетами, ИИ Агенты","ar":"baoyu-comic هو نظام إنشاء قصص مصورة للمعرفة الذي يسمح بإنشاء محتوى مخصص مع العديد من الأساليب البصرية والتخطيطات"},"features":{"en":["Generates knowledge comics with multiple visual styles, including classic, dramatic, and vibrant","Supports various layouts, such as standard, cinematic, and webtoon","Utilizes Flask for web development and SQLite for database management","Provides offline support for comic creation","Sends automated email reports for efficient communication"],"zh":["使用Flask和SQLite进行数据存储","支持离线操作","自动电子邮件报告","多种视觉风格","可自定义布局"],"ja":["FlaskとSQLiteを使用したデータストレージ","オフライン対応","自動電子メールレポート","多種のビジュアルスタイル","レイアウトのカスタマイズ"],"ko":["Flask와 SQLite를 사용한 데이터 저장","오프라인 지원","자동 이메일 보고서","다양한 시각적 스타일","레이아웃 사용자 정의"],"es":["Creación de cómics de conocimiento con múltiples estilos visuales","Soporte offline para la grabación de entrada de almacén","Funcionalidades de correo electrónico automatizado","Integración con Flask y SQLite","Opciones de estilo y disposición personalizables","Compatibilidad con varios formatos de archivo"],"fr":["Création de bandes dessinées de connaissances avec plusieurs styles visuels","Prise en charge hors ligne pour l''enregistrement d''entrée de stock","Fonctionnalités de courrier électronique automatisé","Intégration avec Flask et SQLite","Options de style et de disposition personnalisables","Compatibilité avec plusieurs formats de fichier"],"de":["Erstellung von Wissenscomics mit mehreren visuellen Stilen","Offline-Unterstützung für die Aufzeichnung von Warehouse-Eingängen","Funktionen für automatisierte E-Mails","Integration mit Flask und SQLite","Anpassbare Stil- und Layout-Optionen","Kompatibilität mit verschiedenen Dateiformaten"],"pt":["Criação de quadrinhos de conhecimento personalizados com múltiplos estilos visuais","Suporte a layouts personalizados, incluindo standard, cinematic, dense, splash, mixed e webtoon","Utilização de Flask e SQLite para armazenamento de dados","Suporte offline para criação de conteúdo","Relatórios de e-mail automatizados","Opções de estilo, incluindo classic, dramatic, warm, tech, sepia, vibrant e ohmsha"],"ru":["Создание оригинальных комиксов знаний с несколькими визуальными стилями","Поддержка пользовательских макетов, включая standard, cinematic, dense, splash, mixed и webtoon","Использование Flask и SQLite для хранения данных","Поддержка offline для создания контента","Автоматические отчеты по электронной почте","Варианты стиля, включая classic, dramatic, warm, tech, sepia, vibrant и ohmsha, ИИ Агенты"],"ar":["إنشاء قصص مصورة للمعرفة المخصصة مع العديد من الأساليب البصرية","دعم تخطيطات مخصصة، بما في ذلك standard, cinematic, dense, splash, mixed و webtoon","استخدام Flask و SQLite لتخزين البيانات","دعم عدم الاتصال لإنشاء المحتوى","تقارير البريد الإلكتروني الآلية","خيارات الأسلوب، بما في ذلك classic, dramatic, warm, tech, sepia, vibrant و ohmsha، أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use baoyu-comic","baoyu-comic alternative","baoyu-comic setup guide","what is baoyu-comic","baoyu-comic vs other comic creators","baoyu-comic install","automated comic creation","knowledge comic generation","Flask and SQLite development"],"zh":["baoyu-comic","Flask","SQLite","离线支持","自动电子邮件报告","知识漫画","仓库入库记录系统","AIエージェント"],"ja":["baoyu-comic","Flask","SQLite","オフライン対応","自動電子メールレポート","ナレッジコミック","倉庫入庫記録システム","AIエージェント"],"ko":["baoyu-comic","Flask","SQLite","오프라인 지원","자동 이메일 보고서","지식 만화","창고 입고 기록 시스템","AI 에이전트"],"es":["baoyu-comic","creación de cómics de conocimiento","Flask","SQLite","soporte offline","correo electrónico automatizado","herramientas de creación de cómics","desarrollo de aplicaciones web","tecnologías de creación de contenido"],"fr":["baoyu-comic","création de bandes dessinées de connaissances","Flask","SQLite","prise en charge hors ligne","courrier électronique automatisé","outils de création de bandes dessinées","développement d''applications web","technologies de création de contenu"],"de":["baoyu-comic","Erstellung von Wissenscomics","Flask","SQLite","Offline-Unterstützung","automatisierte E-Mails","Tools zum Erstellen von Wissenscomics","Webanwendungsentwicklung","Inhaltsersstellungstechnologien"],"pt":["baoyu-comic","quadrinhos de conhecimento","Flask","SQLite","suporte offline","relatórios de e-mail automatizados","criação de conteúdo personalizado","estilos visuais","layouts personalizados","desenvolvimento web"],"ru":["baoyu-comic","комиксы знаний","Flask","SQLite","поддержка offline","автоматические отчеты по электронной почте","создание оригинального контента","визуальные стили","пользовательские макеты","разработка веб-приложений","ИИ Агенты"],"ar":["baoyu-comic","قصص مصورة للمعرفة","Flask","SQLite","دعم عدم الاتصال","تقارير البريد الإلكتروني الآلية","إنشاء محتوى مخصص","أساليب بصرية","تخطيطات مخصصة","تطوير الويب","أدوات الذكاء الاصطناعي"]}},"owner":"sayanget","repo":"inbound-recorder-system","repoPath":"sayanget/inbound-recorder-system","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.510Z","topics":[],"category":"community","skillMd":{"name":"baoyu-comic","description":"Knowledge comic creator supporting multiple styles (Logicomix/Ligne Claire, Ohmsha manga guide). Creates original educational comics with detailed panel layouts and sequential image generation. Use when user asks to create 知识漫画, 教育漫画, biography comic, tutorial comic, or Logicomix-style comic.","bodyPreview":"# Knowledge Comic Creator\n\nCreate original knowledge comics with multiple visual styles.\n\n## Usage\n\n```bash\n/baoyu-comic posts/turing-story/source.md\n/baoyu-comic posts/turing-story/source.md --style dramatic --layout cinematic\n/baoyu-comic  # then paste content\n```\n\n## Options\n\n| Option | Values |\n|--------|--------|\n| `--style` | classic (default), dramatic, warm, tech, sepia, vibrant, ohmsha |\n| `--layout` | standard (default), cinematic, dense, splash, mixed, webtoon |\n\nStyle × Layout can be","body":"# Knowledge Comic Creator\n\nCreate original knowledge comics with multiple visual styles.\n\n## Usage\n\n```bash\n/baoyu-comic posts/turing-story/source.md\n/baoyu-comic posts/turing-story/source.md --style dramatic --layout cinematic\n/baoyu-comic  # then paste content\n```\n\n## Options\n\n| Option | Values |\n|--------|--------|\n| `--style` | classic (default), dramatic, warm, tech, sepia, vibrant, ohmsha |\n| `--layout` | standard (default), cinematic, dense, splash, mixed, webtoon |\n\nStyle × Layout can be freely combined.\n\n## Auto Selection\n\n| Content Signals | Style | Layout |\n|-----------------|-------|--------|\n| Tutorial, how-to, beginner | ohmsha | webtoon |\n| Computing, AI, programming | tech | dense |\n| Pre-1950, classical, ancient | sepia | cinematic |\n| Personal story, mentor | warm | standard |\n| Conflict, breakthrough | dramatic | splash |\n| Biography, balanced | classic | mixed |\n\n## File Structure\n\n```\n[target]/\n├── outline.md\n├── characters/\n│   ├── characters.md    # Character definitions\n│   └── characters.png   # Character reference sheet\n├── prompts/\n│   ├── 00-cover.md\n│   └── XX-page.md\n├── 00-cover.png\n└── XX-page.png\n```\n\n**Target directory**:\n- With source path: `[source-dir]/comic/`\n- Without source: `comic-outputs/YYYY-MM-DD/[topic-slug]/`\n\n## Workflow\n\n### Step 1: Analyze Content\n\n1. Read source content\n2. Select style (from `--style` or auto-detect)\n3. Select layout (from `--layout` or auto-detect per page)\n4. Determine page count:\n   - Short story: 5-8 pages\n   - Medium complexity: 9-15 pages\n   - Full biography: 16-25 pages\n\n### Step 2: Define Characters\n\n**Purpose**: Establish visual consistency across all pages.\n\n1. Extract all characters from content (protagonist, supporting, antagonist, narrator)\n2. Create `characters/characters.md` with visual specs for each character\n3. Generate `characters/characters.png` (character reference sheet)\n\n**Reference**: `references/character-template.md` for detailed format and examples.\n\n### Step 3: Generate Outline\n\nCreate `outline.md` with:\n- Metadata (title, style, layout, page count, character reference path)\n- Cover design\n- Each page: layout, panel breakdown, visual prompts\n\n**Reference**: `references/outline-template.md` for detailed format.\n\n### Step 4: Generate Images\n\nFor each page (cover + pages):\n\n1. Save prompt to `prompts/XX-page.md`\n2. Call image generation skill with:\n   - Base prompt: `references/base-prompt.md`\n   - Character reference (text or image, depending on skill capability)\n   - Page prompt\n   - Output path\n\n**Image Generation Skill Selection**:\n- Check available image generation skills in the environment\n- Adapt parameters based on skill capabilities:\n  - If supports `--promptfiles`: pass prompt files\n  - If supports reference image: pass `characters/characters.png`\n  - If text-only: concatenate prompts into single text\n- If multiple skills available, ask user preference\n\n3. Report progress after each generation\n\n### Step 5: Completion Report\n\n```\nComic Complete!\nTitle: [title] | Style: [style] | Pages: [count]\nLocation: [path]\n✓ characters.png\n✓ 00-cover.png ... XX-page.png\n```\n\n## Style-Specific Guidelines\n\n### Ohmsha Style (`--style ohmsha`)\n\nAdditional requirements for educational manga:\n- Default characters: Student (大雄), Mentor (哆啦A梦), Antagonist (胖虎)\n- Custom: `--characters \"Student:小明,Mentor:教授\"`\n- Must use visual metaphors (gadgets, action scenes) - NO talking heads\n- Page titles: narrative style, not \"Page X: Topic\"\n\n**Reference**: `references/ohmsha-guide.md` for detailed guidelines.\n\n## References\n\nDetailed templates and guidelines in `references/` directory:\n- `character-template.md` - Character definition format and examples\n- `outline-template.md` - Outline structure and panel breakdown\n- `ohmsha-guide.md` - Ohmsha manga style specifics\n- `styles/` - Detailed style definitions\n- `layouts/` - Detailed layout definitions\n"},"lastSynced":"2026-03-08T02:10:25.724Z","agentAnalysis":{"suitability":{"en":"Perfect for Creative Agents needing advanced knowledge comic generation capabilities with Flask and SQLite","zh":"非常适合需要使用 Flask 和 SQLite 进行高级漫画生成能力的创意代理","ja":"Flask と SQLite を使用した高度なコミック生成機能が必要なクリエイティブ エージェントに最適","ko":"Flask와 SQLite를 사용하여 고급 만화 생성 기능이 필요한 창의적 에이전트에 적합","es":"Perfecto para agentes creativos que necesitan conocimientos avanzados en generación de cómics con Flask y SQLite","fr":"Parfait pour les agents créatifs ayant besoin de connaissances avancées en génération de bandes dessinées avec Flask et SQLite","de":"Perfekt für kreative Agenten, die erweitertes Wissen über Comic-Generierung mit Flask und SQLite benötigen","pt":"Perfeito para Agentes Criativos que necessitam de conhecimento avançado em capacidades de geração de quadrinhos com Flask e SQLite","ru":"Идеально для Креативных Агентов, которым необходимы продвинутые знания возможностей генерации комиксов с Flask и SQLite","ar":"مثالي للوكلاء الإبداعيين الذين يحتاجون إلى معرفة متقدمة بقدرات توليد القصص المصورة مع Flask و SQLite"},"recommendation":{"en":"Empowers agents to generate original knowledge comics with multiple visual styles, such as dramatic, warm, and tech, and various layouts, including cinematic and webtoon, utilizing automated email reports for seamless content delivery","zh":"赋予代理生成具有多种视觉风格（如戏剧性、温暖和科技）和各种布局（包括电影和网络漫画）原创知识漫画的能力，并利用自动电子邮件报告实现无缝内容交付","ja":"ドラマティック、ウォーム、テックなどの複数の視覚スタイルと、シネマティックやウェブトゥーンなどの様々なレイアウトを使用して、独自の知識コミックを生成し、自動化された電子メールレポートを使用して無шовなコンテンツ配信を実現するエージェントをEmpowerする","ko":"다중 시각 스타일(드라마틱, 따뜻함, 기술 등) 및 다양한 레이아웃(시네마틱 및 웹툰 등)을 사용하여 원创 지식 만화를 생성하고 자동화 된 이메일 보고서를 사용하여 無縫な 콘텐츠 전달을 실현하는 에이전트를 Empower하는 것","es":"Habilita a los agentes para generar cómics de conocimiento originales con múltiples estilos visuales, como dramáticos, cálidos y técnicos, y diversos diseños, incluyendo cinematográficos y webtoon, utilizando informes de correo electrónico automatizados para una entrega de contenido sin problemas","fr":"Permet aux agents de générer des bandes dessinées de connaissances originales avec de multiples styles visuels, tels que dramatiques, chaleureux et techniques, et diverses dispositions, y compris cinématographiques et webtoon, en utilisant des rapports de courrier électronique automatisés pour une livraison de contenu sans interruption","de":"Ermöglicht es den Agenten, originale Wissenscomics mit mehreren visuellen Stilen, wie dramatisch, warm und technisch, und verschiedenen Layouts, einschließlich kinematografischer und Webtoon, zu generieren, indem automatisierte E-Mail-Berichte für eine nahtlose Inhaltslieferung verwendet werden","pt":"Habilita agentes a gerar quadrinhos de conhecimento originais com vários estilos visuais, como dramático, quente e tecnológico, e layouts variados, incluindo cinematográfico e webtoon, utilizando relatórios de e-mail automatizados para entrega de conteúdo sem interrupções","ru":"Наделяет агентов возможностью генерировать оригинальные комиксы знаний с различными визуальными стилями, такими как драматический, тёплый и тех, и различными макетами, включая кинематографический и вебтун, используя автоматические отчёты по электронной почте для бесперебойной доставки контента","ar":"تمكّن الوكلاء من توليد قصص مصورة أصلية مع أساليب بصرية متعددة مثل الدرامية والدافئة والتكنولوجية والتصاميم المختلفة، بما في ذلك السينمائية والويبتون، باستخدام تقارير البريد الإلكتروني الآلية لتسليم المحتوى دون انقطاع"},"useCases":{"en":["Generating knowledge comics from Markdown sources","Customizing comic styles and layouts for diverse content","Automating email reports for content creators and developers"],"zh":["从 Markdown 源生成知识漫画","为多样化内容自定义漫画风格和布局","为内容创作者和开发人员自动化电子邮件报告"],"ja":["Markdown ソースから知識コミックを生成する","多様なコンテンツ用にコミックスタイルとレイアウトをカスタマイズする","コンテンツクリエイターと開発者用に自動化された電子メールレポートを実現する"],"ko":["마크다운 소스에서 지식 만화를 생성하는 것","다양한 콘텐츠를 위한 만화 스타일 및 레이아웃을 사용자 정의하는 것","콘텐츠 제작자 및 개발자용 자동화 된 이메일 보고서를 실현하는 것"],"es":["Generar cómics de conocimiento a partir de fuentes Markdown","Personalizar estilos y diseños de cómics para contenido diverso","Automatizar informes de correo electrónico para creadores y desarrolladores de contenido"],"fr":["Générer des bandes dessinées de connaissances à partir de sources Markdown","Personnaliser les styles et les dispositions de bandes dessinées pour un contenu diversifié","Automatiser les rapports de courrier électronique pour les créateurs et les développeurs de contenu"],"de":["Generieren von Wissenscomics aus Markdown-Quellen","Anpassen von Comic-Stilen und -Layouts für vielfältigen Inhalt","Automatisieren von E-Mail-Berichten für Content-Ersteller und -Entwickler"],"pt":["Gerar quadrinhos de conhecimento a partir de fontes Markdown","Personalizar estilos e layouts de quadrinhos para conteúdo diverso","Automatizar relatórios de e-mail para criadores de conteúdo e desenvolvedores"],"ru":["Генерировать комиксы знаний из источников Markdown","Настроить стили и макеты комиксов для разнообразного контента","Автоматизировать отчёты по электронной почте для создателей контента и разработчиков"],"ar":["توليد قصص مصورة من مصادر Markdown","تخصيص أساليب وقوالب القصص المصورة لمحتوى متنوع","توفير تقارير البريد الإلكتروني آليًا لمبدعي المحتوى والمطورين"]},"limitations":{"en":["Requires Flask and SQLite setup","Limited to specific visual styles and layouts","Dependent on Markdown source files"],"zh":["需要 Flask 和 SQLite 设置","仅限特定视觉风格和布局","依赖于 Markdown 源文件"],"ja":["Flask と SQLite の設定が必要","特定の視覚スタイルとレイアウトのみ","Markdown ソースファイルに依存"],"ko":["Flask와 SQLite 설정이 필요","특정 시각 스타일 및 레이아웃만","마크다운 소스 파일에 의존"],"es":["Requiere configuración de Flask y SQLite","Limitado a estilos visuales y diseños específicos","Dependiente de archivos de fuente Markdown"],"fr":["Nécessite une configuration de Flask et SQLite","Limité à des styles visuels et des dispositions spécifiques","Dépendant des fichiers source Markdown"],"de":["Benötigt eine Einrichtung von Flask und SQLite","Begrenzt auf bestimmte visuelle Stile und Layouts","Abhängig von Markdown-Quelldateien"],"pt":["Requer configuração do Flask e SQLite","Limitado a estilos visuais e layouts específicos","Dependente de arquivos de fonte Markdown"],"ru":["Требует настройки Flask и SQLite","Ограничен конкретными визуальными стилями и макетами","Зависит от файлов источников Markdown"],"ar":["يتطلب إعداد Flask و SQLite","محدود بالأساليب البصرية والتصاميم المحددة","يعتمد على ملفات مصدر Markdown"]},"version":4},"contentHash":"a33eefb2b486118a991ed6a3939d52b4f6dfa9f130de5e70331006a85010cd72","qualityScore":54}');
