INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sayanget/inbound-recorder-system/baoyu-comic', 'baoyu-comic', 'sayanget', 'inbound-recorder-system', 'community', 'baoyu-comic sayanget inbound-recorder-system community The baoyu-comic skill creates original knowledge comics with multiple visual styles and layouts, benefiting developers and content creators. It utilizes Flask, SQLite, and automated email reports. baoyu-comic是一个仓库入库记录系统，使用Flask和SQLite，支持离线操作，并提供自动电子邮件报告 baoyu-comicは、FlaskとSQLiteを使用した倉庫入庫記録システムです。オフライン対応であり、自動電子メールレポートも提供します baoyu-comic은 Flask와 SQLite를 사용한 창고 입고 기록 시스템으로, 오프라인 지원과 자동 이메일 보고서를 제공합니다 baoyu-comic es un sistema de grabación de entrada de almacén con Flask, SQLite y soporte offline, que permite la creación de cómics de conocimiento con múltiples estilos visuales baoyu-comic est un système d''enregistrement d''entrée de stock avec Flask, SQLite et prise en charge hors ligne, qui permet la création de bandes dessinées de connaissances avec plusieurs styles visuels baoyu-comic ist ein Warehouse-Inbound-Recorder-System mit Flask, SQLite und Offline-Unterstützung, das die Erstellung von Wissenscomics mit mehreren visuellen Stilen ermöglicht O baoyu-comic é um sistema de gravação de entrada de armazém que utiliza Flask e SQLite, com suporte offline e relatórios de e-mail automatizados. baoyu-comic - это система записи входа в склад, использующая Flask и SQLite, с поддержкой offline и автоматическими отчетами по электронной почте, ИИ Агенты baoyu-comic هو نظام تسجيل دخول المستودع الذي يستخدم Flask و SQLite، مع دعم عدم الاتصال و تقارير البريد الإلكتروني الآلية، أدوات الذكاء الاصطناعي how to use baoyu-comic baoyu-comic alternative baoyu-comic setup guide what is baoyu-comic baoyu-comic vs other comic creators baoyu-comic install automated comic creation knowledge comic generation Flask and SQLite development baoyu-comic Flask SQLite 离线支持 自动电子邮件报告 知识漫画 仓库入库记录系统 AIエージェント Generates knowledge comics with multiple visual styles, including classic, dramatic, and vibrant Supports various layouts, such as standard, cinematic, and webtoon Utilizes Flask for web development and SQLite for database management Provides offline support for comic creation Sends automated email reports for efficient communication baoyu-comic is a Warehouse Inbound Recorder System that generates knowledge comics with various styles and layouts using Flask and SQLite.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('juanfranem/adha_bot/python-performance-optimization', 'community', 'juanfranem', 'adha_bot', 'juanfranem/adha_bot', 'python-performance-optimization', 0, 0, 54, '2026-03-08T01:57:15.518Z', '2026-03-08T02:10:36.203Z', '485203c990c348629c3c8e1ba30ddcccef834a131b62b40bc197defe117d7103', '{"id":"juanfranem/adha_bot/python-performance-optimization","name":"python-performance-optimization","description":{"en":"Python-performance-optimization is a comprehensive guide for developers to optimize Python code for better performance, including CPU profiling and memory optimization. It benefits developers seeking to improve application latency and response times.","zh":"本指南提供了优化Python代码性能的综合方法，包括CPU профилиング、内存优化和实现最佳实践","ja":"このガイドでは、Pythonコードのパフォーマンスを最適化する方法を紹介します。CPUプロファイリング、メモリ最適化、ベストプラクティスなど","ko":"이 가이드는 파이썬 코드의 성능을 최적화하는 방법을 제공합니다. CPU 프로파일링, 메모리 최적화, 구현 최적화 등","es":"Optimice el rendimiento de su código Python con nuestra guía completa sobre perfilado, análisis y optimización","fr":"Optimisez les performances de votre code Python avec notre guide complet sur le profilage, l''analyse et l''optimisation","de":"Optimieren Sie die Leistung Ihres Python-Codes mit unserer umfassenden Anleitung zu Profiling, Analyse und Optimierung","pt":"Otimização de desempenho Python para melhorar a velocidade e reduzir a latência em aplicações","ru":"Оптимизация производительности Python для улучшения скорости и снижения задержки в приложениях","ar":"تحسين أداء بايثون لتحسين السرعة وتقليل الوقت الإضافي في التطبيقات"},"seo":{"title":{"en":"Python-Performance-Optimization: Expert Guide for AI Agen...","zh":"Python性能优化设置指南","ja":"Pythonパフォーマンス最適化ベストプラクティス","ko":"파이썬 성능 최적화 가이드","es":"Guía de Optimización de Rendimiento de Python","fr":"Guide d''Optimisation des Performances Python","de":"Python-Performance-Optimierungs-Setup","pt":"Guia de Otimização de Desempenho Python","ru":"Оптимизация Производительности Python: Полное Руководство","ar":"دليل تحسين أداء بايثون"},"description":{"en":"Unlock faster Python applications with our expert guide to performance optimization. Learn how to identify bottlenecks, reduce latency, and improve CPU-inten...","zh":"了解如何优化Python代码的性能，包括CPU профилиング、内存优化和实现最佳实践","ja":"Pythonコードのパフォーマンスを最適化する方法を学びます。CPUプロファイリング、メモリ最適化、ベストプラクティスなど","ko":"파이썬 코드의 성능을 최적화하는 방법을 알아보세요. CPU 프로파일링, 메모리 최적화, 구현 최적화 등","es":"Aprende a identificar cuellos de botella y optimizar el rendimiento de tus aplicaciones Python con nuestra guía","fr":"Découvrez comment identifier les goulots d''étranglement et optimiser les performances de vos applications Python avec notre guide","de":"Erfahren Sie, wie Sie Leistungsengpässe identifizieren und die Performance Ihrer Python-Anwendungen optimieren","pt":"Aprenda a identificar gargalos de desempenho em aplicações Python e otimize o código para melhorar a velocidade e reduzir a latência","ru":"Узнайте, как выявить узкие места производительности в приложениях Python и оптимизировать код для улучшения скорости и снижения задержки","ar":"تعلم كيفية تحديد معوقات الأداء في تطبيقات بايثون و تحسين الكود لتحسين السرعة وتقليل الوقت الإضافي"},"definition":{"en":"python-performance-optimization is a set of techniques for profiling, analyzing, and optimizing Python code to achieve better performance, including CPU profiling, memory optimization, and implementation best practices.","zh":"Python性能优化是指优化Python代码的性能，以提高应用程序的响应速度和效率","ja":"Pythonパフォーマンス最適化とは、Pythonコードのパフォーマンスを最適化して、アプリケーションの応答速度と効率を向上させること","ko":"파이썬 성능 최적화는 파이썬 코드의 성능을 최적화하여 응용 프로그램의 응답 속도와 효율성을 향상시키는 것을 말합니다","es":"La optimización de rendimiento de Python es el proceso de mejorar la eficiencia y velocidad de las aplicaciones Python","fr":"L''optimisation des performances Python est le processus d''amélioration de l''efficacité et de la vitesse des applications Python","de":"Die Performance-Optimierung von Python ist der Prozess der Verbesserung der Effizienz und Geschwindigkeit von Python-Anwendungen","pt":"Otimização de desempenho Python é o processo de identificar e resolver gargalos de desempenho em código Python","ru":"Оптимизация производительности Python - это процесс выявления и решения узких мест производительности в коде Python","ar":"تحسين أداء بايثون هو عملية تحديد ومعالجة معوقات الأداء في كود بايثون"},"features":{"en":["Identifies performance bottlenecks in Python applications","Reduces application latency and response times through CPU profiling","Optimizes CPU-intensive operations for improved performance","Minimizes memory consumption and memory leaks","Improves database query performance","Optimizes I/O operations for faster data processing"],"zh":["CPU профилиング","内存优化","实现最佳实践","减少应用程序延迟和响应时间","优化CPU密集型操作","减少内存消耗和内存泄漏"],"ja":["CPUプロファイリング","メモリ最適化","ベストプラクティスの実装","アプリケーションの遅延と応答時間の削減","CPU密集型操作の最適化","メモリ消費とメモリ漏れの削減"],"ko":["CPU 프로파일링","메모리 최적화","구현 최적화","응용 프로그램 지연과 응답 시간의 감소","CPU 집중적 연산의 최적화","메모리 소비와 메모리 누수의 감소"],"es":["Perfilado de CPU para identificar cuellos de botella","Optimización de memoria para reducir la consumición de recursos","Mejora de la performance de consultas de base de datos","Optimización de operaciones de E/S","Implementación de mejores prácticas para operaciones intensivas de CPU"],"fr":["Profilage CPU pour identifier les goulots d''étranglement","Optimisation de la mémoire pour réduire la consommation de ressources","Amélioration des performances des requêtes de base de données","Optimisation des opérations d''E/S","Mise en œuvre de meilleures pratiques pour les opérations intensives de CPU"],"de":["CPU-Profiling zur Identifizierung von Leistungsengpässen","Optimierung des Speichers zur Reduzierung des Ressourcenverbrauchs","Verbesserung der Leistung von Datenbankabfragen","Optimierung von E/A-Operationen","Implementierung von Best Practices für CPU-intensiven Operationen"],"pt":["Profiling de CPU para identificar gargalos de desempenho","Otimização de memória para reduzir consumo e vazamentos","Melhoria do desempenho de consultas de banco de dados","Otimização de operações de I/O","Implementação de práticas recomendadas para melhorar a velocidade"],"ru":["Профилирование CPU для выявления узких мест производительности","Оптимизация памяти для снижения потребления и утечек","Улучшение производительности запросов к базе данных","Оптимизация операций ввода/вывода","Реализация лучших практик для улучшения скорости"],"ar":["تحليل أداء وحدة المعالجة المركزية لتحديد معوقات الأداء","تحسين الذاكرة لتقليل الاستهلاك والتسريبات","تحسين أداء استعلامات قاعدة البيانات","تحسين عمليات الإدخال والإخراج","تنفيذ أفضل الممارسات لتحسين السرعة"]},"keywords":{"en":["how to use python-performance-optimization","python-performance-optimization tutorial","python-performance-optimization vs cProfile","python-performance-optimization install","python-performance-optimization setup guide","python-performance-optimization best practices"],"zh":["Python性能优化","CPU профилиング","内存优化","Python代码优化","应用程序性能优化","AIエージェント","Python开发"],"ja":["Pythonパフォーマンス最適化","CPUプロファイリング","メモリ最適化","Pythonコード最適化","アプリケーション性能最適化","AIエージェント","Python開発"],"ko":["파이썬 성능 최적화","CPU 프로파일링","메모리 최적화","파이썬 코드 최적화","응용 프로그램 성능 최적화","AI 에이전트","파이썬 개발"],"es":["optimización de rendimiento de python","perfilado de cpu","optimización de memoria","mejora de la performance de consultas de base de datos","optimización de operaciones de e/s","python performance optimization","herramientas de optimización de python"],"fr":["optimisation des performances python","profilage cpu","optimisation de la mémoire","amélioration des performances des requêtes de base de données","optimisation des opérations d''e/s","python performance optimization","outils d''optimisation python"],"de":["python-leistungsoptimierung","cpu-profilierung","speicheroptimierung","verbesserung der leistung von datenbankabfragen","optimierung von e/a-operationen","python performance optimization","werkzeuge zur optimierung von python"],"pt":["otimização de desempenho python","profiling de cpu","otimização de memória","melhoria de desempenho de banco de dados","otimização de operações de i/o","práticas recomendadas para python","desenvolvimento de aplicações python","otimização de código python"],"ru":["оптимизация производительности python","профилирование cpu","оптимизация памяти","улучшение производительности запросов к базе данных","оптимизация операций ввода/вывода","лучшие практики для python","разработка приложений python","оптимизация кода python"],"ar":["تحسين أداء بايثون","تحليل أداء وحدة المعالجة المركزية","تحسين الذاكرة","تحسين أداء استعلامات قاعدة البيانات","تحسين عمليات الإدخال والإخراج","أفضل الممارسات لبايثون","تطوير تطبيقات بايثون","تحسين كود بايثون"]}},"owner":"juanfranem","repo":"adha_bot","repoPath":"juanfranem/adha_bot","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.518Z","topics":[],"category":"community","skillMd":{"name":"python-performance-optimization","description":"Profile and optimize Python code using cProfile, memory profilers, and performance best practices. Use when debugging slow Python code, optimizing bottlenecks, or improving application performance.","bodyPreview":"# Python Performance Optimization\n\nComprehensive guide to profiling, analyzing, and optimizing Python code for better performance, including CPU profiling, memory optimization, and implementation best practices.\n\n## When to Use This Skill\n\n- Identifying performance bottlenecks in Python applications\n- Reducing application latency and response times\n- Optimizing CPU-intensive operations\n- Reducing memory consumption and memory leaks\n- Improving database query performance\n- Optimizing I/O operatio","body":"# Python Performance Optimization\n\nComprehensive guide to profiling, analyzing, and optimizing Python code for better performance, including CPU profiling, memory optimization, and implementation best practices.\n\n## When to Use This Skill\n\n- Identifying performance bottlenecks in Python applications\n- Reducing application latency and response times\n- Optimizing CPU-intensive operations\n- Reducing memory consumption and memory leaks\n- Improving database query performance\n- Optimizing I/O operations\n- Speeding up data processing pipelines\n- Implementing high-performance algorithms\n- Profiling production applications\n\n## Core Concepts\n\n### 1. Profiling Types\n\n- **CPU Profiling**: Identify time-consuming functions\n- **Memory Profiling**: Track memory allocation and leaks\n- **Line Profiling**: Profile at line-by-line granularity\n- **Call Graph**: Visualize function call relationships\n\n### 2. Performance Metrics\n\n- **Execution Time**: How long operations take\n- **Memory Usage**: Peak and average memory consumption\n- **CPU Utilization**: Processor usage patterns\n- **I/O Wait**: Time spent on I/O operations\n\n### 3. Optimization Strategies\n\n- **Algorithmic**: Better algorithms and data structures\n- **Implementation**: More efficient code patterns\n- **Parallelization**: Multi-threading/processing\n- **Caching**: Avoid redundant computation\n- **Native Extensions**: C/Rust for critical paths\n\n## Quick Start\n\n### Basic Timing\n\n```python\nimport time\n\ndef measure_time():\n    \"\"\"Simple timing measurement.\"\"\"\n    start = time.time()\n\n    # Your code here\n    result = sum(range(1000000))\n\n    elapsed = time.time() - start\n    print(f\"Execution time: {elapsed:.4f} seconds\")\n    return result\n\n# Better: use timeit for accurate measurements\nimport timeit\n\nexecution_time = timeit.timeit(\n    \"sum(range(1000000))\",\n    number=100\n)\nprint(f\"Average time: {execution_time/100:.6f} seconds\")\n```\n\n## Profiling Tools\n\n### Pattern 1: cProfile - CPU Profiling\n\n```python\nimport cProfile\nimport pstats\nfrom pstats import SortKey\n\ndef slow_function():\n    \"\"\"Function to profile.\"\"\"\n    total = 0\n    for i in range(1000000):\n        total += i\n    return total\n\ndef another_function():\n    \"\"\"Another function.\"\"\"\n    return [i**2 for i in range(100000)]\n\ndef main():\n    \"\"\"Main function to profile.\"\"\"\n    result1 = slow_function()\n    result2 = another_function()\n    return result1, result2\n\n# Profile the code\nif __name__ == \"__main__\":\n    profiler = cProfile.Profile()\n    profiler.enable()\n\n    main()\n\n    profiler.disable()\n\n    # Print stats\n    stats = pstats.Stats(profiler)\n    stats.sort_stats(SortKey.CUMULATIVE)\n    stats.print_stats(10)  # Top 10 functions\n\n    # Save to file for later analysis\n    stats.dump_stats(\"profile_output.prof\")\n```\n\n**Command-line profiling:**\n\n```bash\n# Profile a script\npython -m cProfile -o output.prof script.py\n\n# View results\npython -m pstats output.prof\n# In pstats:\n# sort cumtime\n# stats 10\n```\n\n### Pattern 2: line_profiler - Line-by-Line Profiling\n\n```python\n# Install: pip install line-profiler\n\n# Add @profile decorator (line_profiler provides this)\n@profile\ndef process_data(data):\n    \"\"\"Process data with line profiling.\"\"\"\n    result = []\n    for item in data:\n        processed = item * 2\n        result.append(processed)\n    return result\n\n# Run with:\n# kernprof -l -v script.py\n```\n\n**Manual line profiling:**\n\n```python\nfrom line_profiler import LineProfiler\n\ndef process_data(data):\n    \"\"\"Function to profile.\"\"\"\n    result = []\n    for item in data:\n        processed = item * 2\n        result.append(processed)\n    return result\n\nif __name__ == \"__main__\":\n    lp = LineProfiler()\n    lp.add_function(process_data)\n\n    data = list(range(100000))\n\n    lp_wrapper = lp(process_data)\n    lp_wrapper(data)\n\n    lp.print_stats()\n```\n\n### Pattern 3: memory_profiler - Memory Usage\n\n```python\n# Install: pip install memory-profiler\n\nfrom memory_profiler import profile\n\n@profile\ndef memory_intensive():\n    \"\"\"Function that uses lots of memory.\"\"\"\n    # Create large list\n    big_list = [i for i in range(1000000)]\n\n    # Create large dict\n    big_dict = {i: i**2 for i in range(100000)}\n\n    # Process data\n    result = sum(big_list)\n\n    return result\n\nif __name__ == \"__main__\":\n    memory_intensive()\n\n# Run with:\n# python -m memory_profiler script.py\n```\n\n### Pattern 4: py-spy - Production Profiling\n\n```bash\n# Install: pip install py-spy\n\n# Profile a running Python process\npy-spy top --pid 12345\n\n# Generate flamegraph\npy-spy record -o profile.svg --pid 12345\n\n# Profile a script\npy-spy record -o profile.svg -- python script.py\n\n# Dump current call stack\npy-spy dump --pid 12345\n```\n\n## Optimization Patterns\n\n### Pattern 5: List Comprehensions vs Loops\n\n```python\nimport timeit\n\n# Slow: Traditional loop\ndef slow_squares(n):\n    \"\"\"Create list of squares using loop.\"\"\"\n    result = []\n    for i in range(n):\n        result.append(i**2)\n    return result\n\n# Fast: List comprehension\ndef fast_squares(n):\n    \"\"\"Create list of squares using comprehension.\"\"\"\n    return [i**2 for i in range(n)]\n\n# Benchmark\nn = 100000\n\nslow_time = timeit.timeit(lambda: slow_squares(n), number=100)\nfast_time = timeit.timeit(lambda: fast_squares(n), number=100)\n\nprint(f\"Loop: {slow_time:.4f}s\")\nprint(f\"Comprehension: {fast_time:.4f}s\")\nprint(f\"Speedup: {slow_time/fast_time:.2f}x\")\n\n# Even faster for simple operations: map\ndef faster_squares(n):\n    \"\"\"Use map for even better performance.\"\"\"\n    return list(map(lambda x: x**2, range(n)))\n```\n\n### Pattern 6: Generator Expressions for Memory\n\n```python\nimport sys\n\ndef list_approach():\n    \"\"\"Memory-intensive list.\"\"\"\n    data = [i**2 for i in range(1000000)]\n    return sum(data)\n\ndef generator_approach():\n    \"\"\"Memory-efficient generator.\"\"\"\n    data = (i**2 for i in range(1000000))\n    return sum(data)\n\n# Memory comparison\nlist_data = [i for i in range(1000000)]\ngen_data = (i for i in range(1000000))\n\nprint(f\"List size: {sys.getsizeof(list_data)} bytes\")\nprint(f\"Generator size: {sys.getsizeof(gen_data)} bytes\")\n\n# Generators use constant memory regardless of size\n```\n\n### Pattern 7: String Concatenation\n\n```python\nimport timeit\n\ndef slow_concat(items):\n    \"\"\"Slow string concatenation.\"\"\"\n    result = \"\"\n    for item in items:\n        result += str(item)\n    return result\n\ndef fast_concat(items):\n    \"\"\"Fast string concatenation with join.\"\"\"\n    return \"\".join(str(item) for item in items)\n\ndef faster_concat(items):\n    \"\"\"Even faster with list.\"\"\"\n    parts = [str(item) for item in items]\n    return \"\".join(parts)\n\nitems = list(range(10000))\n\n# Benchmark\nslow = timeit.timeit(lambda: slow_concat(items), number=100)\nfast = timeit.timeit(lambda: fast_concat(items), number=100)\nfaster = timeit.timeit(lambda: faster_concat(items), number=100)\n\nprint(f\"Concatenation (+): {slow:.4f}s\")\nprint(f\"Join (generator): {fast:.4f}s\")\nprint(f\"Join (list): {faster:.4f}s\")\n```\n\n### Pattern 8: Dictionary Lookups vs List Searches\n\n```python\nimport timeit\n\n# Create test data\nsize = 10000\nitems = list(range(size))\nlookup_dict = {i: i for i in range(size)}\n\ndef list_search(items, target):\n    \"\"\"O(n) search in list.\"\"\"\n    return target in items\n\ndef dict_search(lookup_dict, target):\n    \"\"\"O(1) search in dict.\"\"\"\n    return target in lookup_dict\n\ntarget = size - 1  # Worst case for list\n\n# Benchmark\nlist_time = timeit.timeit(\n    lambda: list_search(items, target),\n    number=1000\n)\ndict_time = timeit.timeit(\n    lambda: dict_search(lookup_dict, target),\n    number=1000\n)\n\nprint(f\"List search: {list_time:.6f}s\")\nprint(f\"Dict search: {dict_time:.6f}s\")\nprint(f\"Speedup: {list_time/dict_time:.0f}x\")\n```\n\n### Pattern 9: Local Variable Access\n\n```python\nimport timeit\n\n# Global variable (slow)\nGLOBAL_VALUE = 100\n\ndef use_global():\n    \"\"\"Access global variable.\"\"\"\n    total = 0\n    for i in range(10000):\n        total += GLOBAL_VALUE\n    return total\n\ndef use_local():\n    \"\"\"Use local variable.\"\"\"\n    local_value = 100\n    total = 0\n    for i in range(10000):\n        total += local_value\n    return total\n\n# Local is faster\nglobal_time = timeit.timeit(use_global, number=1000)\nlocal_time = timeit.timeit(use_local, number=1000)\n\nprint(f\"Global access: {global_time:.4f}s\")\nprint(f\"Local access: {local_time:.4f}s\")\nprint(f\"Speedup: {global_time/local_time:.2f}x\")\n```\n\n### Pattern 10: Function Call Overhead\n\n```python\nimport timeit\n\ndef calculate_inline():\n    \"\"\"Inline calculation.\"\"\"\n    total = 0\n    for i in range(10000):\n        total += i * 2 + 1\n    return total\n\ndef helper_function(x):\n    \"\"\"Helper function.\"\"\"\n    return x * 2 + 1\n\ndef calculate_with_function():\n    \"\"\"Calculation with function calls.\"\"\"\n    total = 0\n    for i in range(10000):\n        total += helper_function(i)\n    return total\n\n# Inline is faster due to no call overhead\ninline_time = timeit.timeit(calculate_inline, number=1000)\nfunction_time = timeit.timeit(calculate_with_function, number=1000)\n\nprint(f\"Inline: {inline_time:.4f}s\")\nprint(f\"Function calls: {function_time:.4f}s\")\n```\n\n## Advanced Optimization\n\n### Pattern 11: NumPy for Numerical Operations\n\n```python\nimport timeit\nimport numpy as np\n\ndef python_sum(n):\n    \"\"\"Sum using pure Python.\"\"\"\n    return sum(range(n))\n\ndef numpy_sum(n):\n    \"\"\"Sum using NumPy.\"\"\"\n    return np.arange(n).sum()\n\nn = 1000000\n\npython_time = timeit.timeit(lambda: python_sum(n), number=100)\nnumpy_time = timeit.timeit(lambda: numpy_sum(n), number=100)\n\nprint(f\"Python: {python_time:.4f}s\")\nprint(f\"NumPy: {numpy_time:.4f}s\")\nprint(f\"Speedup: {python_time/numpy_time:.2f}x\")\n\n# Vectorized operations\ndef python_multiply():\n    \"\"\"Element-wise multiplication in Python.\"\"\"\n    a = list(range(100000))\n    b = list(range(100000))\n    return [x * y for x, y in zip(a, b)]\n\ndef numpy_multiply():\n    \"\"\"Vectorized multiplication in NumPy.\"\"\"\n    a = np.arange(100000)\n    b = np.arange(100000)\n    return a * b\n\npy_time = timeit.timeit(python_multiply, number=100)\nnp_time = timeit.timeit(numpy_multiply, number=100)\n\nprint(f\"\\nPython multiply: {py_time:.4f}s\")\nprint(f\"NumPy multiply: {np_time:.4f}s\")\nprint(f\"Speedup: {py_time/np_time:.2f}x\")\n```\n\n### Pattern 12: Caching with functools.lru_cache\n\n```python\nfrom functools import lru_cache\nimport timeit\n\ndef fibonacci_slow(n):\n    \"\"\"Recursive fibonacci without caching.\"\"\"\n    if n < 2:\n        return n\n    return fibonacci_slow(n-1) + fibonacci_slow(n-2)\n\n@lru_cache(maxsize=None)\ndef fibonacci_fast(n):\n    \"\"\"Recursive fibonacci with caching.\"\"\"\n    if n < 2:\n        return n\n    return fibonacci_fast(n-1) + fibonacci_fast(n-2)\n\n# Massive speedup for recursive algorithms\nn = 30\n\nslow_time = timeit.timeit(lambda: fibonacci_slow(n), number=1)\nfast_time = timeit.timeit(lambda: fibonacci_fast(n), number=1000)\n\nprint(f\"Without cache (1 run): {slow_time:.4f}s\")\nprint(f\"With cache (1000 runs): {fast_time:.4f}s\")\n\n# Cache info\nprint(f\"Cache info: {fibonacci_fast.cache_info()}\")\n```\n\n### Pattern 13: Using **slots** for Memory\n\n```python\nimport sys\n\nclass RegularClass:\n    \"\"\"Regular class with __dict__.\"\"\"\n    def __init__(self, x, y, z):\n        self.x = x\n        self.y = y\n        self.z = z\n\nclass SlottedClass:\n    \"\"\"Class with __slots__ for memory efficiency.\"\"\"\n    __slots__ = [''x'', ''y'', ''z'']\n\n    def __init__(self, x, y, z):\n        self.x = x\n        self.y = y\n        self.z = z\n\n# Memory comparison\nregular = RegularClass(1, 2, 3)\nslotted = SlottedClass(1, 2, 3)\n\nprint(f\"Regular class size: {sys.getsizeof(regular)} bytes\")\nprint(f\"Slotted class size: {sys.getsizeof(slotted)} bytes\")\n\n# Significant savings with many instances\nregular_objects = [RegularClass(i, i+1, i+2) for i in range(10000)]\nslotted_objects = [SlottedClass(i, i+1, i+2) for i in range(10000)]\n\nprint(f\"\\nMemory for 10000 regular objects: ~{sys.getsizeof(regular) * 10000} bytes\")\nprint(f\"Memory for 10000 slotted objects: ~{sys.getsizeof(slotted) * 10000} bytes\")\n```\n\n### Pattern 14: Multiprocessing for CPU-Bound Tasks\n\n```python\nimport multiprocessing as mp\nimport time\n\ndef cpu_intensive_task(n):\n    \"\"\"CPU-intensive calculation.\"\"\"\n    return sum(i**2 for i in range(n))\n\ndef sequential_processing():\n    \"\"\"Process tasks sequentially.\"\"\"\n    start = time.time()\n    results = [cpu_intensive_task(1000000) for _ in range(4)]\n    elapsed = time.time() - start\n    return elapsed, results\n\ndef parallel_processing():\n    \"\"\"Process tasks in parallel.\"\"\"\n    start = time.time()\n    with mp.Pool(processes=4) as pool:\n        results = pool.map(cpu_intensive_task, [1000000] * 4)\n    elapsed = time.time() - start\n    return elapsed, results\n\nif __name__ == \"__main__\":\n    seq_time, seq_results = sequential_processing()\n    par_time, par_results = parallel_processing()\n\n    print(f\"Sequential: {seq_time:.2f}s\")\n    print(f\"Parallel: {par_time:.2f}s\")\n    print(f\"Speedup: {seq_time/par_time:.2f}x\")\n```\n\n### Pattern 15: Async I/O for I/O-Bound Tasks\n\n```python\nimport asyncio\nimport aiohttp\nimport time\nimport requests\n\nurls = [\n    \"https://httpbin.org/delay/1\",\n    \"https://httpbin.org/delay/1\",\n    \"https://httpbin.org/delay/1\",\n    \"https://httpbin.org/delay/1\",\n]\n\ndef synchronous_requests():\n    \"\"\"Synchronous HTTP requests.\"\"\"\n    start = time.time()\n    results = []\n    for url in urls:\n        response = requests.get(url)\n        results.append(response.status_code)\n    elapsed = time.time() - start\n    return elapsed, results\n\nasync def async_fetch(session, url):\n    \"\"\"Async HTTP request.\"\"\"\n    async with session.get(url) as response:\n        return response.status\n\nasync def asynchronous_requests():\n    \"\"\"Asynchronous HTTP requests.\"\"\"\n    start = time.time()\n    async with aiohttp.ClientSession() as session:\n        tasks = [async_fetch(session, url) for url in urls]\n        results = await asyncio.gather(*tasks)\n    elapsed = time.time() - start\n    return elapsed, results\n\n# Async is much faster for I/O-bound work\nsync_time, sync_results = synchronous_requests()\nasync_time, async_results = asyncio.run(asynchronous_requests())\n\nprint(f\"Synchronous: {sync_time:.2f}s\")\nprint(f\"Asynchronous: {async_time:.2f}s\")\nprint(f\"Speedup: {sync_time/async_time:.2f}x\")\n```\n\n## Database Optimization\n\n### Pattern 16: Batch Database Operations\n\n```python\nimport sqlite3\nimport time\n\ndef create_db():\n    \"\"\"Create test database.\"\"\"\n    conn = sqlite3.connect(\":memory:\")\n    conn.execute(\"CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT)\")\n    return conn\n\ndef slow_inserts(conn, count):\n    \"\"\"Insert records one at a time.\"\"\"\n    start = time.time()\n    cursor = conn.cursor()\n    for i in range(count):\n        cursor.execute(\"INSERT INTO users (name) VALUES (?)\", (f\"User {i}\",))\n        conn.commit()  # Commit each insert\n    elapsed = time.time() - start\n    return elapsed\n\ndef fast_inserts(conn, count):\n    \"\"\"Batch insert with single commit.\"\"\"\n    start = time.time()\n    cursor = conn.cursor()\n    data = [(f\"User {i}\",) for i in range(count)]\n    cursor.executemany(\"INSERT INTO users (name) VALUES (?)\", data)\n    conn.commit()  # Single commit\n    elapsed = time.time() - start\n    return elapsed\n\n# Benchmark\nconn1 = create_db()\nslow_time = slow_inserts(conn1, 1000)\n\nconn2 = create_db()\nfast_time = fast_inserts(conn2, 1000)\n\nprint(f\"Individual inserts: {slow_time:.4f}s\")\nprint(f\"Batch insert: {fast_time:.4f}s\")\nprint(f\"Speedup: {slow_time/fast_time:.2f}x\")\n```\n\n### Pattern 17: Query Optimization\n\n```python\n# Use indexes for frequently queried columns\n\"\"\"\n-- Slow: No index\nSELECT * FROM users WHERE email = ''user@example.com'';\n\n-- Fast: With index\nCREATE INDEX idx_users_email ON users(email);\nSELECT * FROM users WHERE email = ''user@example.com'';\n\"\"\"\n\n# Use query planning\nimport sqlite3\n\nconn = sqlite3.connect(\"example.db\")\ncursor = conn.cursor()\n\n# Analyze query performance\ncursor.execute(\"EXPLAIN QUERY PLAN SELECT * FROM users WHERE email = ?\", (\"test@example.com\",))\nprint(cursor.fetchall())\n\n# Use SELECT only needed columns\n# Slow: SELECT *\n# Fast: SELECT id, name\n```\n\n## Memory Optimization\n\n### Pattern 18: Detecting Memory Leaks\n\n```python\nimport tracemalloc\nimport gc\n\ndef memory_leak_example():\n    \"\"\"Example that leaks memory.\"\"\"\n    leaked_objects = []\n\n    for i in range(100000):\n        # Objects added but never removed\n        leaked_objects.append([i] * 100)\n\n    # In real code, this would be an unintended reference\n\ndef track_memory_usage():\n    \"\"\"Track memory allocations.\"\"\"\n    tracemalloc.start()\n\n    # Take snapshot before\n    snapshot1 = tracemalloc.take_snapshot()\n\n    # Run code\n    memory_leak_example()\n\n    # Take snapshot after\n    snapshot2 = tracemalloc.take_snapshot()\n\n    # Compare\n    top_stats = snapshot2.compare_to(snapshot1, ''lineno'')\n\n    print(\"Top 10 memory allocations:\")\n    for stat in top_stats[:10]:\n        print(stat)\n\n    tracemalloc.stop()\n\n# Monitor memory\ntrack_memory_usage()\n\n# Force garbage collection\ngc.collect()\n```\n\n### Pattern 19: Iterators vs Lists\n\n```python\nimport sys\n\ndef process_file_list(filename):\n    \"\"\"Load entire file into memory.\"\"\"\n    with open(filename) as f:\n        lines = f.readlines()  # Loads all lines\n        return sum(1 for line in lines if line.strip())\n\ndef process_file_iterator(filename):\n    \"\"\"Process file line by line.\"\"\"\n    with open(filename) as f:\n        return sum(1 for line in f if line.strip())\n\n# Iterator uses constant memory\n# List loads entire file into memory\n```\n\n### Pattern 20: Weakref for Caches\n\n```python\nimport weakref\n\nclass CachedResource:\n    \"\"\"Resource that can be garbage collected.\"\"\"\n    def __init__(self, data):\n        self.data = data\n\n# Regular cache prevents garbage collection\nregular_cache = {}\n\ndef get_resource_regular(key):\n    \"\"\"Get resource from regular cache.\"\"\"\n    if key not in regular_cache:\n        regular_cache[key] = CachedResource(f\"Data for {key}\")\n    return regular_cache[key]\n\n# Weak reference cache allows garbage collection\nweak_cache = weakref.WeakValueDictionary()\n\ndef get_resource_weak(key):\n    \"\"\"Get resource from weak cache.\"\"\"\n    resource = weak_cache.get(key)\n    if resource is None:\n        resource = CachedResource(f\"Data for {key}\")\n        weak_cache[key] = resource\n    return resource\n\n# When no strong references exist, objects can be GC''d\n```\n\n## Benchmarking Tools\n\n### Custom Benchmark Decorator\n\n```python\nimport time\nfrom functools import wraps\n\ndef benchmark(func):\n    \"\"\"Decorator to benchmark function execution.\"\"\"\n    @wraps(func)\n    def wrapper(*args, **kwargs):\n        start = time.perf_counter()\n        result = func(*args, **kwargs)\n        elapsed = time.perf_counter() - start\n        print(f\"{func.__name__} took {elapsed:.6f} seconds\")\n        return result\n    return wrapper\n\n@benchmark\ndef slow_function():\n    \"\"\"Function to benchmark.\"\"\"\n    time.sleep(0.5)\n    return sum(range(1000000))\n\nresult = slow_function()\n```\n\n### Performance Testing with pytest-benchmark\n\n```python\n# Install: pip install pytest-benchmark\n\ndef test_list_comprehension(benchmark):\n    \"\"\"Benchmark list comprehension.\"\"\"\n    result = benchmark(lambda: [i**2 for i in range(10000)])\n    assert len(result) == 10000\n\ndef test_map_function(benchmark):\n    \"\"\"Benchmark map function.\"\"\"\n    result = benchmark(lambda: list(map(lambda x: x**2, range(10000))))\n    assert len(result) == 10000\n\n# Run with: pytest test_performance.py --benchmark-compare\n```\n\n## Best Practices\n\n1. **Profile before optimizing** - Measure to find real bottlenecks\n2. **Focus on hot paths** - Optimize code that runs most frequently\n3. **Use appropriate data structures** - Dict for lookups, set for membership\n4. **Avoid premature optimization** - Clarity first, then optimize\n5. **Use built-in functions** - They''re implemented in C\n6. **Cache expensive computations** - Use lru_cache\n7. **Batch I/O operations** - Reduce system calls\n8. **Use generators** for large datasets\n9. **Consider NumPy** for numerical operations\n10. **Profile production code** - Use py-spy for live systems\n\n## Common Pitfalls\n\n- Optimizing without profiling\n- Using global variables unnecessarily\n- Not using appropriate data structures\n- Creating unnecessary copies of data\n- Not using connection pooling for databases\n- Ignoring algorithmic complexity\n- Over-optimizing rare code paths\n- Not considering memory usage\n\n## Resources\n\n- **cProfile**: Built-in CPU profiler\n- **memory_profiler**: Memory usage profiling\n- **line_profiler**: Line-by-line profiling\n- **py-spy**: Sampling profiler for production\n- **NumPy**: High-performance numerical computing\n- **Cython**: Compile Python to C\n- **PyPy**: Alternative Python interpreter with JIT\n\n## Performance Checklist\n\n- [ ] Profiled code to identify bottlenecks\n- [ ] Used appropriate data structures\n- [ ] Implemented caching where beneficial\n- [ ] Optimized database queries\n- [ ] Used generators for large datasets\n- [ ] Considered multiprocessing for CPU-bound tasks\n- [ ] Used async I/O for I/O-bound tasks\n- [ ] Minimized function call overhead in hot loops\n- [ ] Checked for memory leaks\n- [ ] Benchmarked before and after optimization\n"},"lastSynced":"2026-03-08T02:10:36.203Z","agentAnalysis":{"suitability":{"en":"Perfect for Performance Optimization Agents needing advanced CPU profiling and memory optimization capabilities for Python applications.","zh":"适用于需要高级CPU профилирование和内存优化能力的Python应用性能优化代理。","ja":"Pythonアプリケーションに高度なCPUプロファイリングとメモリ最適化機能を必要とするパフォーマンス最適化エージェントに最適です。","ko":"고급 CPU 프로파일링 및 메모리 최적화 기능이 필요한 파이썬 애플리케이션 성능 최적화 에이전트에 적합합니다.","es":"Perfecto para agentes de optimización de rendimiento que necesitan capacidades de perfilado de CPU avanzadas y optimización de memoria para aplicaciones de Python.","fr":"Parfait pour les agents d''optimisation des performances nécessitant un profilage CPU avancé et des capacités d''optimisation de la mémoire pour les applications Python.","de":"Perfekt für Leistungs-Optimierungs-Agents, die erweiterte CPU-Profiling- und Speicher-Optimierungs-Funktionen für Python-Anwendungen benötigen.","pt":"Perfeito para Agentes de Otimização de Desempenho que necessitam de recursos avançados de perfilamento de CPU e otimização de memória para aplicações Python.","ru":"Идеально подходит для агентов оптимизации производительности, которым требуются расширенные возможности профилирования CPU и оптимизации памяти для приложений Python.","ar":"مثالي للوكلاء الأمثل للأداء الذين يحتاجون إلى功能 متقدمة لتحليل أداء وحدة المعالجة المركزية وتحسين الذاكرة لبرامج Python."},"recommendation":{"en":"Empowers agents to identify performance bottlenecks, reduce application latency, and optimize CPU-intensive operations using techniques such as CPU profiling, memory optimization, and implementation best practices, including database query performance and I/O operation optimization.","zh":"赋予代理识别性能瓶颈、降低应用延迟、使用诸如CPU профилирование、内存优化和最佳实践（包括数据库查询性能和I/O操作优化）等技术优化CPU密集型操作的能力。","ja":"エージェントがパフォーマンスのボトルネックを特定し、アプリケーションの待機時間を短縮し、CPUプロファイリング、メモリ最適化、およびベストプラクティス（データベースクエリのパフォーマンスとI/O操作の最適化を含む）などの技術を使用してCPU密集型の操作を最適化する能力を提供します。","ko":"에이전트가 성능 병목 현상을 식별하고 응용 프로그램 대기 시간을 줄이고 CPU 프로파일링, 메모리 최적화 및 최선의 관행 (데이터베이스 쿼리 성능 및 I/O 작업 최적화를 포함)과 같은 기술을 사용하여 CPU 집약적인 작업을 최적화하는 기능을 제공합니다.","es":"Habilita a los agentes a identificar cuellos de botella de rendimiento, reducir la latencia de la aplicación y optimizar operaciones intensivas en CPU utilizando técnicas como el perfilado de CPU, la optimización de memoria y las mejores prácticas de implementación, incluyendo el rendimiento de consultas de base de datos y la optimización de operaciones de E/S.","fr":"Permet aux agents d''identifier les goulets d''étranglement des performances, de réduire la latence de l''application et d''optimiser les opérations intensives en CPU en utilisant des techniques telles que le profilage CPU, l''optimisation de la mémoire et les meilleures pratiques de mise en œuvre, y compris les performances des requêtes de base de données et l''optimisation des opérations de E/S.","de":"Ermöglicht es den Agents, Leistungsengpässe zu identifizieren, die Anwendungsverzögerung zu reduzieren und CPU-intensiven Operationen zu optimieren, indem sie Techniken wie CPU-Profiling, Speicher-Optimierung und Implementierungsbest-Practices verwenden, einschließlich Datenbankabfrageleistung und E/A-Operationsoptimierung.","pt":"Habilita os agentes a identificar gargalos de desempenho, reduzir a latência da aplicação e otimizar operações intensivas de CPU usando técnicas como perfilamento de CPU, otimização de memória e boas práticas de implementação, incluindo desempenho de consultas de banco de dados e otimização de operações de E/S.","ru":"Позволяет агентам выявлять узкие места производительности, снижать задержку приложения и оптимизировать операции, интенсивно использующие CPU, с помощью таких методов, как профилирование CPU, оптимизация памяти и лучшие практики реализации, включая производительность запросов к базе данных и оптимизацию операций ввода/вывода.","ar":"تمكّن الوكلاء من تحديد مشاكل أداء التطبيق، وتقليل التأخير وتحسين العمليات التي تستخدم وحدة المعالجة المركزية بكثافة باستخدام تقنيات مثل تحليل أداء وحدة المعالجة المركزية، وتحسين الذاكرة وأفضل الممارسات في التنفيذ، بما في ذلك أداء استعلامات قاعدة البيانات وتحسين عمليات الإدخال/الإخراج."},"useCases":{"en":["Profiling Python applications to identify performance bottlenecks","Optimizing CPU-intensive operations for better response times","Reducing memory consumption and fixing memory leaks in Python code"],"zh":["对Python应用程序进行 профилирование以识别性能瓶颈","优化CPU密集型操作以获得更好的响应时间","减少Python代码的内存消耗并修复内存泄漏"],"ja":["パフォーマンスのボトルネックを特定するためにPythonアプリケーションをプロファイリングする","レスポンスタイムの向上のためにCPU密集型の操作を最適化する","Pythonコードのメモリ消費を削減し、メモリ漏れを修正する"],"ko":["성능 병목 현상을 식별하기 위해 파이썬 애플리케이션을 프로파일링한다","응답 시간을 개선하기 위해 CPU 집약적인 작업을 최적화한다","파이썬 코드의 메모리 사용량을 줄이고 메모리 누수를 수정한다"],"es":["Crear perfiles de aplicaciones de Python para identificar cuellos de botella de rendimiento","Optimizar operaciones intensivas en CPU para mejores tiempos de respuesta","Reducir el consumo de memoria y solucionar fugas de memoria en el código de Python"],"fr":["Créer des profils d''applications Python pour identifier les goulets d''étranglement des performances","Optimiser les opérations intensives en CPU pour de meilleurs temps de réponse","Réduire la consommation de mémoire et corriger les fuites de mémoire dans le code Python"],"de":["Erstellen von Profilen für Python-Anwendungen, um Leistungsengpässe zu identifizieren","Optimieren von CPU-intensiven Operationen für bessere Antwortzeiten","Verringern des Speicherverbrauchs und Beheben von Speicherlecks im Python-Code"],"pt":["Perfilar aplicações Python para identificar gargalos de desempenho","Otimizar operações intensivas de CPU para melhores tempos de resposta","Reduzir o consumo de memória e corrigir vazamentos de memória no código Python"],"ru":["Профилирование приложений Python для выявления узких мест производительности","Оптимизация операций, интенсивно использующих CPU, для улучшения времени ответа","Снижение потребления памяти и исправление утечек памяти в коде Python"],"ar":["تحليل تطبيقات Python لتحديد مشاكل الأداء","تحسين العمليات التي تستخدم وحدة المعالجة المركزية بكثافة من أجل تحسين أوقات الاستجابة","تقليل استهلاك الذاكرة وتصحيح التسريبات في代码 Python"]},"limitations":{"en":["Requires Python 3.x compatibility","Limited to Python applications only","May require additional tools for advanced profiling and optimization"],"zh":["需要Python 3.x兼容性","仅限于Python应用程序","可能需要额外的工具进行高级 профилирование和优化"],"ja":["Python 3.xとの互換性が必要","Pythonアプリケーションにのみ限定される","高度なプロファイリングと最適化のために追加のツールが必要になる場合がある"],"ko":["파이썬 3.x와의 호환성이 필요함","파이썬 애플리케이션에만 제한됨","고급 프로파일링 및 최적화를 위해 추가 도구가 필요할 수 있음"],"es":["Requiere compatibilidad con Python 3.x","Limitado a aplicaciones de Python solamente","Puede requerir herramientas adicionales para un perfilado y optimización avanzados"],"fr":["Nécessite la compatibilité avec Python 3.x","Limité aux applications Python uniquement","Peut nécessiter des outils supplémentaires pour un profilage et une optimisation avancés"],"de":["Benötigt Python 3.x-Kompatibilität","Begrenzt auf Python-Anwendungen nur","Kann zusätzliche Tools für erweitertes Profiling und Optimierung erfordern"],"pt":["Requer compatibilidade com Python 3.x","Limitado a aplicações Python apenas","Pode requerer ferramentas adicionais para perfilamento e otimização avançados"],"ru":["Требует совместимости с Python 3.x","Ограничен только приложениями Python","Может требовать дополнительных инструментов для расширенного профилирования и оптимизации"],"ar":["يتطلب توافقًا مع Python 3.x","محدود بتطبيقات Python فقط","قد يتطلب أدوات إضافية لتحليل وتحسين متقدمين"]},"version":4},"contentHash":"485203c990c348629c3c8e1ba30ddcccef834a131b62b40bc197defe117d7103","qualityScore":54}');
