INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ThaiG2Pro/ai-agent-sale-v1/postgres-schema-design', 'community', 'ThaiG2Pro', 'ai-agent-sale-v1', 'ThaiG2Pro/ai-agent-sale-v1', 'postgres-schema-design', 0, 0, 54, '2026-03-08T01:57:15.562Z', '2026-03-08T02:11:36.388Z', '406718999e2f6623bdd34835b6adf3f9a5c911a6267a2ee5f9d42e784ccd41f3', '{"id":"ThaiG2Pro/ai-agent-sale-v1/postgres-schema-design","name":"postgres-schema-design","description":{"en":"The postgres-schema-design skill helps AI agents optimize PostgreSQL schema design using SQLModel. It benefits developers by providing guidance on choosing the right data types and adding manual indexes.","zh":"Postgres Schema 设计是数据库性能优化的关键，了解如何选择合适的数据类型、添加手动索引和使用 JSONB","ja":"Postgres スキーマ設計はデータベースのパフォーマンスを向上させる鍵です。データタイプの選択、手動インデックスの追加、JSONB の使用方法を学びましょう","ko":"Postgres 스키마 디자인은 데이터베이스 성능 최적화의 핵심입니다. 적절한 데이터 유형 선택, 수동 인덱스 추가 및 JSONB 사용법을 알아보세요","es":"Diseño de esquemas de PostgreSQL con SQLModel para mejorar el rendimiento y la escalabilidad. Aprende a elegir los tipos de datos adecuados y a agregar índices manuales","fr":"Conception de schémas PostgreSQL avec SQLModel pour améliorer les performances et la scalabilité. Apprenez à choisir les types de données appropriés et à ajouter des index manuels","de":"Entwerfen von PostgreSQL-Schemata mit SQLModel zur Verbesserung der Leistung und Skalierbarkeit. Erfahren Sie, wie Sie die richtigen Datentypen auswählen und manuelle Indizes hinzufügen","pt":"O Postgres-Schema-Design é uma habilidade que permite aos desenvolvedores projetar esquemas de banco de dados Postgres com SQLModel.","ru":"Postgres-Schema-Design - это навык, который позволяет разработчикам проектировать схемы базы данных Postgres с помощью SQLModel для ИИ Агентов.","ar":"تصميم مخطط قاعدة البيانات Postgres هو مهارة تسمح للمطورين بتصميم مخططات قواعد البيانات Postgres باستخدام SQLModel لملحقات الذكاء الاصطناعي."},"seo":{"title":{"en":"Postgres-Schema-Design: Setup Guide for AI Agents | AI Ag...","zh":"Postgres Schema 设计最佳实践","ja":"Postgres スキーマ設計 AIエージェントセットアップガイド","ko":"Postgres 스키마 디자인 설정 가이드","es":"Guía de configuración de esquemas de PostgreSQL con enfoq...","fr":"Guide de configuration de schémas PostgreSQL avec focus s...","de":"Leitfaden für die Konfiguration von PostgreSQL-Schemata m...","pt":"Guia de Configuração do Postgres-Schema-Design para Desen...","ru":"Настройка Схемы Базы Данных Postgres: Лучшие Практики для...","ar":"دليل تصميم مخطط قاعدة البيانات Postgres لملحقات الذكاء ال..."},"description":{"en":"Unlock efficient PostgreSQL schema design with SQLModel focus. Learn how to choose the right data types, add manual indexes, and integrate pgvector for optim...","zh":"了解 Postgres Schema 设计的技术细节，包括数据类型选择、手动索引和 JSONB 的使用","ja":"Postgres スキーマ設計のテクニカルな詳細を学び、データベースのパフォーマンスを向上させよう","ko":"Postgres 스키마 디자인의 기술적 세부 사항을 익히고 데이터베이스 성능을 향상시키는 방법","es":"Aprende a diseñar esquemas de PostgreSQL de manera efectiva con SQLModel. Mejora el rendimiento y la escalabilidad de tus bases de datos","fr":"Découvrez comment concevoir des schémas PostgreSQL efficaces avec SQLModel. Améliorez les performances et la scalabilité de vos bases de données","de":"Erfahren Sie, wie Sie PostgreSQL-Schemata effektiv mit SQLModel entwerfen. Verbessern Sie die Leistung und Skalierbarkeit Ihrer Datenbanken","pt":"Aprenda a projetar esquemas de banco de dados Postgres com SQLModel, incluindo tipos de dados, índices e metadados JSONB","ru":"Узнайте, как проектировать схемы базы данных Postgres с помощью SQLModel, включая типы данных, индексы и метаданные JSONB для ИИ Агентов","ar":"تعلم كيفية تصميم مخططات قواعد البيانات Postgres باستخدام SQLModel، بما في ذلك أنواع البيانات والفهارس والبيانات الوصفية JSONB لملحقات الذكاء الاصطناعي"},"definition":{"en":"postgres-schema-design is a skill that enables AI agents to create efficient PostgreSQL schema designs using SQLModel, focusing on data type selection, manual indexing, and pgvector integration.","zh":"Postgres Schema 设计是指为 Postgres 数据库设计和优化表结构和关系的过程","ja":"Postgres スキーマ設計とは、Postgres データベースのテーブル構造と関係を設計および最適化するプロセスです","ko":"Postgres 스키마 디자인은 Postgres 데이터베이스의 테이블 구조와 관계를 설계 및 최적화하는 과정입니다","es":"El diseño de esquemas de PostgreSQL es el proceso de planificación y creación de la estructura de una base de datos para almacenar y gestionar datos de manera eficiente","fr":"La conception de schémas PostgreSQL est le processus de planification et de création de la structure d''une base de données pour stocker et gérer des données de manière efficace","de":"Die Konfiguration von PostgreSQL-Schemata ist der Prozess der Planung und Erstellung der Struktur einer Datenbank zur effizienten Speicherung und Verwaltung von Daten","pt":"O que é Postgres-Schema-Design? É uma habilidade que permite projetar esquemas de banco de dados Postgres com SQLModel.","ru":"Что такое Postgres-Schema-Design? Это навык, который позволяет проектировать схемы базы данных Postgres с помощью SQLModel.","ar":"ما هو تصميم مخطط قاعدة البيانات Postgres؟ هو مهارة تسمح بتصميم مخططات قواعد البيانات Postgres باستخدام SQLModel."},"features":{"en":["Auto-generates schema using SQLModel","Supports manual indexes on foreign key columns","Utilizes JSONB for flexible metadata storage","Integrates pgvector for optimized performance","Provides guidance on choosing the right PostgreSQL data types","Generates BIGINT GENERATED ALWAYS AS IDENTITY for product IDs"],"zh":["选择合适的 Postgres 数据类型","添加手动索引，尤其是对于外键列","理解 JSONB 的使用方法","pgvector 集成"],"ja":["適切な Postgres データタイプの選択","手動インデックスの追加（特に外部キー列に対して）","JSONB の使用方法の理解","pgvector の統合"],"ko":["적절한 Postgres 데이터 유형 선택","수동 인덱스 추가, 특히 외부 키 열에 대해","JSONB 사용 방법 이해","pgvector 통합"],"es":["Elección de los tipos de datos de PostgreSQL adecuados","Adición de índices manuales, especialmente en columnas de claves foráneas","Uso de JSONB para metadatos flexibles","Integración con pgvector"],"fr":["Choix des types de données PostgreSQL appropriés","Ajout d''index manuels, en particulier sur les colonnes de clés étrangères","Utilisation de JSONB pour des métadonnées flexibles","Intégration avec pgvector"],"de":["Auswahl der geeigneten PostgreSQL-Datentypen","Hinzufügen manueller Indizes, insbesondere in Fremenschlüsselspalten","Verwendung von JSONB für flexible Metadaten","Integration mit pgvector"],"pt":["Escolha dos tipos de dados certos do Postgres","Adição de índices manuais, especialmente em colunas de chave estrangeira","Entendendo JSONB para metadados flexíveis","Integração com pgvector","Uso de BIGINT GENERATED ALWAYS AS IDENTITY para IDs de produtos","Uso de TEX para nomes de produtos"],"ru":["Выбор правильных типов данных Postgres","Добавление ручных индексов, особенно в столбцах внешних ключей","Понимание JSONB для гибких метаданных","Интеграция с pgvector","Использование BIGINT GENERATED ALWAYS AS IDENTITY для идентификаторов продуктов","Использование TEX для названий продуктов"],"ar":["اختيار أنواع البيانات الصحيحة ل Postgres","إضافة فهارس يدوية، خاصة في أعمدة المفاتيح الخارجية","فهم JSONB للبيانات الوصفية المرنة","التكامل مع pgvector","استخدام BIGINT GENERATED ALWAYS AS IDENTITY لمعرفات المنتجات","استخدام TEX لأسماء المنتجات"]},"keywords":{"en":["how to use postgres-schema-design","postgres-schema-design setup guide","postgres-schema-design vs SQLModel","postgres-schema-design install","what is postgres-schema-design","postgres-schema-design alternative","postgres-schema-design for AI agents","SQLModel focus for postgres-schema-design","pgvector integration with postgres-schema-design","optimizing postgres-schema-design with JSONB"],"zh":["Postgres Schema 设计","Postgres 数据类型","手动索引","JSONB","pgvector","数据库性能优化"],"ja":["Postgres スキーマ設計","Postgres データタイプ","手動インデックス","JSONB","pgvector","データベースパフォーマンス最適化","AIエージェント"],"ko":["Postgres 스키마 디자인","Postgres 데이터 유형","수동 인덱스","JSONB","pgvector","데이터베이스 성능 최적화","AI 툴"],"es":["diseño de esquemas de PostgreSQL","SQLModel","tipos de datos de PostgreSQL","índices manuales","JSONB","pgvector","bases de datos relacionales","gestión de datos"],"fr":["conception de schémas PostgreSQL","SQLModel","types de données PostgreSQL","index manuels","JSONB","pgvector","bases de données relationnelles","gestion de données"],"de":["Konfiguration von PostgreSQL-Schemata","SQLModel","PostgreSQL-Datentypen","manuelle Indizes","JSONB","pgvector","relationale Datenbanken","Datenverwaltung"],"pt":["postgres schema design","sqlmodel","tipos de dados postgres","índices manuais","jsonb","pgvector","desenvolvimento de banco de dados","projeto de esquema de banco de dados","melhores práticas de banco de dados"],"ru":["postgres схема дизайн","sqlmodel","типы данных постгрес","ручные индексы","jsonb","pgvector","разработка базы данных","проектирование схемы базы данных","лучшие практики базы данных для ИИ Агентов"],"ar":["تصميم مخطط قاعدة البيانات Postgres","sqlmodel","أنواع البيانات Postgres","فهارس يدوية","jsonb","pgvector","تطوير قاعدة البيانات","تصميم مخطط قاعدة البيانات","أفضل الممارسات لقواعد البيانات لملحقات الذكاء الاصطناعي"]}},"owner":"ThaiG2Pro","repo":"ai-agent-sale-v1","repoPath":"ThaiG2Pro/ai-agent-sale-v1","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.562Z","topics":[],"category":"community","skillMd":{"name":"postgres-schema-design","description":"|","bodyPreview":"# PostgreSQL Schema Design (SQLModel Focus)\n\n**For AI Sales Agent**: SQLModel auto-generates most schema. Use this skill for:\n- Choosing the right PostgreSQL data types\n- Adding manual indexes (especially on FK columns)\n- Understanding JSONB for flexible metadata\n- pgvector integration\n\n## Quick Reference for This Project\n\n| Week | Scenario | What to Use |\n|------|----------|-------------|\n| 1.4 | Product ID | `BIGINT GENERATED ALWAYS AS IDENTITY` (SQLModel default) |\n| 1.4 | Product name | `TEX","body":"# PostgreSQL Schema Design (SQLModel Focus)\n\n**For AI Sales Agent**: SQLModel auto-generates most schema. Use this skill for:\n- Choosing the right PostgreSQL data types\n- Adding manual indexes (especially on FK columns)\n- Understanding JSONB for flexible metadata\n- pgvector integration\n\n## Quick Reference for This Project\n\n| Week | Scenario | What to Use |\n|------|----------|-------------|\n| 1.4 | Product ID | `BIGINT GENERATED ALWAYS AS IDENTITY` (SQLModel default) |\n| 1.4 | Product name | `TEXT` (not VARCHAR) |\n| 1.4 | Price | `NUMERIC` (never float for money) |\n| 1.4 | Timestamps | `TIMESTAMPTZ` (always with timezone) |\n| 2.1 | Embeddings | `halfvec(1536)` via pgvector |\n| 2.3 | Search terms metadata | `JSONB` + GIN index |\n| 2.2 | FK indexes | **Manual**: `CREATE INDEX ON orders (user_id)` |\n\n## Core Rules (for SQLModel users)\n\n- SQLModel handles **PRIMARY KEY**, **NOT NULL**, **DEFAULT** automatically from your Python models\n- You **must manually add indexes** on foreign key columns: `CREATE INDEX ON orders (user_id)`\n- Choose correct types in SQLModel: `str` → `TEXT`, `Decimal` → `NUMERIC`, `datetime` → `TIMESTAMPTZ`\n- For JSONB: use `Json` from SQLModel or `Column(JSON)` for flexible metadata\n- pgvector: add `embedding: Optional[str] = Field(sa_column=Column(Vector(1536)))` in SQLModel\n\n## Essential Data Types (for SQLModel users)\n\n- Define a **PRIMARY KEY** for reference tables (users, orders, etc.). Not always needed for time-series/event/log data. When used, prefer `BIGINT GENERATED ALWAYS AS IDENTITY`; use `UUID` only when global uniqueness/opacity is needed.\n- **Normalize first (to 3NF)** to eliminate data redundancy and update anomalies; denormalize **only** for measured, high-ROI reads where join performance is proven problematic. Premature denormalization creates maintenance burden.\n- Add **NOT NULL** everywhere it’s semantically required; use **DEFAULT**s for common values.\n- Create **indexes for access paths you actually query**: PK/unique (auto), **FK columns (manual!)**, frequent filters/sorts, and join keys.\n- Prefer **TIMESTAMPTZ** for event time; **NUMERIC** for money; **TEXT** for strings; **BIGINT** for integer values, **DOUBLE PRECISION** for floats (or `NUMERIC` for exact decimal arithmetic).\n\n## PostgreSQL “Gotchas”\n\n- **Identifiers**: unquoted → lowercased. Avoid quoted/mixed-case names. Convention: use `snake_case` for table/column names.\n- **Unique + NULLs**: UNIQUE allows multiple NULLs. Use `UNIQUE (...) NULLS NOT DISTINCT` (PG15+) to restrict to one NULL.\n- **FK indexes**: PostgreSQL **does not** auto-index FK columns. Add them.\n- **No silent coercions**: length/precision overflows error out (no truncation). Example: inserting 999 into `NUMERIC(2,0)` fails with error, unlike some databases that silently truncate or round.\n- **Sequences/identity have gaps** (normal; don''t \"fix\"). Rollbacks, crashes, and concurrent transactions create gaps in ID sequences (1, 2, 5, 6...). This is expected behavior—don''t try to make IDs consecutive.\n- **Heap storage**: no clustered PK by default (unlike SQL Server/MySQL InnoDB); `CLUSTER` is one-off reorganization, not maintained on subsequent inserts. Row order on disk is insertion order unless explicitly clustered.\n- **MVCC**: updates/deletes leave dead tuples; vacuum handles them—design to avoid hot wide-row churn.\n\n## Data Types\n\n- **IDs**: `BIGINT GENERATED ALWAYS AS IDENTITY` preferred (`GENERATED BY DEFAULT` also fine); `UUID` when merging/federating/used in a distributed system or for opaque IDs. Generate with `uuidv7()` (preferred if using PG18+) or `gen_random_uuid()` (if using an older PG version).\n- **Integers**: prefer `BIGINT` unless storage space is critical; `INTEGER` for smaller ranges; avoid `SMALLINT` unless constrained.\n- **Floats**: prefer `DOUBLE PRECISION` over `REAL` unless storage space is critical. Use `NUMERIC` for exact decimal arithmetic.\n- **Strings**: prefer `TEXT`; if length limits needed, use `CHECK (LENGTH(col) <= n)` instead of `VARCHAR(n)`; avoid `CHAR(n)`. Use `BYTEA` for binary data. Large strings/binary (>2KB default threshold) automatically stored in TOAST with compression. TOAST storage: `PLAIN` (no TOAST), `EXTENDED` (compress + out-of-line), `EXTERNAL` (out-of-line, no compress), `MAIN` (compress, keep in-line if possible). Default `EXTENDED` usually optimal. Control with `ALTER TABLE tbl ALTER COLUMN col SET STORAGE strategy` and `ALTER TABLE tbl SET (toast_tuple_target = 4096)` for threshold. Case-insensitive: for locale/accent handling use non-deterministic collations; for plain ASCII use expression indexes on `LOWER(col)` (preferred unless column needs case-insensitive PK/FK/UNIQUE) or `CITEXT`.\n- **Money**: `NUMERIC(p,s)` (never float).\n- **Time**: `TIMESTAMPTZ` for timestamps; `DATE` for date-only; `INTERVAL` for durations. Avoid `TIMESTAMP` (without timezone). Use `now()` for transaction start time, `clock_timestamp()` for current wall-clock time.\n- **Booleans**: `BOOLEAN` with `NOT NULL` constraint unless tri-state values are required.\n- **Enums**: `CREATE TYPE ... AS ENUM` for small, stable sets (e.g. US states, days of week). For business-logic-driven and evolving values (e.g. order statuses) → use TEXT (or INT) + CHECK or lookup table.\n- **Arrays**: `TEXT[]`, `INTEGER[]`, etc. Use for ordered lists where you query elements. Index with **GIN** for containment (`@>`, `<@`) and overlap (`&&`) queries. Access: `arr[1]` (1-indexed), `arr[1:3]` (slicing). Good for tags, categories; avoid for relations—use junction tables instead. Literal syntax: `''{val1,val2}''` or `ARRAY[val1,val2]`.\n- **Range types**: `daterange`, `numrange`, `tstzrange` for intervals. Support overlap (`&&`), containment (`@>`), operators. Index with **GiST**. Good for scheduling, versioning, numeric ranges. Pick a bounds scheme and use it consistently; prefer `[)` (inclusive/exclusive) by default.\n- **Network types**: `INET` for IP addresses, `CIDR` for network ranges, `MACADDR` for MAC addresses. Support network operators (`<<`, `>>`, `&&`).\n- **Geometric types**: `POINT`, `LINE`, `POLYGON`, `CIRCLE` for 2D spatial data. Index with **GiST**. Consider **PostGIS** for advanced spatial features.\n- **Text search**: `TSVECTOR` for full-text search documents, `TSQUERY` for search queries. Index `tsvector` with **GIN**. Always specify language: `to_tsvector(''english'', col)` and `to_tsquery(''english'', ''query'')`. Never use single-argument versions. This applies to both index expressions and queries.\n- **Domain types**: `CREATE DOMAIN email AS TEXT CHECK (VALUE ~ ''^[^@]+@[^@]+$'')` for reusable custom types with validation. Enforces constraints across tables.\n- **Composite types**: `CREATE TYPE address AS (street TEXT, city TEXT, zip TEXT)` for structured data within columns. Access with `(col).field` syntax.\n- **JSONB**: preferred over JSON; index with **GIN**. Use only for optional/semi-structured attrs. ONLY use JSON if the original ordering of the contents MUST be preserved.\n- **Vector types**: `vector` type by `pgvector` for vector similarity search for embeddings.\n\n### Do not use the following data types\n\n- DO NOT use `timestamp` (without time zone); DO use `timestamptz` instead.\n- DO NOT use `char(n)` or `varchar(n)`; DO use `text` instead.\n- DO NOT use `money` type; DO use `numeric` instead.\n- DO NOT use `timetz` type; DO use `timestamptz` instead.\n- DO NOT use `timestamptz(0)` or any other precision specification; DO use `timestamptz` instead\n- DO NOT use `serial` type; DO use `generated always as identity` instead.\n\n## Table Types\n\n- **Regular**: default; fully durable, logged.\n- **TEMPORARY**: session-scoped, auto-dropped, not logged. Faster for scratch work.\n- **UNLOGGED**: persistent but not crash-safe. Faster writes; good for caches/staging.\n\n## Row-Level Security\n\nEnable with `ALTER TABLE tbl ENABLE ROW LEVEL SECURITY`. Create policies: `CREATE POLICY user_access ON orders FOR SELECT TO app_users USING (user_id = current_user_id())`. Built-in user-based access control at the row level.\n\n## Constraints\n\n- **PK**: implicit UNIQUE + NOT NULL; creates a B-tree index.\n- **FK**: specify `ON DELETE/UPDATE` action (`CASCADE`, `RESTRICT`, `SET NULL`, `SET DEFAULT`). Add explicit index on referencing column—speeds up joins and prevents locking issues on parent deletes/updates. Use `DEFERRABLE INITIALLY DEFERRED` for circular FK dependencies checked at transaction end.\n- **UNIQUE**: creates a B-tree index; allows multiple NULLs unless `NULLS NOT DISTINCT` (PG15+). Standard behavior: `(1, NULL)` and `(1, NULL)` are allowed. With `NULLS NOT DISTINCT`: only one `(1, NULL)` allowed. Prefer `NULLS NOT DISTINCT` unless you specifically need duplicate NULLs.\n- **CHECK**: row-local constraints; NULL values pass the check (three-valued logic). Example: `CHECK (price > 0)` allows NULL prices. Combine with `NOT NULL` to enforce: `price NUMERIC NOT NULL CHECK (price > 0)`.\n- **EXCLUDE**: prevents overlapping values using operators. `EXCLUDE USING gist (room_id WITH =, booking_period WITH &&)` prevents double-booking rooms. Requires appropriate index type (often GiST).\n\n## Indexing\n\n- **B-tree**: default for equality/range queries (`=`, `<`, `>`, `BETWEEN`, `ORDER BY`)\n- **Composite**: order matters—index used if equality on leftmost prefix (`WHERE a = ? AND b > ?` uses index on `(a,b)`, but `WHERE b = ?` does not). Put most selective/frequently filtered columns first.\n- **Covering**: `CREATE INDEX ON tbl (id) INCLUDE (name, email)` - includes non-key columns for index-only scans without visiting table.\n- **Partial**: for hot subsets (`WHERE status = ''active''` → `CREATE INDEX ON tbl (user_id) WHERE status = ''active''`). Any query with `status = ''active''` can use this index.\n- **Expression**: for computed search keys (`CREATE INDEX ON tbl (LOWER(email))`). Expression must match exactly in WHERE clause: `WHERE LOWER(email) = ''user@example.com''`.\n- **GIN**: JSONB containment/existence, arrays (`@>`, `?`), full-text search (`@@`)\n- **GiST**: ranges, geometry, exclusion constraints\n- **BRIN**: very large, naturally ordered data (time-series)—minimal storage overhead. Effective when row order on disk correlates with indexed column (insertion order or after `CLUSTER`).\n\n## Partitioning\n\n- Use for very large tables (>100M rows) where queries consistently filter on partition key (often time/date).\n- Alternate use: use for tables where data maintenance tasks dictates e.g. data pruned or bulk replaced periodically\n- **RANGE**: common for time-series (`PARTITION BY RANGE (created_at)`). Create partitions: `CREATE TABLE logs_2024_01 PARTITION OF logs FOR VALUES FROM (''2024-01-01'') TO (''2024-02-01'')`. **TimescaleDB** automates time-based or ID-based partitioning with retention policies and compression.\n- **LIST**: for discrete values (`PARTITION BY LIST (region)`). Example: `FOR VALUES IN (''us-east'', ''us-west'')`.\n- **HASH**: for even distribution when no natural key (`PARTITION BY HASH (user_id)`). Creates N partitions with modulus.\n- **Constraint exclusion**: requires `CHECK` constraints on partitions for query planner to prune. Auto-created for declarative partitioning (PG10+).\n- Prefer declarative partitioning or hypertables. Do NOT use table inheritance.\n- **Limitations**: no global UNIQUE constraints—include partition key in PK/UNIQUE. FKs from partitioned tables not supported; use triggers.\n\n## Special Considerations\n\n### Update-Heavy Tables\n\n- **Separate hot/cold columns**—put frequently updated columns in separate table to minimize bloat.\n- **Use `fillfactor=90`** to leave space for HOT updates that avoid index maintenance.\n- **Avoid updating indexed columns**—prevents beneficial HOT updates.\n- **Partition by update patterns**—separate frequently updated rows in a different partition from stable data.\n\n### Insert-Heavy Workloads\n\n- **Minimize indexes**—only create what you query; every index slows inserts.\n- **Use `COPY` or multi-row `INSERT`** instead of single-row inserts.\n- **UNLOGGED tables** for rebuildable staging data—much faster writes.\n- **Defer index creation** for bulk loads—>drop index, load data, recreate indexes.\n- **Partition by time/hash** to distribute load. **TimescaleDB** automates partitioning and compression of insert-heavy data.\n- **Use a natural key for primary key** such as a (timestamp, device_id) if enforcing global uniqueness is important many insert-heavy tables don''t need a primary key at all.\n- If you do need a surrogate key, **Prefer `BIGINT GENERATED ALWAYS AS IDENTITY` over `UUID`**.\n\n### Upsert-Friendly Design\n\n- **Requires UNIQUE index** on conflict target columns—`ON CONFLICT (col1, col2)` needs exact matching unique index (partial indexes don''t work).\n- **Use `EXCLUDED.column`** to reference would-be-inserted values; only update columns that actually changed to reduce write overhead.\n- **`DO NOTHING` faster** than `DO UPDATE` when no actual update needed.\n\n### Safe Schema Evolution\n\n- **Transactional DDL**: most DDL operations can run in transactions and be rolled back—`BEGIN; ALTER TABLE...; ROLLBACK;` for safe testing.\n- **Concurrent index creation**: `CREATE INDEX CONCURRENTLY` avoids blocking writes but can''t run in transactions.\n- **Volatile defaults cause rewrites**: adding `NOT NULL` columns with volatile defaults (e.g., `now()`, `gen_random_uuid()`) rewrites entire table. Non-volatile defaults are fast.\n- **Drop constraints before columns**: `ALTER TABLE DROP CONSTRAINT` then `DROP COLUMN` to avoid dependency issues.\n- **Function signature changes**: `CREATE OR REPLACE` with different arguments creates overloads, not replacements. DROP old version if no overload desired.\n\n## Generated Columns\n\n- `... GENERATED ALWAYS AS (<expr>) STORED` for computed, indexable fields. PG18+ adds `VIRTUAL` columns (computed on read, not stored).\n\n## Extensions\n\n- **`pgcrypto`**: `crypt()` for password hashing.\n- **`uuid-ossp`**: alternative UUID functions; prefer `pgcrypto` for new projects.\n- **`pg_trgm`**: fuzzy text search with `%` operator, `similarity()` function. Index with GIN for `LIKE ''%pattern%''` acceleration.\n- **`citext`**: case-insensitive text type. Prefer expression indexes on `LOWER(col)` unless you need case-insensitive constraints.\n- **`btree_gin`/`btree_gist`**: enable mixed-type indexes (e.g., GIN index on both JSONB and text columns).\n- **`hstore`**: key-value pairs; mostly superseded by JSONB but useful for simple string mappings.\n- **`timescaledb`**: essential for time-series—automated partitioning, retention, compression, continuous aggregates. Self-hosted and on Tiger Cloud.\n- **`postgis`**: comprehensive geospatial support beyond basic geometric types—essential for location-based applications.\n- **`pgvector`**: vector similarity search for embeddings.\n- **`pgaudit`**: audit logging for all database activity.\n\n## JSONB Guidance\n\n- Prefer `JSONB` with **GIN** index.\n- Default: `CREATE INDEX ON tbl USING GIN (jsonb_col);` → accelerates:\n  - **Containment** `jsonb_col @> ''{\"k\":\"v\"}''`\n  - **Key existence** `jsonb_col ? ''k''`, **any/all keys** `?\\|`, `?&`\n  - **Path containment** on nested docs\n  - **Disjunction** `jsonb_col @> ANY(ARRAY[''{\"status\":\"active\"}'', ''{\"status\":\"pending\"}''])`\n- Heavy `@>` workloads: consider opclass `jsonb_path_ops` for smaller/faster containment-only indexes:\n  - `CREATE INDEX ON tbl USING GIN (jsonb_col jsonb_path_ops);`\n  - **Trade-off**: loses support for key existence (`?`, `?|`, `?&`) queries—only supports containment (`@>`)\n- Equality/range on a specific scalar field: extract and index with B-tree (generated column or expression):\n  - `ALTER TABLE tbl ADD COLUMN price INT GENERATED ALWAYS AS ((jsonb_col->>''price'')::INT) STORED;`\n  - `CREATE INDEX ON tbl (price);`\n  - Prefer queries like `WHERE price BETWEEN 100 AND 500` (uses B-tree) over `WHERE (jsonb_col->>''price'')::INT BETWEEN 100 AND 500` without index.\n- Arrays inside JSONB: use GIN + `@>` for containment (e.g., tags). Consider `jsonb_path_ops` if only doing containment.\n- Keep core relations in tables; use JSONB for optional/variable attributes.\n- Use constraints to limit allowed JSONB values in a column e.g. `config JSONB NOT NULL CHECK(jsonb_typeof(config) = ''object'')`\n\n## Examples\n\n### Users\n\n```sql\nCREATE TABLE users (\n  user_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  email TEXT NOT NULL UNIQUE,\n  name TEXT NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE UNIQUE INDEX ON users (LOWER(email));\nCREATE INDEX ON users (created_at);\n```\n\n### Orders\n\n```sql\nCREATE TABLE orders (\n  order_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n  user_id BIGINT NOT NULL REFERENCES users(user_id),\n  status TEXT NOT NULL DEFAULT ''PENDING'' CHECK (status IN (''PENDING'',''PAID'',''CANCELED'')),\n  total NUMERIC(10,2) NOT NULL CHECK (total > 0),\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\nCREATE INDEX ON orders (user_id);\nCREATE INDEX ON orders (created_at);\n```\n\n### JSONB\n\n```sql\nCREATE TABLE profiles (\n  user_id BIGINT PRIMARY KEY REFERENCES users(user_id),\n  attrs JSONB NOT NULL DEFAULT ''{}'',\n  theme TEXT GENERATED ALWAYS AS (attrs->>''theme'') STORED\n);\nCREATE INDEX profiles_attrs_gin ON profiles USING GIN (attrs);\n```\n"},"lastSynced":"2026-03-08T02:11:36.388Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Modeling Agents needing advanced PostgreSQL schema optimization using SQLModel.","zh":"适用于需要使用 SQLModel 进行高级 PostgreSQL 模式优化的数据建模代理。","ja":"SQLModel を使用した高度な PostgreSQL スキーマ最適化を必要とするデータ モデリング エージェントに最適です。","ko":"SQLModel을 사용하여 고급 PostgreSQL 스키마 최적화를 필요한 데이터 모델링 에이전트에 적합합니다.","es":"Perfecto para agentes de modelado de datos que necesitan una optimización avanzada del esquema de PostgreSQL utilizando SQLModel.","fr":"Parfait pour les agents de modélisation de données nécessitant une optimisation avancée du schéma PostgreSQL à l''aide de SQLModel.","de":"Perfekt für Data Modeling Agents, die eine erweiterte PostgreSQL-Schema-Optimierung mit SQLModel benötigen.","pt":"Perfeito para Agentes de Modelagem de Dados que necessitam de otimização avançada de esquema PostgreSQL usando SQLModel.","ru":"Идеально для Агентов Моделирования Данных, которым требуется продвинутая оптимизация схемы PostgreSQL с использованием SQLModel.","ar":"مثالي لعميلة نمذجة البيانات التي تحتاج إلى تحسين مخطط متقدم PostgreSQL باستخدام SQLModel."},"recommendation":{"en":"Empowers agents to choose optimal PostgreSQL data types, add manual indexes, and leverage JSONB for flexible metadata, all while integrating with pgvector for advanced vector operations.","zh":"赋予代理选择最优的 PostgreSQL 数据类型、添加手动索引，并利用 JSONB 进行灵活的元数据存储，同时集成 pgvector 进行高级向量操作。","ja":"エージェントに最適な PostgreSQL データ型を選択し、手動インデックスを追加し、JSONB を使用して柔軟なメタデータを格納し、同時に pgvector と統合して高度なベクトル操作を行うことを可能にします。","ko":"에이전트가 최적의 PostgreSQL 데이터 유형을 선택하고 수동 인덱스를 추가하며 JSONB를 사용하여 유연한 메타데이터를 저장하고同时 pgvector와 통합하여 고급 벡터 연산을 수행할 수 있도록 합니다.","es":"Permite a los agentes elegir los tipos de datos de PostgreSQL óptimos, agregar índices manuales y aprovechar JSONB para metadatos flexibles, todo mientras se integra con pgvector para operaciones de vector avanzadas.","fr":"Permet aux agents de choisir les types de données PostgreSQL optimaux, d''ajouter des index manuels et d''utiliser JSONB pour des métadonnées flexibles, le tout en s''intégrant à pgvector pour des opérations vectorielles avancées.","de":"Ermöglicht es Agenten, optimale PostgreSQL-Datentypen auszuwählen, manuelle Indizes hinzuzufügen und JSONB für flexible Metadaten zu nutzen, all dies während der Integration mit pgvector für erweiterte Vektoroperationen.","pt":"Permite que os agentes escolham os tipos de dados PostgreSQL ideais, adicionem índices manuais e utilizem JSONB para metadados flexíveis, tudo isso integrando-se com pgvector para operações de vetor avançadas.","ru":"Позволяет агентам выбирать оптимальные типы данных PostgreSQL, добавлять ручные индексы и использовать JSONB для гибких метаданных, все это интегрируясь с pgvector для продвинутых операций с векторами.","ar":"يسمح للعميل باختيار أنواع البيانات المثالية PostgreSQL، وإضافة فهرس يدوي، والاستفادة من JSONB للمتadatadata المرنة، وكل ذلك يتكامل مع pgvector من أجل عمليات متقدمة للเวktor."},"useCases":{"en":["Optimizing database schema for query performance","Automating index creation on foreign key columns","Designing flexible metadata storage using JSONB"],"zh":["优化数据库架构以提高查询性能","自动在外键列上创建索引","使用 JSONB 设计灵活的元数据存储"],"ja":["クエリパフォーマンスのためにデータベーススキーマを最適化する","外部キー列に自動でインデックスを作成する","JSONB を使用して柔軟なメタデータストレージを設計する"],"ko":["쿼리 성능을 위해 데이터베이스 스키마를 최적화하는 것","외부 키 열에 자동으로 인덱스를 생성하는 것","JSONB를 사용하여 유연한 메타데이터 저장소를 설계하는 것"],"es":["Optimización del esquema de base de datos para el rendimiento de la consulta","Automatización de la creación de índices en columnas de clave foránea","Diseño de almacenamiento de metadatos flexibles utilizando JSONB"],"fr":["Optimisation du schéma de base de données pour les performances de requête","Automatisation de la création d''index sur les colonnes de clé étrangère","Conception d''un stockage de métadonnées flexible à l''aide de JSONB"],"de":["Optimierung des Datenbankschemas für die Abfrageleistung","Automatisierung der Indexerstellung in Fremenschlüsselspalten","Entwurf eines flexiblen Metadatenspeichers mit JSONB"],"pt":["Otimização do esquema de banco de dados para desempenho de consulta","Criação automática de índices em colunas de chave estrangeira","Projeto de armazenamento de metadados flexíveis usando JSONB"],"ru":["Оптимизация схемы базы данных для производительности запросов","Автоматическое создание индексов в столбцах внешнего ключа","Проектирование гибкого хранилища метаданных с использованием JSONB"],"ar":["تحسين مخطط قاعدة البيانات لأداء الاستفسار","إنشاء فهرس تلقائي في أعمدة المفتاح الأجنبي","تصميم تخزين متadatadata مرنة باستخدام JSONB"]},"limitations":{"en":["Requires SQLModel library integration","PostgreSQL database compatibility only","Manual configuration needed for pgvector integration"],"zh":["需要集成 SQLModel 库","仅与 PostgreSQL 数据库兼容","需要手动配置 pgvector 集成"],"ja":["SQLModel ライブラリの統合が必要","PostgreSQL データベースのみとの互換性","pgvector 統合の手動設定が必要"],"ko":["SQLModel 라이브러리 통합이 필요함","PostgreSQL 데이터베이스만과 호환됨","pgvector 통합을 위한 수동 구성이 필요함"],"es":["Requiere integración de la biblioteca SQLModel","Compatibilidad solo con bases de datos PostgreSQL","Configuración manual necesaria para la integración de pgvector"],"fr":["Nécessite l''intégration de la bibliothèque SQLModel","Compatibilité uniquement avec les bases de données PostgreSQL","Configuration manuelle nécessaire pour l''intégration de pgvector"],"de":["Erfordert SQLModel-Bibliotheksintegration","Kompatibilität nur mit PostgreSQL-Datenbanken","Manuelle Konfiguration erforderlich für die pgvector-Integration"],"pt":["Requer integração com a biblioteca SQLModel","Compatibilidade apenas com banco de dados PostgreSQL","Configuração manual necessária para integração com pgvector"],"ru":["Требуется интеграция с библиотекой SQLModel","Совместимость только с базой данных PostgreSQL","Необходима ручная настройка для интеграции с pgvector"],"ar":["يتطلب تكامل مع مكتبة SQLModel","متوافق فقط مع قاعدة البيانات PostgreSQL","يتطلب 구성 يدوي للتعامل مع pgvector"]},"version":4},"contentHash":"406718999e2f6623bdd34835b6adf3f9a5c911a6267a2ee5f9d42e784ccd41f3","qualityScore":54}');
