INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ThaiG2Pro/ai-agent-sale-v1/postgres-schema-design', 'postgres-schema-design', 'ThaiG2Pro', 'ai-agent-sale-v1', 'community', 'postgres-schema-design ThaiG2Pro ai-agent-sale-v1 community The postgres-schema-design skill helps AI agents optimize PostgreSQL schema design using SQLModel. It benefits developers by providing guidance on choosing the right data types and adding manual indexes. Postgres Schema 设计是数据库性能优化的关键，了解如何选择合适的数据类型、添加手动索引和使用 JSONB Postgres スキーマ設計はデータベースのパフォーマンスを向上させる鍵です。データタイプの選択、手動インデックスの追加、JSONB の使用方法を学びましょう Postgres 스키마 디자인은 데이터베이스 성능 최적화의 핵심입니다. 적절한 데이터 유형 선택, 수동 인덱스 추가 및 JSONB 사용법을 알아보세요 Diseño de esquemas de PostgreSQL con SQLModel para mejorar el rendimiento y la escalabilidad. Aprende a elegir los tipos de datos adecuados y a agregar índices manuales Conception de schémas PostgreSQL avec SQLModel pour améliorer les performances et la scalabilité. Apprenez à choisir les types de données appropriés et à ajouter des index manuels Entwerfen von PostgreSQL-Schemata mit SQLModel zur Verbesserung der Leistung und Skalierbarkeit. Erfahren Sie, wie Sie die richtigen Datentypen auswählen und manuelle Indizes hinzufügen O Postgres-Schema-Design é uma habilidade que permite aos desenvolvedores projetar esquemas de banco de dados Postgres com SQLModel. Postgres-Schema-Design - это навык, который позволяет разработчикам проектировать схемы базы данных Postgres с помощью SQLModel для ИИ Агентов. تصميم مخطط قاعدة البيانات Postgres هو مهارة تسمح للمطورين بتصميم مخططات قواعد البيانات Postgres باستخدام SQLModel لملحقات الذكاء الاصطناعي. how to use postgres-schema-design postgres-schema-design setup guide postgres-schema-design vs SQLModel postgres-schema-design install what is postgres-schema-design postgres-schema-design alternative postgres-schema-design for AI agents SQLModel focus for postgres-schema-design pgvector integration with postgres-schema-design optimizing postgres-schema-design with JSONB Postgres Schema 设计 Postgres 数据类型 手动索引 JSONB pgvector 数据库性能优化 Auto-generates schema using SQLModel Supports manual indexes on foreign key columns Utilizes JSONB for flexible metadata storage Integrates pgvector for optimized performance Provides guidance on choosing the right PostgreSQL data types Generates BIGINT GENERATED ALWAYS AS IDENTITY for product IDs postgres-schema-design is a skill that enables AI agents to create efficient PostgreSQL schema designs using SQLModel, focusing on data type selection, manual indexing, and pgvector integration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Trongdepzai-dev/Xorium-Stealer-Pulsar/multimodal-io', 'community', 'Trongdepzai-dev', 'Xorium-Stealer-Pulsar', 'Trongdepzai-dev/Xorium-Stealer-Pulsar', 'multimodal-io', 0, 0, 54, '2026-03-08T01:57:15.571Z', '2026-03-08T02:11:45.641Z', '16ffc51e015f9655cb03e030dc8a338b5c3016a6b409c65989a4e7997c74d1b0', '{"id":"Trongdepzai-dev/Xorium-Stealer-Pulsar/multimodal-io","name":"multimodal-io","description":{"en":"The multimodal-io skill provides a unified interface for processing and generating multimodal content via the Gemini 3 API, benefiting developers working with multimedia data.","zh":"Multimodal I/O是一个用于处理和生成多模态内容的统一接口，通过Gemini 3 API实现","ja":"Multimodal I/Oは、マルチモーダルコンテンツの処理と生成を行うための統一されたインターフェースです","ko":"멀티모달 I/O는 멀티모달 콘텐츠를 처리하고 생성하는統一された 인터페이스입니다","es":"Multimodal I/O es una interfaz unificada para procesar y generar contenido multimodal mediante la API Gemini 3. Se puede instalar con pip y requiere una clave de API","fr":"Multimodal I/O est une interface unifiée pour traiter et générer du contenu multimodal via l''API Gemini 3. Il peut être installé avec pip et nécessite une clé d''API","de":"Multimodal I/O ist eine einheitliche Schnittstelle für die Verarbeitung und Generierung von Multimediainhalten über die Gemini 3 API. Es kann mit pip installiert werden und erfordert einen API-Schlüssel","pt":"O Multimodal-io é uma interface unificada para processar e gerar conteúdo multimodal via Gemini 3 API, utilizando bibliotecas como Google GenAI e Pillow.","ru":"Multimodal-io - унифицированный интерфейс для обработки и генерации мультимодального контента через Gemini 3 API, использующий библиотеки Google GenAI и Pillow.","ar":"Multimodal-io هو واجهة موحدة لمعالجة وتوليد المحتوى المتعدد عبر Gemini 3 API، باستخدام مكتبات مثل Google GenAI و Pillow."},"seo":{"title":{"en":"multimodal-io: Unified Multimodal Content 