INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Trongdepzai-dev/Xorium-Stealer-Pulsar/multimodal-io', 'multimodal-io', 'Trongdepzai-dev', 'Xorium-Stealer-Pulsar', 'community', 'multimodal-io Trongdepzai-dev Xorium-Stealer-Pulsar community The multimodal-io skill provides a unified interface for processing and generating multimodal content via the Gemini 3 API, benefiting developers working with multimedia data. Multimodal I/O是一个用于处理和生成多模态内容的统一接口，通过Gemini 3 API实现 Multimodal I/Oは、マルチモーダルコンテンツの処理と生成を行うための統一されたインターフェースです 멀티모달 I/O는 멀티모달 콘텐츠를 처리하고 생성하는統一された 인터페이스입니다 Multimodal I/O es una interfaz unificada para procesar y generar contenido multimodal mediante la API Gemini 3. Se puede instalar con pip y requiere una clave de API Multimodal I/O est une interface unifiée pour traiter et générer du contenu multimodal via l''API Gemini 3. Il peut être installé avec pip et nécessite une clé d''API Multimodal I/O ist eine einheitliche Schnittstelle für die Verarbeitung und Generierung von Multimediainhalten über die Gemini 3 API. Es kann mit pip installiert werden und erfordert einen API-Schlüssel O Multimodal-io é uma interface unificada para processar e gerar conteúdo multimodal via Gemini 3 API, utilizando bibliotecas como Google GenAI e Pillow. Multimodal-io - унифицированный интерфейс для обработки и генерации мультимодального контента через Gemini 3 API, использующий библиотеки Google GenAI и Pillow. Multimodal-io هو واجهة موحدة لمعالجة وتوليد المحتوى المتعدد عبر Gemini 3 API، باستخدام مكتبات مثل Google GenAI و Pillow. how to use multimodal-io multimodal-io setup guide Gemini 3 API integration multimodal content processing multimodal-io alternative multimodal-io install what is multimodal-io multimodal-io vs other AI agent skills multimodal-io for AI agents Multimodal I/O Gemini 3 API 多模态内容处理 环境变量配置 AI工具 google-genai pillow pip安装 Utilizes the Gemini 3 API for multimodal content processing Supports installation via pip with google-genai and pillow Auto-loads GEMINI_API_KEY from .env files in priority order Enables environment variable configuration for seamless integration Processes and generates multimodal content via a unified interface multimodal-io is a modified Xorium Stealer Pulsar that enables unified multimodal content processing and generation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bivex/loreSystem/json-formatter', 'community', 'bivex', 'loreSystem', 'bivex/loreSystem', 'json-formatter', 0, 0, 54, '2026-03-08T01:57:15.579Z', '2026-03-08T02:11:51.192Z', 'db385588989bb1a4e1b774885598e6a456f0d795b87dde36dd987d0ce34111b7', '{"id":"bivex/loreSystem/json-formatter","name":"json-formatter","description":{"en":"The json-formatter skill formats JSON output for worldbuilding software, benefiting developers who need to load data into the Lore GUI. It produces parseable JSON with a defined export schema.","zh":"JSON 格式化工具是一款世界构建软件，用于优化 JSON 输出格式化。它支持有效的 JSON 输出、导出模式和复数集合","ja":"JSON フォーマッターはワールドビルディングソフトウェアであり、JSON 出力形式を最適化します。有効な JSON 出力、エクスポート形式、複数コレクションをサポート","ko":"JSON 형식화 도구는 월드빌딩 소프트웨어로 JSON 출력 형식을 최적화합니다. 유효한 JSON 출력, 내보내기 형식 및 복수 컬렉션을 지원합니다","es":"El json-formatter es una habilidad base para la formateo de salida JSON, que produce JSON válido y compatible con la interfaz de usuario de Lore","fr":"Le json-formatter est une compétence de base pour le formatage de sortie JSON, qui produit du JSON valide et compatible avec l''interface utilisateur de Lore","de":"Der json-formatter ist eine Basisfähigkeit für die Ausgabeformatierung von JSON, die gültiges JSON erzeugt, das mit der Lore-Benutzeroberfläche kompatibel ist","pt":"O json-formatter é uma habilidade base para formatação de saída JSON, projetada para trabalhar com software de worldbuilding","ru":"Json-formatter - базовый навык для форматирования JSON-выхода, предназначенный для работы с программным обеспечением для создания миров","ar":"json-formatter هي مهارة أساسية لتنسيق الإخراج JSON، مصممة للعمل مع برنامج بناء العالم"},"seo":{"title":{"en":"json-formatter: JSON Output Formatting Setup Guide | AI A...","zh":"JSON 格式化工具：世界构建软件设置指南","ja":"JSON フォーマッター：ワールドビルディングソフトウェアのベストプラクティス","ko":"JSON 형식화 도구: 월드빌딩 소프트웨어 설정 가이드","es":"Guía de co