INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bivex/loreSystem/json-formatter', 'json-formatter', 'bivex', 'loreSystem', 'community', 'json-formatter bivex loreSystem community The json-formatter skill formats JSON output for worldbuilding software, benefiting developers who need to load data into the Lore GUI. It produces parseable JSON with a defined export schema. JSON 格式化工具是一款世界构建软件，用于优化 JSON 输出格式化。它支持有效的 JSON 输出、导出模式和复数集合 JSON フォーマッターはワールドビルディングソフトウェアであり、JSON 出力形式を最適化します。有効な JSON 出力、エクスポート形式、複数コレクションをサポート JSON 형식화 도구는 월드빌딩 소프트웨어로 JSON 출력 형식을 최적화합니다. 유효한 JSON 출력, 내보내기 형식 및 복수 컬렉션을 지원합니다 El json-formatter es una habilidad base para la formateo de salida JSON, que produce JSON válido y compatible con la interfaz de usuario de Lore Le json-formatter est une compétence de base pour le formatage de sortie JSON, qui produit du JSON valide et compatible avec l''interface utilisateur de Lore Der json-formatter ist eine Basisfähigkeit für die Ausgabeformatierung von JSON, die gültiges JSON erzeugt, das mit der Lore-Benutzeroberfläche kompatibel ist O json-formatter é uma habilidade base para formatação de saída JSON, projetada para trabalhar com software de worldbuilding Json-formatter - базовый навык для форматирования JSON-выхода, предназначенный для работы с программным обеспечением для создания миров json-formatter هي مهارة أساسية لتنسيق الإخراج JSON، مصممة للعمل مع برنامج بناء العالم how to use json-formatter json-formatter setup guide json-formatter alternative json-formatter vs other formatters what is json-formatter json-formatter install json-formatter for AI agents json output formatting valid JSON generation Lore GUI data loading JSON 格式化工具 世界构建软件 JSON 输出格式化 有效的 JSON 输出 GUI 导出格式 复数集合 AI 工具 AI 에이전트 Generates valid JSON with no trailing commas or comments Uses the GUI export format defined in src/presentation/gui/lore_data.py Supports plural collections with top-level keys and array values Loads JSON data into the Lore GUI using LoreData.from_dict Follows a defined export schema for consistent data formatting Produces parseable JSON for seamless integration with other tools json-formatter is a base skill for formatting JSON output, following rules for valid JSON, export schema, and plural collections.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('agusmdev/fullstack-ai-template/tanstack-client-auth', 'community', 'agusmdev', 'fullstack-ai-template', 'agusmdev/fullstack-ai-template', 'tanstack-client-auth', 0, 0, 54, '2026-03-08T01:57:15.581Z', '2026-03-08T02:11:53.258Z', '277345c7a90dc996d4ddd4e53e23325610b71ea13b9667d5c73896851e51de7b', '{"id":"agusmdev/fullstack-ai-template/tanstack-client-auth","name":"tanstack-client-auth","description":{"en":"The tanstack-client-auth skill provides token-based authentication for TanStack Router and TanStack Start applications, including token storage and protected routes.","zh":"TanStack 客户端身份验证是一个全栈解决方案，使用 TanStack 和 Postgres 实现令牌基于身份验证","ja":"TanStack クライアント認証は、TanStack と Postgres を使用してトークン ベースの認証を実装するフルスタック ソリューション","ko":"TanStack 클라이언트 인증은 TanStack 와 Postgres 를 사용하여 토큰 기반 인증을 구현하는 풀스택 솔루션","es":"tanstack-client-auth es una habilidad para implementar autenticación basada en tokens en aplicaciones TanStack Router y TanStack Start","fr":"tanstack-client-auth est une compétence pour mettre en place l''authentification basée sur les jetons dans les applications TanStack Router et TanStack Start","de":"tanstack-client-auth ist eine Fähigkeit zur Implementierung von Token-basierter Authentifizierung in TanStack Router- und TanStack Start-Anwendungen","pt":"O tanstack-client-auth é uma habilidade que fornece autenticação baseada em tokens para aplicações TanStack Router e TanStack Start","ru":"ИИ Агенты: tanstack-client-auth - это навык, который обеспечивает токеную аутентификацию для приложений TanStack Router и TanStack Start","ar":"تانستاك-كلينت-أوت هو مهارة توفر أتمتة التوكين للعميل لتنفيذ تطبيقات تانستاك روتر و تانستاك ستارت"},"seo":{"title":{"en":"tanstack-client-auth: Token-Based Auth Setup Guide | AI A...","zh":"TanStack 客户端身份验证 Setup Guide","ja":"TanStack クライアント認証のベストプラクティス","ko":"TanStack 클라이언트 인증 튜토리얼","es":"Guía de configuración de tanstack-client-auth para autent...","fr":"Mise en place de l''authentification client avec tanstack-...","de":"Einrichtung von tanstack-client-auth für Client-Authentif...","pt":"Guia de Configuração do tanstack-client-auth para Autenti...","ru":"ИИ Агенты: Настройка tanstack-client-auth для Токенной Ау...","ar":"إعداد تانستاك-كلينت-أوت: مرشد لأتمتة العميل باستخدام التوكين"},"description":{"en":"Unlock secure client-side authentication with tanstack-client-auth. Learn how to implement token-based auth in TanStack Router and TanStack Start applications.","zh":"使用 TanStack 和 Postgres 实现令牌 기반身份验证，AIエージェント 为您提供全栈解决方案","ja":"TanStack と Postgres を使用してトークン ベースの認証を実装し、AIエージェント を活用して開発を効率化","ko":"TanStack 과 Postgres 를 사용하여 토큰 기반 인증을 구현하고 AI 도구를 활용하여 개발을 최적화","es":"Aprende a implementar la autenticación basada en tokens con tanstack-client-auth y mejora la seguridad de tu aplicación","fr":"Découvrez comment mettre en place l''authentification basée sur les jetons avec tanstack-client-auth pour améliorer la sécurité de votre application","de":"Erfahren Sie, wie Sie die Token-basierte Authentifizierung mit tanstack-client-auth implementieren und die Sicherheit Ihrer Anwendung verbessern","pt":"Aprenda a implementar autenticação baseada em tokens com o tanstack-client-auth, incluindo armazenamento de tokens e proteção de rotas","ru":"Откройте для себя, как настроить токеную аутентификацию с помощью ИИ Агентов и tanstack-client-auth, включая хранение токенов и защиту маршрутов","ar":"تعلم كيفية تنفيذ التوكين المستندة إلى العميل مع تانستاك-كلينت-أوت، بما في ذلك تخزين التوكين وحماية المسارات"},"definition":{"en":"tanstack-client-auth is a full-stack repository for implementing token-based authentication in TanStack applications using FastAPI and Postgres.","zh":"TanStack 客户端身份验证是一种使用 TanStack 和 Postgres 实现令牌基于身份验证的技术","ja":"TanStack クライアント認証は、TanStack と Postgres を使用してトークン ベースの認証を実装する技術","ko":"TanStack 클라이언트 인증은 TanStack 와 Postgres 를 사용하여 토큰 기반 인증을 구현하는 기술","es":"tanstack-client-auth es una habilidad de autenticación de cliente que utiliza tokens para proteger rutas y garantizar la seguridad de las aplicaciones","fr":"tanstack-client-auth est une compétence d''authentification client qui utilise des jetons pour protéger les routes et assurer la sécurité des applications","de":"tanstack-client-auth ist eine Client-Authentifizierungsfähigkeit, die Token verwendet, um Routen zu schützen und die Sicherheit von Anwendungen zu gewährleisten","pt":"O que é tanstack-client-auth? É uma habilidade que implementa autenticação baseada em tokens para aplicações TanStack","ru":"Что такое tanstack-client-auth? Это навык, который реализует токеную аутентификацию для приложений TanStack","ar":"ما هو تانستاك-كلينت-أوت؟ هو مهارة تنفذ أتمتة التوكين للعميل لتطبيقات تانستاك"},"features":{"en":["Token storage for secure client-side authentication","Authentication context for managing user sessions","Protected routes with route guards for restricted access","Integration with API clients for seamless authentication","Support for TanStack Router and TanStack Start applications","Compatibility with FastAPI and Postgres for a robust tech stack"],"zh":["使用 TanStack 实现令牌基于身份验证","集成 Postgres 数据库","支持客户端身份验证","提供令牌存储和认证上下文","支持受保护的路由和路由守卫"],"ja":["TanStack を使用してトークン ベースの認証を実装","Postgres データベースとの統合","クライアント認証のサポート","トークンストレージと認証コンテキストの提供","保護されたルートとルート ガードのサポート"],"ko":["TanStack 를 사용하여 토큰 기반 인증을 구현","Postgres 데이터베이스와의 통합","클라이언트 인증의 지원","토큰 저장소와 인증 컨텍스트의 제공","보호된 라우트와 라우트 가드의 지원"],"es":["Implementación de autenticación basada en tokens","Almacenamiento de tokens","Contexto de autenticación","Rutas protegidas","Integración con clientes de API"],"fr":["Mise en place de l''authentification basée sur les jetons","Stockage de jetons","Contexte d''authentification","Routes protégées","Intégration avec les clients d''API"],"de":["Implementierung von Token-basierter Authentifizierung","Token-Speicherung","Authentifizierungskontext","Geschützte Routen","Integration mit API-Clients"],"pt":["Armazenamento de tokens","Contexto de autenticação","Rotas protegidas","Guardas de rota","Integração com clientes de API"],"ru":["Хранение токенов","Контекст аутентификации","Защищенные маршруты","Защитники маршрутов","Интеграция с клиентами API"],"ar":["تخزين التوكين","سياق الأمان","مسارات محمية","حماية المسارات","دمج العملاء API"]},"keywords":{"en":["how to use tanstack-client-auth","tanstack-client-auth setup guide","tanstack-client-auth alternative","tanstack-client-auth vs tanstack-start-auth","token-based authentication in TanStack","FastAPI authentication example","Postgres authentication tutorial","tanstack-client-auth install","tanstack-client-auth documentation"],"zh":["TanStack 客户端身份验证","AIエージェント","TanStack","Postgres","令牌基于身份验证","客户端身份验证","全栈解决方案"],"ja":["TanStack クライアント認証","AIエージェント","TanStack","Postgres","トークン ベースの認証","クライアント認証","フルスタック ソリューション"],"ko":["TanStack 클라이언트 인증","AI 도구","TanStack","Postgres","토큰 기반 인증","클라이언트 인증","풀스택 솔루션"],"es":["autenticación de cliente","tanstack-client-auth","autenticación basada en tokens","seguridad de aplicaciones","Herramientas de AI para desarrolladores","tanstack router","tanstack start"],"fr":["authentification client","tanstack-client-auth","authentification basée sur les jetons","sécurité des applications","Outils d''IA pour développeurs","tanstack router","tanstack start"],"de":["Client-Authentifizierung","tanstack-client-auth","Token-basierte Authentifizierung","Sicherheit von Anwendungen","AI-Tools für Entwickler","tanstack router","tanstack start"],"pt":["tanstack-client-auth","autenticação de tokens","TanStack Router","TanStack Start","armazenamento de tokens","contexto de autenticação","rotas protegidas"],"ru":["tanstack-client-auth","токенная аутентификация","ИИ Агенты","TanStack Router","TanStack Start","хранение токенов","контекст аутентификации"],"ar":["تانستاك-كلينت-أوت","أتمتة التوكين","تانستاك روتر","تانستاك ستارت","تخزين التوكين","سياق الأمان","مسارات محمية"]}},"owner":"agusmdev","repo":"fullstack-ai-template","repoPath":"agusmdev/fullstack-ai-template","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.581Z","topics":[],"category":"community","skillMd":{"name":"tanstack-client-auth","description":"Token-based authentication for TanStack Client (SPA) apps including login/logout, protected routes, auth context, token storage, and route guards. SHARED skill for both TanStack Start (client-only mode) and TanStack Router.","bodyPreview":"# TanStack Client Authentication\n\n## Overview\n\nThis skill covers implementing token-based authentication in TanStack Router (SPA) and TanStack Start (client-only mode) applications. It includes token storage, authentication context, protected routes, route guards, and integration with API clients.\n\n**Important:** This skill is for client-side authentication. For server-side session-based auth in TanStack Start with SSR, use `tanstack-start-auth` instead.\n\n## When to Use This Skill\n\nUse this skil","body":"# TanStack Client Authentication\n\n## Overview\n\nThis skill covers implementing token-based authentication in TanStack Router (SPA) and TanStack Start (client-only mode) applications. It includes token storage, authentication context, protected routes, route guards, and integration with API clients.\n\n**Important:** This skill is for client-side authentication. For server-side session-based auth in TanStack Start with SSR, use `tanstack-start-auth` instead.\n\n## When to Use This Skill\n\nUse this skill when:\n- Building a TanStack Router SPA with external API backend\n- Using TanStack Start in client-only mode (`defaultSsr: false`)\n- Implementing JWT or token-based authentication\n- Need to protect routes behind authentication\n- Managing auth state client-side\n\n## Prerequisites\n\n- TanStack Router or TanStack Start project set up\n- API backend with authentication endpoints\n- Basic understanding of JWT tokens\n\n## Architecture Overview\n\n```\nAuth Flow:\n1. User submits credentials → POST /api/auth/login\n2. Backend returns token → Store in localStorage/sessionStorage\n3. Add token to API requests → Authorization: Bearer {token}\n4. Check auth state → Redirect to /login if needed\n5. Logout → Clear token → Redirect to /login\n\nComponents:\n- AuthContext: Global auth state management\n- AuthProvider: Wraps app with auth context\n- useAuth: Hook to access auth state\n- Protected Routes: Components that require authentication\n- Route Guards: beforeLoad checks for auth\n- Token Storage: localStorage/sessionStorage utilities\n```\n\n## Step 1: Create Auth Types\n\nCreate `src/lib/auth/types.ts`:\n\n```typescript\n// src/lib/auth/types.ts\nexport interface User {\n  id: string\n  email: string\n  display_name: string\n}\n\nexport interface AuthState {\n  user: User | null\n  token: string | null\n  isAuthenticated: boolean\n  isLoading: boolean\n}\n\nexport interface AuthContextValue extends AuthState {\n  login: (email: string, password: string) => Promise<void>\n  logout: () => void\n  register: (email: string, password: string, displayName: string) => Promise<void>\n  refreshUser: () => Promise<void>\n}\n\nexport interface LoginResponse {\n  token: string\n  user: User\n}\n\nexport interface RegisterRequest {\n  email: string\n  password: string\n  display_name: string\n}\n```\n\n## Step 2: Create Token Storage Utilities\n\nCreate `src/lib/auth/storage.ts`:\n\n```typescript\n// src/lib/auth/storage.ts\nconst TOKEN_KEY = ''auth_token''\nconst USER_KEY = ''auth_user''\n\nexport const tokenStorage = {\n  /**\n   * Get stored authentication token\n   */\n  getToken(): string | null {\n    if (typeof window === ''undefined'') return null\n    return localStorage.getItem(TOKEN_KEY)\n  },\n\n  /**\n   * Save authentication token\n   */\n  setToken(token: string): void {\n    if (typeof window === ''undefined'') return\n    localStorage.setItem(TOKEN_KEY, token)\n  },\n\n  /**\n   * Remove authentication token\n   */\n  removeToken(): void {\n    if (typeof window === ''undefined'') return\n    localStorage.removeItem(TOKEN_KEY)\n  },\n\n  /**\n   * Get stored user data\n   */\n  getUser(): User | null {\n    if (typeof window === ''undefined'') return null\n    const userJson = localStorage.getItem(USER_KEY)\n    if (!userJson) return null\n\n    try {\n      return JSON.parse(userJson) as User\n    } catch {\n      return null\n    }\n  },\n\n  /**\n   * Save user data\n   */\n  setUser(user: User): void {\n    if (typeof window === ''undefined'') return\n    localStorage.setItem(USER_KEY, JSON.stringify(user))\n  },\n\n  /**\n   * Remove user data\n   */\n  removeUser(): void {\n    if (typeof window === ''undefined'') return\n    localStorage.removeItem(USER_KEY)\n  },\n\n  /**\n   * Clear all auth data\n   */\n  clear(): void {\n    this.removeToken()\n    this.removeUser()\n  },\n}\n\n// Alternative: sessionStorage version (expires on tab close)\nexport const sessionTokenStorage = {\n  getToken(): string | null {\n    if (typeof window === ''undefined'') return null\n    return sessionStorage.getItem(TOKEN_KEY)\n  },\n\n  setToken(token: string): void {\n    if (typeof window === ''undefined'') return\n    sessionStorage.setItem(TOKEN_KEY, token)\n  },\n\n  removeToken(): void {\n    if (typeof window === ''undefined'') return\n    sessionStorage.removeItem(TOKEN_KEY)\n  },\n\n  getUser(): User | null {\n    if (typeof window === ''undefined'') return null\n    const userJson = sessionStorage.getItem(USER_KEY)\n    if (!userJson) return null\n\n    try {\n      return JSON.parse(userJson) as User\n    } catch {\n      return null\n    }\n  },\n\n  setUser(user: User): void {\n    if (typeof window === ''undefined'') return\n    sessionStorage.setItem(USER_KEY, JSON.stringify(user))\n  },\n\n  removeUser(): void {\n    if (typeof window === ''undefined'') return\n    sessionStorage.removeItem(USER_KEY)\n  },\n\n  clear(): void {\n    this.removeToken()\n    this.removeUser()\n  },\n}\n```\n\n## Step 3: Create Auth API Client\n\nCreate `src/lib/auth/api.ts`:\n\n```typescript\n// src/lib/auth/api.ts\nimport { apiClient } from ''~/lib/api/client''\nimport type { LoginResponse, RegisterRequest, User } from ''./types''\n\nexport const authApi = {\n  /**\n   * Login with email and password\n   */\n  async login(email: string, password: string): Promise<LoginResponse> {\n    const response = await apiClient.post<LoginResponse>(''/auth/login'', {\n      email,\n      password,\n    })\n    return response.data\n  },\n\n  /**\n   * Register new user\n   */\n  async register(data: RegisterRequest): Promise<LoginResponse> {\n    const response = await apiClient.post<LoginResponse>(''/auth/register'', data)\n    return response.data\n  },\n\n  /**\n   * Get current authenticated user\n   */\n  async me(): Promise<User> {\n    const response = await apiClient.get<User>(''/auth/me'')\n    return response.data\n  },\n\n  /**\n   * Logout (optional - call backend logout endpoint)\n   */\n  async logout(): Promise<void> {\n    await apiClient.post(''/auth/logout'')\n  },\n}\n```\n\n## Step 4: Create Auth Context\n\nCreate `src/lib/auth/context.tsx`:\n\n```typescript\n// src/lib/auth/context.tsx\nimport { createContext, useContext, useEffect, useState } from ''react''\nimport { useNavigate } from ''@tanstack/react-router''\nimport { authApi } from ''./api''\nimport { tokenStorage } from ''./storage''\nimport type { AuthContextValue, User } from ''./types''\n\nconst AuthContext = createContext<AuthContextValue | undefined>(undefined)\n\nexport function AuthProvider({ children }: { children: React.ReactNode }) {\n  const navigate = useNavigate()\n  const [user, setUser] = useState<User | null>(null)\n  const [token, setToken] = useState<string | null>(null)\n  const [isLoading, setIsLoading] = useState(true)\n\n  // Initialize auth state from storage on mount\n  useEffect(() => {\n    const initAuth = async () => {\n      const storedToken = tokenStorage.getToken()\n      const storedUser = tokenStorage.getUser()\n\n      if (storedToken && storedUser) {\n        setToken(storedToken)\n        setUser(storedUser)\n\n        // Optionally verify token is still valid\n        try {\n          const currentUser = await authApi.me()\n          setUser(currentUser)\n          tokenStorage.setUser(currentUser)\n        } catch (error) {\n          // Token invalid, clear storage\n          tokenStorage.clear()\n          setToken(null)\n          setUser(null)\n        }\n      }\n\n      setIsLoading(false)\n    }\n\n    initAuth()\n  }, [])\n\n  const login = async (email: string, password: string) => {\n    try {\n      const response = await authApi.login(email, password)\n\n      // Store token and user\n      tokenStorage.setToken(response.token)\n      tokenStorage.setUser(response.user)\n\n      setToken(response.token)\n      setUser(response.user)\n\n      // Redirect to dashboard or intended destination\n      navigate({ to: ''/dashboard'' })\n    } catch (error) {\n      // Re-throw for component to handle\n      throw error\n    }\n  }\n\n  const register = async (\n    email: string,\n    password: string,\n    displayName: string\n  ) => {\n    try {\n      const response = await authApi.register({\n        email,\n        password,\n        display_name: displayName,\n      })\n\n      // Store token and user\n      tokenStorage.setToken(response.token)\n      tokenStorage.setUser(response.user)\n\n      setToken(response.token)\n      setUser(response.user)\n\n      // Redirect to dashboard\n      navigate({ to: ''/dashboard'' })\n    } catch (error) {\n      throw error\n    }\n  }\n\n  const logout = () => {\n    // Clear storage\n    tokenStorage.clear()\n\n    // Clear state\n    setToken(null)\n    setUser(null)\n\n    // Optionally call backend logout\n    authApi.logout().catch(() => {\n      // Ignore errors on logout\n    })\n\n    // Redirect to login\n    navigate({ to: ''/login'' })\n  }\n\n  const refreshUser = async () => {\n    if (!token) return\n\n    try {\n      const currentUser = await authApi.me()\n      setUser(currentUser)\n      tokenStorage.setUser(currentUser)\n    } catch (error) {\n      // Token invalid, logout\n      logout()\n    }\n  }\n\n  const value: AuthContextValue = {\n    user,\n    token,\n    isAuthenticated: !!token && !!user,\n    isLoading,\n    login,\n    logout,\n    register,\n    refreshUser,\n  }\n\n  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>\n}\n\nexport function useAuth() {\n  const context = useContext(AuthContext)\n  if (context === undefined) {\n    throw new Error(''useAuth must be used within an AuthProvider'')\n  }\n  return context\n}\n```\n\n## Step 5: Wrap App with AuthProvider\n\nUpdate `src/routes/__root.tsx`:\n\n```tsx\n// src/routes/__root.tsx\nimport { createRootRoute, Outlet } from ''@tanstack/react-router''\nimport { AuthProvider } from ''~/lib/auth/context''\n\nexport const Route = createRootRoute({\n  component: () => (\n    <AuthProvider>\n      <Outlet />\n    </AuthProvider>\n  ),\n})\n```\n\n## Step 6: Create Protected Route Component\n\nCreate `src/components/auth/protected-route.tsx`:\n\n```tsx\n// src/components/auth/protected-route.tsx\nimport { Navigate } from ''@tanstack/react-router''\nimport { useAuth } from ''~/lib/auth/context''\n\ninterface ProtectedRouteProps {\n  children: React.ReactNode\n}\n\nexport function ProtectedRoute({ children }: ProtectedRouteProps) {\n  const { isAuthenticated, isLoading } = useAuth()\n\n  if (isLoading) {\n    return (\n      <div className=\"flex min-h-screen items-center justify-center\">\n        <div className=\"text-center\">\n          <div className=\"h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent\" />\n          <p className=\"mt-2 text-sm text-muted-foreground\">Loading...</p>\n        </div>\n      </div>\n    )\n  }\n\n  if (!isAuthenticated) {\n    return <Navigate to=\"/login\" />\n  }\n\n  return <>{children}</>\n}\n```\n\n## Step 7: Implement Route Guards with beforeLoad\n\nFor better performance, use `beforeLoad` to check auth before loading route:\n\n```typescript\n// src/routes/dashboard.tsx\nimport { createFileRoute, redirect } from ''@tanstack/react-router''\nimport { tokenStorage } from ''~/lib/auth/storage''\n\nexport const Route = createFileRoute(''/dashboard'')({\n  // Check auth before loading this route\n  beforeLoad: async ({ location }) => {\n    const token = tokenStorage.getToken()\n\n    if (!token) {\n      throw redirect({\n        to: ''/login'',\n        search: {\n          // Save intended destination for redirect after login\n          redirect: location.href,\n        },\n      })\n    }\n  },\n  component: DashboardComponent,\n})\n\nfunction DashboardComponent() {\n  const { user } = useAuth()\n\n  return (\n    <div>\n      <h1>Dashboard</h1>\n      <p>Welcome, {user?.display_name}!</p>\n    </div>\n  )\n}\n```\n\n## Step 8: Create Login Page\n\nCreate `src/routes/login.tsx`:\n\n```tsx\n// src/routes/login.tsx\nimport { createFileRoute, useNavigate, useSearch } from ''@tanstack/react-router''\nimport { useState } from ''react''\nimport { useAuth } from ''~/lib/auth/context''\nimport { Button } from ''~/components/ui/button''\nimport { Input } from ''~/components/ui/input''\nimport { Label } from ''~/components/ui/label''\n\nexport const Route = createFileRoute(''/login'')({\n  component: LoginPage,\n})\n\nfunction LoginPage() {\n  const { login, isAuthenticated } = useAuth()\n  const navigate = useNavigate()\n  const search = useSearch({ from: ''/login'' })\n\n  const [email, setEmail] = useState('''')\n  const [password, setPassword] = useState('''')\n  const [error, setError] = useState<string | null>(null)\n  const [isLoading, setIsLoading] = useState(false)\n\n  // Redirect if already authenticated\n  if (isAuthenticated) {\n    const redirectTo = (search as any)?.redirect || ''/dashboard''\n    navigate({ to: redirectTo })\n    return null\n  }\n\n  const handleSubmit = async (e: React.FormEvent) => {\n    e.preventDefault()\n    setError(null)\n    setIsLoading(true)\n\n    try {\n      await login(email, password)\n      // Navigation handled by AuthContext\n    } catch (err) {\n      setError(err instanceof Error ? err.message : ''Login failed'')\n    } finally {\n      setIsLoading(false)\n    }\n  }\n\n  return (\n    <div className=\"flex min-h-screen items-center justify-center\">\n      <div className=\"w-full max-w-md space-y-6 rounded-lg border p-8\">\n        <div className=\"space-y-2 text-center\">\n          <h1 className=\"text-3xl font-bold\">Sign In</h1>\n          <p className=\"text-muted-foreground\">\n            Enter your credentials to access your account\n          </p>\n        </div>\n\n        <form onSubmit={handleSubmit} className=\"space-y-4\">\n          {error && (\n            <div className=\"rounded-md bg-destructive/10 p-3 text-sm text-destructive\">\n              {error}\n            </div>\n          )}\n\n          <div className=\"space-y-2\">\n            <Label htmlFor=\"email\">Email</Label>\n            <Input\n              id=\"email\"\n              type=\"email\"\n              value={email}\n              onChange={(e) => setEmail(e.target.value)}\n              required\n              disabled={isLoading}\n            />\n          </div>\n\n          <div className=\"space-y-2\">\n            <Label htmlFor=\"password\">Password</Label>\n            <Input\n              id=\"password\"\n              type=\"password\"\n              value={password}\n              onChange={(e) => setPassword(e.target.value)}\n              required\n              disabled={isLoading}\n            />\n          </div>\n\n          <Button type=\"submit\" className=\"w-full\" disabled={isLoading}>\n            {isLoading ? ''Signing in...'' : ''Sign In''}\n          </Button>\n        </form>\n\n        <p className=\"text-center text-sm text-muted-foreground\">\n          Don''t have an account?{'' ''}\n          <a href=\"/register\" className=\"text-primary hover:underline\">\n            Sign up\n          </a>\n        </p>\n      </div>\n    </div>\n  )\n}\n```\n\n## Step 9: Integrate Auth Token with API Client\n\nUpdate your API client to include auth token in requests:\n\n```typescript\n// src/lib/api/client.ts\nimport axios from ''axios''\nimport { tokenStorage } from ''~/lib/auth/storage''\n\nconst API_BASE_URL = import.meta.env.VITE_API_BASE_URL || ''http://localhost:8000/api/v1''\n\nexport const apiClient = axios.create({\n  baseURL: API_BASE_URL,\n  headers: {\n    ''Content-Type'': ''application/json'',\n  },\n})\n\n// Request interceptor: Add auth token to all requests\napiClient.interceptors.request.use(\n  (config) => {\n    const token = tokenStorage.getToken()\n    if (token) {\n      config.headers.Authorization = `Bearer ${token}`\n    }\n    return config\n  },\n  (error) => {\n    return Promise.reject(error)\n  }\n)\n\n// Response interceptor: Handle 401 Unauthorized\napiClient.interceptors.response.use(\n  (response) => response,\n  (error) => {\n    if (error.response?.status === 401) {\n      // Token expired or invalid\n      tokenStorage.clear()\n      window.location.href = ''/login''\n    }\n    return Promise.reject(error)\n  }\n)\n```\n\n## Step 10: Create Logout Component\n\nCreate `src/components/auth/logout-button.tsx`:\n\n```tsx\n// src/components/auth/logout-button.tsx\nimport { useAuth } from ''~/lib/auth/context''\nimport { Button } from ''~/components/ui/button''\n\nexport function LogoutButton() {\n  const { logout, user } = useAuth()\n\n  return (\n    <div className=\"flex items-center gap-4\">\n      <span className=\"text-sm text-muted-foreground\">{user?.email}</span>\n      <Button variant=\"outline\" onClick={logout}>\n        Logout\n      </Button>\n    </div>\n  )\n}\n```\n\n## Advanced Patterns\n\n### Pattern 1: Role-Based Access Control\n\n```typescript\n// src/lib/auth/types.ts\nexport interface User {\n  id: string\n  email: string\n  display_name: string\n  role: ''admin'' | ''user'' | ''guest''\n}\n\n// src/lib/auth/guards.ts\nimport { tokenStorage } from ''./storage''\n\nexport function requireRole(role: ''admin'' | ''user'') {\n  return () => {\n    const user = tokenStorage.getUser()\n\n    if (!user) {\n      throw redirect({ to: ''/login'' })\n    }\n\n    if (user.role !== role && user.role !== ''admin'') {\n      throw redirect({ to: ''/unauthorized'' })\n    }\n  }\n}\n\n// Usage in route\nexport const Route = createFileRoute(''/admin'')({\n  beforeLoad: requireRole(''admin''),\n  component: AdminPage,\n})\n```\n\n### Pattern 2: Refresh Token Handling\n\n```typescript\n// src/lib/auth/storage.ts\nconst REFRESH_TOKEN_KEY = ''refresh_token''\n\nexport const tokenStorage = {\n  // ... existing methods\n\n  getRefreshToken(): string | null {\n    if (typeof window === ''undefined'') return null\n    return localStorage.getItem(REFRESH_TOKEN_KEY)\n  },\n\n  setRefreshToken(token: string): void {\n    if (typeof window === ''undefined'') return\n    localStorage.setItem(REFRESH_TOKEN_KEY, token)\n  },\n\n  removeRefreshToken(): void {\n    if (typeof window === ''undefined'') return\n    localStorage.removeItem(REFRESH_TOKEN_KEY)\n  },\n}\n\n// src/lib/api/client.ts\nlet isRefreshing = false\nlet refreshSubscribers: ((token: string) => void)[] = []\n\nfunction onTokenRefreshed(token: string) {\n  refreshSubscribers.forEach((callback) => callback(token))\n  refreshSubscribers = []\n}\n\napiClient.interceptors.response.use(\n  (response) => response,\n  async (error) => {\n    const originalRequest = error.config\n\n    if (error.response?.status === 401 && !originalRequest._retry) {\n      if (isRefreshing) {\n        // Wait for token refresh\n        return new Promise((resolve) => {\n          refreshSubscribers.push((token: string) => {\n            originalRequest.headers.Authorization = `Bearer ${token}`\n            resolve(apiClient(originalRequest))\n          })\n        })\n      }\n\n      originalRequest._retry = true\n      isRefreshing = true\n\n      try {\n        const refreshToken = tokenStorage.getRefreshToken()\n        if (!refreshToken) {\n          throw new Error(''No refresh token'')\n        }\n\n        const response = await axios.post(`${API_BASE_URL}/auth/refresh`, {\n          refresh_token: refreshToken,\n        })\n\n        const { token } = response.data\n        tokenStorage.setToken(token)\n\n        onTokenRefreshed(token)\n        isRefreshing = false\n\n        originalRequest.headers.Authorization = `Bearer ${token}`\n        return apiClient(originalRequest)\n      } catch (refreshError) {\n        // Refresh failed, logout\n        tokenStorage.clear()\n        window.location.href = ''/login''\n        return Promise.reject(refreshError)\n      }\n    }\n\n    return Promise.reject(error)\n  }\n)\n```\n\n### Pattern 3: Remember Me Functionality\n\n```typescript\n// src/lib/auth/context.tsx\nconst login = async (email: string, password: string, rememberMe: boolean = false) => {\n  try {\n    const response = await authApi.login(email, password)\n\n    const storage = rememberMe ? tokenStorage : sessionTokenStorage\n    storage.setToken(response.token)\n    storage.setUser(response.user)\n\n    setToken(response.token)\n    setUser(response.user)\n\n    navigate({ to: ''/dashboard'' })\n  } catch (error) {\n    throw error\n  }\n}\n```\n\n### Pattern 4: Auth Loading Skeleton\n\n```tsx\n// src/components/auth/auth-guard.tsx\nimport { Outlet } from ''@tanstack/react-router''\nimport { useAuth } from ''~/lib/auth/context''\n\nexport function AuthGuard() {\n  const { isLoading } = useAuth()\n\n  if (isLoading) {\n    return <AuthLoadingSkeleton />\n  }\n\n  return <Outlet />\n}\n\nfunction AuthLoadingSkeleton() {\n  return (\n    <div className=\"flex min-h-screen items-center justify-center\">\n      <div className=\"space-y-4\">\n        <div className=\"h-8 w-8 animate-spin rounded-full border-4 border-primary border-t-transparent\" />\n        <p className=\"text-sm text-muted-foreground\">Authenticating...</p>\n      </div>\n    </div>\n  )\n}\n```\n\n## Security Best Practices\n\n1. **Never store sensitive data in localStorage**\n   - Only store tokens, not passwords\n   - Consider using httpOnly cookies for production\n\n2. **Always use HTTPS in production**\n   - Tokens sent over HTTP can be intercepted\n\n3. **Implement token expiration**\n   - Short-lived access tokens (15 mins - 1 hour)\n   - Long-lived refresh tokens (days - weeks)\n\n4. **Validate tokens on every request**\n   - Backend should verify token signature\n   - Check expiration time\n\n5. **Clear tokens on logout**\n   - Remove from storage\n   - Invalidate on backend\n\n6. **Handle token theft**\n   - Implement token rotation\n   - Monitor for suspicious activity\n   - Add device/IP tracking\n\n## Verification\n\nTest your authentication implementation:\n\n1. **Login flow:**\n   ```bash\n   # Start dev server\n   bun run dev\n\n   # Navigate to /login\n   # Submit credentials\n   # Verify redirect to /dashboard\n   # Check localStorage for token\n   ```\n\n2. **Protected routes:**\n   ```bash\n   # Without auth: Navigate to /dashboard\n   # Should redirect to /login\n\n   # With auth: Navigate to /dashboard\n   # Should show dashboard content\n   ```\n\n3. **Logout:**\n   ```bash\n   # Click logout button\n   # Verify redirect to /login\n   # Check localStorage (should be empty)\n   ```\n\n4. **Token persistence:**\n   ```bash\n   # Login\n   # Refresh page\n   # Should remain authenticated\n   ```\n\n5. **API integration:**\n   ```bash\n   # Check Network tab in DevTools\n   # Verify Authorization header in requests\n   ```\n\n## Troubleshooting\n\n### Issue: \"useAuth must be used within AuthProvider\"\n\n**Cause:** Using `useAuth()` outside of `<AuthProvider>`.\n\n**Solution:** Ensure `__root.tsx` wraps app with `<AuthProvider>`:\n```tsx\nexport const Route = createRootRoute({\n  component: () => (\n    <AuthProvider>\n      <Outlet />\n    </AuthProvider>\n  ),\n})\n```\n\n### Issue: Infinite redirect loop\n\n**Cause:** Protected route redirects to login, which redirects back.\n\n**Solution:** Exclude `/login` from authentication checks:\n```typescript\nexport const Route = createFileRoute(''/login'')({\n  beforeLoad: ({ location }) => {\n    const token = tokenStorage.getToken()\n    if (token) {\n      throw redirect({ to: ''/dashboard'' })\n    }\n  },\n})\n```\n\n### Issue: Token persists after logout\n\n**Cause:** Not clearing all storage.\n\n**Solution:** Use `tokenStorage.clear()` in logout function.\n\n### Issue: 401 errors after page refresh\n\n**Cause:** Token not loaded from storage on mount.\n\n**Solution:** Verify `useEffect` in `AuthProvider` loads token from storage.\n\n## Project Structure\n\n```\nsrc/\n├── routes/\n│   ├── __root.tsx              # AuthProvider wrapper\n│   ├── login.tsx               # Login page\n│   ├── register.tsx            # Registration page\n│   └── dashboard.tsx           # Protected route\n├── lib/\n│   ├── auth/\n│   │   ├── types.ts            # Auth type definitions\n│   │   ├── context.tsx         # AuthContext and AuthProvider\n│   │   ├── storage.ts          # Token storage utilities\n│   │   ├── api.ts              # Auth API client\n│   │   └── guards.ts           # Route guard utilities (optional)\n│   └── api/\n│       └── client.ts           # Axios client with interceptors\n└── components/\n    ├── auth/\n    │   ├── protected-route.tsx # Protected route component\n    │   └── logout-button.tsx   # Logout button\n    └── ui/                     # shadcn/ui components\n```\n\n## Notes\n\n- This skill covers client-side token-based authentication\n- For server-side session auth in TanStack Start (SSR), use `tanstack-start-auth` skill\n- Tokens are stored in localStorage by default (consider security implications)\n- Always use HTTPS in production to protect tokens\n- Implement refresh token rotation for enhanced security\n- Consider using httpOnly cookies for production applications\n\n## Next Steps\n\nAfter implementing authentication:\n- Set up React Query with authenticated requests (see `tanstack-react-query-setup`)\n- Build registration and password reset flows\n- Add multi-factor authentication (MFA)\n- Implement OAuth/SSO providers\n- Add user profile management\n- Set up role-based access control (RBAC)\n\n## Resources\n\n- [TanStack Router Authentication Guide](https://tanstack.com/router/latest/docs/guide/authenticated-routes)\n- [JWT Best Practices](https://tools.ietf.org/html/rfc8725)\n- [OWASP Authentication Cheat Sheet](https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html)\n"},"lastSynced":"2026-03-08T02:11:53.258Z","agentAnalysis":{"suitability":{"en":"Perfect for Web Development Agents needing token-based authentication for TanStack applications.","zh":"非常适合需要基于令牌的身份验证的TanStack Web开发代理。","ja":"TanStackアプリケーションにトークンベースの認証が必要なWeb開発エージェントに最適です。","ko":"TanStack 애플리케이션에 토큰 기반 인증이 필요한 웹 개발 에이전트에 이상적입니다.","es":"Perfecto para agentes de desarrollo web que necesitan autenticación basada en tokens para aplicaciones de TanStack.","fr":"Parfait pour les agents de développement Web nécessitant une authentification basée sur des jetons pour les applications TanStack.","de":"Perfekt für Webentwicklungsagenten, die eine tokenbasierte Authentifizierung für TanStack-Anwendungen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Web que necessitam de autenticação baseada em token para aplicações TanStack.","ru":"Идеально подходит для агентов веб-разработки, требующих токен-аутентификацию для приложений TanStack.","ar":"مثالي لعميل التطوير الويب الذي يحتاج إلى مصادقة تستند إلى رمز لمحطات TanStack."},"recommendation":{"en":"Empowers agents to implement secure token storage, authentication context, and protected routes using TanStack Router and TanStack Start, integrating seamlessly with API clients and route guards.","zh":"赋予代理实现安全的令牌存储、身份验证上下文和受保护的路由，使用TanStack Router和TanStack Start，实现与API客户端和路由守卫的无缝集成。","ja":"TanStack RouterとTanStack Startを使用して、エージェントが安全なトークンストレージ、認証コンテキスト、保護されたルートを実装できるようにし、APIクライアントやルートガードとシームレスに統合します。","ko":"TanStack Router와 TanStack Start를 사용하여 에이전트가 안전한 토큰 저장, 인증 컨텍스트 및 보호된 라우트를 구현할 수 있도록 하며, API 클라이언트 및 라우트 가드와의 통합을 원활하게 구현합니다.","es":"Habilita a los agentes a implementar un almacenamiento de tokens seguro, contexto de autenticación y rutas protegidas utilizando TanStack Router y TanStack Start, integrándose de forma transparente con clientes de API y guardianes de rutas.","fr":"Permet aux agents de mettre en œuvre un stockage de jetons sécurisé, un contexte d''authentification et des routes protégées en utilisant TanStack Router et TanStack Start, en s''intégrant de manière transparente avec les clients API et les gardiens de route.","de":"Ermächtigt Agenten, sichere Token-Speicherung, Authentifizierungscontext und geschützte Routen mithilfe von TanStack Router und TanStack Start zu implementieren, und integriert sich nahtlos mit API-Clients und Routenwächtern.","pt":"Habilita os agentes a implementar armazenamento de token seguro, contexto de autenticação e rotas protegidas usando TanStack Router e TanStack Start, integrando-se perfeitamente com clientes API e guardas de rota.","ru":"Наделяет агентов возможностью реализовать безопасное хранение токенов, контекст аутентификации и защищенные маршруты с помощью TanStack Router и TanStack Start, интегрируясь без проблем с клиентами API и маршрутизационными охранниками.","ar":"يمنح الوكيل khảية تنفيذ تخزين رمز آمن وسياق مصادقة وطرق محمية باستخدام TanStack Router و TanStack Start، متكامل بشكل متسق مع عملاء API وحراس المسار."},"useCases":{"en":["Implementing token-based authentication for Single-Page Applications (SPAs)","Protecting client-only routes in TanStack Start applications","Integrating authentication with API clients for secure data access"],"zh":["为单页应用程序（SPAs）实现基于令牌的身份验证","保护TanStack Start应用程序中的客户端仅路由","将身份验证集成到API客户端以实现安全的数据访问"],"ja":["シングルページアプリケーション（SPAs）にトークンベースの認証を実装する","TanStack Startアプリケーションでクライアント専用のルートを保護する","APIクライアントと統合してセキュアなデータアクセスを実現するための認証を実装する"],"ko":["싱글 페이지 애플리케이션(SPA)에 토큰 기반 인증을 구현하는 것","TanStack Start 애플리케이션에서 클라이언트 전용 라우트를 보호하는 것","API 클라이언트와의 통합을 통해 안전한 데이터 액세스를 위한 인증을 구현하는 것"],"es":["Implementar autenticación basada en tokens para Aplicaciones de una sola página (SPAs)","Proteger rutas solo para clientes en aplicaciones de TanStack Start","Integrar la autenticación con clientes de API para acceso a datos seguro"],"fr":["Mettre en œuvre une authentification basée sur des jetons pour les applications à page unique (SPAs)","Protéger les routes clientes uniquement dans les applications TanStack Start","Intégrer l''authentification avec les clients API pour un accès sécurisé aux données"],"de":["Implementierung von tokenbasierter Authentifizierung für Single-Page-Anwendungen (SPAs)","Schutz von clientseitigen Routen in TanStack Start-Anwendungen","Integration der Authentifizierung mit API-Clients für sicheren Datenzugriff"],"pt":["Implementar autenticação baseada em token para Aplicativos de Página Única (SPAs)","Proteger rotas somente para clientes em aplicações TanStack Start","Integrar autenticação com clientes API para acesso seguro a dados"],"ru":["Реализовать токен-аутентификацию для Одностраничных Приложений (SPAs)","Защитить маршруты только для клиентов в приложениях TanStack Start","Интегрировать аутентификацию с клиентами API для безопасного доступа к данным"],"ar":["تنفيذ مصادقة تستند إلى رمز لمواقع الويب ذات الصفحة الواحدة (SPAs)","حماية مسارات العملاء فقط في تطبيقات TanStack Start","دمج المصادقة مع العملاء API للوصول الآمن إلى البيانات"]},"limitations":{"en":["Limited to client-side authentication","Not suitable for server-side session-based authentication in TanStack Start with Server-Side Rendering (SSR)"],"zh":["仅限客户端身份验证","不适合在TanStack Start中使用服务器端会话身份验证（SSR）"],"ja":["クライアント側の認証のみ","TanStack Startのサーバーサイドレンダリング（SSR）でのサーバーサイドセッションベースの認証には適していません"],"ko":["클라이언트 측 인증만 해당","TanStack Start의 서버 측 렌더링(SSR)에서 서버 측 세션 기반 인증에는 적합하지 않음"],"es":["Limitado a la autenticación del lado del cliente","No adecuado para la autenticación de sesión del lado del servidor en TanStack Start con Representación del lado del servidor (SSR)"],"fr":["Limité à l''authentification côté client","Non adapté à l''authentification de session côté serveur dans TanStack Start avec Rendering du côté du serveur (SSR)"],"de":["Begrenzt auf Client-Seitige-Authentifizierung","Nicht geeignet für Server-Seitige-Sitzungsauthentifizierung in TanStack Start mit Server-Seitigem Rendering (SSR)"],"pt":["Limitado à autenticação do lado do cliente","Não é adequado para autenticação de sessão baseada no servidor em TanStack Start com Renderização do Lado do Servidor (SSR)"],"ru":["Ограничен аутентификацией на стороне клиента","Не подходит для сессионной аутентификации на стороне сервера в TanStack Start с Выдачей на стороне сервера (SSR)"],"ar":["محدود بمصادقة جانب العميل","لا يصلح لمصادقة جلسة على جانب الخادم في TanStack Start مع عرض جانب الخادم (SSR)"]},"version":4},"contentHash":"277345c7a90dc996d4ddd4e53e23325610b71ea13b9667d5c73896851e51de7b","qualityScore":54}');
