INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('agusmdev/fullstack-ai-template/tanstack-client-auth', 'tanstack-client-auth', 'agusmdev', 'fullstack-ai-template', 'community', 'tanstack-client-auth agusmdev fullstack-ai-template community The tanstack-client-auth skill provides token-based authentication for TanStack Router and TanStack Start applications, including token storage and protected routes. TanStack 客户端身份验证是一个全栈解决方案，使用 TanStack 和 Postgres 实现令牌基于身份验证 TanStack クライアント認証は、TanStack と Postgres を使用してトークン ベースの認証を実装するフルスタック ソリューション TanStack 클라이언트 인증은 TanStack 와 Postgres 를 사용하여 토큰 기반 인증을 구현하는 풀스택 솔루션 tanstack-client-auth es una habilidad para implementar autenticación basada en tokens en aplicaciones TanStack Router y TanStack Start tanstack-client-auth est une compétence pour mettre en place l''authentification basée sur les jetons dans les applications TanStack Router et TanStack Start tanstack-client-auth ist eine Fähigkeit zur Implementierung von Token-basierter Authentifizierung in TanStack Router- und TanStack Start-Anwendungen O tanstack-client-auth é uma habilidade que fornece autenticação baseada em tokens para aplicações TanStack Router e TanStack Start ИИ Агенты: tanstack-client-auth - это навык, который обеспечивает токеную аутентификацию для приложений TanStack Router и TanStack Start تانستاك-كلينت-أوت هو مهارة توفر أتمتة التوكين للعميل لتنفيذ تطبيقات تانستاك روتر و تانستاك ستارت how to use tanstack-client-auth tanstack-client-auth setup guide tanstack-client-auth alternative tanstack-client-auth vs tanstack-start-auth token-based authentication in TanStack FastAPI authentication example Postgres authentication tutorial tanstack-client-auth install tanstack-client-auth documentation TanStack 客户端身份验证 AIエージェント TanStack Postgres 令牌基于身份验证 客户端身份验证 全栈解决方案 Token storage for secure client-side authentication Authentication context for managing user sessions Protected routes with route guards for restricted access Integration with API clients for seamless authentication Support for TanStack Router and TanStack Start applications Compatibility with FastAPI and Postgres for a robust tech stack tanstack-client-auth is a full-stack repository for implementing token-based authentication in TanStack applications using FastAPI and Postgres.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tygwan/ultra-codex-init/prd-writer', 'community', 'tygwan', 'ultra-codex-init', 'tygwan/ultra-codex-init', 'prd-writer', 0, 0, 54, '2026-03-08T01:57:15.585Z', '2026-03-08T02:11:56.185Z', 'd5b8db1e170256db836d74eb17298a6599eb7dd596dbe32eb50b64944ff5084e', '{"id":"tygwan/ultra-codex-init/prd-writer","name":"prd-writer","description":{"en":"The prd-writer skill provides a high-efficiency Codex skill framework for product managers to write and structure PRD documents. It benefits senior product managers specializing in PRD writing.","zh":"prd-writer 技术文档提供高效率的 Codex 技能框架，用于快速的 PRD 文档写作和结构化","ja":"prd-writer AIエージェントは、高性能の Codex スキル フレームワークを提供し、効率的な PRD 文書の作成と構造化を実現","ko":"prd-writer 개발자 가이드는 효율적인 Codex 스킬 프레임워크를 제공하여 빠르게 PRD 문서를 작성하고 구조화할 수 있습니다","es":"prd-writer es un marco de habilidades de alta eficiencia para la creación de documentos de requisitos de producto estructurados","fr":"prd-writer est un cadre de compétences à haute efficacité pour la création de documents de spécifications de produit structurés","de":"prd-writer ist ein Rahmenwerk für Hochleistungs-Fähigkeiten zur Erstellung strukturierter Produktanforderungsdokumente","pt":"O prd-writer é uma habilidade de codex que fornece um framework para escrever documentos de requisitos de produto de forma estruturada e eficiente.","ru":"prd-writer - это навык codex, который предоставляет框架 для создания документов требований к продукту в структурированном и эффективном виде с помощью ИИ Агентов","ar":"prd-writer هي مهارة كودكس توفر إطارًا لكتابة توثيق متطلبات المنتج بطريقة منظمة وفعالة"},"seo":{"title":{"en":"prd-writer: PRD Template Setup Guide | AI Agent Skill","zh":"prd-writer 技术文档：高效率 Codex 技能框架设置指南","ja":"prd-writer AIエージェント：高性能 Codex スキル フレームワークの設定ガイド","ko":"prd-writer 개발자 가이드: 효율적인 Codex 스킬 프레임워크 설정 방법","es":"Guía de configuración de prd-writer para documentos de re...","fr":"Guide de mise en place de prd-writer pour les documents d...","de":"Einrichtungsleitfaden für prd-writer zur Erstellung von P...","pt":"Guia de Configuração do prd-writer: Especialista em Docum...","ru":"Настройка прд-writer: Инструмент для создания документов ...","ar":"دليل إعداد prd-writer: أداة الكتابة الفنية لتوثيق متطلبات..."},"description":{"en":"Discover how to leverage prd-writer for efficient PRD writing, with templates and guidelines for AI agents. Get started with our setup guide today!","zh":"了解 prd-writer 技术文档的高效率 Codex 技能框架，实现快速的 PRD 文档写作和结构化","ja":"prd-writer AIエージェントの高性能 Codex スキル フレームワークを使用して、効率的な PRD 文書の作成と構造化を実現","ko":"prd-writer 개발자 가이드: 효율적인 Codex 스킬 프레임워크를 사용하여 빠르게 PRD 문서를 작성하고 구조화하세요","es":"Aprende a utilizar prd-writer para crear documentos de requisitos de producto estructurados y eficientes con plantillas y hooks personalizables","fr":"Découvrez comment utiliser prd-writer pour créer des documents de spécifications de produit structurés et efficaces avec des modèles et des hooks personnalis...","de":"Erfahren Sie, wie Sie prd-writer verwenden können, um strukturierte und effiziente Produktanforderungsdokumente mit anpassbaren Vorlagen und Hooks zu erstellen","pt":"Aprenda a configurar o prd-writer, uma habilidade de codex de alta eficiência para escrever documentos de requisitos de produto de forma estruturada","ru":"Узнайте, как настроить прд-writer, высокоэффективный навык codex для создания документов требований к продукту с использованием ИИ Агентов","ar":"تعرف على كيفية إعداد prd-writer، مهارة كودكس ذكية لكتابة توثيق متطلبات المنتج بطريقة منظمة"},"definition":{"en":"prd-writer is a Codex skill framework that enables efficient PRD writing, with 58 ready-to-use skills, hooks, and phase-based development templates.","zh":"prd-writer 是一种高效率的 Codex 技能框架，用于快速的 PRD 文档写作和结构化","ja":"prd-writer は、高性能の Codex スキル フレームワークであり、効率的な PRD 文書の作成と構造化を実現","ko":"prd-writer는 효율적인 Codex 스킬 프레임워크로 빠르게 PRD 문서를 작성하고 구조화하는 데 사용됩니다","es":"prd-writer es una habilidad de AI que ayuda a crear documentos de requisitos de producto estructurados y eficientes","fr":"prd-writer est une compétence d''IA qui aide à créer des documents de spécifications de produit structurés et efficaces","de":"prd-writer ist eine KI-Fähigkeit, die dabei hilft, strukturierte und effiziente Produktanforderungsdokumente zu erstellen","pt":"O prd-writer é uma habilidade de codex que auxilia na criação de documentos de requisitos de produto","ru":"prd-writer - это навык codex, который помогает в создании документов требований к продукту с использованием ИИ Агентов","ar":"prd-writer هي مهارة كودكس تساعد في إنشاء توثيق متطلبات المنتج"},"features":{"en":["Generates PRD documents using the ~/.codex/commands/dev-doc-planner/PRD-TEMPLATE.md template","Supports structured section writing with guidelines","Stores PRD documents in the {project}/docs/prd/ location","Follows a file naming convention of {feature-name}-prd.md","Enables priority sorting and user story writing","Analyzes and defines requirements for PRD documents"],"zh":["支持 58 个即用技能、钩子和基于阶段的开发模板","提供 PRD 文档写作和结构化功能","支持要求分析和定义、用户故事写作和优先级排序","提供模板参考和写作指南"],"ja":["58 個の即用スキル、フック、およびフェーズベースの開発テンプレートをサポート","PRD 文書の作成と構造化機能を提供","要求分析と定義、ユーザー ストーリーの作成、および優先順位の整理をサポート","テンプレート参照と作成ガイドを提供"],"ko":["58개의 즉시 사용 가능한 스킬, 후크 및 단계 기반 개발 템플릿을 지원","PRD 문서 작성 및 구조화 기능을 제공","요구 사항 분석 및 정의, 사용자 스토리 작성 및 우선 순위 정리를 지원","템플릿 참조 및 작성 가이드를 제공"],"es":["Plantillas de documentos de requisitos de producto personalizables","Hooks para la integración con otros marcos de trabajo","Estructura de documentos basada en fases","Análisis de requisitos y definición de prioridades","Creación de historias de usuario"],"fr":["Modèles de documents de spécifications de produit personnalisables","Hooks pour l''intégration avec d''autres cadres de travail","Structure de documents basée sur les phases","Analyse des exigences et définition des priorités","Création d''histoires d''utilisateur"],"de":["Anpassbare Vorlagen für Produktanforderungsdokumente","Hooks für die Integration mit anderen Rahmenwerken","Phasenbasierte Dokumentenstruktur","Anforderungsanalyse und Prioritätenfestlegung","Erstellung von Benutzerstories"],"pt":["Estruturação de documentos de requisitos de produto","Análise e definição de requisitos","Criação de histórias de usuário","Priorização de requisitos","Uso de template de PRD para facilitar a escrita"],"ru":["Структуризация документов требований к продукту","Анализ и определение требований","Создание историй пользователя","Приоритизация требований","Использование шаблона PRD для облегчения написания с помощью ИИ Агентов"],"ar":["هيكلة توثيق متطلبات المنتج","تحليل وتحديد المتطلبات","إنشاء قصص المستخدم","ترتيب الأولويات للمتطلبات","استخدام قالب توثيق متطلبات المنتج لتبسيط الكتابة"]},"keywords":{"en":["how to use prd-writer","prd-writer setup guide","prd-writer template reference","what is prd-writer","prd-writer alternative","prd-writer vs codex","prd-writer install","prd-writer for product managers","prd-writer skill framework","prd-writer for AI agents"],"zh":["prd-writer","Codex 技能框架","PRD 文档写作","结构化","要求分析","用户故事写作","优先级排序","AI 技术文档"],"ja":["prd-writer","Codex スキル フレームワーク","PRD 文書の作成","構造化","要求分析","ユーザー ストーリーの作成","優先順位の整理","AI エージェント"],"ko":["prd-writer","Codex 스킬 프레임워크","PRD 문서 작성","구조화","요구 사항 분석","사용자 스토리 작성","우선 순위 정리","AI 개발자 가이드"],"es":["prd-writer","documentos de requisitos de producto","plantillas de documentos","hooks para integración","estructura de documentos basada en fases","análisis de requisitos","creación de historias de usuario","herramientas de AI para documentos"],"fr":["prd-writer","documents de spécifications de produit","modèles de documents","hooks pour intégration","structure de documents basée sur les phases","analyse des exigences","création d''histoires d''utilisateur","outils d''IA pour documents"],"de":["prd-writer","Produktanforderungsdokumente","Vorlagen für Dokumente","Hooks für Integration","phasenbasierte Dokumentenstruktur","Anforderungsanalyse","Erstellung von Benutzerstories","KI-Tools für Dokumente"],"pt":["prd-writer","documentos de requisitos de produto","codex","especialista em documentos de requisitos","ferramentas de escrita técnica","guias de configuração","desenvolvimento de produtos"],"ru":["prd-writer","документы требований к продукту","codex","специалист по документам требований","инструменты технической escrita","настройка ИИ Агентов","разработка продуктов"],"ar":["prd-writer","توثيق متطلبات المنتج","codex","خبير في توثيق المتطلبات","أدوات الكتابة الفنية","دليل إعداد أدوات الذكاء الاصطناعي","تحديث المنتجات"]}},"owner":"tygwan","repo":"ultra-codex-init","repoPath":"tygwan/ultra-codex-init","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.585Z","topics":[],"category":"community","skillMd":{"name":"prd-writer","description":"PRD(제품 요구사항 문서) 작성 전문가. PRD 작성, 요구사항 정의, 사용자 스토리 작성 시 사용. PRD, 요구사항, 기능 정의, 사용자 스토리 키워드에 반응.","bodyPreview":"# Prd-writer Skill\n\nMigrated from the legacy agent profile. Use this as an on-demand specialist workflow.\n\n\nYou are a senior product manager specializing in PRD (Product Requirements Document) writing.\n\n## Your Role\n\n- PRD 문서 작성 및 구조화\n- 요구사항 분석 및 정의\n- 사용자 스토리 작성\n- 우선순위 정리\n\n## Document Location\n\n- PRD 저장 위치: `{project}/docs/prd/`\n- 파일명 규칙: `{feature-name}-prd.md`\n\n## Template Reference\n\nPRD 작성 시 `~/.codex/commands/dev-doc-planner/PRD-TEMPLATE.md` 템플릿을 참조하세요.\n\n## Writing Guidelines\n\n### 1. 구조화된 섹션","body":"# Prd-writer Skill\n\nMigrated from the legacy agent profile. Use this as an on-demand specialist workflow.\n\n\nYou are a senior product manager specializing in PRD (Product Requirements Document) writing.\n\n## Your Role\n\n- PRD 문서 작성 및 구조화\n- 요구사항 분석 및 정의\n- 사용자 스토리 작성\n- 우선순위 정리\n\n## Document Location\n\n- PRD 저장 위치: `{project}/docs/prd/`\n- 파일명 규칙: `{feature-name}-prd.md`\n\n## Template Reference\n\nPRD 작성 시 `~/.codex/commands/dev-doc-planner/PRD-TEMPLATE.md` 템플릿을 참조하세요.\n\n## Writing Guidelines\n\n### 1. 구조화된 섹션 작성\n각 섹션은 1,500-2,000자를 넘지 않도록 작성합니다.\n\n### 2. 명확한 요구사항 정의\n- 각 요구사항에 고유 ID 부여 (FR-001, NFR-001)\n- 우선순위 명시 (P0/P1/P2)\n- 체크리스트 형태로 상태 추적\n\n### 3. 사용자 스토리 형식\n```\nAs a {역할}\nI want to {행동}\nSo that {이유}\n```\n\n### 4. 마일스톤 정의\n담당자와 날짜를 반드시 포함합니다.\n\n## Workflow\n\n1. 기존 PRD 확인: `docs/prd/` 디렉토리 탐색\n2. 관련 코드/문서 분석: 요구사항 도출을 위한 컨텍스트 파악\n3. 템플릿 기반 PRD 작성\n4. 체크리스트 및 마일스톤 설정\n\n## Output Format\n\n항상 마크다운 형식으로 작성하며, 다음을 포함합니다:\n- 메타데이터 (작성자, 날짜, 버전, 상태)\n- 체크리스트 기반 요구사항\n- 담당자 및 날짜가 포함된 마일스톤 테이블\n"},"lastSynced":"2026-03-08T02:11:56.185Z","agentAnalysis":{"suitability":{"en":"Perfect for Technical Writing Agents specializing in product management needing structured PRD document generation.","zh":"适合专门从事产品管理、需要结构化PRD文档生成的技术写作代理","ja":"製品管理を専門とし、構造化されたPRDドキュメントの生成を必要とするテクニカルライティングエージェントに最適","ko":"제품 관리를 전문으로 하며 구조화된 PRD 문서 생성을 필요로 하는 기술 작성 에이전트에 적합","es":"Perfecto para Agentes de Escritura Técnica especializados en gestión de productos que necesitan generación de documentos PRD estructurados.","fr":"Parfait pour les agents de rédaction technique spécialisés dans la gestion de produits nécessitant une génération de documents PRD structurés.","de":"Perfekt für technische Schreibagenten, die sich auf Produktmanagement spezialisieren und eine strukturierte PRD-Dokumentgenerierung benötigen.","pt":"Perfeito para Agentes de Escrita Técnica especializados em gerenciamento de produtos que necessitam de geração de documentos PRD estruturados.","ru":"Идеально подходит для технических писателей-агентов, специализирующихся на управлении продуктами и требующих структурированного создания документов PRD.","ar":"مثالي لعميل الكتابة الفنية المتخصص في إدارة المنتجات 需 要 توثيق مستندات PRD منظم."},"recommendation":{"en":"Empowers agents to write and structure PRD documents efficiently, utilizing a high-efficiency Codex skill framework, and providing benefits such as requirements analysis, user story writing, and priority sorting, all while referencing the PRD-TEMPLATE.md template.","zh":"赋予代理高效地编写和结构PRD文档的能力，利用高效率的Codex技能框架，并提供诸如需求分析、用户故事编写和优先级排序等优点，同时参考PRD-TEMPLATE.md模板","ja":"エージェントがPRDドキュメントを効率的に作成および構造化できるようにし、高効率のCodexスキルフレームワークを利用し、要件分析、ユーザーストーリーの作成、優先順位の並び替えなどのメリットを提供し、PRD-TEMPLATE.mdテンプレートを参照","ko":"에이전트가 PRD 문서를 효율적으로 작성하고 구조화할 수 있도록 하며, 높은 효율性的 Codex 스킬 프레임워크를 활용하고, 요구사항 분석, 사용자 스토리 작성, 우선순위 정렬 등의 이점을 제공하며, PRD-TEMPLATE.md 템플릿을 참조","es":"Habilita a los agentes a escribir y estructurar documentos PRD de manera eficiente, utilizando un marco de habilidades Codex de alta eficiencia, y proporcionando beneficios como análisis de requisitos, escritura de historias de usuario y ordenación de prioridades, todo mientras se hace referencia al template PRD-TEMPLATE.md.","fr":"Permet aux agents d''écrire et de structurer des documents PRD de manière efficace, en utilisant un cadre de compétences Codex à haute efficacité, et en fournissant des avantages tels que l''analyse des exigences, la rédaction d''histoires utilisateur et le tri des priorités, le tout en référençant le modèle PRD-TEMPLATE.md.","de":"Ermöglicht es Agenten, PRD-Dokumente effizient zu schreiben und zu strukturieren, indem es ein hoch-effizientes Codex-Fähigkeitsframework nutzt und Vorteile wie Anforderungsanalyse, Benutzerstory-Schreiben und Prioritäten-Sortierung bietet, während auf das PRD-TEMPLATE.md-Template verwiesen wird.","pt":"Habilita os agentes a escrever e estruturar documentos PRD de forma eficiente, utilizando uma estrutura de habilidade Codex de alta eficiência, e fornecendo benefícios como análise de requisitos, escrita de histórias de usuário e ordenação de prioridade, tudo enquanto referencia o modelo PRD-TEMPLATE.md.","ru":"Наделяет агентов возможностью писать и структурировать документы PRD эффективно, используя высокоэффективную структуру навыков Codex, и предоставляя такие преимущества, как анализ требований, написание пользовательских историй и сортировка по приоритету, все при этом ссылаясь на шаблон PRD-TEMPLATE.md.","ar":"يمكن للعميل من كتابة وتشكيل مستندات PRD بفعالية، باستخدام إطار عمل مهارات Codex عالي الفعالية، وتقديم فوائد مثل تحليل المتطلبات، وكتابة قصة المستخدم، وفرز الأولويات، مع الإشارة إلى نموذج PRD-TEMPLATE.md."},"useCases":{"en":["Automating PRD document writing for new product features","Generating user stories and prioritizing requirements","Structuring PRD documents with standardized sections and templates"],"zh":["自动化新的产品功能的PRD文档编写","生成用户故事并优先级排序需求","使用标准化的章节和模板结构化PRD文档"],"ja":["新しい製品機能のPRDドキュメントの自動化","ユーザーストーリーの生成と要件の優先順位の並び替え","標準化されたセクションとテンプレートを使用してPRDドキュメントを構造化"],"ko":["新的 제품 기능의 PRD 문서 작성 자동화","사용자 스토리 생성 및 요구사항 우선순위 정렬","표준화된 섹션 및 템플릿을 사용하여 PRD 문서 구조화"],"es":["Automatización de la escritura de documentos PRD para nuevas características de productos","Generación de historias de usuario y priorización de requisitos","Estructuración de documentos PRD con secciones y plantillas estandarizadas"],"fr":["Automatisation de l''écriture de documents PRD pour les nouvelles fonctionnalités de produits","Génération d''histoires utilisateur et priorisation des exigences","Structuration de documents PRD avec des sections et des modèles standardisés"],"de":["Automatisierung der PRD-Dokumenterstellung für neue Produktfunktionen","Generierung von Benutzerstorys und Priorisierung von Anforderungen","Strukturierung von PRD-Dokumenten mit standardisierten Abschnitten und Vorlagen"],"pt":["Automatizar a escrita de documentos PRD para novos recursos de produtos","Gerar histórias de usuário e priorizar requisitos","Estruturar documentos PRD com seções e modelos padronizados"],"ru":["Автоматизация написания документов PRD для новых функций продукта","Генерация пользовательских историй и установление приоритетов требований","Структуризация документов PRD с использованием стандартизированных разделов и шаблонов"],"ar":["آليّ كتابة توثيق مستندات PRD لسمات المنتج الجديدة","توليد قصص المستخدم وترتيب الأولويات للمتطلبات","هيكلة مستندات PRD باستخدام أقسام ومواد معيارية"]},"limitations":{"en":["Requires access to project documentation folder","Limited to PRD document writing and structuring"],"zh":["需要访问项目文档文件夹","仅限PRD文档编写和结构化"],"ja":["プロジェクト文書フォルダへのアクセスが必要","PRDドキュメントの作成および構造化のみに限定"],"ko":["프로젝트 문서 폴더에 접근이 필요","PRD 문서 작성 및 구조화에만 제한"],"es":["Requiere acceso a la carpeta de documentación del proyecto","Limitado a la escritura y estructuración de documentos PRD"],"fr":["Nécessite un accès au dossier de documentation du projet","Limité à l''écriture et à la structuration de documents PRD"],"de":["Erfordert Zugriff auf das Projekt-Dokumentationsverzeichnis","Begrenzt auf die Erstellung und Strukturierung von PRD-Dokumenten"],"pt":["Requer acesso à pasta de documentação do projeto","Limitado à escrita e estruturação de documentos PRD"],"ru":["Требуется доступ к папке документации проекта","Ограничен только написанием и структурированием документов PRD"],"ar":["يتطلب الوصول إلى مجلد توثيق المشروع","محدود فقط بكتابة وتشكيل مستندات PRD"]},"version":4},"contentHash":"d5b8db1e170256db836d74eb17298a6599eb7dd596dbe32eb50b64944ff5084e","qualityScore":54}');
