INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tygwan/ultra-codex-init/prd-writer', 'prd-writer', 'tygwan', 'ultra-codex-init', 'community', 'prd-writer tygwan ultra-codex-init community The prd-writer skill provides a high-efficiency Codex skill framework for product managers to write and structure PRD documents. It benefits senior product managers specializing in PRD writing. prd-writer 技术文档提供高效率的 Codex 技能框架，用于快速的 PRD 文档写作和结构化 prd-writer AIエージェントは、高性能の Codex スキル フレームワークを提供し、効率的な PRD 文書の作成と構造化を実現 prd-writer 개발자 가이드는 효율적인 Codex 스킬 프레임워크를 제공하여 빠르게 PRD 문서를 작성하고 구조화할 수 있습니다 prd-writer es un marco de habilidades de alta eficiencia para la creación de documentos de requisitos de producto estructurados prd-writer est un cadre de compétences à haute efficacité pour la création de documents de spécifications de produit structurés prd-writer ist ein Rahmenwerk für Hochleistungs-Fähigkeiten zur Erstellung strukturierter Produktanforderungsdokumente O prd-writer é uma habilidade de codex que fornece um framework para escrever documentos de requisitos de produto de forma estruturada e eficiente. prd-writer - это навык codex, который предоставляет框架 для создания документов требований к продукту в структурированном и эффективном виде с помощью ИИ Агентов prd-writer هي مهارة كودكس توفر إطارًا لكتابة توثيق متطلبات المنتج بطريقة منظمة وفعالة how to use prd-writer prd-writer setup guide prd-writer template reference what is prd-writer prd-writer alternative prd-writer vs codex prd-writer install prd-writer for product managers prd-writer skill framework prd-writer for AI agents prd-writer Codex 技能框架 PRD 文档写作 结构化 要求分析 用户故事写作 优先级排序 AI 技术文档 Generates PRD documents using the ~/.codex/commands/dev-doc-planner/PRD-TEMPLATE.md template Supports structured section writing with guidelines Stores PRD documents in the {project}/docs/prd/ location Follows a file naming convention of {feature-name}-prd.md Enables priority sorting and user story writing Analyzes and defines requirements for PRD documents prd-writer is a Codex skill framework that enables efficient PRD writing, with 58 ready-to-use skills, hooks, and phase-based development templates.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JustineDevs/Fyleris/blueprintkit-plugin', 'community', 'JustineDevs', 'Fyleris', 'JustineDevs/Fyleris', 'blueprintkit-plugin', 0, 0, 54, '2026-03-08T01:57:15.588Z', '2026-03-08T02:12:00.330Z', '7a91f6a63de4e9b6235458b6f3bbba81dc7b2f2076c62b4d39f4a714b8007613', '{"id":"JustineDevs/Fyleris/blueprintkit-plugin","name":"blueprintkit-plugin","description":{"en":"The blueprintkit-plugin provides a secure home and control plane for AI assistants, offering small teams and indie founders a production-ready Cloud Home. It includes the complete BlueprintKit framework with 14 planning sections and 9 specialized Claude Skills.","zh":"BlueprintKit Plugin 是一个安全的生产环境，用于构建和部署 AI 助手，提供了 14 个规划部分和 9 个专业的 Claude 技能","ja":"BlueprintKit Plugin は、AI アシスタントの構築とデプロイをサポートする、セキュアなクラウドホームです。14 の計画セクションと 9 の専門の Claude スキルを提供します","ko":"BlueprintKit Plugin은 AI 에이전트를 구축하고 배포할 수 있는 보안 클라우드 홈을 제공합니다. 14개의 계획 섹션과 9개의 전문 Claude 스킬을 제공합니다","es":"El plugin blueprintkit proporciona un marco de planificación completo con 14 secciones y 9 habilidades especializadas para agentes de IA","fr":"Le plugin blueprintkit fournit un cadre de planification complet avec 14 sections et 9 compétences spécialisées pour les agents d''IA","de":"Das blueprintkit-Plugin bietet einen umfassenden Planungsrahmen mit 14 Abschnitten und 9 spezialisierten Fähigkeiten für KI-Agents","pt":"O blueprintkit-plugin oferece uma estrutura de planejamento completa com 14 seções e 9 habilidades especializadas para criar um lar de nuvem seguro para agentes de IA","ru":"Плагин blueprintkit-plugin предоставляет полную структуру планирования с 14 разделами и 9 специализированными навыками для создания безопасного облака для ИИ Агентов","ar":"یوفر plugin blueprintkit هيكل تخطيط كامل مع 14 قسم و 9 مهارات متخصصة لإنشاء منزل سحابي آمن للوكلاء الذكاء الاصطناعي"},"seo":{"title":{"en":"blueprintkit-plugin: Unified Interface for AI Agents | AI...","zh":"BlueprintKit Plugin 安装指南 - AI エージェント的生产环境","ja":"BlueprintKit Plugin セットアップガイド - AIエージェントのクラウドホーム","ko":"BlueprintKit Plugin 설정 가이드 - AI 에이전트를 위한 클라우드 홈","es":"Guía de configuración de blueprintkit-plugin para agentes...","fr":"Guide d''installation de blueprintkit-plugin pour les agen...","de":"Einrichtungsanleitung für blueprintkit-plugin für KI-Agents","pt":"Guia de Configuração do blueprintkit-plugin para Ferramen...","ru":"Настройка плагина blueprintkit-plugin для ИИ Агентов","ar":"دليل إعداد plugin blueprintkit للوكلاء الذكاء الاصطناعي"},"description":{"en":"Discover how blueprintkit-plugin simplifies AI assistant deployment across Slack, Discord, and more. Get started with a production-ready Cloud Home today!","zh":"BlueprintKit Plugin 提供了一个安全的生产环境，用于构建和部署 AI 助手，支持 Slack、Discord、WhatsApp、Telegram 和 WebChat","ja":"BlueprintKit Plugin は、Slack、Discord、WhatsApp、Telegram、WebChat での AI アシスタントの構築とデプロイをサポートする、セキュアなクラウドホームです","ko":"BlueprintKit Plugin은 Slack, Discord, WhatsApp, Telegram, WebChat에서 AI 에이전트를 구축하고 배포할 수 있는 보안 클라우드 홈을 제공합니다","es":"Aprende a configurar el plugin blueprintkit para crear un hogar en la nube para tus agentes de IA en Slack, Discord y más","fr":"Découvrez comment configurer le plugin blueprintkit pour créer un cloud home pour vos agents d''IA sur Slack, Discord et plus","de":"Erfahren Sie, wie Sie das blueprintkit-Plugin konfigurieren, um einen Cloud-Home für Ihre KI-Agents in Slack, Discord und mehr zu erstellen","pt":"Aprenda a configurar o blueprintkit-plugin para criar um lar de nuvem seguro para seus agentes de IA em plataformas como Slack, Discord e WebChat","ru":"Узнайте, как настроить плагин blueprintkit-plugin для создания безопасного облака для ИИ Агентов в платформах như Slack, Discord и WebChat","ar":"تعرف على كيفية إعداد plugin blueprintkit لإنشاء منزل سحابي آمن للوكلاء الذكاء الاصطناعي على منصات مثل Slack و Discord و WebChat"},"definition":{"en":"blueprintkit-plugin is a secure and unified interface for AI assistants, providing a complete planning framework with 14 comprehensive planning sections and 9 specialized skills.","zh":"BlueprintKit Plugin 是一个用于构建和部署 AI 助手的生产环境，提供了安全的クラウドホーム","ja":"BlueprintKit Plugin は、AI アシスタントの構築とデプロイをサポートする、セキュアなクラウドホームです","ko":"BlueprintKit Plugin은 AI 에이전트를 구축하고 배포할 수 있는 보안 클라우드 홈을 제공합니다","es":"El plugin blueprintkit es un marco de planificación para agentes de IA que ofrece un hogar en la nube para la planificación y ejecución de proyectos","fr":"Le plugin blueprintkit est un cadre de planification pour les agents d''IA qui offre un cloud home pour la planification et l''exécution de projets","de":"Das blueprintkit-Plugin ist ein Planungsrahmen für KI-Agents, der ein Cloud-Home für die Planung und Ausführung von Projekten bietet","pt":"O blueprintkit-plugin é um plugin que fornece uma estrutura de planejamento completa para criar um lar de nuvem seguro para agentes de IA","ru":"Плагин blueprintkit-plugin - это плагин, который предоставляет полную структуру планирования для создания безопасного облака для ИИ Агентов","ar":"plugin blueprintkit هو ملحق يوفر هيكل تخطيط كامل لإنشاء منزل سحابي آمن للوكلاء الذكاء الاصطناعي"},"features":{"en":["Includes the complete BlueprintKit framework with 14 planning sections","Provides 9 specialized Claude Skills for project lifecycle management","Offers a unified interface for AI assistants across Slack, Discord, WhatsApp, Telegram, and WebChat","Automatically includes all planning templates and execution skills in a single package","Supports production-ready Cloud Home for small teams and indie founders"],"zh":["提供 14 个规划部分","提供 9 个专业的 Claude 技能","支持 Slack、Discord、WhatsApp、Telegram 和 WebChat","自动包括 BlueprintKit 框架","提供统一的接口"],"ja":["14 の計画セクションを提供","9 の専門の Claude スキルを提供","Slack、Discord、WhatsApp、Telegram、WebChat をサポート","BlueprintKit フレームワークを自動的に含む","統一されたインターフェースを提供"],"ko":["14개의 계획 섹션을 제공","9개의 전문 Claude 스킬을 제공","Slack, Discord, WhatsApp, Telegram, WebChat을 지원","BlueprintKit 프레임워크를 자동으로 포함","통일된 인터페이스를 제공"],"es":["Marco de planificación completo con 14 secciones","9 habilidades especializadas para agentes de IA","Compatibilidad con Slack, Discord, WhatsApp, Telegram y WebChat","Instalación automática del marco de planificación completo","Acceso a plantillas de planificación y habilidades de ejecución"],"fr":["Cadre de planification complet avec 14 sections","9 compétences spécialisées pour les agents d''IA","Compatibilité avec Slack, Discord, WhatsApp, Telegram et WebChat","Installation automatique du cadre de planification complet","Accès à des modèles de planification et des compétences d''exécution"],"de":["Umfassender Planungsrahmen mit 14 Abschnitten","9 spezialisierte Fähigkeiten für KI-Agents","Kompatibilität mit Slack, Discord, WhatsApp, Telegram und WebChat","Automatische Installation des umfassenden Planungsrahmens","Zugriff auf Planungsvorlagen und Ausführungsfähigkeiten"],"pt":["Estrutura de planejamento completa com 14 seções","9 habilidades especializadas para agentes de IA","Integração com plataformas como Slack, Discord e WebChat","Criação de um lar de nuvem seguro para agentes de IA","Suporte a equipes pequenas e fundadores independentes"],"ru":["Полная структура планирования с 14 разделами","9 специализированных навыков для ИИ Агентов","Интеграция с платформами như Slack, Discord и WebChat","Создание безопасного облака для ИИ Агентов","Поддержка небольших команд и независимых основателей"],"ar":["هيكل تخطيط كامل مع 14 قسم","9 مهارات متخصصة للوكلاء الذكاء الاصطناعي","التكامل مع منصات مثل Slack و Discord و WebChat","إنشاء منزل سحابي آمن للوكلاء الذكاء الاصطناعي","دعم الفرق الصغيرة والمؤسسين المستقلين"]},"keywords":{"en":["how to use blueprintkit-plugin","blueprintkit-plugin alternative","blueprintkit-plugin setup guide","what is blueprintkit-plugin","blueprintkit-plugin vs competitors","blueprintkit-plugin install","blueprintkit-plugin for AI agents","blueprintkit-plugin Cloud Home","blueprintkit-plugin project planning"],"zh":["AI エージェント","BlueprintKit Plugin","生产环境","クラウドホーム","AI 助手","Slack","Discord","WhatsApp","Telegram","WebChat"],"ja":["AIエージェント","BlueprintKit Plugin","クラウドホーム","AI アシスタント","Slack","Discord","WhatsApp","Telegram","WebChat"],"ko":["AI 에이전트","BlueprintKit Plugin","클라우드 홈","AI 助手","Slack","Discord","WhatsApp","Telegram","WebChat"],"es":["agentes de IA","plugin blueprintkit","planificación de proyectos","hogar en la nube","Slack","Discord","WhatsApp","Telegram","WebChat"],"fr":["agents d''IA","plugin blueprintkit","planification de projets","cloud home","Slack","Discord","WhatsApp","Telegram","WebChat"],"de":["KI-Agents","blueprintkit-Plugin","Projektplanung","Cloud-Home","Slack","Discord","WhatsApp","Telegram","WebChat"],"pt":["blueprintkit-plugin","Ferramentas de IA","Agentes de IA","Lar de nuvem seguro","Estrutura de planejamento","Habilidades especializadas","Integração com plataformas","Equipes pequenas","Fundadores independentes"],"ru":["blueprintkit-plugin","ИИ Агенты","ИИ инструменты","Безопасное облако","Структура планирования","Специализированные навыки","Интеграция с платформами","Небольшие команды","Независимые основатели"],"ar":["blueprintkit-plugin","الوكلاء الذكاء الاصطناعي","أدوات الذكاء الاصطناعي","منزل سحابي آمن","هيكل تخطيط","مهارات متخصصة","التكامل مع منصات","الفرق الصغيرة","المؤسسين المستقلين"]}},"owner":"JustineDevs","repo":"Fyleris","repoPath":"JustineDevs/Fyleris","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.588Z","topics":[],"category":"community","skillMd":{"name":"blueprintkit-plugin","description":"BlueprintKit Plugin - Complete planning framework automatically including all 14 planning sections (.claude/skills/blueprintkit/planning/0-Master-Index.md through .claude/skills/blueprintkit/planning/13-Lessons-Learned-Continuous-Improvement.md) plus all 9 Claude Skills (tech-stack-selector, architecture-decisions, code-standards-enforcer, ci-cd-pipeline-builder, agile-executor, project-risk-identifier, automation-orchestrator, webapp-testing, web-artifacts-builder). When installed, all files are immediately available.","bodyPreview":"# BlueprintKit Plugin\n\nThis plugin automatically includes the complete BlueprintKit framework: all 14 planning sections plus all 9 specialized Claude Skills. When installed, all planning templates and execution skills are immediately available in a single package.\n\n## Overview\n\nThe Project Planning Starter Pack Plugin provides a unified interface to a complete planning framework with 14 comprehensive planning sections plus nine specialized skills that cover the complete project lifecycle from pl","body":"# BlueprintKit Plugin\n\nThis plugin automatically includes the complete BlueprintKit framework: all 14 planning sections plus all 9 specialized Claude Skills. When installed, all planning templates and execution skills are immediately available in a single package.\n\n## Overview\n\nThe Project Planning Starter Pack Plugin provides a unified interface to a complete planning framework with 14 comprehensive planning sections plus nine specialized skills that cover the complete project lifecycle from planning through deployment and continuous improvement.\n\n## Complete Planning Framework\n\nThis plugin includes 14 comprehensive planning sections:\n\n1. **Master Index** - Complete navigation guide and overview\n2. **Executive Summary** - Vision, problem statement, expected outcomes\n3. **Objectives & Success Metrics** - Quantified success criteria and KPIs\n4. **Scope Definition** - What''s in/out, constraints, assumptions\n5. **System Architecture & Design** - Technical blueprint and architecture decisions\n6. **Technical Execution Workflow** - Complete technical implementation guide\n7. **Project Phases & Timeline** - Phases, milestones, and timeline\n8. **Resource Planning** - Team structure, skills, budget allocation\n9. **Risk Management** - Risk identification, mitigation, contingency planning\n10. **Execution Strategy** - Daily execution, ceremonies, quality assurance\n11. **Monitoring & Reporting** - Metrics tracking and status reporting\n12. **ROI & Value Realization** - Financial projections and value tracking\n13. **Governance & Decision-Making** - Decision authority and escalation procedures\n14. **Lessons Learned & Continuous Improvement** - Learning capture and process improvement\n\n## Bundled Skills\n\nThis plugin also includes nine specialized execution skills:\n\n1. **tech-stack-selector** - Technology decision framework with structured recommendations\n2. **architecture-decisions** - Architecture Decision Records (ADRs) documentation\n3. **code-standards-enforcer** - Comprehensive code review checklists and quality standards\n4. **ci-cd-pipeline-builder** - GitHub Actions workflow templates and automation\n5. **agile-executor** - Sprint planning, retrospectives, and Agile ceremony facilitation\n6. **project-risk-identifier** - Risk assessment frameworks and mitigation strategies\n7. **automation-orchestrator** - Script orchestration for setup, validation, and deployment\n8. **webapp-testing** - Playwright-based web application testing toolkit\n9. **web-artifacts-builder** - React + TypeScript artifact creation with shadcn/ui\n\n## Installation\n\n### For Claude Code Users\n\n1. Clone or copy this repository to your local machine\n2. Ensure the `.claude-plugin/` directory is in your project root\n3. Claude Code will automatically detect and load the plugin\n\n### For Skills.sh Users\n\nInstall BlueprintKit from skills.sh:\n\n```bash\nnpx skills add JustineDevs/blueprintkit\n```\n\nThis automatically installs:\n- All 14 planning sections from `.claude/skills/blueprintkit/planning/` directory\n- All 9 Claude Skills from `.claude/skills/blueprintkit/` directory\n- Complete framework ready to use immediately\n\n## Usage\n\n### Individual Skill Access\n\nEach skill in `.claude/skills/blueprintkit/` can be accessed individually. Skills auto-activate based on natural language queries:\n\n- \"What tech stack should we use?\" → tech-stack-selector\n- \"Create an ADR\" → architecture-decisions\n- \"Code review checklist\" → code-standards-enforcer\n- \"Setup CI/CD\" → ci-cd-pipeline-builder\n- \"Plan sprint\" → agile-executor\n- \"Identify risks\" → project-risk-identifier\n- \"Set up Claude skills\" → automation-orchestrator\n- \"Test web application\" → webapp-testing\n- \"Build web artifact\" → web-artifacts-builder\n\n### Plugin-Level Usage\n\nThe plugin provides unified access to all skills. Ask Claude:\n\n- \"Help me plan this project\" - Activates multiple relevant skills\n- \"Set up project automation\" - Uses automation-orchestrator and related skills\n- \"Review project quality\" - Combines code-standards-enforcer with risk management\n\n## Automatic File Access\n\nWhen BlueprintKit is installed, the following files are automatically available:\n\n### Planning Sections (All 14 Files)\n- `.claude/skills/blueprintkit/planning/0-Master-Index.md` - Complete navigation guide\n- `.claude/skills/blueprintkit/planning/1-Executive-Summary.md` - Vision and problem statement\n- `.claude/skills/blueprintkit/planning/2-Objectives-Success-Metrics.md` - Success criteria and KPIs\n- `.claude/skills/blueprintkit/planning/3-Scope-Definition.md` - Project boundaries\n- `.claude/skills/blueprintkit/planning/4-System-Architecture-Design.md` - Technical blueprint\n- `.claude/skills/blueprintkit/planning/5-Technical-Execution-Workflow.md` - Implementation guide\n- `.claude/skills/blueprintkit/planning/6-Project-Phases-Timeline.md` - Phases and milestones\n- `.claude/skills/blueprintkit/planning/7-Resource-Planning.md` - Team and budget\n- `.claude/skills/blueprintkit/planning/8-Risk-Management.md` - Risk identification and mitigation\n- `.claude/skills/blueprintkit/planning/9-Execution-Strategy.md` - Daily execution and ceremonies\n- `.claude/skills/blueprintkit/planning/10-Monitoring-Reporting.md` - Metrics and reporting\n- `.claude/skills/blueprintkit/planning/11-ROI-Value-Realization.md` - Financial projections\n- `.claude/skills/blueprintkit/planning/12-Governance-Decision-Making.md` - Decision authority\n- `.claude/skills/blueprintkit/planning/13-Lessons-Learned-Continuous-Improvement.md` - Learning capture\n\n### Claude Skills (All 9 Skills)\n- `.claude/skills/blueprintkit/tech-stack-selector/SKILL-INTERNAL.md` - Technology decisions\n- `.claude/skills/blueprintkit/architecture-decisions/SKILL-INTERNAL.md` - ADR documentation\n- `.claude/skills/blueprintkit/code-standards-enforcer/SKILL-INTERNAL.md` - Code quality\n- `.claude/skills/blueprintkit/ci-cd-pipeline-builder/SKILL-INTERNAL.md` - CI/CD automation\n- `.claude/skills/blueprintkit/agile-executor/SKILL-INTERNAL.md` - Agile ceremonies\n- `.claude/skills/blueprintkit/project-risk-identifier/SKILL-INTERNAL.md` - Risk assessment\n- `.claude/skills/blueprintkit/automation-orchestrator/SKILL-INTERNAL.md` - Script orchestration\n- `.claude/skills/blueprintkit/webapp-testing/SKILL-INTERNAL.md` - Web testing toolkit\n- `.claude/skills/blueprintkit/web-artifacts-builder/SKILL-INTERNAL.md` - Artifact creation\n\nEach skill directory contains:\n- `SKILL-INTERNAL.md` - Internal skill definition (not detected by skills.sh, only accessible via blueprintkit)\n- `references/` - Detailed documentation and templates\n- `scripts/` - Utility scripts for automation\n\n## Integration with Project Planning\n\nThis plugin integrates with the Project Planning Starter Pack''s comprehensive planning framework:\n\n- **Planning Sections** (`.claude/skills/blueprintkit/planning/`) - 14 planning templates\n- **Technical Documentation** (`docs/reference/`) - Architecture and technical summaries\n- **Configuration Files** - CI/CD, linting, testing configurations\n- **Ready-to-Build Structure** - Organized application code directories\n\n## Examples\n\n### Example 1: Complete Project Setup\n\n**User**: \"Help me set up a new TypeScript project with CI/CD\"\n\n**Plugin Response**:\n1. Activates tech-stack-selector for technology recommendations\n2. Activates ci-cd-pipeline-builder for GitHub Actions setup\n3. Activates code-standards-enforcer for quality gates\n4. Activates automation-orchestrator for script setup\n5. Provides integrated workflow combining all skills\n\n### Example 2: Architecture Documentation\n\n**User**: \"Document our database choice and set up testing\"\n\n**Plugin Response**:\n1. Activates architecture-decisions for ADR creation\n2. Activates webapp-testing for test setup\n3. Links to planning sections for context\n4. Provides integrated documentation workflow\n\n## Configuration\n\nThe plugin is configured via `.claude-plugin/plugin.mdc` which defines:\n- Activation rules\n- File patterns to monitor\n- Related documentation references\n- Plugin metadata\n\n## Contributing\n\nTo contribute to this plugin:\n\n1. Review individual skill definitions in `.claude/skills/blueprintkit/`\n2. Follow the skill creation guidelines in `skills-reference/template/SKILL.md`\n3. Update this plugin''s SKILL.md when adding new skills\n4. Test plugin loading in Claude Code\n5. Submit improvements via pull request\n\n## Related Documentation\n\n- [Main README](../README.md) - Project overview\n- [Claude Skills README](../.claude/README.md) - Skills documentation\n- [Planning Framework](../.claude/skills/blueprintkit/planning/) - Complete planning templates\n- [Technical Summary](../docs/reference/TECHNICAL-SUMMARY.md) - Technical reference\n\n## License\n\nMIT License - See [LICENSE](../LICENSE) file for details.\n\n"},"lastSynced":"2026-03-08T02:12:00.330Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Assistant Agents needing a comprehensive project planning framework with Cloud Home capabilities.","zh":"非常适合需要全面项目规划框架和Cloud Home功能的AI助手代理。","ja":"AIアシスタントエージェントが包括的なプロジェクト計画フレームワークとCloud Home機能を必要とする場合に最適です。","ko":"전체적인 프로젝트 계획 프레임워크와 Cloud Home 기능이 필요한 AI 보조 에이전트 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Asistentes de IA que necesitan un marco de planificación de proyectos integral con capacidades de Cloud Home.","fr":"Parfait pour les Agents d''Assistants d''IA ayant besoin d''un cadre de planification de projet complet avec des capacités de Cloud Home.","de":"Perfekt für AI-Assistenten-Agenten, die ein umfassendes Projektplanungsframework mit Cloud-Home-Funktionen benötigen.","pt":"Perfeito para Agentes de Assistente de IA que precisam de um framework de planejamento de projeto abrangente com capacidades de Cloud Home.","ru":"Идеально для агентов-ассистентов ИИ, которым необходим комплексный фреймворк планирования проектов с возможностями Cloud Home.","ar":"مثالي لعميل مساعد ذكاء اصطناعي يحتاج إلى إطار شاملي لتخطيط المشروع مع khảيات Cloud Home."},"recommendation":{"en":"Empowers agents to manage projects seamlessly with 14 planning sections and 9 specialized Claude Skills, leveraging the complete BlueprintKit framework for unified project lifecycle control, including planning templates and execution skills, all via a secure Cloud Home interface.","zh":"赋予代理管理项目的能力，使用14个规划部分和9个专门的Claude Skills，利用完整的BlueprintKit框架进行统一的项目生命周期控制，包括规划模板和执行技能，所有这些都通过安全的Cloud Home接口实现。","ja":"エージェントが14の計画セクションと9つの専門のClaude Skillsを使用してプロジェクトをシームレスに管理できるようにします。完全なBlueprintKitフレームワークを使用して、プロジェクトのライフサイクルを統一的に制御できます。計画テンプレートや実行スキルなど、すべての機能が安全なCloud Homeインターフェイスを通じて提供されます。","ko":"에이전트가 14개의 계획 섹션과 9개의 전문 Claude Skills를 사용하여 프로젝트를 무리없이 관리할 수 있도록 합니다. 완전한 BlueprintKit 프레임워크를 사용하여 프로젝트 생명주기를 통일된 방식으로 제어할 수 있습니다. 계획 템플릿 및 실행 스킬을 포함하여 모든 기능이 안전한 Cloud Home 인터페이스를 통해 제공됩니다.","es":"Habilita a los agentes a gestionar proyectos de manera fluida con 14 secciones de planificación y 9 habilidades especializadas de Claude, aprovechando el marco de trabajo completo de BlueprintKit para el control unificado del ciclo de vida del proyecto, incluyendo plantillas de planificación y habilidades de ejecución, todo a través de una interfaz de Cloud Home segura.","fr":"Permet aux agents de gérer les projets de manière fluide avec 14 sections de planification et 9 compétences spécialisées de Claude, en exploitant le cadre de travail complet de BlueprintKit pour le contrôle unifié du cycle de vie du projet, y compris des modèles de planification et des compétences d''exécution, le tout via une interface Cloud Home sécurisée.","de":"Ermöglicht es Agenten, Projekte nahtlos zu verwalten, mit 14 Planungsabschnitten und 9 spezialisierten Claude-Fähigkeiten, die das vollständige BlueprintKit-Framework für eine einheitliche Projekt-Lebenszyklus-Kontrolle nutzen, einschließlich Planungsvorlagen und Ausführungsfähigkeiten, alles über eine sichere Cloud-Home-Schnittstelle.","pt":"Habilita agentes a gerenciar projetos de forma transparente com 14 seções de planejamento e 9 habilidades especializadas Claude, aproveitando o framework BlueprintKit completo para controle unificado do ciclo de vida do projeto, incluindo modelos de planejamento e habilidades de execução, tudo por meio de uma interface Cloud Home segura.","ru":"Наделяет агентов возможностью управлять проектами без проблем с 14 разделами планирования и 9 специализированными навыками Claude, используя полный фреймворк BlueprintKit для единого контроля жизненного цикла проекта, включая шаблоны планирования и навыки выполнения, все через защищенный интерфейс Cloud Home.","ar":"يمنح الوكلاء القدرة على إدارة المشاريع بسلاسة مع 14 قسمًا للتخطيط و 9 مهارات مخصصة من كلود، مستفيدًا من إطار العمل الكامل BlueprintKit للسيطرة الموحدة على دورة حياة المشروع، بما في ذلك قوالب التخطيط ومهارات التنفيذ، كل ذلك من خلال واجهة Cloud Home آمنة."},"useCases":{"en":["Automating project planning workflows","Generating comprehensive project plans with 14 planning sections","Executing projects with 9 specialized Claude Skills"],"zh":["自动化项目规划工作流程","生成包含14个规划部分的综合项目计划","使用9个专门的Claude Skills执行项目"],"ja":["プロジェクト計画ワークフローの自動化","14の計画セクションを含む包括的なプロジェクト計画の生成","9つの専門のClaude Skillsを使用したプロジェクトの実行"],"ko":["프로젝트 계획 워크플로 자동화","14개의 계획 섹션을 포함한 전체적인 프로젝트 계획 생성","9개의 전문 Claude Skills를 사용한 프로젝트 실행"],"es":["Automatización de flujos de trabajo de planificación de proyectos","Generación de planes de proyecto integrales con 14 secciones de planificación","Ejecución de proyectos con 9 habilidades especializadas de Claude"],"fr":["Automatisation des flux de travail de planification de projets","Génération de plans de projets complets avec 14 sections de planification","Exécution de projets avec 9 compétences spécialisées de Claude"],"de":["Automatisierung von Projektplanungs-Workflows","Erzeugung von umfassenden Projektplänen mit 14 Planungsabschnitten","Ausführung von Projekten mit 9 spezialisierten Claude-Fähigkeiten"],"pt":["Automar fluxos de trabalho de planejamento de projetos","Gerar planos de projeto abrangentes com 14 seções de planejamento","Executar projetos com 9 habilidades especializadas Claude"],"ru":["Автоматизировать рабочие процессы планирования проектов","Генерировать комплексные планы проектов с 14 разделами планирования","Выполнять проекты с 9 специализированными навыками Claude"],"ar":["تحويل سير عمل تخطيط المشروع إلى أتمتيكية","توليد خطط مشروع شاملة مع 14 قسمًا للتخطيط","تنفيذ المشاريع مع 9 مهارات مخصصة من كلود"]},"limitations":{"en":["Requires BlueprintKit framework compatibility","Cloud Home setup necessary"],"zh":["需要BlueprintKit框架兼容性","需要Cloud Home设置"],"ja":["BlueprintKitフレームワークの互換性が必要","Cloud Homeの設定が必要"],"ko":["BlueprintKit 프레임워크 호환성이 필요함","Cloud Home 설정이 필요함"],"es":["Se requiere compatibilidad con el marco de trabajo BlueprintKit","Configuración de Cloud Home necesaria"],"fr":["Compatibilité avec le cadre de travail BlueprintKit requise","Configuration de Cloud Home nécessaire"],"de":["Kompatibilität mit dem BlueprintKit-Framework erforderlich","Cloud-Home-Setup erforderlich"],"pt":["Requer compatibilidade com o framework BlueprintKit","Configuração de Cloud Home necessária"],"ru":["Требуется совместимость с фреймворком BlueprintKit","Необходимо настроить Cloud Home"],"ar":["يتطلب توافقًا مع إطار العمل BlueprintKit","يتطلب إعداد Cloud Home"]},"version":4},"contentHash":"7a91f6a63de4e9b6235458b6f3bbba81dc7b2f2076c62b4d39f4a714b8007613","qualityScore":54}');
