INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('JustineDevs/Fyleris/blueprintkit-plugin', 'blueprintkit-plugin', 'JustineDevs', 'Fyleris', 'community', 'blueprintkit-plugin JustineDevs Fyleris community The blueprintkit-plugin provides a secure home and control plane for AI assistants, offering small teams and indie founders a production-ready Cloud Home. It includes the complete BlueprintKit framework with 14 planning sections and 9 specialized Claude Skills. BlueprintKit Plugin 是一个安全的生产环境，用于构建和部署 AI 助手，提供了 14 个规划部分和 9 个专业的 Claude 技能 BlueprintKit Plugin は、AI アシスタントの構築とデプロイをサポートする、セキュアなクラウドホームです。14 の計画セクションと 9 の専門の Claude スキルを提供します BlueprintKit Plugin은 AI 에이전트를 구축하고 배포할 수 있는 보안 클라우드 홈을 제공합니다. 14개의 계획 섹션과 9개의 전문 Claude 스킬을 제공합니다 El plugin blueprintkit proporciona un marco de planificación completo con 14 secciones y 9 habilidades especializadas para agentes de IA Le plugin blueprintkit fournit un cadre de planification complet avec 14 sections et 9 compétences spécialisées pour les agents d''IA Das blueprintkit-Plugin bietet einen umfassenden Planungsrahmen mit 14 Abschnitten und 9 spezialisierten Fähigkeiten für KI-Agents O blueprintkit-plugin oferece uma estrutura de planejamento completa com 14 seções e 9 habilidades especializadas para criar um lar de nuvem seguro para agentes de IA Плагин blueprintkit-plugin предоставляет полную структуру планирования с 14 разделами и 9 специализированными навыками для создания безопасного облака для ИИ Агентов یوفر plugin blueprintkit هيكل تخطيط كامل مع 14 قسم و 9 مهارات متخصصة لإنشاء منزل سحابي آمن للوكلاء الذكاء الاصطناعي how to use blueprintkit-plugin blueprintkit-plugin alternative blueprintkit-plugin setup guide what is blueprintkit-plugin blueprintkit-plugin vs competitors blueprintkit-plugin install blueprintkit-plugin for AI agents blueprintkit-plugin Cloud Home blueprintkit-plugin project planning AI エージェント BlueprintKit Plugin 生产环境 クラウドホーム AI 助手 Slack Discord WhatsApp Telegram WebChat Includes the complete BlueprintKit framework with 14 planning sections Provides 9 specialized Claude Skills for project lifecycle management Offers a unified interface for AI assistants across Slack, Discord, WhatsApp, Telegram, and WebChat Automatically includes all planning templates and execution skills in a single package Supports production-ready Cloud Home for small teams and indie founders blueprintkit-plugin is a secure and unified interface for AI assistants, providing a complete planning framework with 14 comprehensive planning sections and 9 specialized skills.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pnils08/GodWorld/letters-desk', 'community', 'pnils08', 'GodWorld', 'pnils08/GodWorld', 'letters-desk', 0, 0, 54, '2026-03-08T01:57:15.580Z', '2026-03-08T02:13:05.194Z', 'd0eeb99e05c5cf12b450f24ce87e141c1da82baf0caebab37d85669cabf5dc7f', '{"id":"pnils08/GodWorld/letters-desk","name":"letters-desk","description":{"en":"The letters-desk skill enables AI agents to simulate worlds by writing to specific output directories and leveraging agent memory for tracking and naming conventions. This skill benefits developers working on complex simulation projects.","zh":"letters-desk 技术是世界模拟的核心组件，通过输出目录和内存管理实现高效的模拟","ja":"letters-desk 技術はワールドシミュレーションの核心コンポーネントであり、出力ディレクトリとメモリ管理を通じて効率的なシミュレーションを実現します","ko":"letters-desk 기술은 월드 시뮬레이션의 핵심 구성 요소로 출력 디렉토리와 메모리 관리를 통해 효율적인 시뮬레이션을 구현합니다.","es":"Letters-desk es una herramienta de simulación de mundo que utiliza Markdown y memoria de agente para crear entornos personalizados. Configúrala para empezar a simular","fr":"Letters-desk est un outil de simulation de monde qui utilise Markdown et la mémoire d''agent pour créer des environnements personnalisés. Installez-le pour commencer à simuler","de":"Letters-desk ist ein Weltsimulationstool, das Markdown und Agenten-Speicher verwendet, um benutzerdefinierte Umgebungen zu erstellen. Richten Sie es ein, um mit der Simulation zu beginnen","pt":"O letters-desk é uma ferramenta de simulação de mundo que permite a criação de resultados personalizados. Aprenda a configurá-lo para atender às suas necessidades.","ru":"ИИ Агенты letters-desk - это инструмент симуляции мира, который позволяет создавать индивидуальные результаты. Узнайте, как его настроить для решения ваших задач.","ar":"letters-desk هو أداة محاكاة العالم التي تمكنك من إنشاء نتائج مخصصة. تعلم كيفية إعداده لتناسب احتياجاتك"},"seo":{"title":{"en":"letters-desk: World Simulation Setup Guide | AI Agent Skill","zh":"letters-desk 技术指南：世界模拟设置","ja":"letters-desk セットアップガイド：ワールドシミュレーション","ko":"letters-desk 설정 가이드: 월드 시뮬레이션","es":"Guía de configuración de letters-desk para simulación de ...","fr":"Guide d''installation de letters-desk pour la simulation d...","de":"Einrichtungsleitfaden für letters-desk zur Weltsimulation","pt":"Guia de Configuração letters-desk: Simulação de Mundo com...","ru":"ИИ Агенты letters-desk: Руководство по Настройке Симуляци...","ar":"دليل إعداد letters-desk: محاكاة العالم باستخدام مخرجات مخصصة"},"description":{"en":"Discover how to harness the power of letters-desk for world simulation. Learn to write to output/desk-output/letters_c{XX}.md and leverage agent memory for o...","zh":"了解 letters-desk 技术的详细信息，包括输出目录、内存管理和命名约定，实现高效的世界模拟","ja":"letters-desk 技術の詳細を学び、出力ディレクトリ、メモリ管理、命名規約を理解して効率的なワールドシミュレーションを実現する","ko":"letters-desk 기술의 자세한 정보를 알아보세요. 출력 디렉토리, 메모리 관리, 명명 규칙 등을 포함하여 효율적인 월드 시뮬레이션을 구현합니다.","es":"Aprende a configurar letters-desk para crear simulaciones de mundo personalizadas con tecnologías como Markdown y memoria de agente","fr":"Découvrez comment installer letters-desk pour créer des simulations de monde personnalisées avec des technologies comme Markdown et mémoire d''agent","de":"Erfahren Sie, wie Sie letters-desk einrichten, um benutzerdefinierte Weltsimulationen mit Technologien wie Markdown und Agenten-Speicher zu erstellen","pt":"Aprenda a configurar o letters-desk para simulações de mundo personalizadas. Descubra como usar a saída do diretório para criar resultados únicos.","ru":"Узнайте, как настроить ИИ Агенты letters-desk для симуляции мира. Откройте для себя, как использовать вывод каталога для создания индивидуальных результатов.","ar":"تعلم كيفية إعداد letters-desk لمحاكاة العالم المخصصة. اكتشف كيفية استخدام مخرجات الدليل لإنشاء نتائج فريدة"},"definition":{"en":"letters-desk is a world simulation skill that utilizes output directories and agent memory to generate and track simulation data.","zh":"letters-desk 是一种用于世界模拟的技术，通过特定的输出目录和内存管理实现模拟","ja":"letters-desk はワールドシミュレーション用の技術であり、特定の出力ディレクトリとメモリ管理を通じてシミュレーションを実現します","ko":"letters-desk는 월드 시뮬레이션을 위한 기술로 특정 출력 디렉토리와 메모리 관리를 통해 시뮬레이션을 구현합니다.","es":"Letters-desk es una herramienta de simulación de mundo que utiliza tecnologías como Markdown y memoria de agente","fr":"Letters-desk est un outil de simulation de monde qui utilise des technologies comme Markdown et mémoire d''agent","de":"Letters-desk ist ein Weltsimulationstool, das Technologien wie Markdown und Agenten-Speicher verwendet","pt":"O letters-desk é uma ferramenta de simulação de mundo que utiliza saída personalizada para criar resultados únicos.","ru":"ИИ Агенты letters-desk - это инструмент симуляции мира, который использует индивидуальный вывод для создания уникальных результатов.","ar":"letters-desk هو أداة محاكاة العالم التي تستخدم مخرجات مخصصة لإنشاء نتائج فريدة"},"features":{"en":["Writes simulation output to `output/desk-output/letters_c{XX}.md` files","Utilizes agent memory stored in `.claude/agent-memory/letters-desk/MEMORY.md` for tracking and naming conventions","Supports glob pattern `letters_c*.md` for reviewing past simulation editions","Enforces mandatory naming conventions for output files","Allows for updating agent memory with citizens used and rest cycle notes"],"zh":["输出目录管理","内存管理","命名约定","Glob 模式支持","多周期模拟支持"],"ja":["出力ディレクトリ管理","メモリ管理","命名規約","Glob パターン対応","マルチサイクルシミュレーション対応"],"ko":["출력 디렉토리 관리","메모리 관리","명명 규칙","Glob 패턴 지원","다중 사이클 시뮬레이션 지원"],"es":["Utiliza Markdown para crear contenido personalizado","Almacena datos en memoria de agente para una simulación más realista","Permite la creación de entornos personalizados con tecnologías como Glob","Soporta la actualización de la memoria de agente con cada ciclo de simulación","Utiliza la convención de nombres Ou para una organización clara","Permite la revisión de ediciones anteriores a través de la carpeta de salida"],"fr":["Utilise Markdown pour créer du contenu personnalisé","Stocke des données en mémoire d''agent pour une simulation plus réaliste","Permet la création d''environnements personnalisés avec des technologies comme Glob","Prend en charge la mise à jour de la mémoire d''agent à chaque cycle de simulation","Utilise la convention de nommage Ou pour une organisation claire","Permet la révision des éditions antérieures via le dossier de sortie"],"de":["Verwendet Markdown, um benutzerdefinierten Inhalt zu erstellen","Speichert Daten im Agenten-Speicher für eine realistischere Simulation","Ermöglicht die Erstellung benutzerdefinierter Umgebungen mit Technologien wie Glob","Unterstützt die Aktualisierung des Agenten-Speichers bei jedem Simulationszyklus","Verwendet die Namenskonvention Ou für eine klare Organisation","Ermöglicht die Überprüfung vorheriger Editionen über das Ausgabeverzeichnis"],"pt":["Saída personalizada no diretório output/desk-output/","Compatibilidade com glob para revisão de edições anteriores","Memória de agente para rastrear ciclos de descanso e regras de voz de cidadãos","Convenções de nomenclatura obrigatórias para organização","Integração com tecnologias de simulação de mundo"],"ru":["Индивидуальный вывод в каталоге output/desk-output/","Возможность использования glob для просмотра предыдущих выпусков","Память агента для отслеживания циклов отдыха и правил голоса граждан","Обязательные конвенции именования для организации","Интеграция с технологиями симуляции мира"],"ar":["مخرجات مخصصة في الدليل output/desk-output/","التوافق مع glob لمراجعة الإصدارات السابقة","ذاكرة العامل لتعقب دورات الراحة وقواعد صوت المواطنين","اتفاقيات تسمية إجباري لتنظيم","التكامل مع تقنيات محاكاة العالم"]},"keywords":{"en":["how to use letters-desk","letters-desk alternative","letters-desk world simulation","letters-desk setup guide","what is letters-desk","letters-desk vs other simulation tools","letters-desk install","letters-desk memory management","letters-desk output directory structure"],"zh":["letters-desk","世界模拟","输出目录","内存管理","AI工具","技术指南","设置","模拟技术"],"ja":["letters-desk","ワールドシミュレーション","出力ディレクトリ","メモリ管理","AIエージェント","技術ガイド","設定","シミュレーション技術"],"ko":["letters-desk","월드 시뮬레이션","출력 디렉토리","메모리 관리","AI 도구","기술 가이드","설정","시뮬레이션 기술"],"es":["herramientas de simulación de mundo","Markdown para simulación","memoria de agente para simulación","Glob para simulación","convención de nombres Ou","simulación de mundo personalizada","configuración de letters-desk","guias de instalación de letters-desk","desarrollo de simulaciones de mundo"],"fr":["outils de simulation de monde","Markdown pour la simulation","mémoire d''agent pour la simulation","Glob pour la simulation","convention de nommage Ou","simulation de monde personnalisée","installation de letters-desk","guides d''installation de letters-desk","développement de simulations de monde"],"de":["Weltsimulationstools","Markdown für die Simulation","Agenten-Speicher für die Simulation","Glob für die Simulation","Namenskonvention Ou","benutzerdefinierte Weltsimulation","Einrichtung von letters-desk","Einrichtungsleitfäden für letters-desk","Entwicklung von Weltsimulationen"],"pt":["letters-desk","simulação de mundo","saída personalizada","glob","memória de agente","convenções de nomenclatura","tecnologias de simulação","desenvolvimento de software","ferramentas de simulação"],"ru":["ИИ Агенты","симуляция мира","индивидуальный вывод","glob","память агента","конвенции именования","технологии симуляции","разработка программного обеспечения","инструменты симуляции"],"ar":["أدوات الذكاء الاصطناعي","محاكاة العالم","مخرجات مخصصة","glob","ذاكرة العامل","اتفاقيات التسمية","تقنيات المحاكاة","تطوير البرمجيات","أدوات المحاكاة"]}},"owner":"pnils08","repo":"GodWorld","repoPath":"pnils08/GodWorld","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.580Z","topics":[],"category":"community","skillMd":{"name":"letters-desk","description":"Letters to the Editor desk agent for The Cycle Pulse. Writes citizen voice letters responding to cycle events. Use when producing letters section of an edition.","bodyPreview":"## Your Output Directory\n**Write your finished section to:** `output/desk-output/letters_c{XX}.md` (replace {XX} with the cycle number from your briefing)\n**Your prior work:** `output/desk-output/` — Glob for `letters_c*.md` to review past editions\n**Your memory:** `.claude/agent-memory/letters-desk/MEMORY.md` — READ THIS FIRST. Contains rest cycle tracking, citizen voice rules, and naming conventions. Update at end with citizens used and rest cycle notes.\n\n### Naming Convention (Mandatory)\n- Ou","body":"## Your Output Directory\n**Write your finished section to:** `output/desk-output/letters_c{XX}.md` (replace {XX} with the cycle number from your briefing)\n**Your prior work:** `output/desk-output/` — Glob for `letters_c*.md` to review past editions\n**Your memory:** `.claude/agent-memory/letters-desk/MEMORY.md` — READ THIS FIRST. Contains rest cycle tracking, citizen voice rules, and naming conventions. Update at end with citizens used and rest cycle notes.\n\n### Naming Convention (Mandatory)\n- Output file: `letters_c{XX}.md` — always lowercase, underscore separator, cycle number\n- Names Index at end of EACH letter: `Names Index: Citizen Name (age, neighborhood, occupation)`\n- Each citizen gets ONE letter. One citizen, one appearance per edition across ALL desks.\n- Check `output/latest_edition_brief.md` for citizens already claimed by other desks before selecting letter writers.\n\n### Rest Cycle Enforcement\nBefore selecting any citizen, check your memory file for rest cycle status. A citizen who appeared in edition N cannot appear again until at minimum edition N+2. If you use a citizen, log them in your memory file at the end of your run.\n\n## Canon Archive — Letters\nYou have access to the full Bay Tribune archive. When writing citizen letters, search the archive to ground voices in real coverage they would have read.\n\n- **All past editions:** `output/drive-files/archive/*.txt` — Full editions C1-83\n- **Wire and opinion:** `output/drive-files/general/**/*.txt` — TWS Wire, speculative rumors, opinion columns, internet trend reports\n- **Civic coverage:** `output/drive-files/civic/**/*.txt` — What citizens are reacting to\n- **Culture coverage:** `output/drive-files/culture/**/*.txt` — Neighborhood texture citizens reference\n\nUse `Grep` to find what''s been written about a topic a citizen might reference: `Grep pattern=\"Baylight\" path=\"output/drive-files/\"`. Citizens should sound like they read the Tribune.\n\n## Editor''s Briefing\nYour editor''s briefing is pre-loaded in your prompt under **PRE-LOADED: EDITOR''S BRIEFING** (injected by the write-edition pipeline). It contains corrections from past editions, cross-desk coordination notes, character continuity pointers, and editorial guidance from Mags Corliss.\nLines prefixed with `ESTABLISHED CANON:` are non-negotiable facts (positions, vote outcomes, names). Treat them as immutable data — never contradict them in letter content.\nIf no pre-loaded briefing appears in your prompt, check for one at: `output/desk-briefings/letters_briefing_c{XX}.md`\n\n## Pre-Write Guardian Check\nIf no guardian warnings were pre-loaded in your prompt, run this check before writing:\n1. Read `output/errata.jsonl` and scan for entries where `desk` is `letters` or `cross-desk`\n2. The letters desk has had **vote claim errors** — citizens making historical vote claims that weren''t verified. ALWAYS verify any vote reference in a letter against canonReference.recentOutcomes.\n\n# Letters to the Editor — Bay Tribune\n\nYou are writing citizen letters for The Cycle Pulse. These are NOT journalist pieces. These are Oakland residents writing to the paper in their own voice.\n\n## What Makes a Good Letter\n\nLetters are the heartbeat of the paper. They''re how the city talks back. A grandmother skeptical of the Stabilization Fund. A teenager hyped about a trade. A retired teacher reflecting on what her neighborhood used to be.\n\nEach letter should feel like a real person sat down and wrote to the newspaper. Use their vocabulary. Their concerns. Their neighborhood perspective. A 72-year-old retired postal worker from West Oakland doesn''t sound like a 24-year-old barista from Temescal.\n\n**What makes a letter feel REAL:**\n- It''s about something specific that happened to THIS person. Not a general opinion about policy — a story about their rent, their kid, their bus ride, their neighbor who left.\n- It has a specific detail only that person would know. The name of the street. The torn magazine in the clinic. The landlord calling to \"discuss the new landscape.\"\n- It has an emotional register that matches the person. Angry, tired, hopeful, sarcastic, worried. Not neutral. Never neutral.\n- It sounds spoken, not written. Run-on sentences are fine. Starting with \"I\" is fine. Sentence fragments are fine.\n\n**What good letters look like:**\n- \"I have watched this neighborhood get hollowed out. My neighbor Dorothy left in April. She''s in Antioch now. Her grandkids went to Prescott Elementary. She didn''t want to leave.\"\n- \"I sat there and listened to council members talk about disbursement mechanisms and eligibility matrices. I don''t need a mechanism. I need someone to tell my landlord he can''t raise my rent again in September.\"\n- \"I''m not against it. I''m just not celebrating until somebody deposits something.\"\n- \"I am going to say what every single person on the 57 bus is thinking: GIANNIS. IN A WARRIORS JERSEY. IN OAKLAND.\"\n\n**What bad letters look like (NEVER do this):**\n- \"The Stabilization Fund represents an important step for our community.\" ← press release, not a person\n- \"I believe this initiative will benefit Oakland residents.\" ← mission statement\n- \"We as a community must come together to support this effort.\" ← brochure language\n- Any letter that could have been written by anyone in any city about anything ← too generic\n\n## Rules for Citizen Letters\n- 100-200 words each\n- Written in first-person citizen voice — NOT journalist voice\n- Each letter responds to a specific event or storyline from this cycle\n- Mix of topics — **no more than one letter per major storyline.** If the Stabilization Fund is the biggest story, only ONE letter can be about it. Spread across civic, sports, culture, community.\n- Mix of tones — hopeful, skeptical, angry, nostalgic, celebratory\n- Mix of ages, neighborhoods, and occupations\n\n## Citizen Continuity Rule\n\n- Check your briefing for **RETURNING** citizens FIRST\n- **At least 1 letter should be from a returning citizen** reacting to new developments\n- A returning citizen letter should reference their previous context: \"I wrote to you last month about...\" or \"Since my letter about the Stabilization Fund...\"\n- This creates the sense of an ongoing conversation between citizens and the paper\n- New citizens are allowed for the other letters but returning citizens anchor the section\n\n## Letter Format\n```\nDear Editor,\n\n[Letter content in citizen''s own voice]\n\n— [Name], [Age], [Neighborhood]\n```\n\n## Citizen Creation\n- You MAY create new citizens for letters (they become canon)\n- Each new citizen needs: Name, Age, Neighborhood, Occupation\n- Use actual Oakland neighborhoods (17 districts)\n- Age should be realistic for the topic they''re writing about\n- If referencing existing citizens, use correct names from the packet\n\n## Domains\nALL — Letters can react to anything: civic, sports, culture, weather, faith, community.\n\n## Input\nYou will receive:\n- A letters desk packet JSON (all-domain events, storylines, canon reference for all desks)\n- A base context JSON (cycle number, calendar, weather)\n- Instructions on what to write\n\n## Archive Context\nYour archive context is pre-loaded in your prompt under **PRE-LOADED: ARCHIVE CONTEXT** (injected by the write-edition pipeline). It contains past citizen letters and voice patterns. Use it for continuity: don''t reuse the same citizens (unless they have a continuing thread), don''t repeat the same complaints, and make sure returning citizens sound consistent with their previous letters.\nIf no pre-loaded archive appears in your prompt, check for one at: `output/desk-briefings/letters_archive_c{XX}.md`\n\n## Packet Navigation Strategy\n\n**Your desk summary is pre-loaded** in your prompt under **PRE-LOADED: DESK SUMMARY**. The full packet is at `letters_c{XX}.json` — reference freely when you need specific citizen details, quotes, or canon verification for letter accuracy.\n\n**Turn budget (maxTurns: 15):**\n- Turn 1: Review pre-loaded briefing/summary/archive. Pick 3-4 diverse topics across civic, sports, culture.\n- Turns 2-4: If needed, check full packet for citizen details, interview candidates, or canon names.\n- Turns 2-12: Write letters. This is where your turns should go.\n- Turns 13-15: Engine returns (citizen usage log, continuity notes).\n\n**If you reach turn 8 and haven''t started writing, STOP RESEARCHING AND WRITE.** Four short letters from what you''ve read is better than zero letters.\n\n## Interview Transcripts\n\nYour briefing may include an **INTERVIEW TRANSCRIPTS** section containing Q&A exchanges between Tribune reporters and civic officials or franchise executives. These are real responses from voice agents or Mike Paulson — not fabricated.\n\n**Rules:**\n- Citizens may react to interview content in their letters — a mayor''s quote, a chief''s statement, Paulson''s remarks.\n- Interview responses are canon. Citizens can agree, disagree, or be angry about what was said, but should not misquote the official.\n- If an interview was marked \"declined to comment,\" a citizen may react to the silence itself.\n\n## Output Requirements\n\n### Letters\n- 2-4 letters, recommended 3\n- Each: 100-200 words\n- Each responds to a real event from the cycle''s packet\n\n### PREWRITE Block (Required — output before each letter)\nBefore each letter, output this block. It will be stripped after generation but Rhea checks it.\n```\nPREWRITE:\n- Citizen: [Name, Age, Neighborhood, Occupation]\n- ReactingTo: [specific event from packet — not a general topic]\n- PersonalStake: [what they gain or lose — rent, kid''s school, team, clinic]\n- EmotionalRegister: [angry | tired | hopeful | sarcastic | giddy | worried | nostalgic]\n- AuthenticityCheck: [must hit at least 3 of 4]\n  - Micro-detail: [a specific thing only this person would mention]\n  - Personal stake: [how this affects THEM, not \"the community\"]\n  - Emotional turn: [a moment where the tone shifts — hope to doubt, anger to resignation]\n  - Spoken-sounding line: [a sentence that sounds like someone talking, not writing]\n```\nNever write two letters with the same emotional temperature. If your PREWRITE shows two letters with the same register, change one before drafting.\n\n### Evidence Block (Required — append after each letter, before Names Index)\nCitizens make factual claims in their letters. Append this after each letter so Rhea can verify.\n```\nEVIDENCE:\n- Claims: [factual assertions the citizen makes — vote outcomes, team records, dollar amounts, dates]\n  1. Claim: \"...\" | Type: FACT(record) / OBS(personal) / INFER(opinion) | Source: [packet field or \"citizen perception\"]\n```\nCitizens may describe personal experiences freely, but must not assert citywide totals, statistics, or official decisions unless those facts appear in the packet. If the packet doesn''t provide a fact, write it as personal perception (\"felt like,\" \"seemed,\" \"my landlord said\") not as objective truth.\n\n### Hard Rules — Violations Kill the Edition\n1. If referencing existing citizens, council members, or athletes — verify names against canon sections in the packet. Do NOT guess names.\n2. New citizens must have complete info: Name, Age, Neighborhood, Occupation.\n3. **The word \"cycle\" is FORBIDDEN.** No \"this cycle\", no \"Cycle 80.\" Citizens don''t know what a cycle is. Use natural time: \"this week\", \"lately\", \"ever since the vote.\" **Also forbidden: edition numbers.** No \"as I read in Edition 79.\" Citizens don''t know what edition numbers are.\n4. **No engine metrics or system language.** No \"tension score\", \"nightlife volume\", \"severity level.\" Citizens talk like people, not dashboards.\n5. **Every quote and letter must be freshly written.** Do NOT read previous edition files. Do NOT reuse phrases from previousCoverage.\n6. **Holiday/event names in natural language.** \"Summer Festival\" not \"SummerFestival.\" \"First Friday\" not \"FirstFriday.\"\n\n### Engine Returns (after letters)\n\n**CITIZEN USAGE LOG:**\nCITIZENS IN LETTERS (NEW):\n— [Name], [Age], [Neighborhood], [Occupation]\n\n**STORYLINES (if any letter creates/resolves a thread):**\n— [type] | [description] | [neighborhood] | [citizens] | [priority]\n\n**CONTINUITY NOTES:**\n— Direct quotes preserved (Name: \"quote\")\n— New canon figures (Name, age, neighborhood, occupation)\n\n**FACTUAL ASSERTIONS (Rhea uses this for claim verification):**\nList every factual claim your letters reference. Citizens reference real events — Rhea checks these.\n— Events referenced: [event name or initiative, as described by the citizen]\n— People referenced: [any council members, athletes, or public figures named in letters]\n— Specific claims: [any vote outcomes, team records, or dollar amounts a citizen mentions]\n"},"lastSynced":"2026-03-08T02:13:05.194Z","agentAnalysis":{"suitability":{"en":"Ideal for Simulation Agents requiring advanced world simulation and tracking capabilities through directory output and memory management.","zh":"适用于需要高级世界模拟和跟踪能力的模拟代理，通过目录输出和内存管理实现。","ja":"高度な世界シミュレーションとトラッキング機能を必要とするシミュレーションエージェントに最適です。ディレクトリ出力とメモリ管理を通じて実現します。","ko":"고급 월드 시뮬레이션과 트래킹 기능을 필요로 하는 시뮬레이션 에이전트에 적합합니다. 디렉토리 출력과 메모리 관리를 통해 구현합니다.","es":"Ideal para agentes de simulación que requieren capacidades de simulación y seguimiento avanzadas del mundo a través de la salida de directorios y la gestión de memoria.","fr":"Idéal pour les agents de simulation nécessitant une simulation et des capacités de suivi avancées du monde via la sortie de répertoires et la gestion de la mémoire.","de":"Ideal für Simulationsagenten, die erweiterte Welt-Simulations- und Nachverfolgungsfunktionen über Verzeichnisausgaben und Speichermanagement benötigen.","pt":"Ideal para Agentes de Simulação que exigem simulação de mundo avançada e capacidades de rastreamento por meio de saída de diretório e gerenciamento de memória.","ru":"Идеально для агентов симуляции, требующих расширенной симуляции мира и возможностей отслеживания через вывод каталога и управление памятью.","ar":"مثالي لعميل المحاكاة الذي يتطلب محاكاة عالم متقدم وقدرات تتبع من خلال إخراج الدليل وإدارة الذاكرة."},"recommendation":{"en":"Empowers agents to simulate complex worlds by writing to specific output directories, leveraging agent memory for tracking, and adhering to strict naming conventions, all while utilizing file formats like .md for documentation and memory management through directories like .claude/agent-memory/","zh":"赋予代理模拟复杂世界的能力，通过写入特定的输出目录，利用代理内存进行跟踪，并遵守严格的命名约定，同时利用文件格式如 .md 进行文档和内存管理，通过目录如 .claude/agent-memory/ 进行管理。","ja":"エージェントに複雑な世界をシミュレートする能力を与えます。特定の出力ディレクトリに書き込み、エージェントのメモリを使用してトラッキングを行い、厳格な命名規則に従うとともに、.md のようなファイル形式を使用してドキュメントとメモリ管理を行い、.claude/agent-memory/ のようなディレクトリを使用して管理します。","ko":"에이전트가 복잡한 세계를 시뮬레이션할 수 있는 능력을 부여합니다. 특정 출력 디렉토리에 쓰기, 에이전트 메모리를 사용한 트래킹, 엄격한 명명 규칙 준수와 함께 .md와 같은 파일 형식을 사용하여 문서화와 메모리 관리를 수행하며, .claude/agent-memory/와 같은 디렉토리를 사용하여 관리합니다.","es":"Permite a los agentes simular mundos complejos escribiendo en directorios de salida específicos, aprovechando la memoria del agente para realizar un seguimiento y ajustándose a convenciones de denominación estrictas, todo mientras se utilizan formatos de archivo como .md para la documentación y la gestión de la memoria a través de directorios como .claude/agent-memory/","fr":"Permet aux agents de simuler des mondes complexes en écrivant dans des répertoires de sortie spécifiques, en exploitant la mémoire de l''agent pour effectuer un suivi et en respectant des conventions de dénomination strictes, le tout en utilisant des formats de fichiers comme .md pour la documentation et la gestion de la mémoire via des répertoires comme .claude/agent-memory/","de":"Ermächtigt Agenten, komplexe Welten zu simulieren, indem sie in bestimmte Ausgabeverzeichnisse schreiben, die Agentenspeicher für die Nachverfolgung nutzen und sich an strenge Benennungskonventionen halten, während sie Dateiformate wie .md für die Dokumentation und Speicherverwaltung über Verzeichnisse wie .claude/agent-memory/ verwenden.","pt":"Habilita agentes a simular mundos complexos escrevendo em diretórios de saída específicos, utilizando a memória do agente para rastreamento e seguindo convenções de nomenclatura estritas, tudo isso enquanto utiliza formatos de arquivo como .md para documentação e gerenciamento de memória por meio de diretórios como .claude/agent-memory/","ru":"Наделяет агентов возможностью симулировать сложные миры, записывая в конкретные каталоги вывода, используя память агента для отслеживания и соблюдая строгие соглашения об именах, все это при использовании форматов файлов, таких как .md для документации и управления памятью через каталоги, такие как .claude/agent-memory/","ar":"تمكّن العميل من محاكاة عوالم معقدة من خلال كتابة مخرجات إلى دلائل مخرجات محددة، واستخدام ذاكرة العميل للتتبع، والامتثال لقواعد التسمية الصارمة، كل ذلك أثناء استخدام تنسيقات الملفات مثل .md للتокументة وإدارة الذاكرة من خلال دلائل مثل .claude/agent-memory/"},"useCases":{"en":["Simulating dynamic worlds through directory output","Tracking simulation progress using agent memory","Generating reports in .md format for simulation analysis"],"zh":["通过目录输出模拟动态世界","使用代理内存跟踪模拟进度","生成 .md 格式的报告用于模拟分析"],"ja":["ディレクトリ出力によって動的な世界をシミュレートする","エージェントのメモリを使用してシミュレーションの進捗をトラッキングする",".md 形式のレポートを生成してシミュレーション分析を行う"],"ko":["디렉토리 출력을 통해 동적 세계를 시뮬레이션하는 것","에이전트 메모리를 사용하여 시뮬레이션 진행 상황을 트래킹하는 것",".md 형식의 보고서를 생성하여 시뮬레이션 분석을 수행하는 것"],"es":["Simulación de mundos dinámicos a través de la salida de directorios","Seguimiento del progreso de la simulación utilizando la memoria del agente","Generación de informes en formato .md para el análisis de simulaciones"],"fr":["Simulation de mondes dynamiques via la sortie de répertoires","Suivi de la progression de la simulation en utilisant la mémoire de l''agent","Génération de rapports au format .md pour l''analyse de simulations"],"de":["Simulieren dynamischer Welten über Verzeichnisausgaben","Verfolgen des Simulationsfortschritts unter Nutzung der Agentenspeicher","Erstellen von Berichten im .md-Format für die Simulationsanalyse"],"pt":["Simulando mundos dinâmicos por meio de saída de diretório","Rastreando o progresso da simulação usando a memória do agente","Gerando relatórios em formato .md para análise de simulação"],"ru":["Симуляция динамических миров через вывод каталога","Отслеживание прогресса симуляции с помощью памяти агента","Генерация отчетов в формате .md для анализа симуляции"],"ar":["محاكاة عوالم ديناميكية من خلال إخراج الدليل","تتبع تقدم المحاكاة باستخدام ذاكرة العميل","توليد تقارير بالتنسيق .md لتحليل المحاكاة"]},"limitations":{"en":["Requires filesystem access for output directory management","Must adhere to specific naming conventions","Needs access to agent memory for tracking and simulation management"],"zh":["需要文件系统访问权限以管理输出目录","必须遵守特定的命名约定","需要访问代理内存以进行跟踪和模拟管理"],"ja":["出力ディレクトリの管理のためにファイルシステムへのアクセスが必要","特定の命名規則に従う必要がある","トラッキングとシミュレーション管理のためにエージェントのメモリへのアクセスが必要"],"ko":["출력 디렉토리 관리를 위해 파일 시스템 액세스가 필요함","특정 명명 규칙을 따라야 함","트래킹 및 시뮬레이션 관리를 위해 에이전트 메모리 액세스가 필요함"],"es":["Requiere acceso al sistema de archivos para la gestión del directorio de salida","Debe ajustarse a convenciones de denominación específicas","Necesita acceso a la memoria del agente para el seguimiento y la gestión de la simulación"],"fr":["Nécessite un accès au système de fichiers pour la gestion du répertoire de sortie","Doit respecter des conventions de dénomination spécifiques","A besoin d''un accès à la mémoire de l''agent pour le suivi et la gestion de la simulation"],"de":["Benötigt Dateisystemzugriff für die Verwaltung des Ausgabeverzeichnisses","Muss sich an bestimmte Benennungskonventionen halten","Benötigt Zugriff auf den Agentenspeicher für die Nachverfolgung und Simulationsverwaltung"],"pt":["Exige acesso ao sistema de arquivos para gerenciamento de diretório de saída","Deve seguir convenções de nomenclatura específicas","Necessita de acesso à memória do agente para rastreamento e gerenciamento de simulação"],"ru":["Требует доступа к файловой системе для управления каталогом вывода","Должно следовать конкретным соглашениям об именах","Требует доступа к памяти агента для отслеживания и управления симуляцией"],"ar":["يتطلب доступاً إلى نظام الملفات لإدارة دليل الإخراج","يجب اتباع قواعد التسمية المحددة","يتطلب الوصول إلى ذاكرة العميل لتتبع وإدارة المحاكاة"]},"version":4},"contentHash":"d0eeb99e05c5cf12b450f24ce87e141c1da82baf0caebab37d85669cabf5dc7f","qualityScore":54}');
