INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pnils08/GodWorld/letters-desk', 'letters-desk', 'pnils08', 'GodWorld', 'community', 'letters-desk pnils08 GodWorld community The letters-desk skill enables AI agents to simulate worlds by writing to specific output directories and leveraging agent memory for tracking and naming conventions. This skill benefits developers working on complex simulation projects. letters-desk 技术是世界模拟的核心组件，通过输出目录和内存管理实现高效的模拟 letters-desk 技術はワールドシミュレーションの核心コンポーネントであり、出力ディレクトリとメモリ管理を通じて効率的なシミュレーションを実現します letters-desk 기술은 월드 시뮬레이션의 핵심 구성 요소로 출력 디렉토리와 메모리 관리를 통해 효율적인 시뮬레이션을 구현합니다. Letters-desk es una herramienta de simulación de mundo que utiliza Markdown y memoria de agente para crear entornos personalizados. Configúrala para empezar a simular Letters-desk est un outil de simulation de monde qui utilise Markdown et la mémoire d''agent pour créer des environnements personnalisés. Installez-le pour commencer à simuler Letters-desk ist ein Weltsimulationstool, das Markdown und Agenten-Speicher verwendet, um benutzerdefinierte Umgebungen zu erstellen. Richten Sie es ein, um mit der Simulation zu beginnen O letters-desk é uma ferramenta de simulação de mundo que permite a criação de resultados personalizados. Aprenda a configurá-lo para atender às suas necessidades. ИИ Агенты letters-desk - это инструмент симуляции мира, который позволяет создавать индивидуальные результаты. Узнайте, как его настроить для решения ваших задач. letters-desk هو أداة محاكاة العالم التي تمكنك من إنشاء نتائج مخصصة. تعلم كيفية إعداده لتناسب احتياجاتك how to use letters-desk letters-desk alternative letters-desk world simulation letters-desk setup guide what is letters-desk letters-desk vs other simulation tools letters-desk install letters-desk memory management letters-desk output directory structure letters-desk 世界模拟 输出目录 内存管理 AI工具 技术指南 设置 模拟技术 Writes simulation output to `output/desk-output/letters_c{XX}.md` files Utilizes agent memory stored in `.claude/agent-memory/letters-desk/MEMORY.md` for tracking and naming conventions Supports glob pattern `letters_c*.md` for reviewing past simulation editions Enforces mandatory naming conventions for output files Allows for updating agent memory with citizens used and rest cycle notes letters-desk is a world simulation skill that utilizes output directories and agent memory to generate and track simulation data.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ocn/zk-activity/eve-esi-api', 'community', 'ocn', 'zk-activity', 'ocn/zk-activity', 'eve-esi-api', 0, 0, 54, '2026-03-08T01:57:15.614Z', '2026-03-08T02:13:18.996Z', '65d031b3ae0562ac831c8d1b8d950d3667498463eee7c39b717e4329babea188', '{"id":"ocn/zk-activity/eve-esi-api","name":"eve-esi-api","description":{"en":"The eve-esi-api skill integrates EVE Online''s ESI API and zkillboard, providing real-time killmail updates. It benefits developers working with EVE Online data.","zh":"EVE ESI API 是一个用于 EVE Online 的 API，提供数据获取、处理和缓存功能","ja":"EVE ESI API は、EVE Online 用の API で、データの取得、処理、キャッシュ機能を提供","ko":"EVE ESI API는 EVE Online용 API로 데이터 가져오기, 처리 및 캐싱 기능을 제공","es":"La API eve-esi permite a los desarrolladores interactuar con EVE Online y zkillboard para obtener actualizaciones de Killmail en tiempo real","fr":"L''API eve-esi permet aux développeurs d''interagir avec EVE Online et zkillboard pour obtenir des mises à jour de Killmail en temps réel","de":"Die eve-esi-API ermöglicht es Entwicklern, mit EVE Online und zkillboard zu interagieren, um Echtzeit-Killmail-Updates zu erhalten","pt":"O eve-esi-api é uma ferramenta para interagir com a API do EVE Online, permitindo o acesso a dados de personagens, sistemas e navios.","ru":"eve-esi-api - это инструмент для взаимодействия с API EVE Online, позволяющий получить доступ к данным персонажей, систем и кораблей.","ar":"eve-esi-api هو أداة للتفاعل مع واجهة برمجة تطبيقات EVE Online، مما يسمح بالوصول إلى بيانات الشخصيات والنظم والسفن."},"seo":{"title":{"en":"eve-esi-api: ESI API Integration Guide for AI Agents","zh":"EVE ESI API 集成指南","ja":"EVE ESI API 統合ガイド","ko":"EVE ESI API 통합 가이드","es":"Guía de configuración de eve-esi-api para desarrolladores","fr":"Guide de mise en route de l''API eve-esi pour les développ...","de":"Einrichtungsleitfaden für eve-esi-api-Entwickler","pt":"Guia de Configuração do eve-esi-api para Desenvolvedores","ru":"Настройка eve-esi-api: Лучшие Практики для Разработчиков","ar":"دليل إعداد eve-esi-api للعاملات الإلكترونية"},"description":{"en":"Unlock EVE Online data with eve-esi-api. Learn how to fetch characters, systems, and ships data using ESI API and zkillboard. Get started now!","zh":"了解 EVE ESI API 的技术细节，实现数据获取、处理和缓存","ja":"EVE ESI API の技術的詳細を学び、データの取得、処理、キャッシュを実現","ko":"EVE ESI API의 기술적 세부 사항을 학습하고 데이터 가져오기, 처리 및 캐싱을 구현","es":"Aprende a integrar la API eve-esi en tus proyectos de desarrollo con nuestra guía paso a paso","fr":"Découvrez comment intégrer l''API eve-esi dans vos projets de développement avec notre guide étape par étape","de":"Erfahren Sie, wie Sie die eve-esi-API in Ihre Entwicklungsprojekte integrieren können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a integrar o eve-esi-api em seu projeto, com dicas e truques para desenvolvedores","ru":"Интегрируйте eve-esi-api в ваш проект с помощью нашего руководства для разработчиков","ar":"تعرف على كيفية دمج eve-esi-api في مشروعك مع نصائح للعاملات الإلكترونية"},"definition":{"en":"eve-esi-api is an API integration skill for interacting with EVE Online''s ESI API and zkillboard data feeds.","zh":"EVE ESI API 是一个用于 EVE Online 的 API 接口","ja":"EVE ESI API は、EVE Online 用の API インターフェース","ko":"EVE ESI API는 EVE Online용 API 인터페이스","es":"La API eve-esi es un conjunto de patrones para interactuar con EVE Online y zkillboard","fr":"L''API eve-esi est un ensemble de modèles pour interagir avec EVE Online et zkillboard","de":"Die eve-esi-API ist eine Sammlung von Mustern zur Interaktion mit EVE Online und zkillboard","pt":"O que é eve-esi-api? É uma API para interagir com o EVE Online, fornecendo dados de killmail e informações do universo.","ru":"Что такое eve-esi-api? Это API для взаимодействия с EVE Online, предоставляющая данные о killmail и информацию об игровом мире.","ar":"ما هو eve-esi-api؟ هو واجهة برمجة تطبيقات للتفاعل مع EVE Online، مما يوفر بيانات killmail ومعلومات عن الكون."},"features":{"en":["Fetches data from ESI API for characters, systems, and ships","Processes killmail data from zkillboard with customizable filters","Implements ESI authentication using SSO","Caches EVE universe data for efficient access","Works with EVE-specific IDs and data structures"],"zh":["支持 ESI 数据获取","实现 zkillboard 数据处理","提供 ESI 认证（SSO）","支持 EVE 宇宙数据缓存","处理 EVE 特定 ID 和数据结构"],"ja":["ESI データの取得をサポート","zkillboard データの処理を実現","ESI 認証（SSO）を提供","EVE 宇宙データのキャッシュをサポート","EVE 特定の ID とデータ構造を処理"],"ko":["ESI 데이터 가져오기 지원","zkillboard 데이터 처리 구현","ESI 인증（SSO） 제공","EVE 우주 데이터 캐싱 지원","EVE 특정 ID 및 데이터 구조 처리"],"es":["Integración con EVE Online para obtener datos de personajes y sistemas","Procesamiento de datos de killmail de zkillboard","Implementación de autenticación ESI (SSO)","Caché de datos del universo de EVE","Trabajo con IDs y estructuras de datos específicas de EVE"],"fr":["Intégration avec EVE Online pour obtenir des données de personnages et de systèmes","Traitement des données de killmail de zkillboard","Mise en œuvre de l''authentification ESI (SSO)","Mise en cache des données de l''univers de EVE","Travail avec des IDs et des structures de données spécifiques à EVE"],"de":["Integration mit EVE Online für die Beschaffung von Charakter- und Systemdaten","Verarbeitung von Killmail-Daten von zkillboard","Implementierung der ESI-Authentifizierung (SSO)","Caching von EVE-Universumsdaten","Arbeit mit EVE-spezifischen IDs und Datenstrukturen"],"pt":["Acesso a dados de personagens, sistemas e navios via ESI","Processamento de dados de killmail do zkillboard","Implementação de autenticação ESI (SSO)","Cache de dados do universo EVE","Trabalho com IDs e estruturas de dados específicas do EVE"],"ru":["Доступ к данным персонажей, систем и кораблей через ESI","Обработка данных о killmail с zkillboard","Реализация аутентификации ESI (SSO)","Кэширование данных игрового мира EVE","Работа с идентификаторами и структурами данных, специфичными для EVE"],"ar":["الوصول إلى بيانات الشخصيات والنظم والسفن عبر ESI","معالجة بيانات killmail من zkillboard","تنفيذ مصادقة ESI (SSO)","แคش البيانات الكونية EVE","العمل مع معرّفات وهياكل بيانات محددة ل EVE"]},"keywords":{"en":["how to use eve-esi-api","eve-esi-api setup guide","esi api integration","zkillboard data feeds","eve online api alternatives","eve-esi-api vs other APIs","install eve-esi-api","eve-esi-api documentation","eve online development"],"zh":["EVE ESI API","EVE Online API","ESI 数据获取","zkillboard 数据处理","EVE 宇宙数据缓存","EVE 特定 ID","AIエージェント","API 接口"],"ja":["EVE ESI API","EVE Online API","ESI データの取得","zkillboard データの処理","EVE 宇宙データのキャッシュ","EVE 特定の ID","AIエージェント","API インターフェース"],"ko":["EVE ESI API","EVE Online API","ESI 데이터 가져오기","zkillboard 데이터 처리","EVE 우주 데이터 캐싱","EVE 특정 ID","AI 에이전트","API 인터페이스"],"es":["eve-esi-api","desarrollo de EVE Online","zkillboard API","autenticación ESI","datos de EVE","desarrollo de juegos","API de juegos","herramientas de desarrollo de EVE"],"fr":["eve-esi-api","développement EVE Online","API zkillboard","authentification ESI","données EVE","développement de jeux","API de jeux","outils de développement EVE"],"de":["eve-esi-api","EVE-Online-Entwicklung","zkillboard-API","ESI-Authentifizierung","EVE-Daten","Spieleentwicklung","Spiel-API","EVE-Entwicklertools"],"pt":["eve-esi-api","EVE Online API","zkillboard","ESI autenticação","cache de dados EVE","desenvolvimento de jogos","API de jogos","ferramentas de desenvolvimento"],"ru":["eve-esi-api","EVE Online API","zkillboard","ESI аутентификация","кэш данных EVE","разработка игр","API игр","инструменты разработки"],"ar":["eve-esi-api","واجهة برمجة تطبيقات EVE Online","zkillboard","مصادقة ESI","แคช البيانات الكونية EVE","تطوير الألعاب","واجهة برمجة تطبيقات الألعاب","أدوات التطوير"]}},"owner":"ocn","repo":"zk-activity","repoPath":"ocn/zk-activity","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.614Z","topics":[],"category":"community","skillMd":{"name":"eve-esi-api","description":"EVE Online ESI API patterns and zkillboard integration. Covers ESI endpoints, authentication, data models, zkillboard RedisQ listener, caching strategies, and EVE-specific IDs (characters, corporations, alliances, ships, systems, regions). Use when working with killmail data, fetching EVE universe info, or implementing ESI calls.","bodyPreview":"# EVE Online ESI API Guidelines\n\n## Purpose\n\nPatterns for interacting with the EVE Online ESI API and zkillboard data feeds in this project.\n\n## When to Use\n\n- Fetching data from ESI (characters, systems, ships, etc.)\n- Processing killmail data from zkillboard\n- Implementing ESI authentication (SSO)\n- Caching EVE universe data\n- Working with EVE-specific IDs and data structures\n\n---\n\n## Key URLs and Endpoints\n\n| Service | Base URL | Purpose |\n|---------|----------|---------|\n| ESI | `https://esi","body":"# EVE Online ESI API Guidelines\n\n## Purpose\n\nPatterns for interacting with the EVE Online ESI API and zkillboard data feeds in this project.\n\n## When to Use\n\n- Fetching data from ESI (characters, systems, ships, etc.)\n- Processing killmail data from zkillboard\n- Implementing ESI authentication (SSO)\n- Caching EVE universe data\n- Working with EVE-specific IDs and data structures\n\n---\n\n## Key URLs and Endpoints\n\n| Service | Base URL | Purpose |\n|---------|----------|---------|\n| ESI | `https://esi.evetech.net/latest/` | Official EVE API |\n| zkillboard RedisQ | `https://zkillredisq.stream/listen.php` | Real-time killmail feed |\n| zkillboard | `https://zkillboard.com/` | Killmail browser |\n| Fuzzwork | `https://www.fuzzwork.co.uk/api/` | Third-party celestial data |\n| EVE SSO | `https://login.eveonline.com/` | OAuth authentication |\n| EVE Images | `https://images.evetech.net/` | Character/ship/alliance icons |\n\n---\n\n## ESI Client Pattern\n\n### Basic Structure\n\n```rust\npub struct EsiClient {\n    client: Client,  // reqwest::Client\n}\n\nimpl EsiClient {\n    pub fn new() -> Self {\n        EsiClient {\n            client: Client::new(),\n        }\n    }\n\n    async fn fetch<T: for<''de> Deserialize<''de>>(\n        &self,\n        path: &str,\n    ) -> Result<T, Box<dyn Error + Send + Sync>> {\n        let url = format!(\"{}{}\", ESI_URL, path);\n        let response = self.client.get(&url).send().await?;\n        if !response.status().is_success() {\n            return Err(format!(\"ESI API returned status: {}\", response.status()).into());\n        }\n        let data: T = response.json().await?;\n        Ok(data)\n    }\n}\n```\n\n### Common ESI Endpoints\n\n```rust\n// Get system info\npub async fn get_system(&self, system_id: u32) -> Result<System, Error> {\n    self.fetch(&format!(\"universe/systems/{}/\", system_id)).await\n}\n\n// Get ship/item group\npub async fn get_ship_group_id(&self, type_id: u32) -> Result<u32, Error> {\n    #[derive(Deserialize)]\n    struct EsiType { group_id: u32 }\n    let type_info: EsiType = self.fetch(&format!(\"universe/types/{}/\", type_id)).await?;\n    Ok(type_info.group_id)\n}\n\n// Get names (POST endpoint)\npub async fn get_name(&self, id: u64) -> Result<String, Error> {\n    let names: Vec<EsiName> = self.client\n        .post(format!(\"{}universe/names/\", ESI_URL))\n        .json(&[id])  // Array of IDs\n        .send()\n        .await?\n        .json()\n        .await?;\n    Ok(names.into_iter().next()?.name)\n}\n\n// Get character affiliation (POST endpoint)\npub async fn get_character_affiliation(&self, character_id: u64)\n    -> Result<(u64, Option<u64>), Error>  // (corp_id, alliance_id)\n{\n    let affiliations: Vec<Affiliation> = self.client\n        .post(format!(\"{}characters/affiliation/\", ESI_URL))\n        .json(&[character_id])\n        .send()\n        .await?\n        .json()\n        .await?;\n    let a = affiliations.into_iter().next()?;\n    Ok((a.corporation_id, a.alliance_id))\n}\n```\n\n---\n\n## zkillboard RedisQ\n\n### Listener Pattern\n\n```rust\nconst REDISQ_URL: &str = \"https://zkillredisq.stream/listen.php\";\n\npub struct RedisQListener {\n    client: Client,\n    url: String,\n}\n\nimpl RedisQListener {\n    pub fn new(queue_id: &str) -> Self {\n        // Each listener needs a unique queue ID\n        let url = format!(\"{}?queueID={}\", REDISQ_URL, queue_id);\n        RedisQListener {\n            client: Client::new(),\n            url,\n        }\n    }\n\n    pub async fn listen(&self) -> Result<Option<ZkData>, Error> {\n        let response = self.client.get(&self.url)\n            .timeout(Duration::from_secs(60))  // Long-polling\n            .send()\n            .await?;\n\n        let wrapper: RedisQResponse = response.json().await?;\n        Ok(wrapper.package)  // None if no new killmails\n    }\n}\n```\n\n### Main Loop Pattern\n\n```rust\nloop {\n    match listener.listen().await {\n        Ok(Some(zk_data)) => {\n            info!(\"[Kill: {}] Received\", zk_data.kill_id);\n            process_killmail(&zk_data).await;\n            sleep(Duration::from_secs(1)).await;\n        }\n        Ok(None) => {\n            // No new data, RedisQ timed out\n            sleep(Duration::from_secs(1)).await;\n        }\n        Err(e) => {\n            error!(\"Error: {}\", e);\n            sleep(Duration::from_secs(5)).await;  // Backoff on error\n        }\n    }\n}\n```\n\n---\n\n## Data Models\n\n### Killmail Structure\n\n```rust\n#[derive(Debug, Deserialize)]\npub struct ZkData {\n    pub kill_id: u64,\n    pub killmail: KillmailData,\n    pub zkb: ZkbMeta,\n}\n\n#[derive(Debug, Deserialize)]\npub struct KillmailData {\n    pub killmail_id: u64,\n    pub killmail_time: String,  // RFC3339 format\n    pub solar_system_id: u32,\n    pub victim: Victim,\n    pub attackers: Vec<Attacker>,\n}\n\n#[derive(Debug, Deserialize)]\npub struct Victim {\n    pub ship_type_id: u32,\n    pub character_id: Option<u64>,\n    pub corporation_id: Option<u64>,\n    pub alliance_id: Option<u64>,\n    pub position: Option<Position>,\n}\n\n#[derive(Debug, Deserialize)]\npub struct Attacker {\n    pub ship_type_id: Option<u32>,\n    pub weapon_type_id: Option<u32>,\n    pub character_id: Option<u64>,\n    pub corporation_id: Option<u64>,\n    pub alliance_id: Option<u64>,\n    pub final_blow: bool,\n}\n\n#[derive(Debug, Deserialize)]\npub struct ZkbMeta {\n    pub total_value: f64,\n    pub location_id: Option<u64>,\n    pub esi: String,  // URL to full ESI killmail\n}\n```\n\n### System Data\n\n```rust\n#[derive(Debug, Clone, Serialize, Deserialize)]\npub struct System {\n    pub id: u32,\n    pub name: String,\n    pub security_status: f64,\n    pub region_id: u32,\n    pub region: String,\n    pub x: f64,\n    pub y: f64,\n    pub z: f64,\n}\n```\n\n---\n\n## Caching Strategy\n\n### Cache ESI Data Locally\n\n```rust\n// Check cache first\n{\n    let systems = app_state.systems.read().unwrap();\n    if let Some(system) = systems.get(&system_id) {\n        return Some(system.clone());\n    }\n}\n\n// Fetch and cache\nmatch esi_client.get_system(system_id).await {\n    Ok(system) => {\n        let mut systems = app_state.systems.write().unwrap();\n        systems.insert(system_id, system.clone());\n        save_systems(&systems);  // Persist to disk\n        Some(system)\n    }\n    Err(e) => {\n        warn!(\"Failed to fetch system {}: {}\", system_id, e);\n        None\n    }\n}\n```\n\n### Using Moka for In-Memory Cache\n\n```rust\nuse moka::future::Cache;\n\npub struct AppState {\n    // Time-based expiry cache\n    pub celestial_cache: Cache<u32, Arc<Celestial>>,\n}\n\n// Check cache\nif let Some(celestial) = app_state.celestial_cache.get(&system_id) {\n    return Some(celestial);\n}\n\n// Fetch and cache\nlet celestial = Arc::new(fetch_celestial().await?);\napp_state.celestial_cache.insert(system_id, celestial.clone()).await;\n```\n\n---\n\n## EVE-Specific Knowledge\n\n### Important IDs\n\n| Type | Example IDs | Notes |\n|------|-------------|-------|\n| Ship Groups | 485 (Dread), 659 (Super), 30 (Titan) | Used for filtering |\n| Regions | 10000030 (Devoid), 10000012 (Curse) | Universe IDs |\n| Systems | 30000142 (Jita), 30002086 (Turnur) | Solar system IDs |\n\n### Ship Group Priorities\n\n```rust\nconst SHIP_GROUP_PRIORITY: &[u32] = &[\n    30,   // Titan\n    659,  // Supercarrier\n    4594, // Lancer\n    485,  // Dreadnought\n    1538, // FAX\n    547,  // Carrier\n    883,  // Capital Industrial Ship\n    902,  // Jump Freighter\n    513,  // Freighter\n];\n```\n\n### Image URLs\n\n```rust\n// Alliance logo\nfn alliance_icon(id: u64) -> String {\n    format!(\"https://images.evetech.net/alliances/{}/logo?size=64\", id)\n}\n\n// Corporation logo\nfn corp_icon(id: u64) -> String {\n    format!(\"https://images.evetech.net/corporations/{}/logo?size=64\", id)\n}\n\n// Ship/item icon\nfn ship_icon(id: u32) -> String {\n    format!(\"https://images.evetech.net/types/{}/icon?size=64\", id)\n}\n\n// Character portrait\nfn character_portrait(id: u64) -> String {\n    format!(\"https://images.evetech.net/characters/{}/portrait?size=64\", id)\n}\n```\n\n### External Links\n\n```rust\n// zkillboard\nfn zkb_kill(id: u64) -> String {\n    format!(\"https://zkillboard.com/kill/{}/\", id)\n}\nfn zkb_character(id: u64) -> String {\n    format!(\"https://zkillboard.com/character/{}/\", id)\n}\nfn zkb_corp(id: u64) -> String {\n    format!(\"https://zkillboard.com/corporation/{}/\", id)\n}\n\n// Dotlan\nfn dotlan_system(id: u32) -> String {\n    format!(\"http://evemaps.dotlan.net/system/{}\", id)\n}\nfn dotlan_region(id: u32) -> String {\n    format!(\"http://evemaps.dotlan.net/region/{}\", id)\n}\n\n// EVE Tools battle report\nfn br_link(system_id: u32, timestamp: &str) -> String {\n    format!(\"https://br.evetools.org/related/{}/{}\", system_id, timestamp)\n}\n```\n\n---\n\n## SSO Authentication\n\n### OAuth2 Flow\n\n```rust\nconst ESI_AUTH_URL: &str = \"https://login.eveonline.com/v2/oauth/token\";\nconst ESI_VERIFY_URL: &str = \"https://login.eveonline.com/oauth/verify\";\n\npub async fn exchange_code_for_token(\n    &self,\n    code: &str,\n    client_id: &str,\n    client_secret: &str,\n) -> Result<EveAuthToken, Error> {\n    // 1. Exchange authorization code for tokens\n    let params = [(\"grant_type\", \"authorization_code\"), (\"code\", code)];\n    let auth_response: Value = self.client\n        .post(ESI_AUTH_URL)\n        .basic_auth(client_id, Some(client_secret))\n        .form(&params)\n        .send()\n        .await?\n        .json()\n        .await?;\n\n    let access_token = auth_response[\"access_token\"].as_str()?.to_string();\n    let refresh_token = auth_response[\"refresh_token\"].as_str()?.to_string();\n\n    // 2. Verify token and get character info\n    let verify_response: Value = self.client\n        .get(ESI_VERIFY_URL)\n        .bearer_auth(&access_token)\n        .send()\n        .await?\n        .json()\n        .await?;\n\n    let character_id = verify_response[\"CharacterID\"].as_u64()?;\n    let character_name = verify_response[\"CharacterName\"].as_str()?.to_string();\n\n    Ok(EveAuthToken { character_id, character_name, access_token, refresh_token, ... })\n}\n```\n\n### Authenticated Requests\n\n```rust\npub async fn get_contacts(\n    &self,\n    entity_id: u64,\n    token: &str,\n    endpoint: &str,  // \"characters\", \"corporations\", or \"alliances\"\n) -> Result<Vec<StandingContact>, Error> {\n    let url = format!(\"{}{}/{}/contacts/\", ESI_URL, endpoint, entity_id);\n    let contacts: Vec<StandingContact> = self.client\n        .get(&url)\n        .bearer_auth(token)  // Include access token\n        .send()\n        .await?\n        .json()\n        .await?;\n    Ok(contacts)\n}\n```\n\n---\n\n## Reference Files\n\n- [resources/endpoints.md](resources/endpoints.md) - Complete ESI endpoint reference\n- [resources/ids.md](resources/ids.md) - Common EVE IDs lookup table\n"},"lastSynced":"2026-03-08T02:13:18.996Z","agentAnalysis":{"suitability":{"en":"Perfect for Game Data Analysis Agents needing real-time EVE Online data and ESI API integration.","zh":"非常适合需要实时EVE Online数据和ESI API集成的游戏数据分析代理。","ja":"リアルタイムのEVE OnlineデータとESI APIの統合が必要なゲームデータ分析エージェントに最適です。","ko":"실시간 EVE Online 데이터와 ESI API 통합이 필요한 게임 데이터 분석 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Análisis de Datos de Juegos que necesitan datos en tiempo real de EVE Online y integración de la API de ESI.","fr":"Parfait pour les agents d''analyse de données de jeu nécessitant des données EVE Online en temps réel et une intégration à l''API ESI.","de":"Perfekt für Game Data Analysis Agents, die Echtzeit-Daten von EVE Online und ESI-API-Integration benötigen.","pt":"Perfeito para Agentes de Análise de Dados de Jogos que precisam de dados em tempo real do EVE Online e integração da ESI API.","ru":"Идеально подходит для агентов анализа игровых данных, которым необходимы данные EVE Online в режиме реального времени и интеграция с ESI API.","ar":"مثالي للوكلاء تحليل بيانات الألعاب الذين يحتاجون إلى بيانات EVE Online في الوقت الفعلي وتكامل ESI API."},"recommendation":{"en":"Empowers agents to fetch character, system, and ship data from the EVE Online ESI API, process killmail data from zkillboard, and implement ESI authentication using SSO, while caching EVE universe data for efficient access.","zh":"赋予代理从EVE Online ESI API中获取角色、系统和船舶数据的能力，处理来自zkillboard的杀戮邮件数据，并使用SSO实现ESI身份验证，同时缓存EVE宇宙数据以实现高效访问。","ja":"EVE Online ESI APIからリアルタイムのキャラクター、システム、シップデータを取得する機能をエージェントに与え、zkillboardからのキルメールデータを処理し、SSOを使用したESI認証を実装し、EVE宇宙データをキャッシュして効率的なアクセスを実現します。","ko":"EVE Online ESI API에서 캐릭터, 시스템, 船舶 데이터를 가져오는 기능을 에이전트에게 부여하고, zkillboard의 킬메일 데이터를 처리하고, SSO를 사용한 ESI 인증을 구현하며, EVE 우주 데이터를 캐시하여 효율적인 접근을 제공합니다.","es":"Habilita a los agentes a recuperar datos de personajes, sistemas y naves desde la API de ESI de EVE Online, procesar datos de killmail desde zkillboard e implementar la autenticación de ESI mediante SSO, mientras que almacena en caché los datos del universo de EVE para un acceso eficiente.","fr":"Permet aux agents de récupérer des données de personnages, de systèmes et de navires à partir de l''API ESI d''EVE Online, de traiter les données de killmail à partir de zkillboard et de mettre en œuvre l''authentification ESI à l''aide de SSO, tout en mettant en cache les données de l''univers d''EVE pour un accès efficace.","de":"Ermächtigt Agenten, Charakter-, System- und Schiffdaten aus der EVE Online ESI-API abzurufen, Killmail-Daten von zkillboard zu verarbeiten und ESI-Authentifizierung mithilfe von SSO umzusetzen, während sie EVE-Universumsdaten für einen effizienten Zugriff zwischenspeichert.","pt":"Habilita os agentes a buscar dados de personagens, sistemas e naves do EVE Online ESI API, processar dados de killmail do zkillboard e implementar autenticação ESI usando SSO, enquanto armazena em cache os dados do universo EVE para acesso eficiente.","ru":"Наделяет агентов возможностью получать данные персонажей, систем и кораблей из EVE Online ESI API, обрабатывать данные killmail из zkillboard и реализовывать аутентификацию ESI с помощью SSO, а также кэшировать данные вселенной EVE для эффективного доступа.","ar":"يمنح الوكلاء القدرة على استرجاع بيانات الشخصيات والنظم والسفن من EVE Online ESI API، ومعالجة بيانات killmail من zkillboard وتنفيذ مصادقة ESI باستخدام SSO، مع تخزين بيانات الكون EVE في ذاكرة التخزين المؤقت للوصول الفعال."},"useCases":{"en":["Fetching real-time character and ship data from the EVE Online ESI API","Processing killmail data from zkillboard for game analytics","Implementing ESI authentication using SSO for secure data access"],"zh":["从EVE Online ESI API中获取实时角色和船舶数据","处理来自zkillboard的杀戮邮件数据以进行游戏分析","使用SSO实现ESI身份验证以实现安全的数据访问"],"ja":["EVE Online ESI APIからリアルタイムのキャラクターとシップデータを取得する","zkillboardからのキルメールデータを処理してゲーム分析を行う","SSOを使用したESI認証を実装して安全なデータアクセスを実現する"],"ko":["EVE Online ESI API에서 실시간 캐릭터와 船舶 데이터를 가져오는 것","zkillboard의 킬메일 데이터를 처리하여 게임 분석을 수행하는 것","SSO를 사용한 ESI 인증을 구현하여 안전한 데이터 접근을 제공하는 것"],"es":["Recuperar datos de personajes y naves en tiempo real desde la API de ESI de EVE Online","Procesar datos de killmail desde zkillboard para análisis de juego","Implementar la autenticación de ESI mediante SSO para un acceso seguro a los datos"],"fr":["Récupérer des données de personnages et de navires en temps réel à partir de l''API ESI d''EVE Online","Traiter les données de killmail à partir de zkillboard pour l''analyse de jeu","Mettre en œuvre l''authentification ESI à l''aide de SSO pour un accès sécurisé aux données"],"de":["Abrufen von Charakter- und Schiffdaten in Echtzeit aus der EVE Online ESI-API","Verarbeiten von Killmail-Daten von zkillboard für Spielanalyse","Umsetzen der ESI-Authentifizierung mithilfe von SSO für einen sicheren Datenzugriff"],"pt":["Buscar dados de personagens e naves em tempo real do EVE Online ESI API","Processar dados de killmail do zkillboard para análise de jogos","Implementar autenticação ESI usando SSO para acesso de dados seguro"],"ru":["Получать данные персонажей и кораблей в режиме реального времени из EVE Online ESI API","Обрабатывать данные killmail из zkillboard для аналитики игр","Реализовывать аутентификацию ESI с помощью SSO для безопасного доступа к данным"],"ar":["استرجاع بيانات الشخصيات والسفن في الوقت الفعلي من EVE Online ESI API","معالجة بيانات killmail من zkillboard لتحليل الألعاب","تنفيذ مصادقة ESI باستخدام SSO للوصول الآمن إلى البيانات"]},"limitations":{"en":["Requires EVE Online ESI API access","Limited to EVE Online data and zkillboard integration","Needs caching mechanism for efficient data access"],"zh":["需要EVE Online ESI API访问","仅限EVE Online数据和zkillboard集成","需要缓存机制以实现高效数据访问"],"ja":["EVE Online ESI APIへのアクセスが必要","EVE Onlineデータとzkillboardの統合のみ","効率的なデータアクセスを実現するためのキャッシュメカニズムが必要"],"ko":["EVE Online ESI API 접근이 필요합니다","EVE Online 데이터와 zkillboard 통합만 가능합니다","효율적인 데이터 접근을 위해 캐싱 메커니즘이 필요합니다"],"es":["Requiere acceso a la API de ESI de EVE Online","Limitado a los datos de EVE Online y la integración con zkillboard","Necesita un mecanismo de caché para un acceso eficiente a los datos"],"fr":["Nécessite un accès à l''API ESI d''EVE Online","Limité aux données d''EVE Online et à l''intégration à zkillboard","Nécessite un mécanisme de mise en cache pour un accès efficace aux données"],"de":["Benötigt Zugriff auf die EVE Online ESI-API","Begrenzt auf EVE-Online-Daten und zkillboard-Integration","Benötigt einen Zwischenspeichermechanismus für einen effizienten Datenzugriff"],"pt":["Exige acesso à ESI API do EVE Online","Limitado a dados do EVE Online e integração do zkillboard","Necessita de mecanismo de cache para acesso eficiente aos dados"],"ru":["Требует доступа к ESI API EVE Online","Ограничен данными EVE Online и интеграцией с zkillboard","Требует механизма кэширования для эффективного доступа к данным"],"ar":["يتطلب الوصول إلى ESI API EVE Online","محدود ببيانات EVE Online وتكامل zkillboard","يحتاج إلى آلية تخزين مؤقت للوصول الفعال إلى البيانات"]},"version":4},"contentHash":"65d031b3ae0562ac831c8d1b8d950d3667498463eee7c39b717e4329babea188","qualityScore":54}');
